begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L3-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بحرارة الاحتراق ΔHcomb؟', null, null, '["الحرارة اللازمة لتبخر 1 mol من المادة السائلة","المحتوى الحراري الناتج عن حرق 1 g من المادة احتراقًا كاملًا","المحتوى الحراري الناتج عن حرق 1 mol من المادة احتراقًا كاملًا","الحرارة الممتصة عند تفاعل 1 mol من الأكسجين مع الوقود"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 25 — حرارة الاحتراق والمحتوى الحراري القياسي'),
('mcq', 2, 'عند حرق 1 mol من الجلوكوز C₆H₁₂O₆ احتراقًا كاملًا تنطلق 2808 kJ من الحرارة. ما قيمة حرارة الاحتراق ΔHcomb للجلوكوز؟', null, null, '["−2808 kJ/mol","+2808 kJ/mol","−2808 kJ/g","−15.6 kJ/mol"]'::jsonb, 'فهم', 'تذكر الظروف القياسية', 'سهل', 'الكتاب ص 25، 26 — حرارة الاحتراق، الجدول 1-3'),
('mcq', 3, 'علامَ يدل الرمز ° في الرمز ΔH°؟', null, null, '["أن قيمة ΔH مقيسة بوحدة الدرجة السيلزية","أن التفاعل يحدث في درجة الحرارة والضغط القياسيين STP","أن التفاعل طارد للحرارة في جميع الأحوال","أن تغيرات المحتوى الحراري حُددت والمواد كلها في الظروف القياسية"]'::jsonb, 'فهم', 'تفسير رمز', 'متوسط', 'الكتاب ص 25 — حرارة الاحتراق والمحتوى الحراري القياسي'),
('mcq', 4, 'لماذا تكون قيم حرارة الاحتراق القياسية ΔH°comb لجميع المواد سالبة؟', null, null, '["لأن الاحتراق يمتص الحرارة من المحيط","لأن الاحتراق يطلق الحرارة إلى المحيط","لأن طاقة المواد في الظروف القياسية تساوي صفرًا","لأن نواتج الاحتراق تكون غازات دائمًا"]'::jsonb, 'فهم', 'تفسير إشارة', 'متوسط', 'الكتاب ص 25، 26 — مراجعة المفردات، الجدول 1-3'),
('mcq', 5, 'بالاستعانة بالجدول، ما كمية الحرارة المنطلقة عند حرق 2.00 mol من البروبان احتراقًا كاملًا في الظروف القياسية؟', '{"headers":["المادة","الصيغة الكيميائية","ΔH°comb (kJ/mol)"],"rows":[["السكروز","C₁₂H₂₂O₁₁(s)","−5644"],["الأوكتان","C₈H₁₈(l)","−5471"],["الجلوكوز","C₆H₁₂O₆(s)","−2808"],["البروبان","C₃H₈(g)","−2219"],["الميثان","CH₄(g)","−891"]]}'::jsonb, null, '["2.22×10³ kJ","1.11×10³ kJ","4.44×10³ kJ","1.78×10³ kJ"]'::jsonb, 'تطبيق', 'استعمال جدول حرارة الاحتراق', 'متوسط', 'الكتاب ص 26 — الجدول 1-3 حرارة الاحتراق القياسية'),
('mcq', 6, 'حرارة الاحتراق المولارية للميثان −891 kJ/mol. أيّ معادلة كيميائية حرارية تعبّر عن ΔHcomb للميثان وفق تعريفها؟', null, null, '["CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)   ΔH = −891 kJ","2CH₄(g) + 4O₂(g) → 2CO₂(g) + 4H₂O(l)   ΔH = −891 kJ","CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)   ΔH = +891 kJ","CO₂(g) + 2H₂O(l) → CH₄(g) + 2O₂(g)   ΔH = −891 kJ"]'::jsonb, 'فهم', 'ربط التعريف بالمعادلة', 'صعب', 'الكتاب ص 25، 30 — حرارة الاحتراق، تفاعلات الاحتراق'),
('mcq', 7, 'قال طالب: «تُقاس قيمة ΔH° للتفاعلات عند 0 °C و1 atm». ما تقويمك لعبارته؟', null, null, '["صحيحة؛ لأن الظروف القياسية للمحتوى الحراري هي نفسها STP","خاطئة؛ لأن الظروف القياسية هي 1 atm و100 °C","صحيحة؛ لأن الرمز ° يشير إلى درجة الصفر السيلزي","خاطئة؛ لأن الظروف القياسية هي 1 atm و25 °C وليست STP"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 25 — حرارة الاحتراق والمحتوى الحراري القياسي'),
('essay', 1, 'عرّف حرارة الاحتراق، واذكر رمزها ووحدتها، ثم وضّح التعريف بمثال الجلوكوز الذي حرارة احتراقه −2808 kJ/mol.', null, null, null, 'تذكر', 'تعريف وتوضيح بمثال', 'سهل', 'الكتاب ص 25، 26 — حرارة الاحتراق، الجدول 1-3'),
('essay', 2, 'وضّح المقصود بتغير المحتوى الحراري القياسي ΔH°، وحدّد الظروف القياسية، ثم قارن بينها وبين درجة الحرارة والضغط القياسيين STP.', null, null, null, 'فهم', 'توضيح ومقارنة', 'متوسط', 'الكتاب ص 25 — حرارة الاحتراق والمحتوى الحراري القياسي'),
('essay', 3, 'حرارة الاحتراق القياسية للأوكتان C₈H₁₈(l) هي −5471 kJ/mol. (أ) اكتب المعادلة الكيميائية الحرارية التي تعبّر عن حرارة احتراقه وفق تعريفها، علمًا بأن نواتج الاحتراق الكامل CO₂(g) وH₂O(l). (ب) احسب كمية الحرارة المنطلقة عند حرق 0.500 mol من الأوكتان. (ج) فسّر لماذا يكون معامل الأكسجين في المعادلة كسرًا.', null, null, null, 'تطبيق', 'تطبيق التعريف في معادلة وحساب', 'صعب', 'الكتاب ص 25، 26، 30 — الجدول 1-3، تفاعلات الاحتراق')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L3-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'حرارة الاحتراق هي المحتوى الحراري الناتج عن حرق 1 mol من المادة احتراقًا كاملًا، ويرمز لها بالرمز ΔHcomb.', '["هذا تعريف حرارة التبخر المولارية ΔHvap لا حرارة الاحتراق.","التعريف يُبنى على 1 mol من المادة لا على 1 g منها.","","الاحتراق طارد للحرارة، والتعريف يُبنى على 1 mol من المادة المحترقة لا من الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.375Z"}'::jsonb),
('mcq', 2, 0, 'حرارة الاحتراق هي المحتوى الحراري الناتج عن حرق 1 mol من المادة احتراقًا كاملًا، والحرارة هنا منطلقة فالتفاعل طارد وإشارة ΔH سالبة؛ لذا ΔHcomb للجلوكوز = −2808 kJ/mol.', '["","الحرارة منطلقة (الاحتراق طارد)، فإشارة ΔHcomb سالبة لا موجبة.","حرارة الاحتراق تُنسب إلى 1 mol من المادة، فوحدتها kJ/mol لا kJ/g.","قُسمت 2808 kJ على الكتلة المولية للجلوكوز (180.18 g/mol)، والكمية المحروقة 1 mol كاملة لا 1 g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.375Z"}'::jsonb),
('mcq', 3, 3, 'يستعمل الرمز ΔH° ليدل على تغير المحتوى الحراري القياسي؛ فالرمز ° يبيّن أن تغيرات المحتوى الحراري قد حُددت للمواد المتفاعلة والناتجة جميعها عند الظروف القياسية (1 atm و25 °C).', '["وحدة ΔH هي kJ، والرمز ° لا يدل على وحدة درجة الحرارة.","الظروف القياسية للمحتوى الحراري (1 atm و25 °C) تختلف عن STP (1 atm و0 °C).","الرمز ° يدل على الظروف لا على نوع التفاعل؛ فقد يكون ΔH° موجبًا أو سالبًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-07T17:19:00.375Z"}'::jsonb),
('mcq', 4, 1, 'الاحتراق تفاعل مادة مع الأكسجين يطلق طاقة على شكل حرارة وضوء، أي أنه طارد للحرارة؛ لذا تكون إشارة ΔH°comb سالبة.', '["لو امتص الاحتراق الحرارة لكانت ΔH موجبة، والاحتراق طارد لا ماص.","","ليست طاقة المواد صفرًا في الظروف القياسية، والإشارة سببها انطلاق الحرارة.","نواتج الاحتراق ليست غازات دائمًا (فالماء قد يكون سائلًا)، والإشارة لا تتعلق بحالة النواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.375Z"}'::jsonb),
('mcq', 5, 2, 'حرارة احتراق البروبان −2219 kJ/mol، أي يُطلق 2219 kJ لكل 1 mol؛ فالحرارة المنطلقة = 2.00 mol × 2219 kJ/mol = 4438 kJ = 4.44×10³ kJ.', '["هذه الحرارة الناتجة عن 1 mol فقط؛ لم تُضرب في عدد المولات.","قُسمت ΔHcomb على عدد المولات بدلًا من ضربها فيه.","","استُعملت قيمة الميثان (−891 kJ/mol) بدلًا من البروبان: 2.00 × 891 = 1782 kJ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.375Z"}'::jsonb),
('mcq', 6, 0, 'حرارة الاحتراق تخص حرق 1 mol من المادة احتراقًا كاملًا، فمعامل CH₄ يكون 1، والاحتراق طارد فإشارة ΔH سالبة: CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)   ΔH = −891 kJ.', '["","المعادلة لحرق 2 mol من الميثان، فتكون الحرارة المنطلقة ضعف القيمة، والتعريف يُبنى على 1 mol.","الاحتراق طارد للحرارة فإشارة ΔH سالبة لا موجبة.","هذه معادلة التفاعل العكسي لا الاحتراق، وهي ماصة للحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.376Z"}'::jsonb),
('mcq', 7, 3, 'الطالب خلط بين الظروف القياسية للمحتوى الحراري (1 atm و25 °C) ودرجة الحرارة والضغط القياسيين STP (0 °C و1 atm)؛ فعبارته خاطئة لأن الظروف القياسية هي 1 atm و25 °C وليست STP.', '["الظروف القياسية للمحتوى الحراري تختلف عن STP، ويجب عدم الخلط بينهما.","العبارة خاطئة فعلًا، لكن درجة الحرارة القياسية 25 °C لا 100 °C.","الرمز ° يدل على الظروف القياسية (1 atm و25 °C)، لا على درجة الصفر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.376Z"}'::jsonb),
('essay', 1, null::int, null, null, 'حرارة الاحتراق: المحتوى الحراري الناتج عن حرق 1 mol من المادة احتراقًا كاملًا. رمزها ΔHcomb ووحدتها kJ/mol. مثال: عند حرق 1 mol من الجلوكوز C₆H₁₂O₆ احتراقًا كاملًا يُطلق 2808 kJ من الحرارة، فتكون ΔHcomb = −2808 kJ/mol، والإشارة السالبة لأن الاحتراق طارد للحرارة.', '["تعريف حرارة الاحتراق: حرق 1 mol احتراقًا كاملًا","الرمز ΔHcomb","الوحدة kJ/mol","مثال الجلوكوز: 1 mol يطلق 2808 kJ"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف كاملًا","marks":2},{"element":"الرمز والوحدة","marks":1},{"element":"توضيح المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل بشرطي 1 mol والاحتراق الكامل، مع الرمز والوحدة ومثال صحيح"},{"level":"2–3 درجات","description":"تعريف ناقص أحد الشرطين، أو تعريف صحيح دون الرمز أو المثال"},{"level":"1 درجة","description":"ذكر الرمز أو المثال دون تعريف صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال شرط «1 mol»","إغفال كلمة «كاملًا»","القول إن الجلوكوز يمتص 2808 kJ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.376Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ΔH° هو تغير المحتوى الحراري القياسي، والرمز ° يبيّن أن تغيرات المحتوى الحراري قد حُددت والمواد المتفاعلة والناتجة جميعها في الظروف القياسية. والظروف القياسية هي ضغط جوي 1 atm ودرجة حرارة 25 °C. أما STP فهي 0 °C و1 atm؛ فالضغط واحد في الحالتين، لكن درجة الحرارة مختلفة (25 °C مقابل 0 °C)، لذا يجب عدم الخلط بينهما.', '["ΔH° تغير المحتوى الحراري في الظروف القياسية","الرمز ° يدل على أن جميع المواد في الظروف القياسية","الظروف القياسية 1 atm و25 °C","STP هي 0 °C و1 atm","وجه الاختلاف: درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"توضيح معنى ΔH° والرمز °","marks":2},{"element":"تحديد الظروف القياسية","marks":1},{"element":"تحديد STP","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"توضيح كامل، وظروف قياسية صحيحة، ومقارنة صحيحة مع STP"},{"level":"3–4 درجات","description":"توضيح صحيح وظروف صحيحة مع مقارنة ناقصة"},{"level":"1–2 درجة","description":"ذكر الظروف القياسية فقط أو STP فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الظروف القياسية للمحتوى الحراري هي STP","ذكر 273 K بدلًا من 298 K للظروف القياسية","القول إن ° تعني درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.376Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) C₈H₁₈(l) + (25/2)O₂(g) → 8CO₂(g) + 9H₂O(l)   ΔH°comb = −5471 kJ. (ب) الحرارة المنطلقة = 0.500 mol × 5471 kJ/mol = 2735.5 kJ ≈ 2.74×10³ kJ. (ج) لأن حرارة الاحتراق تُعرَّف لحرق 1 mol من المادة، فيجب أن يكون معامل الأوكتان 1، ويلزم عندئذٍ 25 ذرة أكسجين (16 في 8CO₂ و9 في 9H₂O)، أي 25/2 mol من O₂.', '["معادلة موزونة بمعامل 1 للأوكتان و25/2 للأكسجين","الحالات الفيزيائية وΔH° = −5471 kJ","الحرارة المنطلقة 2.74×10³ kJ","التفسير بأن التعريف لـ 1 mol من المادة"]'::jsonb, '["وزن C: 8CO₂، ووزن H: 9H₂O","ذرات O في النواتج: 8 × 2 + 9 = 25 → (25/2)O₂","q = 0.500 mol × 5471 kJ/mol = 2.74×10³ kJ"]'::jsonb, '[{"element":"المعادلة الموزونة","marks":2},{"element":"الحالات وقيمة ΔH°","marks":1},{"element":"حساب الحرارة المنطلقة","marks":1},{"element":"تفسير المعامل الكسري","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة صحيحة كاملة، وحساب صحيح بالأرقام المعنوية، وتفسير صحيح"},{"level":"3–4 درجات","description":"معادلة صحيحة وحساب صحيح دون تفسير، أو خطأ في الوزن مع حساب وتفسير صحيحين"},{"level":"1–2 درجة","description":"جزء واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مضاعفة المعاملات إلى 2C₈H₁₈ مع إبقاء ΔH = −5471 kJ","كتابة 25O₂ بدلًا من 25/2","إعطاء الحرارة المنطلقة إشارة موجبة لـ ΔH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.376Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
