('mcq', 5, 'امتصت عينة من الماء السائل عند 100°C كمية من الحرارة مقدارها 122 kJ فتبخرت كلها. ما كتلة العينة؟ (ΔHvap = 40.7 kJ/mol، الكتلة المولية 18.02 g/mol)', null, null, '["366 g","54.0 g","3.00 g","6.01 g"]'::jsonb, 'تطبيق', 'حساب الكتلة من كمية الحرارة', 'متوسط', 'الكتاب ص 43 — تقويم الفصل (س72، س75، س76)'),
('mcq', 6, 'ما كمية الحرارة اللازمة لتبخير 23.0 g من الإيثانول C₂H₅OH عند درجة غليانه؟ (ΔHvap = 38.6 kJ/mol، الكتلة المولية 46.07 g/mol)', null, null, '["19.3 kJ","2.47 kJ","888 kJ","77.3 kJ"]'::jsonb, 'تطبيق', 'حساب حرارة التبخر لمادة غير الماء', 'سهل', 'الكتاب ص 26 — حرارة التبخر والانصهار المولارية (الجدول 1-4)'),
('mcq', 7, 'عينتان: الأولى 30.0 g من حمض الإيثانويك الصلب CH₃COOH تنصهر عند درجة انصهارها، والثانية 30.0 g من حمض الإيثانويك السائل تتبخر عند درجة غليانها. (ΔHfus = 11.7 kJ/mol، ΔHvap = 23.4 kJ/mol، الكتلة المولية 60.05 g/mol). أيّ العبارات الآتية صحيحة؟', null, null, '["تمتص الأولى 11.7 kJ والثانية 23.4 kJ","تمتص الأولى 11.7 kJ والثانية 5.85 kJ","تمتص الأولى 5.85 kJ وتطلق الثانية 11.7 kJ","تمتص الأولى 5.85 kJ والثانية 11.7 kJ"]'::jsonb, 'تحليل', 'مقارنة حسابية بين عمليتين', 'صعب', 'الكتاب ص 26 — حرارة التبخر والانصهار المولارية (الجدول 1-4)'),
('essay', 1, 'احسب كمية الحرارة المنطلقة عند تكثف 450 g من بخار الماء إلى ماء سائل عند 100°C، موضحًا خطوات الحل ومبينًا إشارة ΔH. (ΔHvap = 40.7 kJ/mol، الكتلة المولية للماء 18.02 g/mol)', null, null, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 43 — تقويم الفصل (س72، س75، س76)'),
('essay', 2, 'أطلقت عينة من الإيثانول السائل C₂H₅OH كمية من الحرارة مقدارها 9.88 kJ عندما تجمدت كلها عند درجة انصهارها. احسب كتلة العينة. (ΔHfus للإيثانول = 4.94 kJ/mol، الكتلة المولية 46.07 g/mol)', null, null, null, 'تطبيق', 'مسألة عكسية', 'صعب', 'الكتاب ص 43 — تقويم الفصل (س72، س75، س76)'),
('essay', 3, 'قارن حسابيًّا بين كمية الحرارة اللازمة لصهر 100. g من الجليد عند 0°C وكمية الحرارة اللازمة لتبخير 100. g من الماء عند 100°C، ثم احسب عدد المرات التي تزيد بها إحداهما على الأخرى. (ΔHfus = 6.01 kJ/mol، ΔHvap = 40.7 kJ/mol، الكتلة المولية للماء 18.02 g/mol)', null, null, null, 'تحليل', 'مقارنة حسابية', 'صعب', 'الكتاب ص 26 — حرارة التبخر والانصهار المولارية (الجدول 1-4)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
