('mcq', 4, 1, 'n = 51.0 g ÷ 17.03 g/mol = 2.99 mol، و ΔHcond = −23.3 kJ/mol، فـ q = 2.99 mol × (−23.3 kJ/mol) = −69.8 kJ، أي تنطلق 69.8 kJ.', '["القيمة العددية صحيحة لكن التكثف طارد للحرارة (ΔHcond = −ΔHvap)، فالحرارة تنطلق ولا تُمتص.","","استعمل الطالب حرارة الانصهار 5.66 kJ/mol، والتكثف يقابل التبخر لا الانصهار.","ضرب الطالب الكتلة 51.0 g في 23.3 مباشرة دون تحويلها إلى مولات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.381Z"}'::jsonb),
('mcq', 5, 1, 'n = q ÷ ΔHvap = 122 kJ ÷ 40.7 kJ/mol = 3.00 mol، ثم m = 3.00 mol × 18.02 g/mol = 54.0 g.', '["استعمل الطالب حرارة الانصهار 6.01 kJ/mol بدلًا من حرارة التبخر.","","حسب الطالب عدد المولات (3.00 mol) ثم كتبه على أنه كتلة دون الضرب في الكتلة المولية.","قلب الطالب النسبة فقسم 40.7 على 122 ثم ضرب في الكتلة المولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-07T17:19:00.381Z"}'::jsonb),
('mcq', 6, 0, 'n = 23.0 g ÷ 46.07 g/mol = 0.499 mol، ثم q = 0.499 mol × 38.6 kJ/mol = 19.3 kJ.', '["","استعمل الطالب حرارة انصهار الإيثانول 4.94 kJ/mol بدلًا من حرارة التبخر.","ضرب الطالب الكتلة بالغرام في ΔHvap مباشرة (23.0 × 38.6) دون التحويل إلى مولات.","قسم الطالب ΔHvap على عدد المولات (38.6 ÷ 0.499) بدلًا من الضرب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-07T17:19:00.381Z"}'::jsonb),
('mcq', 7, 3, 'n = 30.0 g ÷ 60.05 g/mol = 0.500 mol. الانصهار: 0.500 × 11.7 = 5.85 kJ تُمتص، والتبخر: 0.500 × 23.4 = 11.7 kJ تُمتص؛ فالعبارة الصحيحة: تمتص الأولى 5.85 kJ والثانية 11.7 kJ.', '["هذه حرارة 1 mol من كل عملية، والعينة 0.500 mol فقط؛ نسي الطالب التحويل من الكتلة إلى المولات.","عكس الطالب القيمتين؛ فحرارة التبخر أكبر من حرارة الانصهار فالثانية تمتص أكثر.","التبخر ماص للحرارة لا طارد لها، فإشارة ΔHvap موجبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.381Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عدد المولات n = 450 g ÷ 18.02 g/mol = 25.0 mol. التكثف عكس التبخر فـ ΔHcond = −40.7 kJ/mol. q = 25.0 mol × (−40.7 kJ/mol) = −1.02×10³ kJ؛ أي تنطلق 1.02×10³ kJ من الحرارة.', '["تحويل الكتلة إلى مولات: 25.0 mol","ΔHcond = −ΔHvap = −40.7 kJ/mol","q = n × ΔHcond = −1.02×10³ kJ","تفسير الإشارة السالبة بانطلاق الحرارة"]'::jsonb, '["n = 450 g ÷ 18.02 g/mol = 25.0 mol","ΔHcond = −ΔHvap = −40.7 kJ/mol","q = 25.0 mol × (−40.7 kJ/mol) = −1.02×10³ kJ","الإشارة السالبة: تنطلق 1.02×10³ kJ"]'::jsonb, '[{"element":"تحويل الكتلة إلى مولات","marks":1},{"element":"تحديد ΔHcond بإشارتها","marks":1},{"element":"الحساب الصحيح بالوحدة والأرقام المعنوية","marks":1},{"element":"تفسير الإشارة","marks":1}]'::jsonb, '[{"level":"4","description":"حل كامل بخطوات صحيحة وإشارة ووحدة صحيحتين"},{"level":"3","description":"حل صحيح مع خطأ في الإشارة أو الأرقام المعنوية"},{"level":"2","description":"تحويل صحيح إلى مولات مع استعمال ΔH خاطئة"},{"level":"1","description":"خطوة صحيحة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة مباشرة في ΔHvap","استعمال ΔHfus بدلًا من ΔHvap","كتابة الإشارة موجبة للتكثف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-07T17:19:00.381Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التجمد عكس الانصهار فـ ΔHsolid = −4.94 kJ/mol، والحرارة المنطلقة 9.88 kJ (q = −9.88 kJ). n = q ÷ ΔHsolid = (−9.88 kJ) ÷ (−4.94 kJ/mol) = 2.00 mol. m = 2.00 mol × 46.07 g/mol = 92.1 g.', '["ΔHsolid = −ΔHfus = −4.94 kJ/mol","n = 2.00 mol","m = 92.1 g"]'::jsonb, '["ΔHsolid = −ΔHfus = −4.94 kJ/mol","n = (−9.88 kJ) ÷ (−4.94 kJ/mol) = 2.00 mol","m = n × M = 2.00 mol × 46.07 g/mol = 92.1 g"]'::jsonb, '[{"element":"ربط حرارة التجمد بحرارة الانصهار","marks":1},{"element":"حساب عدد المولات","marks":1},{"element":"حساب الكتلة بالوحدة الصحيحة","marks":1}]'::jsonb, '[{"level":"3","description":"حل كامل صحيح بالوحدة"},{"level":"2","description":"حساب المولات صحيح مع خطأ في التحويل إلى كتلة"},{"level":"1","description":"يربط ΔHsolid بـ ΔHfus فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب 9.88 في 4.94 بدلًا من القسمة","التوقف عند عدد المولات دون حساب الكتلة","استعمال حرارة التبخر 38.6 kJ/mol"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.382Z"}'::jsonb),
('essay', 3, null::int, null, null, 'n = 100. g ÷ 18.02 g/mol = 5.55 mol. حرارة الصهر = 5.55 mol × 6.01 kJ/mol = 33.4 kJ. حرارة التبخر = 5.55 mol × 40.7 kJ/mol = 226 kJ. النسبة = 226 ÷ 33.4 = 6.77؛ فتبخير الكتلة نفسها يحتاج إلى حرارة تزيد نحو 6.77 مرة على صهرها (وهي النسبة نفسها 40.7 ÷ 6.01).', '["n = 5.55 mol","حرارة الصهر 33.4 kJ","حرارة التبخر 226 kJ","النسبة نحو 6.77 مرة لصالح التبخر"]'::jsonb, '["n = 100. g ÷ 18.02 g/mol = 5.55 mol","q(fus) = 5.55 × 6.01 = 33.4 kJ","q(vap) = 5.55 × 40.7 = 226 kJ","226 ÷ 33.4 = 6.77"]'::jsonb, '[{"element":"تحويل الكتلة إلى مولات","marks":1},{"element":"حساب حرارة الصهر","marks":1},{"element":"حساب حرارة التبخر","marks":1},{"element":"حساب النسبة والمقارنة","marks":1}]'::jsonb, '[{"level":"4","description":"حسابات صحيحة ومقارنة بالنسبة"},{"level":"3","description":"الحسابان صحيحان دون نسبة صحيحة"},{"level":"2","description":"حساب واحد صحيح"},{"level":"1","description":"تحويل صحيح إلى مولات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال التحويل إلى مولات","عكس النسبة","الخلط بين القيمتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-07T17:19:00.382Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
