('mcq', 1, 'يمثل المنحنى الآتي تسخين عينة من الجليد عند −20 °C بمعدل ثابت حتى تحولت إلى بخار عند 120 °C. ما الذي يحدث للعينة في الجزء (2)؟', null, '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, '["يسخن الجليد وترتفع درجة حرارته","يغلي الماء متحولًا إلى بخار","يتكثف بخار الماء إلى سائل","ينصهر الجليد متحولًا إلى ماء سائل"]'::jsonb, 'فهم', 'تحديد ما يحدث في منطقة', 'سهل', 'الكتاب ص 47 — اختبار مقنن (س9: منحنى تسخين الماء)'),
('mcq', 2, 'في الجزء (4) من منحنى تسخين الماء الآتي (الغليان عند 100 °C)، كيف تتغير طاقة الحركة وطاقة الوضع لجزيئات الماء؟', null, '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, '["تزداد طاقة الحركة وتبقى طاقة الوضع ثابتة","تبقى طاقة الحركة ثابتة وتزداد طاقة الوضع","تزداد طاقة الحركة وطاقة الوضع معًا","تقل طاقة الوضع وتبقى طاقة الحركة ثابتة"]'::jsonb, 'تحليل', 'تحليل تغير الطاقة في منطقة', 'متوسط', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 3, 'يبين الجدول بيانات تسخين 180 g من الماء بمعدل ثابت من −20°C إلى 120°C. في أيّ فترة زمنية يغلي الماء؟', '{"headers":["الزمن (min)","درجة الحرارة (°C)"],"rows":[["0.0","−20"],["1.0","0"],["2.0","0"],["3.0","9"],["6.0","58"],["9.0","92"],["11.0","100"],["18.0","100"],["24.0","100"],["25.0","120"]]}'::jsonb, null, '["من 1.0 min إلى 2.0 min","من 3.0 min إلى 11.0 min","من 11.0 min إلى 24.0 min","من 24.0 min إلى 25.0 min"]'::jsonb, 'تحليل', 'تفسير بيانات جدول', 'متوسط', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 4, 'في منحنى تسخين الماء الآتي بمعدل ثابت، يكون الجزء (4) عند 100 °C أطول كثيرًا من الجزء (2) عند 0 °C. ما سبب ذلك؟', null, '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, '["لأن ΔHvap للماء (40.7 kJ/mol) أكبر كثيرًا من ΔHfus (6.01 kJ/mol)","لأن الحرارة النوعية للبخار أكبر من الحرارة النوعية للجليد","لأن درجة الغليان أعلى من درجة الانصهار","لأن كتلة الماء تزداد في أثناء الغليان"]'::jsonb, 'تحليل', 'تعليل طول الأجزاء الأفقية', 'متوسط', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 5, 'في منحنى تسخين الماء الآتي بمعدل ثابت، يكون ميل الجزء (5) (تسخين بخار الماء) أكبر من ميل الجزء (3) (تسخين الماء السائل). ما تفسير ذلك؟ (C للسائل = 4.184 J/g·°C، C للبخار = 2.01 J/g·°C)', null, '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, '["الحرارة النوعية للبخار أكبر، فيمتص حرارة أكثر في كل دقيقة","البخار يمتص حرارة التبخر في أثناء تسخينه","الحرارة النوعية للبخار أقل، فترتفع درجة حرارته أسرع بالحرارة نفسها","كتلة البخار أقل من كتلة السائل الذي تكوّن منه"]'::jsonb, 'تحليل', 'تفسير ميل المنحنى', 'صعب', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 6, 'ما كمية الحرارة التي تمتصها عينة كتلتها 90.0 g من الماء في الجزء (3) من منحنى التسخين الآتي، حيث ترتفع درجة حرارتها من 0 °C إلى 100 °C؟ (C للماء السائل = 4.184 J/g·°C، C للجليد = 2.03 J/g·°C)', null, '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, '["18.3 kJ","37.7 kJ","0.418 kJ","203 kJ"]'::jsonb, 'تطبيق', 'حساب الحرارة لمنطقة من المنحنى', 'متوسط', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('mcq', 7, 'ينصهر الإيثانول عند −114°C ويغلي عند 78°C. إذا سُخنت عينة من الإيثانول الصلب بمعدل ثابت من −120°C إلى 90°C، فعند أيّ درجتي حرارة يظهر جزءا المنحنى الأفقيان؟', null, null, '["عند −114°C وعند 78°C","عند 0°C وعند 100°C","عند −120°C وعند 90°C","عند −114°C فقط"]'::jsonb, 'تطبيق', 'التنبؤ بشكل منحنى تسخين مادة أخرى', 'سهل', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('essay', 1, 'يمثل المنحنى الآتي تسخين عينة من الجليد عند −20 °C بمعدل ثابت حتى أصبحت بخارًا عند 120 °C. حدّد ماذا يحدث للماء في كل جزء من الأجزاء الخمسة المرقمة، وبيّن أين تُستهلك الحرارة الممتصة: في زيادة طاقة الحركة أم طاقة الوضع.', null, '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, null, 'فهم', 'تفسير أجزاء منحنى', 'سهل', 'الكتاب ص 47 — اختبار مقنن (س9: منحنى تسخين الماء)'),
('essay', 2, 'احسب كمية الحرارة الكلية اللازمة لتحويل 90.0 g من الجليد عند −20.0°C إلى بخار عند 120.0°C، بحساب الحرارة في كل جزء من أجزاء منحنى التسخين الخمسة. (C للجليد = 2.03 J/g·°C، C للماء السائل = 4.184 J/g·°C، C للبخار = 2.01 J/g·°C، ΔHfus = 6.01 kJ/mol، ΔHvap = 40.7 kJ/mol، الكتلة المولية للماء 18.02 g/mol)', null, '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, null, 'تطبيق', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء'),
('essay', 3, 'حلّل منحنى تسخين عينة من الماء بمعدل ثابت، مفسرًا: (أ) لماذا يتناسب طول كل جزء من المنحنى (زمنه) مع كمية الحرارة الممتصة فيه؟ (ب) لماذا يكون الجزء الأفقي عند 100°C أطول الأجزاء جميعًا؟ (ج) لماذا يكون ميل جزء تسخين الجليد وميل جزء تسخين البخار أكبر من ميل جزء تسخين الماء السائل؟ (C للجليد = 2.03، C للسائل = 4.184، C للبخار = 2.01 J/g·°C؛ ΔHfus = 6.01، ΔHvap = 40.7 kJ/mol)', null, '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, null, 'تحليل', 'تحليل منحنى', 'صعب', 'الكتاب ص 28 — مختبر حل المشكلات: منحنى التسخين للماء')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
