from (values
('mcq', 1, 0, 'تفاعل الاحتراق تفاعل كيميائي يحدث عند تفاعل مادة مع الأكسجين، مطلقًا طاقة على شكل حرارة وضوء.', '["","هذا وصف لتفاعل تفكك ماص للحرارة، والاحتراق تفاعل مع الأكسجين يطلق الطاقة.","هذا وصف للتبخر، وهو تغير حالة فيزيائي لا تفاعل كيميائي.","الاحتراق يشترط التفاعل مع الأكسجين لا مع الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('mcq', 2, 2, 'يعرّف الاحتراق بأنه تفاعل الوقود مع الأكسجين؛ فالأكسجين متفاعل أساسي في كل تفاعل احتراق.', '["ثاني أكسيد الكربون من نواتج احتراق الوقود الكربوني، لا من المتفاعلات.","الهيدروجين أحد أنواع الوقود، لكن الاحتراق لا يشترطه؛ فالميثان والأوكتان يحترقان أيضًا.","","الماء من نواتج احتراق الهيدروكربونات والهيدروجين، لا من المتفاعلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('mcq', 3, 1, 'يتفاعل الهيدروجين والأكسجين معًا لتوفير الطاقة اللازمة لرفع مكوك الفضاء إلى ارتفاعات شاهقة: H₂(g) + ½O₂(g) → H₂O(l) + 286 kJ.', '["احتراق الميثان يستعمل في طهو الطعام وتدفئة المنازل، لا في رفع مكوك الفضاء.","","احتراق الجلوكوز مصدر الطاقة في جسم الإنسان، لا وقود مكوك الفضاء.","احتراق الأوكتان (الجازولين) يشغّل معظم المركبات كالسيارات والطائرات، لا مكوك الفضاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('mcq', 4, 3, 'يتكون الجازولين غالبًا من الأوكتان C₈H₁₈، واحتراق 1 mol منه ينتج 5471 kJ من الحرارة.', '["الميثان غاز طبيعي يستعمل لطهو الطعام وتدفئة المنازل، وليس المكون الرئيس للجازولين.","البروبان وقود غازي، وليس المكون الغالب للجازولين.","السكروز سكر المائدة، وهو غذاء لا وقود للمركبات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('mcq', 5, 1, 'ينتج عن حرق 1 mol من الميثان 891 kJ من الطاقة الحرارية: CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l) + 891 kJ.', '["هذه الحرارة الناتجة عن احتراق 1 mol من الهيدروجين.","","هذه حرارة احتراق 1 mol من البروبان.","هذه حرارة احتراق 1 mol من الأوكتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('mcq', 6, 3, 'في التفاعل C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(l) يتفاعل الوقود (البروبان) مع الأكسجين منتجًا CO₂ و H₂O ومطلقًا الطاقة، فهو تفاعل احتراق؛ أما البدائل الأخرى فلا يدخل فيها الأكسجين متفاعلًا.', '["هذا تفكك لمادة واحدة دون تفاعل مع الأكسجين، فليس احتراقًا.","هذا تبخر للإيثانول، وهو تغير حالة فيزيائي ماص للحرارة لا يدخل فيه الأكسجين، فليس احتراقًا رغم أن الإيثانول وقود.","هذا ذوبان مركب أيوني وتفكك أيوناته في الماء، ولا يدخل فيه الأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('mcq', 7, 2, 'في الأنظمة الحيوية يُعد الطعام الوقود اللازم للاحتراق؛ فالأغذية التي تحتوي على الكربوهيدرات تتحول إلى جلوكوز يتفاعل مع الأكسجين داخل الجسم فيطلق الطاقة.', '["الأكسجين هو المادة التي يتفاعل معها الوقود، وليس الوقود نفسه.","ثاني أكسيد الكربون من نواتج الاحتراق، لا من المتفاعلات.","","الماء من نواتج الاحتراق ولا يحترق، فليس وقودًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تفاعل الاحتراق تفاعل كيميائي يحدث عند تفاعل مادة مع الأكسجين، مطلقًا طاقة على شكل حرارة وضوء. أمثلة: (1) حرق غاز الميثان CH₄ لطهو الطعام وتدفئة المنازل. (2) احتراق الجازولين المكون غالبًا من الأوكتان C₈H₁₈ لتشغيل معظم المركبات كالسيارات والطائرات والسفن والشاحنات. (3) تفاعل الهيدروجين مع الأكسجين لتوفير الطاقة اللازمة لرفع مكوك الفضاء. (ويقبل أيضًا: احتراق الجلوكوز في الجسم لإمداده بالطاقة.)', '["التعريف: تفاعل مادة مع الأكسجين","انطلاق الطاقة على شكل حرارة وضوء","مثال أول بوقوده وغرضه","مثال ثانٍ بوقوده وغرضه","مثال ثالث بوقوده وغرضه"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف كاملًا","marks":2},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1},{"element":"المثال الثالث","marks":1}]'::jsonb, '[{"level":"5","description":"تعريف كامل وثلاثة أمثلة صحيحة بوقودها وغرضها"},{"level":"4","description":"تعريف ناقص مع ثلاثة أمثلة صحيحة، أو تعريف كامل مع مثالين"},{"level":"2","description":"تعريف كامل دون أمثلة، أو أمثلة دون تعريف"},{"level":"1","description":"مثال واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال ذكر الأكسجين في التعريف","ذكر الوقود دون الغرض من احتراقه","عدّ الانصهار أو التبخر احتراقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('essay', 2, null::int, null, null, 'CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)   ΔHcomb = −891 kJ (أو CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l) + 891 kJ). تعني القيمة أن حرق 1 mol من الميثان احتراقًا كاملًا يطلق 891 kJ من الحرارة، والإشارة السالبة تدل على أن التفاعل طارد للحرارة. يستعمل في المنازل لطهو الطعام وللتدفئة.', '["معادلة موزونة بالحالات الفيزيائية","قيمة ΔH بإشارتها","معنى القيمة: 1 mol يطلق 891 kJ","التفاعل طارد للحرارة","استعمال منزلي: الطهو أو التدفئة"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة موزونة بالحالات","marks":2},{"element":"ΔH بإشارتها الصحيحة","marks":1},{"element":"تفسير معنى القيمة والإشارة","marks":1},{"element":"استعمال منزلي صحيح","marks":1}]'::jsonb, '[{"level":"5","description":"معادلة موزونة بحالاتها وقيمة صحيحة وتفسير واستعمال"},{"level":"4","description":"خطأ في حالة فيزيائية أو نقص في التفسير"},{"level":"3","description":"معادلة موزونة دون حالات مع قيمة صحيحة"},{"level":"1","description":"استعمال صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم موازنة الأكسجين","كتابة ΔH موجبة","إهمال الحالات الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.385Z"}'::jsonb),
('essay', 3, null::int, null, null, 'C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l)   ΔHcomb = −1367 kJ. احتراق الإيثانول ينتج ثاني أكسيد الكربون والماء لاحتوائه على الكربون، أما احتراق الهيدروجين H₂(g) + ½O₂(g) → H₂O(l) + 286 kJ فينتج الماء فقط. والمول الواحد من الإيثانول يطلق حرارة أكبر (1367 kJ) من المول الواحد من الهيدروجين (286 kJ)، لكن الهيدروجين لا ينتج CO₂.', '["معادلة احتراق الإيثانول موزونة بالحالات","ΔHcomb = −1367 kJ","نواتج الإيثانول CO₂ و H₂O","ناتج الهيدروجين H₂O فقط","مقارنة كمية الحرارة لكل مول"]'::jsonb, '["كتابة المتفاعلات: C₂H₅OH و O₂، والنواتج: CO₂ و H₂O","موازنة الكربون: 2CO₂، والهيدروجين: 3H₂O، ثم الأكسجين: 3O₂","إضافة ΔHcomb = −1367 kJ","المقارنة بنواتج احتراق الهيدروجين وحرارته"]'::jsonb, '[{"element":"المعادلة موزونة بالحالات","marks":2},{"element":"ΔH بإشارتها","marks":1},{"element":"مقارنة النواتج","marks":1},{"element":"مقارنة الحرارة لكل مول","marks":1}]'::jsonb, '[{"level":"5","description":"معادلة صحيحة كاملة ومقارنة صحيحة في النواتج والحرارة"},{"level":"4","description":"خطأ في الحالات أو نقص في جانب من المقارنة"},{"level":"3","description":"معادلة صحيحة دون مقارنة"},{"level":"2","description":"مقارنة صحيحة مع معادلة غير موزونة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 7/2 O₂ بدلًا من 3O₂ بنسيان أكسجين الإيثانول","الظن أن الهيدروجين ينتج CO₂","إشارة ΔH موجبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.386Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
