('essay', 2, 'تناول شخص طعامًا يحتوي على 45.0 g من الجلوكوز C₆H₁₂O₆. احسب كمية الطاقة التي يمكن أن تنطلق من أيضه كاملًا في الجسم، ثم بيّن هل تختلف هذه الكمية عن الطاقة المنطلقة عند حرق الكتلة نفسها في مسعر، مع التعليل. (ΔHcomb = −2808 kJ/mol، الكتلة المولية 180.18 g/mol)', null, null, null, 'تطبيق', 'مسألة مع تعليل', 'سهل', 'الكتاب ص 29 — مثال 1-4 (حرارة احتراق الجلوكوز)'),
('essay', 3, 'قارن بين احتراق الجلوكوز في المسعر وأيضه في خلايا الجسم من حيث: المتفاعلات، والنواتج، وكمية الطاقة المنطلقة لكل 1 mol، وعدد خطوات التفاعل، ومصير الطاقة الناتجة. ثم اكتب المعادلة الكيميائية الحرارية المشتركة بينهما.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 30 — تفاعلات الاحتراق (الشكل 1-10)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
