('mcq', 4, 'يتكثف 51.1 g من غاز الأمونيا NH₃ (الكتلة المولية 17.03 g/mol) إلى سائل عند درجة غليانه، علمًا بأن ΔHvap للأمونيا = 23.3 kJ/mol. ما كمية الحرارة المصاحبة لذلك؟', null, null, '["تُمتص 69.9 kJ","تنطلق 1.19×10³ kJ","تنطلق 69.9 kJ","تنطلق 17.0 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 29 — مسائل تدريبية (24)، وص 26 جدول حرارة التبخر والانصهار'),
('mcq', 5, 'يحترق 10.0 g من غاز الهيدروجين H₂ (الكتلة المولية 2.016 g/mol) وفق المعادلة: H₂(g) + ½O₂(g) → H₂O(l)، ΔHcomb = −286 kJ/mol. ما كمية الحرارة المنطلقة؟', null, null, '["2.86×10³ kJ","1.42×10³ kJ","57.7 kJ","14.2 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 30 — تقويم 1-3 (29)'),
('mcq', 6, 'لديك كتلة معلومة من مادة تحترق، وقيمة ΔHcomb لها بوحدة kJ/mol. ما الخطوة الأولى لحساب كمية الحرارة المنطلقة؟', null, null, '["ضرب الكتلة مباشرة في قيمة ΔHcomb","ضرب الكتلة في الكتلة المولية لإيجاد عدد المولات","قسمة قيمة ΔHcomb على كتلة المادة","قسمة الكتلة على الكتلة المولية لإيجاد عدد المولات"]'::jsonb, 'فهم', 'خطوات الحل', 'سهل', 'الكتاب ص 29 — مثال 1-4: الحرارة المنطلقة من تفاعل'),
('mcq', 7, 'يُحرق 10.0 g من الهيدروجين H₂ (2.016 g/mol؛ ΔHcomb = −286 kJ/mol) و10.0 g من الميثان CH₄ (16.04 g/mol؛ ΔHcomb = −891 kJ/mol) كلٌّ على حدة. أيّ العبارات الآتية صحيحة؟', null, null, '["الهيدروجين يطلق حرارة أكبر بنحو 2.6 مرة","الميثان يطلق حرارة أكبر بنحو 3.1 مرات","تنطلق من المادتين كمية الحرارة نفسها","الهيدروجين يطلق حرارة أكبر بنحو 8.0 مرات"]'::jsonb, 'تحليل', 'مقارنة حسابية', 'صعب', 'الكتاب ص 26 — جدول حرارة الاحتراق القياسية'),
('essay', 1, 'تُستعمل عينة من الفحم كتلتها 2.00 kg في التدفئة، ونسبة الكربون فيها 90.0% بالكتلة، والمواد الأخرى فيها لا تتفاعل. احسب كمية الحرارة المنطلقة عند احتراق الكربون الموجود فيها احتراقًا كاملًا، علمًا بأن ΔHcomb للكربون = −394 kJ/mol، والكتلة المولية للكربون 12.01 g/mol.', null, null, null, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'متوسط', 'الكتاب ص 43 — مسألة 74 (التدفئة باستعمال الفحم)'),
('essay', 2, 'تحتاج إلى 1.00×10³ kJ من الطاقة. احسب كتلة الجلوكوز C₆H₁₂O₆ (الكتلة المولية 180.16 g/mol) التي يلزم حرقها لإطلاق هذه الكمية، علمًا بأن ΔHcomb للجلوكوز = −2808 kJ/mol، ووضح خطوات الحل.', null, null, null, 'تطبيق', 'مسألة حسابية عكسية', 'متوسط', 'الكتاب ص 29 — مثال 1-4 ومسألة 25'),
('essay', 3, 'قارن بين الميثان CH₄ (16.04 g/mol؛ ΔHcomb = −891 kJ/mol) والبروبان C₃H₈ (44.09 g/mol؛ ΔHcomb = −2219 kJ/mol) من حيث الحرارة المنطلقة من احتراق 1 g من كل منهما. أيهما يطلق حرارة أكبر لكل مول، وأيهما يطلق حرارة أكبر لكل جرام؟ فسّر الفرق.', null, null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 26 — جدول حرارة الاحتراق القياسية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'عدد المولات = 90.0 g ÷ 180.16 g/mol = 0.500 mol، والحرارة المنطلقة = 0.500 mol × 2808 kJ/mol = 1.40×10³ kJ.', '["ناتج ضرب الكتلة بالجرامات مباشرة في ΔHcomb دون تحويلها إلى مولات.","","هذه حرارة احتراق 1 mol فقط؛ والعينة 0.500 mol وليست مولًا واحدًا.","نتج من قلب النسبة (الكتلة المولية ÷ الكتلة) بدل (الكتلة ÷ الكتلة المولية)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-07T17:19:00.388Z"}'::jsonb),
('mcq', 2, 3, 'عدد مولات CH₄ = 32.0 g ÷ 16.04 g/mol = 1.995 mol، والحرارة المنطلقة = 1.995 mol × 891 kJ/mol = 1.78×10³ kJ.', '["ناتج ضرب الكتلة 32.0 g في ΔHcomb دون التحويل إلى مولات.","نتج من قلب النسبة: الحرارة × (الكتلة المولية ÷ الكتلة).","هذه حرارة احتراق 1 mol فقط، والعينة نحو 2.00 mol من الميثان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.388Z"}'::jsonb),
('mcq', 3, 0, 'عدد المولات = 5000 kJ ÷ 2219 kJ/mol = 2.253 mol، والكتلة = 2.253 mol × 44.09 g/mol = 99.4 g.', '["","هذا عدد المولات 2.25 mol كُتب بوحدة الجرام دون ضربه في الكتلة المولية.","نتج من قلب النسبة: (2219 ÷ 5000) × 44.09 بدل (5000 ÷ 2219) × 44.09.","نتج من قسمة عدد المولات على الكتلة المولية بدل ضربه فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.388Z"}'::jsonb),
('mcq', 4, 2, 'عدد المولات = 51.1 g ÷ 17.03 g/mol = 3.00 mol، وΔHcond = −23.3 kJ/mol، فالحرارة المنطلقة = 3.00 mol × 23.3 kJ/mol = 69.9 kJ.', '["القيمة صحيحة لكن التكثف عملية طاردة للحرارة؛ فـ ΔHcond = −ΔHvap، أي أن الحرارة تنطلق ولا تُمتص.","ناتج ضرب الكتلة 51.1 g في 23.3 kJ/mol دون التحويل إلى مولات.","","استُعملت حرارة الانصهار المولارية 5.66 kJ/mol بدل حرارة التبخر؛ والتكثف عكس التبخر لا عكس الانصهار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-07T17:19:00.388Z"}'::jsonb),
('mcq', 5, 1, 'عدد مولات H₂ = 10.0 g ÷ 2.016 g/mol = 4.96 mol، والحرارة المنطلقة = 4.96 mol × 286 kJ/mol = 1.42×10³ kJ.', '["ناتج ضرب الكتلة 10.0 g في 286 kJ/mol دون التحويل إلى مولات.","","نتج من ضرب ΔHcomb في الكتلة المولية ثم القسمة على الكتلة (قلب النسبة).","نتج من قسمة 286 على الكتلة المولية ثم على الكتلة، أي قسمة بدل ضرب في عدد المولات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-07T17:19:00.388Z"}'::jsonb),
('mcq', 6, 3, 'لأن ΔHcomb مقدرة لكل مول، يجب أولًا تحويل الجرامات إلى مولات بقسمة الكتلة على الكتلة المولية (الضرب في مقلوبها)، ثم ضرب عدد المولات في ΔHcomb.', '["وحدة ΔHcomb هي kJ/mol، فلا بد أولًا من تحويل الكتلة إلى مولات؛ والضرب المباشر يعطي وحدة غير صحيحة.","ضرب الكتلة في الكتلة المولية لا يعطي عدد المولات؛ عدد المولات = الكتلة ÷ الكتلة المولية.","قسمة ΔHcomb على الكتلة لا تعطي كمية الحرارة، بل كمية لا معنى لها في هذه المسألة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.388Z"}'::jsonb),
('mcq', 7, 0, 'حرارة الهيدروجين = (10.0 ÷ 2.016) × 286 = 1.42×10³ kJ، وحرارة الميثان = (10.0 ÷ 16.04) × 891 = 555 kJ، والنسبة 1419 ÷ 555 = 2.6، فالهيدروجين يطلق حرارة أكبر بنحو 2.6 مرة.', '["","هذه نسبة ΔHcomb لكل مول (891 ÷ 286)؛ والكتلتان متساويتان لا عدد المولات، ومولات H₂ أكثر بكثير.","تساوي الكتلتين لا يعني تساوي الحرارة؛ فعدد المولات وقيمة ΔHcomb مختلفان.","هذه نسبة الكتلتين المولاريتين (16.04 ÷ 2.016) وحدها، دون مراعاة اختلاف ΔHcomb."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.389Z"}'::jsonb),
('essay', 1, null::int, null, null, 'كتلة الكربون = 2.00 kg × 0.900 = 1.80 kg = 1.80×10³ g؛ عدد مولاته = 1.80×10³ g ÷ 12.01 g/mol = 149.9 mol؛ الحرارة المنطلقة = 149.9 mol × 394 kJ/mol = 5.91×10⁴ kJ (أي ΔH = −5.91×10⁴ kJ).', '["إيجاد كتلة الكربون من النسبة المئوية وتحويلها إلى جرامات","تحويل كتلة الكربون إلى مولات","ضرب عدد المولات في ΔHcomb","كتابة الناتج بالوحدة والأرقام المعنوية الصحيحة مع بيان أن الحرارة منطلقة"]'::jsonb, '["كتلة الكربون = 2.00 kg × 0.900 = 1.80 kg = 1.80×10³ g","n(C) = 1.80×10³ g × (1 mol ÷ 12.01 g) = 149.9 mol","q = 149.9 mol × 394 kJ/mol = 5.91×10⁴ kJ","الحرارة منطلقة لأن ΔHcomb سالبة"]'::jsonb, '[{"element":"كتلة الكربون 1.80×10³ g","marks":1},{"element":"عدد المولات 149.9 mol","marks":1},{"element":"الحرارة 5.91×10⁴ kJ","marks":1},{"element":"الوحدة وبيان أنها منطلقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل صحيح بالخطوات والوحدات والأرقام المعنوية."},{"level":"2–3 درجات","description":"طريقة صحيحة مع خطأ في التحويل أو إهمال النسبة المئوية أو الوحدة."},{"level":"1 درجة","description":"تحويل الكتلة إلى مولات فقط أو كتابة العلاقة دون تطبيق صحيح."},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة كليًا."}]'::jsonb, '["إهمال النسبة المئوية واستعمال 2.00 kg كاملة (6.56×10⁴ kJ)","نسيان تحويل kg إلى g","ضرب الكتلة مباشرة في ΔHcomb"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.389Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عدد مولات الجلوكوز = 1.00×10³ kJ ÷ 2808 kJ/mol = 0.356 mol؛ الكتلة = 0.356 mol × 180.16 g/mol = 64.2 g.', '["قسمة الحرارة المطلوبة على قيمة ΔHcomb (بالقيمة المطلقة) لإيجاد عدد المولات","ضرب عدد المولات في الكتلة المولية","كتابة الناتج 64.2 g بأرقام معنوية صحيحة"]'::jsonb, '["n = 1.00×10³ kJ × (1 mol ÷ 2808 kJ) = 0.356 mol","m = 0.356 mol × 180.16 g/mol = 64.2 g"]'::jsonb, '[{"element":"حساب عدد المولات 0.356 mol","marks":1},{"element":"حساب الكتلة 64.2 g","marks":1},{"element":"الوحدات والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حل صحيح كامل بالوحدات."},{"level":"2 درجتان","description":"عدد مولات صحيح مع خطأ في التحويل إلى الكتلة أو في الوحدة."},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة فقط."},{"level":"صفر","description":"لا إجابة أو حل خاطئ."}]'::jsonb, '["قلب النسبة: 2808 ÷ 1000 ثم الضرب في الكتلة المولية (506 g)","التوقف عند عدد المولات وكتابته بالجرام","إبقاء الإشارة السالبة فتكون الكتلة سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.389Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لكل مول: البروبان أكبر (2219 kJ مقابل 891 kJ). لكل جرام: الميثان = 891 ÷ 16.04 = 55.5 kJ/g، والبروبان = 2219 ÷ 44.09 = 50.3 kJ/g، فالميثان يطلق حرارة أكبر لكل جرام. والسبب أن الكتلة المولية للبروبان أكبر بنحو 2.75 مرة، بينما حرارة احتراقه لكل مول أكبر بنحو 2.5 مرة فقط، فيحتوي الجرام الواحد من الميثان على مولات أكثر تعوض صغر ΔHcomb له.', '["تحديد أن البروبان أكبر لكل مول","حساب الحرارة لكل جرام للميثان 55.5 kJ/g","حساب الحرارة لكل جرام للبروبان 50.3 kJ/g","استنتاج أن الميثان أكبر لكل جرام","التفسير بعدد المولات في الجرام الواحد (الكتلة المولية)"]'::jsonb, '["حرارة 1 g ميثان = (1 ÷ 16.04) mol × 891 kJ/mol = 55.5 kJ","حرارة 1 g بروبان = (1 ÷ 44.09) mol × 2219 kJ/mol = 50.3 kJ","المقارنة: 55.5 kJ/g > 50.3 kJ/g"]'::jsonb, '[{"element":"المقارنة لكل مول","marks":1},{"element":"حساب الميثان لكل جرام","marks":1},{"element":"حساب البروبان لكل جرام","marks":1},{"element":"الاستنتاج لكل جرام","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان ومقارنتان صحيحتان وتفسير سليم."},{"level":"3–4 درجات","description":"حسابان صحيحان مع نقص في التفسير أو في إحدى المقارنتين."},{"level":"1–2 درجة","description":"مقارنة لكل مول فقط أو حساب واحد صحيح."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة كليًا."}]'::jsonb, '["الحكم بأن البروبان أكبر لكل جرام لأن ΔHcomb له أكبر لكل مول","قسمة الكتلة المولية على ΔHcomb بدل العكس","إهمال الوحدة kJ/g"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.390Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
