from (values
('mcq', 1, 'أيّ العبارات الآتية تعبّر عن قانون هس؟', null, null, '["حرارة التفاعل تتوقف على عدد الخطوات التي يتم فيها التفاعل، لا على طبيعة المواد المتفاعلة","الطاقة لا تفنى ولا تُستحدث، ولكن يمكن تحويلها من شكل إلى آخر في التفاعلات الكيميائية","حرارة التفاعل تتوقف على طبيعة المواد المتفاعلة والناتجة، لا على المسار الذي يتم فيه التفاعل","حرارة التفاعل تساوي دائمًا كمية الحرارة اللازمة لرفع درجة حرارة 1 g من الماء 1°C"]'::jsonb, 'تذكر', 'تذكر نص قانون', 'سهل', 'الكتاب ص 31 — قانون هس'),
('mcq', 2, 'وفق قانون هس، على أيّ مما يأتي تتوقف قيمة ΔH لتفاعل ما؟', null, null, '["طبيعة المواد المتفاعلة والمواد الناتجة","عدد الخطوات التي يمر بها التفاعل","سرعة حدوث التفاعل في المختبر","الأداة المستعملة في قياس الحرارة"]'::jsonb, 'تذكر', 'تذكر مضمون القانون', 'سهل', 'الكتاب ص 31 — قانون هس'),
('mcq', 3, 'يتحول الكربون من صورة الجرافيت إلى صورة الألماس تحولًا بطيئًا جدًا: C(s, جرافيت) → C(s, ألماس). لماذا يُلجأ إلى قانون هس لإيجاد ΔH لهذا التحول؟', null, null, '["لأن التحول يطلق كمية كبيرة جدًا من الحرارة تتلف المسعر","لأن الجرافيت والألماس عنصران مختلفان كيميائيًّا","لأن ΔH لهذا التحول تساوي صفرًا دائمًا","لأن بطء التحول الشديد يجعل قياس ΔH له عمليًّا مستحيلًا"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 31 — قانون هس'),
('mcq', 4, 'لماذا لا تُقاس ΔH لتفاعل 2S(s) + 3O₂(g) → 2SO₃(g) مباشرة في المختبر، ويُستعمل قانون هس بدلًا من ذلك؟', null, null, '["لأن الكبريت لا يتفاعل مع الأكسجين إطلاقًا","لأن التفاعل ينتج مخلوطًا من النواتج معظمه SO₂","لأن SO₃ مادة صلبة لا يمكن تسخينها","لأن ΔH لهذا التفاعل موجبة وكبيرة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 31 — قانون هس'),
('mcq', 5, 'يتحول المركب A إلى المركب C مباشرة بتغير في المحتوى الحراري ΔH، أو على خطوتين: A → B بتغير ΔH₁، ثم B → C بتغير ΔH₂. وفق قانون هس، ما العلاقة الصحيحة؟', null, null, '["ΔH = ΔH₁ − ΔH₂","ΔH = ΔH₁ × ΔH₂","ΔH = ΔH₁ + ΔH₂","ΔH = 2(ΔH₁ + ΔH₂)"]'::jsonb, 'فهم', 'تطبيق مفهوم القانون', 'متوسط', 'الكتاب ص 32 — تطبيق قانون هس (تكوين SO₃)'),
('mcq', 6, 'أيّ مما يأتي يمكن تحقيقه باستعمال قانون هس؟', null, null, '["حساب ΔH لتفاعل بجمع معادلتين حراريتين أو أكثر مع تغيرات المحتوى الحراري لها","حساب سرعة التفاعل الكيميائي بجمع سرعات تفاعلات أبسط منه","تحويل التفاعل الطارد للحرارة إلى تفاعل ماص للحرارة في الظروف نفسها","قياس الحرارة النوعية للمادة بالمسعر دون معرفة كتلتها"]'::jsonb, 'تذكر', 'تذكر استعمال القانون', 'سهل', 'الكتاب ص 41 — دليل مراجعة الفصل (1-4)'),
('mcq', 7, 'يُحضَّر غاز CO₂ من الكربون والأكسجين بطريقتين: الأولى حرق الكربون مباشرة إلى CO₂، والثانية حرقه أولًا إلى CO ثم حرق CO إلى CO₂. ما العلاقة بين كميتي الحرارة المنطلقتين في الطريقتين عند إنتاج الكمية نفسها من CO₂؟', null, null, '["الطريقة الثانية تطلق حرارة أكبر؛ لأنها تتم على خطوتين","الطريقة الأولى تطلق حرارة أكبر؛ لأنها أسرع وأكثر مباشرة","لا يمكن المقارنة إلا بقياس الطريقتين بالمسعر","متساويتان؛ لأن المواد الابتدائية والنهائية واحدة في الطريقتين"]'::jsonb, 'فهم', 'تفسير ظاهرة بالقانون', 'صعب', 'الكتاب ص 31 — قانون هس'),
('essay', 1, 'عرّف قانون هس، واذكر سببين يدفعان الكيميائيين إلى استعماله بدلًا من قياس ΔH للتفاعل مباشرة، مع مثال لكل سبب.', null, null, null, 'تذكر', 'تعريف وتعليل', 'سهل', 'الكتاب ص 31 — قانون هس'),
('essay', 2, 'يتكوّن SO₃ من الكبريت على خطوتين: 2S(s) + 2O₂(g) → 2SO₂(g)، ΔH = −594 kJ، ثم 2SO₂(g) + O₂(g) → 2SO₃(g)، ΔH = −198 kJ. والتفاعل الكلي: 2S(s) + 3O₂(g) → 2SO₃(g)، ΔH = −792 kJ. وضّح كيف تمثل هذه البيانات قانون هس، وماذا تتوقع لقيمة ΔH لو أمكن إجراء التفاعل الكلي في خطوة واحدة؟', null, null, null, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 32 — تطبيق قانون هس (تكوين SO₃)'),
('essay', 3, 'تُعطى المعادلات الحرارية الآتية: C(s) + ½O₂(g) → CO(g)، ΔH = −111 kJ؛ CO(g) + ½O₂(g) → CO₂(g)، ΔH = −283 kJ؛ C(s) + O₂(g) → CO₂(g)، ΔH = −394 kJ. ادّعى طالب أن تحويل الكربون إلى CO₂ على خطوتين عبر CO يطلق حرارة أكبر من حرق الكربون مباشرة؛ لأن هناك تفاعلين يطلق كل منهما حرارة. قوّم ادعاء الطالب مستعينًا بقانون هس والبيانات.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 31–32 — قانون هس وتطبيقه')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'ينص قانون هس على أن حرارة التفاعل أو التغير في المحتوى الحراري تتوقف على طبيعة المواد الداخلة في التفاعل والمواد الناتجة منه، وليس على الخطوات أو المسار الذي يتم فيه التفاعل.', '["هذا عكس القانون؛ فالحرارة لا تتوقف على عدد الخطوات أو المسار.","هذا نص قانون حفظ الطاقة، وليس قانون هس.","","هذا تعريف السُّعر (cal)، ولا علاقة له بقانون هس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.390Z"}'::jsonb),
('mcq', 2, 0, 'ΔH تتوقف على طبيعة المواد الداخلة في التفاعل والناتجة منه فقط؛ فإذا تساوت المواد الابتدائية والنهائية تساوت ΔH مهما اختلف المسار.', '["","قانون هس ينص صراحة على أن ΔH لا تتوقف على الخطوات أو المسار.","سرعة التفاعل لا تغير ΔH؛ فتحول الجرافيت إلى ألماس بطيء جدًا ومع ذلك له ΔH محددة.","ΔH خاصية للتفاعل نفسه، ولا تتغير بتغير أداة القياس أو طريقة الحساب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.390Z"}'::jsonb),
('mcq', 3, 3, 'يحدث تحول الجرافيت إلى ألماس ببطء شديد، مما يجعل من المستحيل قياس التغير في محتواه الحراري مباشرة بالمسعر؛ لذا تُحسب ΔH نظريًا بقانون هس من تفاعلات أخرى معروفة.', '["سبب اللجوء إلى قانون هس هو بطء التحول، لا كبر الحرارة المنطلقة.","الجرافيت والألماس صورتان متآصلتان لعنصر واحد هو الكربون، لا عنصران مختلفان.","ΔH لهذا التحول ليست صفرًا؛ فالجرافيت والألماس صورتان مختلفتان في المحتوى الحراري، وتختلف حرارة احتراق كل منهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.390Z"}'::jsonb),
('mcq', 4, 1, 'التجارب المخبرية لإنتاج SO₃ من الكبريت ينتج عنها مخلوط من النواتج معظمه SO₂، فلا يمكن قياس ΔH للتفاعل المطلوب وحده؛ لذا تُحسب بجمع معادلات حرارية معروفة وفق قانون هس.', '["الكبريت يتفاعل مع الأكسجين، لكنه ينتج في الغالب SO₂ بدل SO₃.","","SO₃ في هذا التفاعل غاز، والسبب الحقيقي هو تكوّن مخلوط من النواتج.","ΔH لهذا التفاعل سالبة (−792 kJ)، وليست الإشارة سبب صعوبة القياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.390Z"}'::jsonb),
('mcq', 5, 2, 'لأن ΔH لا تتوقف على المسار، فإن جمع المعادلتين A → B وB → C يعطي A → C، وتكون ΔH للتفاعل المباشر مساوية لمجموع ΔH₁ وΔH₂.', '["المعادلتان تُجمعان كما هما للحصول على A → C، فتُجمع قيمتا ΔH لا تُطرحان.","لا تُضرب قيم ΔH في بعضها؛ بل تُجمع عند جمع المعادلات.","","لا يوجد ما يستدعي الضرب في 2؛ فالمعادلتان تُجمعان مرة واحدة لتعطيا A → C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.391Z"}'::jsonb),
('mcq', 6, 0, 'يمكن حساب التغير في المحتوى الحراري لتفاعل بجمع معادلتين كيميائيتين حراريتين أو أكثر مع تغيرات المحتوى الحراري لها، وهذا هو تطبيق قانون هس.', '["","قانون هس يتعلق بالتغير في المحتوى الحراري لا بسرعة التفاعل.","قانون هس أداة حسابية لإيجاد ΔH، ولا يغير طبيعة التفاعل.","الحرارة النوعية تُحسب من q = c × m × ΔT وتحتاج إلى الكتلة، ولا علاقة لقانون هس بها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.391Z"}'::jsonb),
('mcq', 7, 3, 'وفق قانون هس تتوقف ΔH على طبيعة المواد المتفاعلة (C وO₂) والناتجة (CO₂) فقط، وهي واحدة في الطريقتين، فتتساوى كميتا الحرارة المنطلقتين.', '["زيادة عدد الخطوات لا تزيد الحرارة؛ فـ ΔH لا تتوقف على المسار.","سرعة الطريقة أو كونها مباشرة لا تغير ΔH ما دامت المواد الابتدائية والنهائية واحدة.","قانون هس يتيح المقارنة دون قياس؛ فالحرارتان متساويتان حتمًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.391Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قانون هس: حرارة التفاعل أو التغير في المحتوى الحراري تتوقف على طبيعة المواد الداخلة في التفاعل والمواد الناتجة منه، وليس على الخطوات أو المسار الذي يتم فيه التفاعل. من أسباب استعماله: (1) بعض التفاعلات بطيئة جدًا فيستحيل قياس ΔH لها، مثل تحول الجرافيت إلى ألماس. (2) بعض التفاعلات تعطي نواتج غير مطلوبة أو مخلوطًا من النواتج، مثل تفاعل الكبريت مع الأكسجين الذي ينتج معظمه SO₂ بدل SO₃. وقد يصعب إيجاد الظروف المناسبة لبعض التفاعلات في المختبر.', '["نص قانون هس كاملًا (المواد المتفاعلة والناتجة، لا المسار)","السبب الأول: بطء التفاعل الشديد","مثال: الجرافيت → الألماس","السبب الثاني: تكوّن نواتج غير مطلوبة أو مخلوط","مثال: الكبريت مع الأكسجين ينتج معظمه SO₂"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":2},{"element":"السبب الأول ومثاله","marks":1},{"element":"السبب الثاني ومثاله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف دقيق وسببان صحيحان مع مثالين."},{"level":"2–3 درجات","description":"تعريف صحيح مع سبب واحد، أو سببان مع تعريف ناقص."},{"level":"1 درجة","description":"تعريف ناقص فقط أو سبب واحد دون تعريف."},{"level":"صفر","description":"لا إجابة أو تعريف قانون آخر."}]'::jsonb, '["الخلط بين قانون هس وقانون حفظ الطاقة","القول إن ΔH تتوقف على عدد الخطوات","ذكر أسباب لا علاقة لها بصعوبة القياس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.391Z"}'::jsonb),
('essay', 2, null::int, null, null, 'جمع الخطوتين يلغي 2SO₂ من الطرفين فيعطي التفاعل الكلي، ومجموع قيمتي ΔH (−594 kJ) + (−198 kJ) = −792 kJ يساوي ΔH للتفاعل الكلي. ولو أُجري التفاعل في خطوة واحدة لكانت ΔH = −792 kJ أيضًا؛ لأن المواد المتفاعلة (2S و3O₂) والناتجة (2SO₃) هي نفسها، وΔH وفق قانون هس لا تتوقف على المسار.', '["جمع المعادلتين وحذف SO₂ المشترك","جمع قيمتي ΔH يساوي −792 kJ","توقع ΔH = −792 kJ للخطوة الواحدة","التعليل بعدم اعتماد ΔH على المسار"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن جمع المعادلتين يعطي التفاعل الكلي","marks":1},{"element":"بيان أن مجموع ΔH يساوي ΔH الكلية","marks":1},{"element":"التوقع الصحيح","marks":1},{"element":"التعليل بقانون هس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شرح كامل للجمع والتوقع والتعليل."},{"level":"2–3 درجات","description":"شرح الجمع صحيح مع تعليل ناقص أو توقع دون تعليل."},{"level":"1 درجة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["توقع قيمة مختلفة لأن التفاعل في خطوة واحدة","طرح القيمتين بدل جمعهما","عدم ملاحظة حذف 2SO₂ من الطرفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.391Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الادعاء خاطئ. جمع الخطوتين يلغي CO فيعطي C(s) + O₂(g) → CO₂(g)، ومجموع الحرارة (−111 kJ) + (−283 kJ) = −394 kJ، وهي القيمة نفسها لحرق الكربون مباشرة. فالحرارة الكلية واحدة في المسارين؛ لأن ΔH وفق قانون هس تتوقف على طبيعة المواد المتفاعلة والناتجة فقط لا على عدد الخطوات، وكل خطوة تطلق جزءًا من الحرارة الكلية فقط.', '["الحكم بأن الادعاء خاطئ","جمع المعادلتين وحذف CO","حساب المجموع −394 kJ ومقارنته بالحرق المباشر","التعليل بقانون هس (عدم الاعتماد على المسار)"]'::jsonb, '["(−111 kJ) + (−283 kJ) = −394 kJ","مقارنة: −394 kJ للمسارين"]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"الجمع والحساب","marks":2},{"element":"التعليل بقانون هس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مدعوم بالحساب والتعليل بقانون هس."},{"level":"2–3 درجات","description":"حكم صحيح مع حساب دون تعليل، أو تعليل دون حساب."},{"level":"1 درجة","description":"حكم صحيح دون دعم."},{"level":"صفر","description":"لا إجابة أو تأييد الادعاء."}]'::jsonb, '["تأييد الادعاء لأن عدد الخطوات أكبر","جمع القيم الثلاث كلها","طرح القيمتين بدل جمعهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.391Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
