from (values
('mcq', 1, 'استعمل المعادلتين الحراريتين: (a) S(s) + O₂(g) → SO₂(g)، ΔH = −297 kJ؛ (b) 2SO₃(g) → 2SO₂(g) + O₂(g)، ΔH = +198 kJ. ما قيمة ΔH للتفاعل: S(s) + 3/2O₂(g) → SO₃(g)؟', null, null, '["−495 kJ","−198 kJ","−792 kJ","−396 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 32 — تطبيق قانون هس (تكوين SO₃)'),
('mcq', 2, 'استعمل المعادلتين: (a) C(s, جرافيت) + O₂(g) → CO₂(g)، ΔH = −394 kJ؛ (b) C(s, ألماس) + O₂(g) → CO₂(g)، ΔH = −396 kJ. ما قيمة ΔH للتحول: C(s, جرافيت) → C(s, ألماس)؟', null, null, '["−2 kJ","+2 kJ","−790 kJ","0 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 44 — تقويم الفصل (80، 83، 84)'),
('mcq', 3, 'استعمل المعادلتين: (a) P₄(s) + 6Cl₂(g) → 4PCl₃(l)، ΔH = −1280 kJ؛ (b) P₄(s) + 10Cl₂(g) → 4PCl₅(s)، ΔH = −1774 kJ. ما قيمة ΔH للتفاعل: PCl₃(l) + Cl₂(g) → PCl₅(s)؟', null, null, '["−494 kJ","+123.5 kJ","−123.5 kJ","−763.5 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'صعب', 'الكتاب ص 44 — تقويم الفصل (80، 83، 84)'),
('mcq', 4, 'استعمل المعادلتين: (a) 2H₂(g) + O₂(g) → 2H₂O(l)، ΔH = −572 kJ؛ (b) H₂(g) + O₂(g) → H₂O₂(l)، ΔH = −188 kJ. ما قيمة ΔH للتفاعل: H₂O₂(l) → H₂O(l) + ½O₂(g)؟', null, null, '["−98 kJ","−196 kJ","−384 kJ","−474 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 33 — مثال 1-5: تحلل فوق أكسيد الهيدروجين'),
('mcq', 5, 'يُراد حساب ΔH للتفاعل C₂H₄(g) + H₂(g) → C₂H₆(g) من المعادلات: (a) C₂H₄(g) + 3O₂(g) → 2CO₂(g) + 2H₂O(l)؛ (b) C₂H₆(g) + 7/2O₂(g) → 2CO₂(g) + 3H₂O(l)؛ (c) H₂(g) + ½O₂(g) → H₂O(l). ما الإجراء الصحيح؟', null, null, '["استعمال a وb كما هما، وعكس c","عكس a وc، واستعمال b كما هي","استعمال المعادلات الثلاث كما هي","استعمال a وc كما هما، وعكس b"]'::jsonb, 'تحليل', 'تخطيط الحل', 'سهل', 'الكتاب ص 32 — تطبيق قانون هس (تكوين SO₃)'),
('mcq', 6, 'استعمل المعادلتين: (a) ½N₂(g) + ½O₂(g) → NO(g)، ΔH = +91.3 kJ؛ (b) NO(g) + ½O₂(g) → NO₂(g)، ΔH = −58.1 kJ. ما قيمة ΔH للتفاعل: ½N₂(g) + O₂(g) → NO₂(g)؟', null, null, '["−33.2 kJ","+149.4 kJ","+33.2 kJ","−149.4 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 38 — مسائل تدريبية (37) وتقويم 1-4 (42)'),
('mcq', 7, 'استعمل المعادلتين: (a) 2A + 3/2C₂ → A₂C₃، ΔH = −1874 kJ؛ (b) 2B + 3/2C₂ → B₂C₃، ΔH = −285 kJ. ما قيمة ΔH للتفاعل: 2A + B₂C₃ → 2B + A₂C₃؟', null, null, '["−2159 kJ","−1589 kJ","+1589 kJ","−1304 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 44 — تقويم الفصل (80، 83، 84)'),
('essay', 1, 'استعمل المعادلتين الحراريتين: (a) 2CO(g) + O₂(g) → 2CO₂(g)، ΔH = −566.0 kJ؛ (b) N₂(g) + O₂(g) → 2NO(g)، ΔH = −180.6 kJ، لحساب ΔH للتفاعل: 2CO(g) + 2NO(g) → 2CO₂(g) + N₂(g). وضح كل خطوة.', null, null, null, 'تطبيق', 'مسألة حسابية بالخطوات', 'متوسط', 'الكتاب ص 34 — مسائل تدريبية (32–33)'),
('essay', 2, 'إذا علمت أن: 4Al(s) + 3MnO₂(s) → 2Al₂O₃(s) + 3Mn(s)، ΔH = −1789 kJ، وأن (a) 4Al(s) + 3O₂(g) → 2Al₂O₃(s)، ΔH = −3352 kJ، فاحسب ΔH للتفاعل: (b) Mn(s) + O₂(g) → MnO₂(s).', null, null, null, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'صعب', 'الكتاب ص 34 — مسائل تدريبية (32–33)'),
('essay', 3, 'استعمل قانون هس لإيجاد ΔH للتفاعل: NO(g) + O(g) → NO₂(g)، مستعينًا بالتفاعلات الآتية: O₂(g) → 2O(g)، ΔH = +495 kJ؛ 2O₃(g) → 3O₂(g)، ΔH = −427 kJ؛ NO(g) + O₃(g) → NO₂(g) + O₂(g)، ΔH = −199 kJ.', null, null, null, 'تحليل', 'مسألة حسابية متعددة الخطوات', 'صعب', 'الكتاب ص 38 — مسائل تدريبية (37) وتقويم 1-4 (42)')
