insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L4-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بحرارة التكوين القياسية ΔH°f لمركب؟', null, null, '["التغير في المحتوى الحراري المرافق لتكوين مول واحد من المركب في الظروف القياسية من عناصره في حالاتها القياسية","التغير في المحتوى الحراري المرافق لتفكك مول واحد من المركب إلى عناصره في الظروف القياسية","الحرارة المنطلقة عند احتراق مول واحد من المركب احتراقًا كاملًا في الأكسجين عند 25°C","التغير في المحتوى الحراري المرافق لتكوين جرام واحد من المركب من ذرات عناصره الغازية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 34 — حرارة التكوين القياسية'),
('mcq', 2, 'ما الظروف القياسية المعتمدة عند تحديد حرارة التكوين القياسية؟', null, null, '["ضغط 1 atm ودرجة حرارة 0°C (273 K)","ضغط 2 atm ودرجة حرارة 25°C (298 K)","ضغط 1 atm ودرجة حرارة 25°C (298 K)","ضغط 1 atm ودرجة حرارة 100°C (373 K)"]'::jsonb, 'تذكر', 'تذكر شرط', 'سهل', 'الكتاب ص 34 — حرارة التكوين القياسية'),
('mcq', 3, 'حرارة التكوين القياسية لثالث أكسيد الكبريت SO₃(g) تساوي −396 kJ/mol. ما كمية الحرارة المنطلقة عند تكوين 2 mol من SO₃(g) من عناصره في الظروف القياسية، وما قيمة ΔH°f له؟', null, null, '["تنطلق 396 kJ، وΔH°f = −396 kJ/mol","تنطلق 792 kJ، وΔH°f = −396 kJ/mol","تنطلق 792 kJ، وΔH°f = −792 kJ/mol","تنطلق 198 kJ، وΔH°f = −198 kJ/mol"]'::jsonb, 'فهم', 'تفسير تعريف', 'متوسط', 'الكتاب ص 34 — حرارة التكوين القياسية'),
('mcq', 4, 'للتفاعل CO(g) + ½O₂(g) → CO₂(g) قيمة ΔH = −283 kJ. لماذا لا تُعدّ هذه القيمة حرارة التكوين القياسية لـ CO₂(g)؟', null, null, '["لأن التفاعل ينتج أكثر من مول واحد من CO₂","لأن معامل الأكسجين في المعادلة كسري","لأن التفاعل طارد للحرارة وقيمة ΔH له سالبة","لأن أحد المتفاعلات (CO) مركب وليس عنصرًا"]'::jsonb, 'فهم', 'تطبيق التعريف', 'متوسط', 'الكتاب ص 34 — حرارة التكوين القياسية'),
('mcq', 5, 'حرارة التكوين القياسية لثاني أكسيد النيتروجين NO₂(g) تساوي +33.2 kJ/mol. ماذا تعني هذه القيمة؟', null, null, '["المحتوى الحراري لـ NO₂ أعلى من محتوى عناصره في حالاتها القياسية بمقدار 33.2 kJ","تنطلق 33.2 kJ عند تكوين 1 mol من NO₂ من عناصره في حالاتها القياسية","المحتوى الحراري لـ NO₂ أقل من محتوى عناصره في حالاتها القياسية بمقدار 33.2 kJ","يلزم امتصاص 33.2 kJ لتفكيك 1 mol من NO₂ إلى عناصره في حالاتها القياسية"]'::jsonb, 'فهم', 'تفسير قيمة', 'متوسط', 'الكتاب ص 35 — مصدر حرارة التكوين وجدول حرارة التكوين القياسية'),
('mcq', 6, 'للتفاعل C(s) + O₂(g) → CO₂(g) قيمة ΔH = −394 kJ في الظروف القياسية. ماذا تمثل هذه القيمة؟', null, null, '["حرارة التكوين القياسية لـ CO₂ فقط، ولا تمثل حرارة احتراق","حرارة التكوين القياسية لـ CO₂ وحرارة الاحتراق القياسية للكربون معًا","حرارة الاحتراق القياسية للكربون فقط؛ لأن الأكسجين من المتفاعلات","حرارة التكوين القياسية للكربون؛ لأنه المادة المتفاعلة الأولى"]'::jsonb, 'تحليل', 'تمييز مفاهيم', 'صعب', 'الكتاب ص 34، 37 — حرارة التكوين القياسية، والمثال 1-6'),
('mcq', 7, 'تُكتب معادلة تكوين ثالث أكسيد الكبريت بمعامل كسري للأكسجين: S(s) + 3/2O₂(g) → SO₃(g)، ΔH°f = −396 kJ. ما سبب استعمال المعامل الكسري؟', null, null, '["لأن الأكسجين يوجد في حالته القياسية على شكل ذرات منفردة","لأن المعاملات الكسرية تجعل قيمة ΔH موجبة دائمًا","لأن حرارة التكوين تُعرَّف لتكوين مول واحد من المركب","لأن معادلة 2S + 3O₂ → 2SO₃ لا يمكن موازنتها"]'::jsonb, 'فهم', 'تعليل', 'صعب', 'الكتاب ص 33–34 — المعاملات الكسرية وحرارة التكوين القياسية'),
('essay', 1, 'حرارة التكوين القياسية لثالث أكسيد الكبريت SO₃(g) تساوي −396 kJ/mol، ولثاني أكسيد النيتروجين NO₂(g) تساوي +33.2 kJ/mol. وضّح المقصود بكل قيمة، وحدد موقع كل مركب على تدريج حرارة التكوين الذي يكون فيه صفره للعناصر في حالاتها القياسية.', null, null, null, 'فهم', 'توضيح مفهوم', 'سهل', 'الكتاب ص 35 — مصدر حرارة التكوين وجدول حرارة التكوين القياسية'),
('essay', 2, 'حدد أيّ المعادلات الآتية تمثل تفاعل تكوين قياسي، وعلّل حكمك لكل منها: (a) 2H₂(g) + O₂(g) → 2H₂O(l)؛ (b) H₂(g) + ½O₂(g) → H₂O(l)؛ (c) CO(g) + ½O₂(g) → CO₂(g)؛ (d) S(s) + 3F₂(g) → SF₆(g).', null, null, null, 'تحليل', 'تصنيف وتعليل', 'متوسط', 'الكتاب ص 34 — حرارة التكوين القياسية'),
('essay', 3, 'حرارة التكوين القياسية للماء السائل H₂O(l) تساوي −285.8 kJ/mol، وللماء الغازي H₂O(g) تساوي −241.8 kJ/mol. (1) لماذا تكون حرارة التكوين القياسية لكل من H₂(g) وO₂(g) صفرًا؟ (2) فسّر اختلاف القيمتين للماء، واحسب منهما حرارة تبخر الماء عند 298 K. (3) ما أهمية تحديد الحالة الفيزيائية للماء في المعادلات الحرارية؟', null, null, null, 'تحليل', 'تفسير وحساب', 'صعب', 'الكتاب ص 38 — تقويم 1-4 (43)، وص 35 مصدر حرارة التكوين')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
