select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'تُعرّف حرارة التكوين القياسية ΔH°f بأنها التغير في المحتوى الحراري الذي يرافق تكوين مول واحد من المركب في الظروف القياسية من عناصره في حالاتها القياسية.', '["","هذا وصف للتفاعل العكسي (التفكك)، وحرارته تساوي حرارة التكوين عدديًا وتخالفها في الإشارة.","هذا تعريف حرارة الاحتراق القياسية ΔH°comb، لا حرارة التكوين.","التعريف لمول واحد لا لجرام، ومن العناصر في حالاتها القياسية لا من ذراتها الغازية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.394Z"}'::jsonb),
('mcq', 2, 2, 'الحالة القياسية هي حالة المادة عند ضغط جوي واحد 1 atm ودرجة حرارة 25°C أي 298 K.', '["هذه الظروف المعيارية للغازات STP، وليست الظروف القياسية لحرارة التكوين.","الضغط القياسي 1 atm، لا 2 atm.","","100°C درجة غليان الماء عند 1 atm، وليست درجة الحرارة القياسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.394Z"}'::jsonb),
('mcq', 3, 1, 'حرارة التكوين القياسية تخص تكوين مول واحد من المركب، فتبقى ΔH°f(SO₃) = −396 kJ/mol مهما كانت الكمية، أما الحرارة المنطلقة عند تكوين 2 mol فهي 2 × 396 kJ = 792 kJ؛ فالإجابة: تنطلق 792 kJ، وΔH°f = −396 kJ/mol.', '["الحرارة المنطلقة تتناسب مع كمية المادة؛ فتكوين 2 mol يطلق ضعف حرارة تكوين 1 mol، أي 792 kJ لا 396 kJ.","","ΔH°f تُعرَّف لتكوين مول واحد من المركب، فلا تتغير بتغير الكمية المتكونة؛ وتبقى −396 kJ/mol.","قُسمت القيمة على 2 بدل ضربها؛ فتكوين كمية أكبر يطلق حرارة أكبر، وΔH°f ثابتة لكل مول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.395Z"}'::jsonb),
('mcq', 4, 3, 'حرارة التكوين القياسية تخص تكوين 1 mol من المركب من عناصره في حالاتها القياسية، والتفاعل المعطى يبدأ بالمركب CO لا بالعنصر C(s)، فلا تُعدّ ΔH له حرارة تكوين قياسية لـ CO₂.', '["التفاعل ينتج 1 mol فقط من CO₂، فليس هذا سبب عدم عدّها حرارة تكوين.","المعاملات الكسرية مقبولة في معادلات التكوين، مثل S(s) + 3/2O₂(g) → SO₃(g).","حرارة التكوين قد تكون سالبة كما في SO₃(g) (−396 kJ/mol)، فالإشارة ليست السبب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.395Z"}'::jsonb),
('mcq', 5, 0, 'عند تكوين 1 mol من NO₂ من N₂ وO₂ يُمتص 33.2 kJ، أي أن المحتوى الحراري للناتج NO₂ أعلى من المحتوى الحراري لعناصره (التي تساوي صفرًا) بمقدار 33.2 kJ.', '["","الإشارة الموجبة تعني أن التكوين ماص للحرارة، فالطاقة تُمتص ولا تنطلق.","المركب ذو ΔH°f الموجبة يقع فوق الصفر على التدريج، أي أن محتواه الحراري أعلى لا أقل.","تفكك NO₂ عكس تكوينه، فإشارته سالبة؛ أي تنطلق 33.2 kJ ولا تُمتص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.395Z"}'::jsonb),
('mcq', 6, 1, 'يكوّن التفاعل 1 mol من المركب CO₂ من عنصريه C(s) وO₂(g) في حالتيهما القياسيتين، فقيمة ΔH له هي ΔH°f(CO₂) = −394 kJ/mol؛ وهو في الوقت نفسه حرق 1 mol من الكربون حرقًا كاملًا في الأكسجين، فالقيمة نفسها هي حرارة الاحتراق القياسية للكربون.', '["التفاعل هو أيضًا حرق كامل لمول واحد من الكربون في الأكسجين، فقيمته تمثل حرارة احتراق الكربون كذلك.","","التفاعل يكوّن 1 mol من CO₂ من عنصريه في حالتيهما القياسيتين، فهو تفاعل تكوين قياسي أيضًا؛ ووجود الأكسجين متفاعلًا لا يمنع ذلك.","الكربون عنصر في حالته القياسية فحرارة تكوينه صفر، والقيمة تخص الناتج CO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-07T17:19:00.395Z"}'::jsonb),
('mcq', 7, 2, 'المعادلة الحرارية لحرارة التكوين تُوزن لمول واحد من الناتج، ولموازنة مول واحد من SO₃ يلزم 3/2 mol من O₂، فيظهر المعامل الكسري.', '["الحالة القياسية للأكسجين جزيئات O₂، والمعامل الكسري لا يعني وجود ذرات منفردة.","المعامل الكسري لا يغير إشارة ΔH؛ فـ ΔH°f لـ SO₃ سالبة.","","هذه المعادلة موزونة، لكنها تنتج 2 mol من SO₃ فلا تمثل حرارة التكوين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.395Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تعني القيمة −396 kJ/mol أن تكوين 1 mol من SO₃(g) من S(s) وO₂(g) في الظروف القياسية يطلق 396 kJ، فيقع SO₃ تحت الصفر بمقدار 396 kJ (محتواه الحراري أقل من محتوى عناصره). وتعني القيمة +33.2 kJ/mol أن تكوين 1 mol من NO₂(g) من N₂(g) وO₂(g) يمتص 33.2 kJ، فيقع NO₂ فوق الصفر بمقدار 33.2 kJ. والصفر يمثل العناصر في حالاتها القياسية لأن ΔH°f لها 0.0 kJ/mol، كما يمثل الصفر المئوي نقطة تجمد الماء.', '["معنى −396 kJ/mol: تكوين طارد للحرارة لمول واحد","موقع SO₃ تحت الصفر بمقدار 396 kJ","معنى +33.2 kJ/mol: تكوين ماص للحرارة لمول واحد","موقع NO₂ فوق الصفر بمقدار 33.2 kJ","الصفر يمثل العناصر في حالاتها القياسية"]'::jsonb, '[]'::jsonb, '[{"element":"معنى قيمة SO₃","marks":1},{"element":"موقع SO₃","marks":1},{"element":"معنى قيمة NO₂","marks":1},{"element":"موقع NO₂","marks":1},{"element":"دلالة الصفر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"شرح القيمتين والموقعين ودلالة الصفر كاملة."},{"level":"3–4 درجات","description":"شرح صحيح لقيمة واحدة وموقعها مع نقص في الأخرى أو في دلالة الصفر."},{"level":"1–2 درجة","description":"إشارة صحيحة إلى طارد/ماص دون ربط بالتدريج."},{"level":"صفر","description":"لا إجابة أو تفسير خاطئ."}]'::jsonb, '["اعتبار القيمة السالبة امتصاصًا للحرارة","وضع NO₂ تحت الصفر","نسيان أن القيمة لمول واحد من المركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.395Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) لا تمثل تفاعل تكوين قياسي؛ لأنها تنتج 2 mol من الماء لا مولًا واحدًا. (b) تمثل تفاعل تكوين قياسي؛ تنتج 1 mol من H₂O(l) من عنصريه H₂(g) وO₂(g) في حالتيهما القياسيتين. (c) لا تمثل؛ لأن CO مركب وليس عنصرًا. (d) تمثل؛ تنتج 1 mol من SF₆ من عنصريه S(s) وF₂(g) في حالتيهما القياسيتين.', '["(a) لا — ينتج 2 mol","(b) نعم — 1 mol من عناصر في حالاتها القياسية","(c) لا — CO مركب لا عنصر","(d) نعم — 1 mol من عناصر في حالاتها القياسية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم والتعليل لـ a","marks":1},{"element":"الحكم والتعليل لـ b","marks":1},{"element":"الحكم والتعليل لـ c","marks":1},{"element":"الحكم والتعليل لـ d","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أحكام صحيحة مع تعليل صحيح للمعادلات الأربع."},{"level":"2–3 درجات","description":"حكمان أو ثلاثة صحيحة معللة."},{"level":"1 درجة","description":"حكم واحد صحيح معلل أو أحكام دون تعليل."},{"level":"صفر","description":"لا إجابة أو أحكام خاطئة."}]'::jsonb, '["قبول (a) لأن العناصر في حالاتها القياسية مع تجاهل عدد المولات","قبول (c) لأن الناتج مول واحد مع تجاهل أن CO مركب","رفض (b) أو (d) بسبب المعامل الكسري أو كبر المعاملات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.396Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) لأن H₂(g) وO₂(g) عنصران في حالتيهما القياسيتين، وقد اتُّفق على أن ΔH°f للعناصر في حالاتها القياسية تساوي 0.0 kJ/mol لتكون نقطة بداية التدريج. (2) الماء الغازي محتواه الحراري أعلى من الماء السائل؛ لأن تحويل السائل إلى غاز يحتاج إلى طاقة، فيكون تكوين الغاز أقل إطلاقًا للحرارة. حرارة التبخر: H₂O(l) → H₂O(g)، ΔH = (−241.8) − (−285.8) = +44.0 kJ/mol. (3) لأن ΔH تختلف باختلاف الحالة الفيزيائية للمادة؛ فاستعمال قيمة الحالة الخطأ يعطي ΔH غير صحيحة.', '["العناصر في حالاتها القياسية ΔH°f = 0 بالاتفاق","الماء الغازي أعلى في المحتوى الحراري من السائل","حساب حرارة التبخر +44.0 kJ/mol","ΔH تعتمد على الحالة الفيزيائية فيجب تحديدها"]'::jsonb, '["H₂O(l) → H₂O(g)","ΔH = ΔH°f(H₂O(g)) − ΔH°f(H₂O(l)) = −241.8 − (−285.8) = +44.0 kJ/mol"]'::jsonb, '[{"element":"تعليل صفر العناصر","marks":1},{"element":"تفسير اختلاف القيمتين","marks":1},{"element":"حساب حرارة التبخر","marks":2},{"element":"أهمية تحديد الحالة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة عن الأجزاء الثلاثة مع الحساب."},{"level":"3–4 درجات","description":"حساب صحيح مع نقص في أحد التفسيرين."},{"level":"1–2 درجة","description":"جزء واحد صحيح فقط."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["كتابة حرارة التبخر سالبة (−44.0 kJ/mol)","جمع القيمتين بدل طرحهما","القول إن ΔH°f للعناصر صفر لأنها لا تتفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.396Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
