('mcq', 4, 'احسب ΔH°rxn للتفاعل: 4NH₃(g) + 7O₂(g) → 4NO₂(g) + 6H₂O(l)، علمًا بأن ΔH°f(NH₃) = −46 kJ/mol، ΔH°f(NO₂) = +33.2 kJ/mol، ΔH°f(H₂O(l)) = −286 kJ/mol.', null, null, '["−1399 kJ","−1767 kJ","−207 kJ","+1399 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'صعب', 'الكتاب ص 38 — مسائل تدريبية (34–37)'),
('mcq', 5, 'ما العلاقة الصحيحة لحساب ΔH°rxn للتفاعل: 2C₂H₆(g) + 7O₂(g) → 4CO₂(g) + 6H₂O(l)؟', null, null, '["[2ΔH°f(C₂H₆) + 7ΔH°f(O₂)] − [4ΔH°f(CO₂) + 6ΔH°f(H₂O)]","[ΔH°f(CO₂) + ΔH°f(H₂O)] − [ΔH°f(C₂H₆) + ΔH°f(O₂)]","[4ΔH°f(CO₂) + 6ΔH°f(H₂O)] − [2ΔH°f(C₂H₆) + 7ΔH°f(O₂)]","[4ΔH°f(CO₂) + 6ΔH°f(H₂O)] + [2ΔH°f(C₂H₆) + 7ΔH°f(O₂)]"]'::jsonb, 'فهم', 'اختيار العلاقة', 'سهل', 'الكتاب ص 37 — معادلة التجميع ومثال 1-6'),
('mcq', 6, 'ΔH°comb للإيثانول C₂H₅OH(l) تساوي −1367 kJ/mol وفق المعادلة: C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l). إذا علمت أن ΔH°f(CO₂) = −394 kJ/mol وΔH°f(H₂O(l)) = −286 kJ/mol، فما حرارة التكوين القياسية للإيثانول؟', null, null, '["+279 kJ/mol","−1646 kJ/mol","−3013 kJ/mol","−279 kJ/mol"]'::jsonb, 'تحليل', 'مسألة حسابية عكسية', 'صعب', 'الكتاب ص 37 — معادلة التجميع ومثال 1-6'),
('mcq', 7, 'احسب ΔH°rxn للتفاعل: P₄O₆(s) + 2O₂(g) → P₄O₁₀(s)، علمًا بأن ΔH°f(P₄O₆) = −1640 kJ/mol وΔH°f(P₄O₁₀) = −2984 kJ/mol.', null, null, '["−1344 kJ","−4624 kJ","+1344 kJ","−2984 kJ"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 44 — تقويم الفصل (79)'),
('essay', 1, 'احسب ΔH°comb لحمض البيوتانويك وفق المعادلة: C₃H₇COOH(l) + 5O₂(g) → 4CO₂(g) + 4H₂O(l)، علمًا بأن ΔH°f(C₃H₇COOH) = −534 kJ/mol، ΔH°f(CO₂) = −394 kJ/mol، ΔH°f(H₂O(l)) = −286 kJ/mol.', null, null, null, 'تطبيق', 'مسألة حسابية بالخطوات', 'متوسط', 'الكتاب ص 38 — مسائل تدريبية (34–37)'),
('essay', 2, 'يحترق الإيثان وفق المعادلة: 2C₂H₆(g) + 7O₂(g) → 4CO₂(g) + 6H₂O(l). إذا علمت أن ΔH°f(C₂H₆) = −84 kJ/mol، ΔH°f(CO₂) = −394 kJ/mol، ΔH°f(H₂O(l)) = −286 kJ/mol، فاحسب ΔH°rxn للمعادلة، ثم احسب حرارة الاحتراق القياسية لمول واحد من الإيثان.', null, null, null, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'متوسط', 'الكتاب ص 44 — مسألة تحفيز (86)'),
('essay', 3, 'استعمل القيم: ΔH°f(CO₂) = −394 kJ/mol، ΔH°f(CH₄) = −75 kJ/mol، ΔH°f(H₂O(l)) = −286 kJ/mol، ΔH°f(H₂O(g)) = −242 kJ/mol، لحساب ΔH°rxn لاحتراق الميثان CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O مرة عندما يكون الماء الناتج سائلًا ومرة عندما يكون غازًا. قارن بين القيمتين وفسّر الفرق بينهما.', null, null, null, 'تحليل', 'حساب ومقارنة وتفسير', 'صعب', 'الكتاب ص 37 — مثال 1-6، وص 44 تقويم الفصل (82)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
