select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'المعادلة المطلوبة هي عكس المعادلة المعطاة بالمعاملات نفسها، فتبقى القيمة العددية 286 kJ وتتغير الإشارة: ΔH = +286 kJ.', '["عند عكس المعادلة يجب تغيير إشارة ΔH؛ وهنا بقيت الإشارة كما هي.","عُكست الإشارة لكن ضُوعفت القيمة دون داعٍ؛ فالمعاملات لم تتغير.","","قُسمت القيمة على 2 دون تغيير الإشارة؛ والمعادلة معكوسة فقط ولم تتغير معاملاتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.398Z"}'::jsonb),
('mcq', 2, 0, 'معادلة تكوين مول واحد هي H₂(g) + ½O₂(g) → H₂O(l)، ΔH = −286 kJ، والمعادلة الموزونة هي هذه المعادلة مضروبة في 2 (تكوين 2 mol)، فتُضرب ΔH في 2: ΔH = 2(−286 kJ) = −572 kJ.', '["","ضُربت المعاملات في 2، فيجب ضرب ΔH في 2 أيضًا؛ لأن ضعف كمية المواد يطلق ضعف الحرارة.","قُسمت ΔH على 2 بدل ضربها؛ والمعاملات تضاعفت لا تنصفت.","ضُوعفت القيمة صحيحًا لكن غُيرت الإشارة؛ والمعادلة لم تُعكس فتبقى الإشارة سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.398Z"}'::jsonb),
('mcq', 3, 1, 'ΔH تتناسب مع كمية المواد المتفاعلة؛ فعند تفاعل 2 mol من الكبريت مثلًا بدل 1 mol تتضاعف الحرارة، لذا تُضرب ΔH في المعامل نفسه.', '["السرعة لا علاقة لها بقيمة ΔH؛ التضاعف سببه تضاعف عدد المولات المتفاعلة.","","طبيعة المواد لا تتغير بضرب المعاملات؛ تتغير الكميات فقط.","الضرب لا يغير إشارة ΔH؛ الذي يغير الإشارة هو عكس المعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-07T17:19:00.398Z"}'::jsonb),
('mcq', 4, 3, 'إذا أطلق تفاعل كمية من الحرارة فإن التفاعل العكسي يمتص الكمية نفسها (مثل ΔHcond = −ΔHvap)؛ أي أن ما ينطلق من حرارة في اتجاه يُمتص مثله في الاتجاه المعاكس، لذا تبقى القيمة العددية وتتغير الإشارة.', '["التفاعل العكسي يمتص أو يطلق المقدار نفسه من الطاقة لا ضعفه.","عكس المعادلة لا يغير المعاملات ولا عدد المولات، بل يبدل المتفاعلات والنواتج.","تغير الإشارة لا علاقة له بالظروف؛ سببه أن الطاقة المنطلقة في اتجاه تُمتص في الاتجاه الآخر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-07T17:19:00.399Z"}'::jsonb),
('mcq', 5, 1, 'المعادلة المطلوبة هي عكس المعادلة المعطاة مضروبة في 3، فتُضرب ΔH في 3 وتُعكس إشارتها: ΔH = −3(−120 kJ) = +360 kJ.', '["ضُربت القيمة في 3 دون تغيير الإشارة؛ والمعادلة معكوسة أيضًا.","","غُيرت الإشارة للعكس لكن لم تُضرب القيمة في 3.","قُسمت القيمة على 3 بدل ضربها؛ فالمعاملات تضاعفت ثلاث مرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.399Z"}'::jsonb),
('mcq', 6, 0, 'المعادلة المطلوبة هي عكس المعطاة مقسومة على 2، فتُعكس الإشارة وتُقسم القيمة على 2: ΔH = −198 kJ ÷ 2 = −99 kJ.', '["","عُكست المعادلة وغُيرت الإشارة، لكن لم تُقسم القيمة على 2 مع أن المعاملات نُصّفت.","قُسمت القيمة على 2 لكن لم تُغير الإشارة مع أن المعادلة معكوسة.","ضُربت القيمة في 2 بدل قسمتها؛ والمعاملات في المعادلة المطلوبة نصف المعطاة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.399Z"}'::jsonb),
('mcq', 7, 3, 'المعادلة المطلوبة هي عكس المعطاة مضروبة في 2، فتُضرب ΔH في 2 وتُعكس إشارتها: ΔH = −2(+33.2 kJ) = −66.4 kJ.', '["ضُربت القيمة في 2 لكن لم تُغير الإشارة مع أن المعادلة معكوسة.","غُيرت الإشارة لكن لم تُضرب في 2، مع أن المعادلة المطلوبة لـ 2 mol من NO₂.","قُسمت القيمة على 2 بدل ضربها؛ والمعاملات تضاعفت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.399Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) العكس: H₂O(g) → H₂O(l)، ΔH = −40.7 kJ؛ تتغير الإشارة وتبقى القيمة؛ لأن الحرارة التي تُمتص عند تبخر 1 mol من الماء تنطلق نفسها عند تكثفه (ΔHcond = −ΔHvap). (2) الضرب في 3: 3H₂O(l) → 3H₂O(g)، ΔH = 3(+40.7 kJ) = +122.1 kJ؛ تُضرب القيمة في 3 وتبقى الإشارة؛ لأن تبخر 3 mol يحتاج إلى ثلاثة أمثال الحرارة.', '["معادلة العكس وΔH = −40.7 kJ","تعليل تغير الإشارة","معادلة الضرب وΔH = +122.1 kJ","تعليل تضاعف القيمة"]'::jsonb, '["العكس: ΔH = −(+40.7 kJ) = −40.7 kJ","الضرب: ΔH = 3 × 40.7 kJ = +122.1 kJ"]'::jsonb, '[{"element":"حالة العكس","marks":1},{"element":"تعليل العكس","marks":1},{"element":"حالة الضرب","marks":1},{"element":"تعليل الضرب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحالتان صحيحتان مع التعليل."},{"level":"2–3 درجات","description":"الحالتان صحيحتان دون تعليل كافٍ، أو حالة واحدة مع تعليلها."},{"level":"1 درجة","description":"قيمة واحدة صحيحة فقط."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["تغيير الإشارة عند الضرب","ضرب القيمة عند العكس","نسيان الحالة الفيزيائية في المعادلة الناتجة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.399Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) المعادلة معكوسة ومضروبة في 2، فتُعكس الإشارة وتُضرب القيمة في 2: ΔH = −2(−394 kJ) = +788 kJ. (2) المعادلة مضروبة في ½ دون عكس، فتُقسم القيمة على 2 وتبقى الإشارة: ΔH = ½(−394 kJ) = −197 kJ.', '["(1) تحديد العكس والضرب في 2","(1) ΔH = +788 kJ","(2) تحديد الضرب في ½ دون عكس","(2) ΔH = −197 kJ"]'::jsonb, '["(1) ΔH = −2 × (−394 kJ) = +788 kJ","(2) ΔH = ½ × (−394 kJ) = −197 kJ"]'::jsonb, '[{"element":"القاعدة في (1)","marks":1},{"element":"القيمة في (1)","marks":1},{"element":"القاعدة في (2)","marks":1},{"element":"القيمة في (2)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القيمتان والقاعدتان صحيحة."},{"level":"2–3 درجات","description":"قيمة صحيحة مع قاعدتها وخطأ في الأخرى."},{"level":"1 درجة","description":"قاعدة واحدة صحيحة دون حساب صحيح."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["إعطاء (1) القيمة −788 kJ بنسيان عكس الإشارة","إعطاء (1) القيمة +394 kJ بنسيان الضرب في 2","تغيير الإشارة في (2) مع أن المعادلة لم تُعكس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.399Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطالب أصاب في ضرب المعادلة a في 2 وعكس المعادلة b وجمعهما، لكنه أخطأ مرتين: (1) ضرب معاملات a في 2 ولم يضرب ΔH في 2؛ والصحيح ΔH = 2(−297 kJ) = −594 kJ. (2) عكس المعادلة b ولم يغير إشارة ΔH؛ والصحيح ΔH = −198 kJ. وبعد التصحيح: ΔH = −594 kJ + (−198 kJ) = −792 kJ.', '["بيان ما أصاب فيه الطالب (معالجة المعادلات وجمعها)","الخطأ الأول: لم يضرب ΔH في 2","الخطأ الثاني: لم يغير الإشارة عند العكس","التصحيح: −594 kJ و−198 kJ","الناتج الصحيح −792 kJ"]'::jsonb, '["2 × a: ΔH = 2(−297) = −594 kJ","عكس b: ΔH = −198 kJ","الجمع: ΔH = −594 + (−198) = −792 kJ"]'::jsonb, '[{"element":"تحديد الخطأ الأول","marks":1},{"element":"تحديد الخطأ الثاني","marks":1},{"element":"تصحيح القيمتين","marks":1},{"element":"الناتج الصحيح","marks":1},{"element":"الحكم العام على الحل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد الخطأين وتصحيحهما والناتج −792 kJ مع حكم واضح."},{"level":"3–4 درجات","description":"تحديد الخطأين مع خطأ في التصحيح أو الناتج."},{"level":"1–2 درجة","description":"تحديد خطأ واحد فقط."},{"level":"صفر","description":"لا إجابة أو قبول حل الطالب."}]'::jsonb, '["اكتشاف خطأ واحد فقط","تغيير إشارة a أيضًا","الحصول على −495 kJ أو −396 kJ بعد تصحيح جزئي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.400Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L4-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تختلف الظروف القياسية المعتمدة في الكيمياء الحرارية عن الظروف المعيارية STP المعتمدة للغازات. فيمَ يكمن هذا الاختلاف؟', null, null, '["في الضغط فقط؛ فهو 2 atm في الظروف القياسية و1 atm في STP","في درجة الحرارة فقط؛ فهي 25°C في الظروف القياسية و0°C في STP","في الضغط ودرجة الحرارة معًا؛ فالظروف القياسية 2 atm و100°C","لا اختلاف بينهما؛ فكلاهما عند 1 atm و0°C"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 34 — حرارة التكوين القياسية (الحالة القياسية)'),
('mcq', 2, 'أيّ مما يأتي يمثل عنصرًا في حالته القياسية عند 25°C و 1 atm؟', null, null, '["Fe(l)","O(g)","N(g)","Hg(l)"]'::jsonb, 'فهم', 'تحديد الحالة القياسية لعنصر', 'سهل', 'الكتاب ص 34 — الحالة القياسية للعناصر (الحديد والزئبق والأكسجين)'),
('mcq', 3, 'أيّ المواد الآتية تساوي حرارة تكوينها القياسية ΔH°f صفرًا؟', null, null, '["S(s)","SO₃(g)","O(g)","H₂O(l)"]'::jsonb, 'فهم', 'تمييز مادة ΔH°f لها صفر', 'متوسط', 'الكتاب ص 35 — ما مصدر حرارة التكوين؟ (ΔH°f للعناصر = 0.0)'),
('mcq', 4, 'لماذا تُعدّ حرارة التكوين القياسية للعناصر في حالاتها القياسية مساوية لصفر؟', null, null, '["لأن العناصر لا تمتلك أي محتوى حراري أو طاقة كامنة على الإطلاق","لأن تكوين العناصر من مكوناتها يطلق دائمًا كمية صغيرة جدًّا من الحرارة","لأنها قيمة مرجعية مفترضة تمثل نقطة الصفر التي تُقاس بالنسبة إليها حرارة تكوين المركبات","لأن العناصر في الظروف القياسية لا تتفاعل مع غيرها من المواد إطلاقًا"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 35 — ما مصدر حرارة التكوين؟'),
('mcq', 5, 'في التفاعل الآتي: 4C(s) + 4H₂(g) + O₂(g) → C₃H₇COOH(l)   ΔH = −534 kJ. ما مجموع حرارة التكوين القياسية للمواد المتفاعلة ΣΔH°f(reactants)؟', null, null, '["−534 kJ","0.0 kJ","+534 kJ","−133.5 kJ"]'::jsonb, 'تطبيق', 'تطبيق قاعدة ΔH°f = 0', 'متوسط', 'الكتاب ص 38 — مسألة 36 (تفاعل تكوين حمض البيوتانويك)'),
('mcq', 6, 'أيّ العبارات الآتية صحيحة بشأن عنصر الأكسجين عند 25°C و 1 atm؟', null, null, '["حالته القياسية O₂(g)، لذا ΔH°f(O₂) = 0، أما ΔH°f لـ O(g) فلا تساوي صفرًا","حالته القياسية O(g) أحادي الذرة، لذا ΔH°f(O) = 0، أما O₂(g) فلا تساوي صفرًا","ΔH°f لكل من O₂(g) و O(g) و O₃(g) تساوي صفرًا لأنها جميعًا صور لعنصر واحد","حالته القياسية O₂(l)، لذا ΔH°f(O₂(l)) = 0، أما O₂(g) فلا تساوي صفرًا"]'::jsonb, 'فهم', 'تمييز الحالة القياسية من غيرها', 'صعب', 'الكتاب ص 34–35 و ص 38 (س42) — الأكسجين غاز ثنائي الذرة في الحالة القياسية'),
('mcq', 7, 'أعدّ طالب القيم الآتية لحرارة التكوين القياسية. أيّ قيمة منها خاطئة؟', '{"headers":["المادة","ΔH°f (kJ/mol)"],"rows":[["Fe(s)","0.0"],["Hg(l)","0.0"],["O₂(g)","0.0"],["NO₂(g)","0.0"],["SO₃(g)","−396"]]}'::jsonb, null, '["Hg(l): 0.0 kJ/mol","O₂(g): 0.0 kJ/mol","SO₃(g): −396 kJ/mol","NO₂(g): 0.0 kJ/mol"]'::jsonb, 'تحليل', 'اكتشاف خطأ في بيانات', 'صعب', 'الكتاب ص 34–35 — الحالة القياسية، وتكوين NO₂ (+33.2 kJ)'),
('essay', 1, 'عرّف الحالة القياسية في الكيمياء الحرارية، ثم حدّد الحالة القياسية لكل من: الحديد، والزئبق، والأكسجين، والنيتروجين، واذكر قيمة حرارة التكوين القياسية لكل منها في تلك الحالة.', null, null, null, 'فهم', 'تعريف وتحديد', 'سهل', 'الكتاب ص 34 — حرارة التكوين القياسية (الحالة القياسية)'),
('essay', 2, 'فسّر لماذا تساوي حرارة التكوين القياسية ΔH°f للعناصر في حالاتها القياسية صفرًا، ووضّح فائدة اتخاذ هذه القيمة نقطة بداية، مقارنًا ذلك بتدريج درجة الحرارة المئوية الذي صفره درجة تجمد الماء.', null, null, null, 'فهم', 'تفسير وتوضيح بتشبيه', 'متوسط', 'الكتاب ص 35 — ما مصدر حرارة التكوين؟ والشكل 1-14'),
('essay', 3, 'صنّف المواد الآتية إلى مواد حرارة تكوينها القياسية تساوي صفرًا، ومواد لا تساوي صفرًا، مع تعليل كل تصنيف: Fe(s)، Hg(l)، O₂(g)، O(g)، O₃(g)، N₂(g)، NO₂(g).', null, null, null, 'تحليل', 'تصنيف مع تعليل', 'صعب', 'الكتاب ص 34–35 و ص 38 (س40، س42) — الحالة القياسية للعناصر و ΔH°f = 0')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الظروف القياسية في الكيمياء الحرارية ضغط 1 atm ودرجة حرارة 25°C (298 K)، أما STP فضغط 1 atm ودرجة حرارة 0°C (273 K)؛ فالضغط واحد، والاختلاف في درجة الحرارة فقط.', '["الضغط واحد في الحالتين (1 atm)، والاختلاف في درجة الحرارة.","","الظروف القياسية 1 atm و25°C (298 K)، لا 2 atm و100°C.","STP عند 0°C، أما الظروف القياسية في الكيمياء الحرارية فعند 25°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.400Z"}'::jsonb),
('mcq', 2, 3, 'الزئبق فلز سائل عند 25°C و 1 atm، فحالته القياسية Hg(l). أما الحديد فصلب، والأكسجين والنيتروجين غازان ثنائيا الذرة.', '["الحديد صلب في الحالة القياسية Fe(s)، ولا يكون سائلًا إلا عند درجات حرارة عالية جدًّا.","الأكسجين في الحالة القياسية غاز ثنائي الذرة O₂(g)، لا ذرات منفردة O(g).","النيتروجين في الحالة القياسية غاز ثنائي الذرة N₂(g)، لا ذرات منفردة N(g).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.400Z"}'::jsonb),
('mcq', 3, 0, 'الكبريت الصلب S(s) عنصر في حالته القياسية، والعناصر في حالاتها القياسية يكون لها ΔH°f = 0.0 kJ/mol.', '["","SO₃(g) مركب يتكون من عناصره بانطلاق حرارة، و ΔH°f له تساوي −396 kJ/mol.","O(g) ليس الحالة القياسية للأكسجين؛ فحالته القياسية O₂(g)، لذا لا تساوي ΔH°f لـ O(g) صفرًا.","H₂O(l) مركب وليس عنصرًا، و ΔH°f له تساوي −286 kJ/mol."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.400Z"}'::jsonb),
('mcq', 4, 2, 'تعتمد حرارة التكوين القياسية على فرضية أن ΔH°f للعناصر في حالاتها القياسية تساوي 0.0 kJ/mol؛ فهي نقطة بداية (مرجع) تُنظَّم بالنسبة إليها قيم حرارة تكوين المركبات، كما يُتخذ 0.0°C نقطة صفر لتدريج درجة الحرارة المئوية.', '["الصفر هنا قيمة مرجعية متفق عليها، ولا يعني أن العنصر خالٍ من الطاقة؛ فالمحتوى الحراري المطلق لا يُقاس.","العنصر في حالته القياسية لا يتكون من مواد أخرى، فلا يوجد تفاعل تكوين يطلق حرارة؛ والقيمة صفر تمامًا لا قيمة صغيرة.","","العناصر تتفاعل مع غيرها في الظروف القياسية، مثل تفاعل الكبريت مع الأكسجين، وهذا لا علاقة له بكون ΔH°f لها صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.400Z"}'::jsonb),
('mcq', 5, 1, 'المتفاعلات C(s) و H₂(g) و O₂(g) كلها عناصر في حالاتها القياسية، فحرارة تكوين كل منها 0.0 kJ/mol، ومجموعها مهما كانت المعاملات 0.0 kJ.', '["−534 kJ هي ΔH للتفاعل كله، أي حرارة تكوين الناتج C₃H₇COOH، وليست مجموع حرارة تكوين المتفاعلات.","","هذه قيمة ΔH للتفاعل بعد عكس إشارتها، ولا علاقة لها بالمتفاعلات التي هي عناصر حرارة تكوينها صفر.","هذا ناتج قسمة −534 kJ على معامل الكربون 4، وهو خطأ؛ فحرارة تكوين كل عنصر في حالته القياسية صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.401Z"}'::jsonb),
('mcq', 6, 0, 'الأكسجين في الحالة القياسية غاز ثنائي الذرة O₂(g)، فتكون ΔH°f له صفرًا. أما الصور الأخرى مثل O(g) فليست الحالة القياسية، ويلزم طاقة لتكوينها من O₂(g) (مثل O₂(g) → 2O(g) ΔH = +495 kJ)، فلا تساوي حرارة تكوينها صفرًا.', '["","الأكسجين يوجد في الظروف القياسية جزيئات ثنائية الذرة O₂ لا ذرات منفردة.","قاعدة الصفر تخص الحالة القياسية للعنصر فقط (O₂(g))، لا كل صوره؛ فتكوين O(g) أو O₃(g) من O₂(g) يصاحبه تغير في المحتوى الحراري.","الأكسجين غاز عند 25°C و 1 atm، ولا يكون سائلًا إلا عند درجات حرارة منخفضة جدًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.401Z"}'::jsonb),
('mcq', 7, 3, 'NO₂(g) مركب لا عنصر، ويتكون من N₂(g) و O₂(g) بامتصاص 33.2 kJ لكل مول، فقيمة ΔH°f له +33.2 kJ/mol لا صفر. أما Fe(s) و Hg(l) و O₂(g) فعناصر في حالاتها القياسية قيمتها 0.0، وقيمة SO₃(g) صحيحة.', '["الزئبق سائل في الحالة القياسية، فـ Hg(l) هي حالته القياسية وقيمتها 0.0 صحيحة رغم أنه فلز.","O₂(g) هي الحالة القياسية للأكسجين، فقيمة 0.0 صحيحة.","حرارة التكوين القياسية لـ SO₃(g) تساوي −396 kJ/mol فعلًا، فهذه القيمة صحيحة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.401Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحالة القياسية: ضغط جوي واحد 1 atm ودرجة حرارة 25°C (298 K). الحديد صلب Fe(s)، والزئبق سائل Hg(l)، والأكسجين غاز ثنائي الذرة O₂(g)، والنيتروجين غاز ثنائي الذرة N₂(g). وحرارة التكوين القياسية لكل منها في هذه الحالات تساوي 0.0 kJ/mol؛ لأنها عناصر في حالاتها القياسية.', '["الحالة القياسية: 1 atm و 25°C (298 K)","Fe(s) و Hg(l)","O₂(g) و N₂(g) غازان ثنائيا الذرة","ΔH°f لكل منها = 0.0 kJ/mol"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الحالة القياسية (الضغط ودرجة الحرارة)","marks":1},{"element":"تحديد الحالة القياسية للعناصر الأربعة (نصف درجة لكل عنصر)","marks":2},{"element":"ذكر أن ΔH°f لكل منها = 0.0 kJ/mol","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وحالات العناصر الأربعة صحيحة، وقيمة ΔH°f صحيحة"},{"level":"2–3 درجات","description":"خطأ في حالة عنصر أو عنصرين، أو نقص في التعريف"},{"level":"1 درجة","description":"ذكر جزء من التعريف أو قيمة الصفر فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الحالة القياسية (25°C) والظروف المعيارية STP (0°C)","كتابة الزئبق صلبًا لأنه فلز","كتابة الأكسجين أو النيتروجين ذرات منفردة O(g) أو N(g)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.401Z"}'::jsonb),
('essay', 2, null::int, null, null, 'حرارة التكوين القياسية هي التغير في المحتوى الحراري عند تكوين 1 mol من مادة من عناصرها في حالاتها القياسية، والعنصر في حالته القياسية لا يتكون من شيء آخر، لذا اتُّفق (فرضًا) على أن ΔH°f له 0.0 kJ/mol. ولا يعني الصفر أن العنصر بلا طاقة، بل هو مرجع. وفائدته أنه نقطة بداية تُنظَّم بالنسبة إليها قيم حرارة تكوين المركبات التي تُقاس عمليًّا: فالمركب الذي يمتص حرارة عند تكوينه (مثل NO₂: +33.2 kJ/mol) يقع فوق الصفر، والذي يطلق حرارة (مثل SO₃: −396 kJ/mol) يقع تحته. وهذا يشبه تدريج درجة الحرارة المئوية الذي يتخذ 0.0°C (تجمد الماء) صفرًا، فتكون المواد الأدفأ فوقه والأبرد تحته.', '["العنصر في حالته القياسية لا يتكون من مواد أخرى، فاتُّفق على ΔH°f = 0.0","الصفر قيمة مرجعية وليس انعدامًا للطاقة","الفائدة: نقطة بداية تُقاس بالنسبة إليها حرارة تكوين المركبات","التشبيه: مركبات فوق الصفر (ماصة) وتحته (طاردة) كما في التدريج المئوي"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير كون ΔH°f للعنصر صفرًا","marks":1},{"element":"بيان أن الصفر مرجع لا انعدام للطاقة","marks":1},{"element":"فائدة نقطة البداية مع مثال لمركب فوق الصفر وآخر تحته","marks":1},{"element":"المقارنة الصحيحة بالتدريج المئوي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح، وبيان معنى المرجع، وفائدة واضحة بمثالين، ومقارنة سليمة"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في الفائدة أو المقارنة"},{"level":"1 درجة","description":"ذكر أن القيمة صفر دون تفسير مقبول"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن العناصر لا تمتلك طاقة","القول إن العناصر لا تتفاعل لذا حرارتها صفر","عكس موضع المركبات الماصة والطاردة بالنسبة إلى الصفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.401Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تساوي صفرًا: Fe(s) و Hg(l) و O₂(g) و N₂(g)؛ لأنها عناصر في حالاتها القياسية عند 1 atm و 25°C (الحديد صلب، والزئبق سائل، والأكسجين والنيتروجين غازان ثنائيا الذرة). لا تساوي صفرًا: O(g) و O₃(g)؛ فهما صورتان للأكسجين لكنهما ليستا حالته القياسية، وتكوين أي منهما من O₂(g) يصاحبه تغير في المحتوى الحراري. و NO₂(g) مركب يتكون من عناصره بامتصاص 33.2 kJ لكل مول، فقيمة ΔH°f له +33.2 kJ/mol.', '["صفر: Fe(s)، Hg(l)، O₂(g)، N₂(g) — عناصر في حالاتها القياسية","ليس صفرًا: O(g)، O₃(g) — ليستا الحالة القياسية للأكسجين","ليس صفرًا: NO₂(g) — مركب، ΔH°f = +33.2 kJ/mol","التعليل مرتبط بالحالة القياسية لا بنوع العنصر فقط"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف المواد الأربع ذات القيمة صفر مع التعليل","marks":2},{"element":"تصنيف O(g) و O₃(g) مع التعليل","marks":2},{"element":"تصنيف NO₂(g) مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف المواد السبع صحيح مع تعليل سليم لكل مجموعة"},{"level":"3–4 درجات","description":"خطأ في تصنيف مادة واحدة أو نقص في أحد التعليلات"},{"level":"1–2 درجة","description":"تصنيف بعض المواد صحيحًا دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ O(g) و O₃(g) صفرًا لأنهما من عنصر الأكسجين","عدّ NO₂ صفرًا لأنه يتكون من غازين ثنائيي الذرة","الحكم على Hg(l) بأنه ليس في حالته القياسية لأنه فلز سائل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.401Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
