select (select id from public.objectives where code = 'K22-C1-L4-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الشرط الذي يجب أن تحققه معادلة تكوين مركب حتى تمثل ΔH لها حرارة التكوين القياسية ΔH°f؟', null, null, '["أن تكون جميع معاملاتها أعدادًا صحيحة غير كسرية","أن يتفاعل 1 mol من كل عنصر من العناصر المكونة","أن يتكون المركب فيها من مركبات أبسط منه","أن يتكون 1 mol من المركب من عناصره في حالاتها القياسية"]'::jsonb, 'فهم', 'شروط معادلة التكوين', 'سهل', 'الكتاب ص 34 — تعريف حرارة التكوين القياسية'),
('mcq', 2, 'أيّ المعادلات الآتية هي معادلة تكوين فلوريد الهيدروجين HF(g) من عناصره في حالاتها القياسية؟', null, null, '["H₂(g) + F₂(g) → 2HF(g)","H(g) + F(g) → HF(g)","½H₂(g) + ½F₂(g) → HF(g)","2HF(g) → H₂(g) + F₂(g)"]'::jsonb, 'تطبيق', 'اختيار معادلة تكوين', 'سهل', 'الكتاب ص 35 — الجدول 1-5 (معادلة تكوين HF)'),
('mcq', 3, 'أيّ المعادلات الآتية تمثل معادلة تكوين ثاني أكسيد النيتروجين NO₂(g) القياسية؟', null, null, '["N₂(g) + 2O₂(g) → 2NO₂(g)","½N₂(g) + O₂(g) → NO₂(g)","NO(g) + ½O₂(g) → NO₂(g)","N(g) + 2O(g) → NO₂(g)"]'::jsonb, 'تطبيق', 'اختيار معادلة تكوين', 'متوسط', 'الكتاب ص 35 — إيجاد حرارة التكوين بالتجارب المختبرية (NO₂)'),
('mcq', 4, 'عند كتابة معادلة تكوين الإيثانول C₂H₅OH(l) من عناصره في حالاتها القياسية، ما معامل O₂(g) فيها؟', null, null, '["بمعامل 1/2","بمعامل 1","بمعامل 3","بمعامل 2"]'::jsonb, 'تطبيق', 'موازنة معادلة تكوين', 'متوسط', 'الكتاب ص 33–34 — المعاملات الكسرية في المعادلات الحرارية'),
('mcq', 5, 'أيّ التفاعلات الآتية تساوي ΔH له حرارة التكوين القياسية ΔH°f للميثان CH₄(g)؟', null, null, '["CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)","C(g) + 4H(g) → CH₄(g)","C(s) + 2H₂(g) → CH₄(g)","2C(s) + 4H₂(g) → 2CH₄(g)"]'::jsonb, 'تطبيق', 'تمييز معادلة التكوين', 'متوسط', 'الكتاب ص 37 — مثال 1-6 (ΔH°f(CH₄) = −75 kJ)'),
('mcq', 6, 'كتب طالب معادلة تكوين الماء السائل على النحو: 2H₂(g) + O₂(g) → 2H₂O(l). ما الحكم الصحيح على معادلته؟', null, null, '["الخطأ في حالة الماء، والصواب أن يكون بخارًا H₂O(g) لأن المتفاعلات غازات","تكوّن 2 mol من الماء، والصواب H₂(g) + ½O₂(g) → H₂O(l)","الخطأ في استعمال O₂، والصواب استعمال ذرات الأكسجين O(g)","صحيحة؛ لأنها موزونة وتبدأ بالعناصر في حالاتها القياسية"]'::jsonb, 'تحليل', 'اكتشاف خطأ', 'صعب', 'الكتاب ص 30 و ص 34 — H₂ + ½O₂ → H₂O، وتعريف حرارة التكوين القياسية'),
('mcq', 7, 'أيّ المعادلات الآتية هي معادلة تكوين حمض البيوتانويك C₃H₇COOH(l) من عناصره في حالاتها القياسية؟', null, null, '["4C(s) + 8H₂(g) + O₂(g) → C₃H₇COOH(l)","4C(s) + 4H₂(g) + 2O₂(g) → C₃H₇COOH(l)","4C(g) + 4H₂(g) + O₂(g) → C₃H₇COOH(l)","4C(s) + 4H₂(g) + O₂(g) → C₃H₇COOH(l)"]'::jsonb, 'تطبيق', 'اختيار معادلة تكوين', 'صعب', 'الكتاب ص 38 — مسألة 36 (تكوين حمض البيوتانويك)'),
('essay', 1, 'اكتب معادلة تكوين قياسية (تنتج 1 mol من المركب من عناصره في حالاتها القياسية) لكل من: H₂O(l)، CO₂(g)، NH₃(g)، SF₆(g).', null, null, null, 'تطبيق', 'كتابة معادلات تكوين', 'سهل', 'الكتاب ص 35–37 — الجدول 1-5 ومثال 1-6'),
('essay', 2, 'بيّن كيف يعطي جمع معادلات حرارة التكوين التفاعل الآتي دون استعمال قيم ΔH: 2NO(g) + O₂(g) → 2NO₂(g). اكتب معادلتي تكوين NO(g) و NO₂(g)، ووضح ما تفعله بكل منهما.', null, null, null, 'تحليل', 'دمج معادلات التكوين', 'صعب', 'الكتاب ص 38 — مسألة 34 (a)'),
('essay', 3, 'علّل استعمال معاملات كسرية في كثير من معادلات التكوين القياسية، ثم اكتب معادلة تكوين SO₃(g) ومعادلة تكوين C₂H₅OH(l)، وبيّن لماذا لا تُعدّ المعادلة 2S(s) + 3O₂(g) → 2SO₃(g)  ΔH = −792 kJ معادلة تكوين قياسية.', null, null, null, 'تطبيق', 'تعليل وكتابة معادلات', 'متوسط', 'الكتاب ص 32–34 — المعاملات الكسرية وتكوين SO₃')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
