select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'حرارة التكوين القياسية هي التغير في المحتوى الحراري المرافق لتكوين مول واحد من المركب من عناصره في حالاتها القياسية؛ لذا يجب أن يكون معامل المركب 1 والمتفاعلات عناصر في حالاتها القياسية.', '["كثيرًا ما تحتاج معادلة التكوين إلى معاملات كسرية حتى يكون معامل المركب 1، مثل S(s) + 3/2O₂(g) → SO₃(g).","المطلوب 1 mol من الناتج، أما العناصر فمعاملاتها تتحدد بالموازنة وقد تكون كسرية أو أكبر من 1.","المتفاعلات في معادلة التكوين عناصر لا مركبات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.404Z"}'::jsonb),
('mcq', 2, 2, 'الهيدروجين والفلور غازان ثنائيا الذرة في الحالة القياسية، ولتكوين 1 mol من HF يلزم ½ mol من كل منهما: ½H₂(g) + ½F₂(g) → HF(g).', '["المعادلة موزونة لكنها تكوّن 2 mol من HF، وحرارة التكوين تخص 1 mol.","H(g) و F(g) ذرات منفردة وليست الحالة القياسية للعنصرين؛ فحالتهما القياسية H₂(g) و F₂(g).","","هذه معادلة تحلل HF إلى عناصره، أي عكس معادلة التكوين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-07T17:19:00.404Z"}'::jsonb),
('mcq', 3, 1, 'معادلة التكوين تنتج 1 mol من NO₂ من النيتروجين والأكسجين في حالتيهما القياسيتين (غازين ثنائيي الذرة): ½N₂(g) + O₂(g) → NO₂(g)، ولها ΔH°f = +33.2 kJ.', '["المعادلة تكوّن 2 mol من NO₂، فتكون ΔH لها ضعف ΔH°f.","","NO مركب وليس عنصرًا، ومعادلة التكوين تبدأ بالعناصر فقط.","N(g) و O(g) ذرات منفردة وليست الحالة القياسية للعنصرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.404Z"}'::jsonb),
('mcq', 4, 0, 'يحتوي 1 mol من C₂H₅OH على 2 mol من C و 6 mol من H و 1 mol من ذرات O، فالمعادلة: 2C(s) + 3H₂(g) + ½O₂(g) → C₂H₅OH(l)، ومعامل O₂ هو 1/2.', '["","عُدّت ذرة الأكسجين الواحدة جزيء O₂ كاملًا؛ وجزيء O₂ فيه ذرتان، فيلزم نصف جزيء.","3 هو معامل O₂ في معادلة احتراق الإيثانول C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O، لا في معادلة تكوينه.","لا يوجد في جزيء الإيثانول إلا ذرة أكسجين واحدة، فمعامل O₂ لا يمكن أن يكون 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.404Z"}'::jsonb),
('mcq', 5, 2, 'يتكون 1 mol من CH₄ من الكربون الصلب والهيدروجين الغازي ثنائي الذرة، وهما حالتا العنصرين القياسيتان: C(s) + 2H₂(g) → CH₄(g)، فتكون ΔH له هي ΔH°f = −75 kJ.', '["هذه معادلة احتراق الميثان (ΔH = −891 kJ)، والميثان فيها متفاعل لا ناتج.","C(g) و H(g) ليستا الحالتين القياسيتين للكربون والهيدروجين.","","المعادلة تكوّن 2 mol من CH₄، فتكون ΔH لها ضعف ΔH°f."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.404Z"}'::jsonb),
('mcq', 6, 1, 'معادلة التكوين يجب أن تنتج 1 mol من المركب، والمعادلة المكتوبة تنتج 2 mol، فقسمة المعاملات على 2 تعطي H₂(g) + ½O₂(g) → H₂O(l) و ΔH°f = −286 kJ.', '["الماء السائل مركب صحيح وله حرارة تكوين قياسية (−286 kJ/mol)؛ وحالة الناتج لا تُفرض من حالة المتفاعلات.","","O₂(g) هو الحالة القياسية للأكسجين، فاستعماله صحيح.","الموازنة والبدء بالعناصر لا يكفيان؛ فلا بد أن يكون الناتج 1 mol فقط من المركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.404Z"}'::jsonb),
('mcq', 7, 3, 'في C₃H₇COOH أربع ذرات C وثماني ذرات H وذرتا O، فيلزم 4C(s) و 4H₂(g) (8 ذرات H) و O₂(g) واحد (ذرتا O)، والكربون صلب في حالته القياسية: 4C(s) + 4H₂(g) + O₂(g) → C₃H₇COOH(l).', '["عُدّت كل ذرة H جزيء H₂؛ فثماني ذرات H تحتاج إلى 4H₂ لا 8H₂.","عُدّت كل ذرة O جزيء O₂؛ فذرتا O تحتاجان إلى O₂ واحد لا 2O₂.","الكربون في حالته القياسية صلب C(s) لا غاز C(g).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-07T17:19:00.404Z"}'::jsonb),
('essay', 1, null::int, null, null, 'H₂(g) + ½O₂(g) → H₂O(l)
C(s) + O₂(g) → CO₂(g)
½N₂(g) + 3/2H₂(g) → NH₃(g)
S(s) + 3F₂(g) → SF₆(g)', '["H₂(g) + ½O₂(g) → H₂O(l)","C(s) + O₂(g) → CO₂(g)","½N₂(g) + 3/2H₂(g) → NH₃(g)","S(s) + 3F₂(g) → SF₆(g)"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة تكوين H₂O(l)","marks":1},{"element":"معادلة تكوين CO₂(g)","marks":1},{"element":"معادلة تكوين NH₃(g)","marks":1},{"element":"معادلة تكوين SF₆(g)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلات الأربع صحيحة بالمعاملات والحالات الفيزيائية"},{"level":"2–3 درجات","description":"معادلتان أو ثلاث صحيحة، أو خطأ في الحالات الفيزيائية"},{"level":"1 درجة","description":"معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تكوين 2 mol من الناتج لتجنب المعاملات الكسرية","كتابة العناصر ذرات منفردة مثل N(g) أو H(g)","كتابة الكربون أو الكبريت في الحالة الغازية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.404Z"}'::jsonb),
('essay', 2, null::int, null, null, 'معادلتا التكوين: ½N₂(g) + ½O₂(g) → NO(g)، و ½N₂(g) + O₂(g) → NO₂(g). NO متفاعل في المعادلة المطلوبة، فنعكس معادلة تكوينه ونضربها في 2: 2NO(g) → N₂(g) + O₂(g). و NO₂ ناتج بمعامل 2، فنضرب معادلة تكوينه في 2: N₂(g) + 2O₂(g) → 2NO₂(g). بالجمع: 2NO(g) + N₂(g) + 2O₂(g) → N₂(g) + O₂(g) + 2NO₂(g)، وبحذف N₂(g) من الطرفين وحذف O₂(g) واحد من الطرفين نحصل على 2NO(g) + O₂(g) → 2NO₂(g).', '["معادلة تكوين NO: ½N₂(g) + ½O₂(g) → NO(g)","معادلة تكوين NO₂: ½N₂(g) + O₂(g) → NO₂(g)","عكس معادلة NO وضربها في 2","ضرب معادلة NO₂ في 2","الجمع وحذف المواد المشتركة للوصول إلى المعادلة المطلوبة"]'::jsonb, '["½N₂(g) + ½O₂(g) → NO(g)  و  ½N₂(g) + O₂(g) → NO₂(g)","عكس الأولى وضربها في 2: 2NO(g) → N₂(g) + O₂(g)","ضرب الثانية في 2: N₂(g) + 2O₂(g) → 2NO₂(g)","الجمع: 2NO(g) + N₂(g) + 2O₂(g) → N₂(g) + O₂(g) + 2NO₂(g)","الحذف: 2NO(g) + O₂(g) → 2NO₂(g)"]'::jsonb, '[{"element":"كتابة معادلتي التكوين صحيحتين","marks":2},{"element":"عكس معادلة NO وضربها في 2","marks":1},{"element":"ضرب معادلة NO₂ في 2","marks":1},{"element":"الجمع والحذف الصحيحان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتا تكوين صحيحتان، ومعالجة صحيحة لكل منهما، وجمع وحذف صحيحان"},{"level":"3–4 درجات","description":"معادلتا تكوين صحيحتان مع خطأ في العكس أو الضرب أو الحذف"},{"level":"1–2 درجة","description":"معادلة تكوين واحدة صحيحة أو فكرة الجمع دون تنفيذ صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم عكس معادلة NO مع أنه متفاعل","نسيان ضرب المعادلتين في 2","حذف O₂ كله من الطرفين بدل حذف المقدار المشترك فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.405Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تُكتب معادلة التكوين لتكوين 1 mol من المركب، فإذا احتاج ذلك إلى عدد غير صحيح من جزيئات العناصر ثنائية الذرة استُعملت معاملات كسرية. معادلة تكوين SO₃: S(s) + 3/2O₂(g) → SO₃(g)  ΔH°f = −396 kJ. ومعادلة تكوين الإيثانول: 2C(s) + 3H₂(g) + ½O₂(g) → C₂H₅OH(l). أما المعادلة 2S(s) + 3O₂(g) → 2SO₃(g) فتكوّن 2 mol من SO₃، فقيمة ΔH لها (−792 kJ) ضعف ΔH°f، لذا ليست معادلة تكوين قياسية.', '["التعليل: معادلة التكوين تخص 1 mol من المركب","S(s) + 3/2O₂(g) → SO₃(g)","2C(s) + 3H₂(g) + ½O₂(g) → C₂H₅OH(l)","المعادلة المعطاة تكوّن 2 mol، و −792 kJ ضعف ΔH°f (−396 kJ)"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل استعمال المعاملات الكسرية","marks":1},{"element":"معادلة تكوين SO₃(g)","marks":1},{"element":"معادلة تكوين C₂H₅OH(l)","marks":1},{"element":"بيان سبب عدم عدّ المعادلة المعطاة معادلة تكوين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل صحيح، ومعادلتان صحيحتان، وبيان صحيح لسبب رفض المعادلة المعطاة"},{"level":"2–3 درجات","description":"نقص في أحد العناصر أو خطأ في معادلة واحدة"},{"level":"1 درجة","description":"معادلة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن المعاملات الكسرية خطأ في الموازنة","كتابة 3O₂ بدل ½O₂ في معادلة تكوين الإيثانول","عدّ المعادلة المعطاة معادلة تكوين لأنها تبدأ بالعناصر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.405Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C1-L4-O09') and x.type = v.type and x.number = v.number
