insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C1-L4-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'عندما يتحد ثالث أكسيد الكبريت SO₃ مع الماء في الجو يتكون حمض. ما هذا الحمض؟', null, null, '["حمض الكبريتيك H₂SO₄","حمض الكبريتوز H₂SO₃","كبريتيد الهيدروجين H₂S","حمض النيتريك HNO₃"]'::jsonb, 'تذكر', 'تذكر ناتج', 'سهل', 'الكتاب ص 34 — الشكل 1-13 (SO₃ وحمض الكبريتيك)'),
('mcq', 2, 'ما التفاعل الذي ينتج عنه ثالث أكسيد الكبريت SO₃ المسبب للمطر الحمضي؟', null, null, '["تفاعل الكبريت مع الهيدروجين","تفاعل الكبريت مع الفلور","تفاعل الكبريت مع الأكسجين","تحلل حمض الكبريتيك في التربة"]'::jsonb, 'تذكر', 'تذكر مصدر', 'سهل', 'الكتاب ص 34 — تكوّن ثالث أكسيد الكبريت'),
('mcq', 3, 'أيّ مما يأتي يصف ثالث أكسيد الكبريت SO₃ وصفًا صحيحًا؟', null, null, '["غاز خامل لا أثر له في البيئة","سائل يتجمع على سطح التربة","غاز نبيل في طبقات الجو العليا","غاز خانق يسبب المطر الحمضي"]'::jsonb, 'تذكر', 'تذكر صفة', 'متوسط', 'الكتاب ص 34 — «وهو غاز خانق يتسبب في إنتاج المطر الحمضي»'),
('mcq', 4, 'أيّ المعادلات الآتية تمثل تكوّن الحمض من ثالث أكسيد الكبريت ورطوبة الجو؟', null, null, '["SO₂(g) + H₂O(l) → H₂SO₄(aq)","SO₃(g) + H₂O(l) → H₂SO₄(aq)","SO₃(g) + H₂(g) → H₂SO₄(aq)","S(s) + 3/2O₂(g) → SO₃(g)"]'::jsonb, 'فهم', 'اختيار معادلة', 'متوسط', 'الكتاب ص 34 و ص 38 — الشكل 1-13 ومسألة 34 (b)'),
('mcq', 5, 'ما الأثر الذي يُحدثه المطر الحمضي الناتج عن حمض الكبريتيك عند وصوله إلى الأرض؟', null, null, '["يدمّر الأشجار والممتلكات ببطء","يزيد خصوبة التربة ونمو الغابات","يكوّن طبقة تحمي المباني من التآكل","يخفض حرارة الجو ويمنع الاحتباس الحراري"]'::jsonb, 'تذكر', 'تذكر أثر بيئي', 'متوسط', 'الكتاب ص 34 — الشكل 1-13 (أثر المطر الحمضي في الأشجار)'),
('mcq', 6, 'كيف يوصف حمض الكبريتيك H₂SO₄ الذي يتكون من ثالث أكسيد الكبريت في الجو؟', null, null, '["حمض ضعيف لا يؤثر في الأشجار والمباني","مادة متعادلة ليست حمضية ولا قاعدية","حمض قوي يصل إلى الأرض مطرًا حمضيًّا","قاعدة قوية تتفاعل مع الأشجار فتتلفها"]'::jsonb, 'تذكر', 'تذكر صفة', 'متوسط', 'الكتاب ص 34 — الشكل 1-13 (حمض الكبريتيك حمض قوي)'),
('mcq', 7, 'أيّ تسلسل مما يأتي يصف مراحل تكوّن المطر الحمضي الناتج عن ثالث أكسيد الكبريت وصفًا صحيحًا؟', null, null, '["يتحلل H₂SO₄ في الجو ← يتكون منه SO₃ ← يسقط SO₃ على الأرض مطرًا حمضيًّا","يتفاعل S مع O₂ فيتكون SO₃ ← يختلط SO₃ برطوبة الجو فيتكون H₂SO₄ ← يسقط مطرًا حمضيًّا","يتحد SO₃ مع O₂ في الجو ← يتكون S ← يذوب S في الماء فيسقط مطرًا حمضيًّا","يتفاعل S مع الماء فيتكون H₂S ← يتأكسد H₂S إلى SO₃ في التربة ← يتبخر مطرًا حمضيًّا"]'::jsonb, 'فهم', 'ترتيب مراحل', 'صعب', 'الكتاب ص 34 — تكوّن SO₃ والمطر الحمضي (الشكل 1-13)'),
('essay', 1, 'اذكر التفاعل الذي ينتج عنه ثالث أكسيد الكبريت، واسم الحمض الذي يتكون عندما يختلط برطوبة الجو، وأثر المطر الحمضي الناتج في البيئة.', null, null, null, 'تذكر', 'ذكر حقائق', 'سهل', 'الكتاب ص 34 — حرارة التكوين القياسية (SO₃ والمطر الحمضي)'),
('essay', 2, 'اكتب المعادلة الكيميائية الحرارية لتكوين 1 mol من SO₃(g) من عناصره، علمًا بأن ΔH°f له −396 kJ، ثم اكتب معادلة اتحاده مع الماء، وصف بالاستعانة بالمعادلتين دور SO₃ في تكوين المطر الحمضي.', null, null, null, 'فهم', 'كتابة معادلات ووصف', 'صعب', 'الكتاب ص 34 و ص 38 — تكوّن SO₃ والشكل 1-13 ومسألة 34 (b)'),
('essay', 3, 'غابة تقع قرب منطقة صناعية ينبعث منها ثالث أكسيد الكبريت بكثرة، ولوحظ بعد سنوات موت كثير من أشجارها وتآكل بعض المنشآت المجاورة. صف بالتسلسل ما حدث كيميائيًّا وأدى إلى هذه النتائج.', null, null, null, 'فهم', 'وصف تسلسل في موقف', 'صعب', 'الكتاب ص 34 — الشكل 1-13 (المطر الحمضي والأشجار)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
