insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'يتحد SO₃ مع الماء في الجو مكونًا حمض الكبريتيك H₂SO₄: SO₃ + H₂O → H₂SO₄.', '["","H₂SO₃ يحتوي على ثلاث ذرات أكسجين، ويتكون من SO₂ لا من SO₃؛ فاتحاد SO₃ مع H₂O يعطي أربع ذرات أكسجين.","H₂S لا يحتوي على أكسجين، ويتكون من الهيدروجين والكبريت لا من SO₃ والماء.","HNO₃ حمض يحتوي على النيتروجين، ولا يمكن أن يتكون من SO₃ والماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.405Z"}'::jsonb),
('mcq', 2, 2, 'ينتج SO₃ من تفاعل الكبريت مع الأكسجين: S(s) + 3/2O₂(g) → SO₃(g)  ΔH°f = −396 kJ.', '["تفاعل الكبريت مع الهيدروجين ينتج كبريتيد الهيدروجين H₂S لا SO₃.","تفاعل الكبريت مع الفلور ينتج سادس فلوريد الكبريت SF₆.","","SO₃ ينتج من اتحاد الكبريت بالأكسجين، وحمض الكبريتيك ناتج عن SO₃ لا مصدر له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-07T17:19:00.405Z"}'::jsonb),
('mcq', 3, 3, 'SO₃ غاز خانق، يتسبب في إنتاج المطر الحمضي عندما يختلط بالرطوبة الموجودة في الجو.', '["SO₃ ليس خاملًا؛ فهو يتحد مع الماء مكونًا حمضًا قويًّا يضر بالبيئة.","SO₃ يُنتج في التفاعل S(s) + 3/2O₂(g) → SO₃(g) في الحالة الغازية، ويختلط برطوبة الجو.","SO₃ مركب من الكبريت والأكسجين، والغازات النبيلة عناصر لا مركبات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-07T17:19:00.405Z"}'::jsonb),
('mcq', 4, 1, 'يتحد SO₃ مع الماء مكونًا حمض الكبريتيك: SO₃(g) + H₂O(l) → H₂SO₄(aq)، وهي معادلة موزونة (S واحدة، و H اثنتان، و O أربع في كل طرف).', '["المتفاعل في المطر الحمضي المقصود هو SO₃ لا SO₂، والمعادلة غير موزونة (ثلاث ذرات O مقابل أربع).","","الحمض يتكون من اتحاد SO₃ بالماء (الرطوبة) لا بغاز الهيدروجين، والمعادلة غير موزونة.","هذه معادلة تكوين SO₃ نفسه من عناصره، لا معادلة تكوّن الحمض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-07T17:19:00.406Z"}'::jsonb),
('mcq', 5, 0, 'حمض الكبريتيك حمض قوي يصل إلى الأرض على شكل مطر حمضي، فيدمّر الأشجار والممتلكات ببطء.', '["","المطر الحمضي يضر الأشجار ويدمّرها، ولا يزيد نمو الغابات.","الحمض القوي يُتلف الممتلكات والمباني ولا يحميها.","أثر المطر الحمضي هو إتلاف الأشجار والممتلكات، ولا علاقة له بخفض حرارة الجو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.406Z"}'::jsonb),
('mcq', 6, 2, 'H₂SO₄ حمض قوي يصل إلى الأرض على شكل مطر حمضي، فيدمّر الأشجار والممتلكات ببطء.', '["H₂SO₄ حمض قوي لا ضعيف، وهو يؤثر في الأشجار والممتلكات.","H₂SO₄ حمض، ولذلك يسمى المطر الناتج عنه مطرًا حمضيًّا.","","H₂SO₄ حمض لا قاعدة، رغم أنه يتلف الأشجار فعلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.406Z"}'::jsonb),
('mcq', 7, 1, 'يتكون SO₃ من تفاعل الكبريت مع الأكسجين، ثم يتحد SO₃ مع الماء (الرطوبة) في الجو مكونًا حمض الكبريتيك القوي H₂SO₄ الذي يصل إلى الأرض على شكل مطر حمضي.', '["الترتيب معكوس؛ فـ SO₃ هو الذي يتكون أولًا ثم يتحول إلى H₂SO₄، لا العكس.","","SO₃ لا يتحول إلى كبريت؛ والكبريت هو المادة الأولية التي تتأكسد إلى SO₃.","SO₃ يتكون من الكبريت والأكسجين ويتحول إلى حمض في الجو لا في التربة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-07T17:19:00.406Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينتج ثالث أكسيد الكبريت SO₃ من تفاعل الكبريت مع الأكسجين. وعندما يختلط SO₃ بالرطوبة الموجودة في الجو يتكون حمض الكبريتيك H₂SO₄، وهو حمض قوي يصل إلى الأرض على شكل مطر حمضي، فيدمّر الأشجار والممتلكات ببطء.', '["SO₃ ينتج من تفاعل الكبريت مع الأكسجين","يتكون حمض الكبريتيك H₂SO₄ (حمض قوي)","يصل إلى الأرض مطرًا حمضيًّا يدمّر الأشجار والممتلكات ببطء"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر تفاعل الكبريت مع الأكسجين","marks":1},{"element":"تسمية الحمض H₂SO₄ ووصفه بأنه قوي","marks":1},{"element":"ذكر أثر المطر الحمضي في الأشجار والممتلكات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ذكر التفاعل والحمض والأثر البيئي صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان من الثلاثة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الحمض حمض الكبريتوز H₂SO₃","القول إن SO₃ ينتج من الكبريت والهيدروجين","إغفال الأثر البيئي أو وصفه بأثر مفيد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-07T17:19:00.406Z"}'::jsonb),
('essay', 2, null::int, null, null, 'معادلة التكوين: S(s) + 3/2O₂(g) → SO₃(g)  ΔH°f = −396 kJ. ومعادلة اتحاده مع الماء: SO₃(g) + H₂O(l) → H₂SO₄(aq). دور SO₃: يتكون غاز SO₃ الخانق من تفاعل الكبريت مع الأكسجين، ثم يختلط بالرطوبة الموجودة في الجو فيتكون حمض الكبريتيك، وهو حمض قوي يسقط على الأرض على شكل مطر حمضي يدمّر الأشجار والممتلكات ببطء.', '["S(s) + 3/2O₂(g) → SO₃(g)  ΔH°f = −396 kJ","SO₃(g) + H₂O(l) → H₂SO₄(aq)","SO₃ غاز خانق يختلط برطوبة الجو","H₂SO₄ حمض قوي يسقط مطرًا حمضيًّا ويدمّر الأشجار والممتلكات"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة تكوين SO₃ بالمعاملات والحالات و ΔH","marks":1},{"element":"معادلة اتحاد SO₃ مع الماء موزونة","marks":1},{"element":"وصف دور SO₃ في تكوين المطر الحمضي","marks":1},{"element":"ذكر أثر المطر الحمضي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلتان صحيحتان، ووصف كامل لدور SO₃ وأثر المطر الحمضي"},{"level":"2–3 درجات","description":"معادلة واحدة صحيحة مع وصف صحيح، أو معادلتان مع وصف ناقص"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة معامل O₂ عددًا صحيحًا وتكوين 2 mol من SO₃","كتابة SO₂ بدل SO₃ في معادلة تكوين الحمض","إعطاء ΔH إشارة موجبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.406Z"}'::jsonb),
('essay', 3, null::int, null, null, '1) يتصاعد غاز SO₃ (وهو ناتج عن تفاعل الكبريت مع الأكسجين) إلى الجو. 2) يختلط SO₃ بالرطوبة الموجودة في الجو فيتحد مع الماء مكونًا حمض الكبريتيك: SO₃ + H₂O → H₂SO₄. 3) حمض الكبريتيك حمض قوي يصل إلى الأرض على شكل مطر حمضي. 4) يدمّر المطر الحمضي الأشجار والممتلكات (المنشآت) ببطء، ولذلك ظهرت النتائج بعد سنوات.', '["انبعاث SO₃ إلى الجو","اتحاده برطوبة الجو مكونًا H₂SO₄","H₂SO₄ حمض قوي يسقط مطرًا حمضيًّا","تدمير الأشجار والممتلكات ببطء (تفسير تأخر ظهور الأثر)"]'::jsonb, '[]'::jsonb, '[{"element":"انبعاث SO₃ ومصدره","marks":1},{"element":"تكوّن H₂SO₄ من SO₃ والرطوبة","marks":1},{"element":"سقوط المطر الحمضي","marks":1},{"element":"ربط النتائج بتدمير الأشجار والممتلكات ببطء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسلسل كامل وصحيح للمراحل الأربع مع الربط بالنتائج"},{"level":"2–3 درجات","description":"تسلسل صحيح مع إغفال مرحلة أو عدم الربط بالنتائج"},{"level":"1 درجة","description":"ذكر المطر الحمضي فقط دون تسلسل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن SO₃ نفسه يسقط على الأشجار دون تكوّن حمض","إغفال دور الرطوبة في الجو","عكس ترتيب المراحل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.406Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
