('mcq', 3, 'في التعبير عن سرعة التفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g)، علامَ يدل الرمز [NO₂]؟', null, null, '["عدد مولات NO₂ في المعادلة الموزونة","كتلة غاز NO₂ بالجرام","الضغط الجزئي لغاز NO₂","التركيز المولاري لغاز NO₂"]'::jsonb, 'تذكر', 'تذكر رمز', 'سهل', 'الكتاب ص 51 — التعبير عن سرعة التفاعل'),
('mcq', 4, 'أيّ العبارات الآتية تعبّر عن سرعة تفاعل كيميائي؟', null, null, '["كان تركيز المادة X عند بدء التفاعل 0.020 mol/L","انخفض تركيز المادة X بمقدار 0.020 mol/L في كل ثانية","استغرق تحول المادة X كلها إلى نواتج 20 s","انخفضت كتلة المادة X بمقدار 2.0 g في أثناء التفاعل"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 51 — التعبير عن سرعة التفاعل'),
('mcq', 5, 'يمثل المنحنيان الآتيان تغير التركيز مع الزمن لمادتين في التفاعل A → B. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c2-l1a-conc-two-curves.svg","alt":"منحنيان لتغير التركيز (mol/L) مع الزمن (s) في أثناء التفاعل A → B، دون تسمية المادة: المنحنى (س) يبدأ من 0.00 ويتزايد إلى 0.30 عند 10 s ثم 0.50 عند 20 s ثم 0.60 عند 30 s ثم 0.65 عند 40 s. والمنحنى (ص) يبدأ من 0.80 ويتناقص إلى 0.50 عند 10 s ثم 0.30 عند 20 s ثم 0.20 عند 30 s ثم 0.15 عند 40 s."}]'::jsonb, '["المنحنى (س) يمثل [A] لأن تركيز المتفاعل يزداد مع مرور الزمن","المنحنى (س) يمثل [B] لأن تركيز الناتج يزداد مع مرور الزمن","المنحنى (ص) يمثل [B] لأن تركيز الناتج يقل مع مرور الزمن","المنحنيان يمثلان المادة نفسها في تجربتين مختلفتين"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 51، 70 — سرعة التفاعل وتغير التراكيز (س30)'),
('mcq', 6, 'أيّ الوحدات الآتية لا تصلح للتعبير عن سرعة تفاعل كيميائي؟', null, null, '["M/min","M/s","mol/L·h","L/s"]'::jsonb, 'فهم', 'تمييز وحدات', 'صعب', 'الكتاب ص 74 — اختبار مقنن (س4)'),
('mcq', 7, 'كيف تُحدَّد سرعة تفاعل كيميائي معيّن؟', null, null, '["نظريًّا من معاملات المواد في المعادلة الموزونة","من قيمة ΔH للتفاعل المسجّلة في الجداول","عمليًّا بقياس تراكيز المتفاعلات أو النواتج في أثناء التفاعل","من الكتل المولية للمتفاعلات والنواتج"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 51 — التعبير عن سرعة التفاعل'),
('essay', 1, 'عرّف سرعة التفاعل الكيميائي، واذكر وحدتها، ثم فسّر لماذا تكون قيمة سرعة تكوّن النواتج Δ[products]/Δt موجبة دون حاجة إلى إشارة سالبة.', null, null, null, 'فهم', 'تعريف وتفسير', 'سهل', 'الكتاب ص 51 — التعبير عن سرعة التفاعل'),
('essay', 2, 'يمثل المنحنيان الآتيان تغير تركيزي A وB مع الزمن في التفاعل A → B. صف ما يحدث لكل من التركيزين في أثناء التفاعل، واكتب تعبيرين لمتوسط سرعة التفاعل: أحدهما بدلالة A والآخر بدلالة B، مبيّنًا سبب الاختلاف في الإشارة بينهما.', null, '[{"src":"qimg/chem22/c2-l1a-conc-ab.svg","alt":"منحنيان لتغير التركيز (mol/L) مع الزمن (s) للتفاعل A → B. منحنى [A] يتناقص: 0.80 عند 0 s، و0.50 عند 10 s، و0.30 عند 20 s، و0.20 عند 30 s، و0.15 عند 40 s. ومنحنى [B] يتزايد: 0.00 عند 0 s، و0.30 عند 10 s، و0.50 عند 20 s، و0.60 عند 30 s، و0.65 عند 40 s. خطوط الشبكة كل 0.10 mol/L وكل 10 s."}]'::jsonb, null, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 51–52، 70 — التعبير عن سرعة التفاعل (س30، س32)'),
('essay', 3, 'قيّم صحة العبارة الآتية، وفسّر إجابتك: «يمكن تحديد سرعة تفاعل كيميائي من خلال معرفة نسبة مولات المواد المتفاعلة في المعادلة الموزونة».', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 51، 71 — التعبير عن سرعة التفاعل (س51)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'سرعة التفاعل الكيميائي هي التغير في تركيز المواد المتفاعلة أو الناتجة في وحدة الزمن، ويُعبّر عنها بوحدة mol/L·s.', '["السرعة تُعبّر عن تغير التركيز (لا الكتلة) منسوبًا إلى الزمن، ويمكن حسابها من المتفاعلات أو من النواتج.","الزمن وحده ليس سرعة؛ فالسرعة تغيّرٌ في التركيز مقسوم على التغير في الزمن.","","عدد التصادمات يفسّر السرعة وفق نظرية التصادم، لكنه ليس تعريفها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('mcq', 2, 0, 'السرعة = Δ[التركيز] ÷ Δt، أي (mol/L) ÷ s = mol/L·s؛ فالوحدة المعتادة لسرعة التفاعل هي mol/L·s.', '["","هذه وحدة التركيز المولاري وحده، دون القسمة على الزمن.","هذه وحدة حجم في وحدة الزمن، ولا تتضمن كمية المادة بالمول.","الزمن يقع في المقام لا في البسط؛ فالسرعة = التغير في التركيز ÷ التغير في الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('mcq', 3, 3, 'تشير الأقواس المربعة حول الصيغة الجزيئية إلى التركيز المولاري؛ فـ [NO₂] هو التركيز المولاري لغاز NO₂ بوحدة mol/L.', '["الأقواس المربعة تدل على التركيز المولاري، لا على المعامل في المعادلة.","الأقواس المربعة لا تعني الكتلة؛ بل تعني التركيز بوحدة mol/L.","الأقواس المربعة تدل على التركيز المولاري M وليس على الضغط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('mcq', 4, 1, 'سرعة التفاعل هي التغير في تركيز المواد المتفاعلة أو الناتجة في وحدة الزمن؛ وعبارة «انخفض تركيز X بمقدار 0.020 mol/L في كل ثانية» تتضمن تغيرًا في التركيز منسوبًا إلى الزمن، أي سرعة مقدارها 0.020 mol/L·s.', '["هذا تركيز عند لحظة واحدة، ولا يتضمن تغيرًا في التركيز ولا زمنًا.","","هذا زمن فقط؛ والسرعة تغير في التركيز مقسوم على التغير في الزمن.","هذا تغير في الكتلة دون نسبته إلى الزمن، والسرعة تُعبَّر بتغير التركيز في وحدة الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('mcq', 5, 1, 'في أثناء التفاعل A → B يُستهلك A فيقل تركيزه، ويتكوّن B فيزداد تركيزه بدءًا من الصفر؛ إذن المنحنى المتزايد (س) يمثل [B] لأن تركيز الناتج يزداد مع مرور الزمن.', '["تركيز المتفاعل A يقل مع الزمن لأنه يُستهلك؛ فالمنحنى المتزايد يمثل الناتج.","","الناتج يتكوّن في أثناء التفاعل فيزداد تركيزه، أما المنحنى المتناقص (ص) فيمثل المتفاعل.","أحد المنحنيين يبدأ من الصفر ويزداد (ناتج)، والآخر يتناقص (متفاعل)؛ فهما لمادتين مختلفتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('mcq', 6, 3, 'وحدة السرعة يجب أن تكون تركيزًا (كمية مادة ÷ حجم) مقسومًا على زمن؛ أما L/s فهي حجم في وحدة الزمن ولا تتضمن كمية المادة، فهي الوحدة التي لا تصلح.', '["M تعني mol/L، فـ M/min تغير في التركيز في وحدة الزمن، وهي وحدة صالحة للسرعة.","M/s تعني mol/L·s، أي تغير في التركيز في كل ثانية، فهي وحدة صالحة للسرعة.","هي تغير في التركيز (mol/L) في كل ساعة؛ وحدة غير مألوفة لكنها صالحة للسرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('mcq', 7, 2, 'يمكن تحديد سرعة التفاعل عمليًّا بحساب تراكيز المواد المتفاعلة أو الناتجة في أثناء التفاعل، ولا يمكن حسابها من المعادلات الموزونة.', '["لا يمكن حساب سرعة التفاعل من المعادلة الموزونة؛ فهي تُحدَّد تجريبيًّا.","ΔH تعبّر عن الحرارة المنطلقة أو الممتصة، ولا تدل على سرعة التفاعل.","","الكتل المولية لا تحدد التغير في التركيز مع الزمن؛ فالسرعة تُقاس تجريبيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('essay', 1, null::int, null, null, 'سرعة التفاعل الكيميائي هي التغير في تركيز المواد المتفاعلة أو الناتجة في وحدة الزمن، ووحدتها mol/L·s. وتكون Δ[products]/Δt موجبة لأن تركيز النواتج يزداد مع استمرار التفاعل، فيكون التغير في تركيزها موجبًا، والتغير في الزمن موجبًا أيضًا.', '["التغير في التركيز","للمتفاعلات أو النواتج","في وحدة الزمن","الوحدة mol/L·s","تركيز النواتج يزداد فيكون التغير موجبًا"]'::jsonb, '[]'::jsonb, '[{"element":"التغير في التركيز للمتفاعلات أو النواتج","marks":1},{"element":"في وحدة الزمن","marks":1},{"element":"الوحدة mol/L·s","marks":1},{"element":"تفسير الإشارة الموجبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل ووحدة صحيحة وتفسير سليم"},{"level":"2–3 درجات","description":"تعريف ناقص أو غياب الوحدة أو التفسير"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف السرعة بأنها الزمن اللازم لانتهاء التفاعل","كتابة الوحدة mol/L دون الزمن","القول إن تركيز النواتج يقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يتناقص [A] من 0.80 mol/L إلى 0.15 mol/L لأن A يُستهلك، ويزداد [B] من 0.00 mol/L إلى 0.65 mol/L لأن B يتكوّن. متوسط السرعة بدلالة A: Rate = −Δ[A]/Δt، وبدلالة B: Rate = Δ[B]/Δt. تُوضع الإشارة السالبة مع A لأن Δ[A] سالب، فتصبح السرعة موجبة، أما Δ[B] فموجب أصلًا.', '["[A] يتناقص لأن A يُستهلك","[B] يزداد لأن B يتكوّن","Rate = −Δ[A]/Δt","Rate = Δ[B]/Δt","الإشارة السالبة تجعل السرعة موجبة لأن Δ[A] سالب"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تغير [A]","marks":1},{"element":"وصف تغير [B]","marks":1},{"element":"التعبير بدلالة A","marks":1},{"element":"التعبير بدلالة B","marks":1},{"element":"تفسير الإشارة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف صحيح للتركيزين والتعبيران صحيحان مع التفسير"},{"level":"3–4 درجات","description":"خطأ في أحد التعبيرين أو غياب التفسير"},{"level":"1–2 درجة","description":"وصف التغير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة −Δ[B]/Δt للناتج","إهمال الإشارة السالبة مع المتفاعل","عدّ المنحنى المتزايد للمتفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ لأن سرعة التفاعل هي التغير في تركيز المتفاعلات أو النواتج في وحدة الزمن، وهذا التغير لا يظهر في المعادلة الموزونة التي تبين نسب المولات فقط ولا تتضمن أي معلومة عن الزمن. لذلك تُحدَّد السرعة عمليًّا بقياس تراكيز المتفاعلات أو النواتج على فترات زمنية في أثناء التفاعل.', '["العبارة غير صحيحة","السرعة تغير في التركيز في وحدة الزمن","المعادلة الموزونة لا تتضمن الزمن","السرعة تُحدَّد تجريبيًّا بقياس التراكيز"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"الاستناد إلى تعريف السرعة","marks":1},{"element":"المعادلة لا تتضمن معلومات زمنية","marks":1},{"element":"التحديد التجريبي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتفسير كامل"},{"level":"2–3 درجات","description":"حكم صحيح وتفسير ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"حكم خاطئ أو لا إجابة"}]'::jsonb, '["الحكم بصحة العبارة","الخلط بين نسب المولات في المعادلة وسرعة التفاعل","عدم ذكر طريقة تحديد السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.409Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
