on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C2-L1-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في تفاعلٍ ما انخفض تركيز المادة المتفاعلة X من 0.500 M إلى 0.350 M خلال 6.00 s. ما متوسط سرعة التفاعل؟', null, null, '["0.0583 mol/L·s","0.0250 mol/L·s","−0.0250 mol/L·s","0.900 mol/L·s"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 52 — المثال 2-1'),
('mcq', 2, 'في التفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g) كان [NO] = 0.000 M عند بداية التفاعل، وأصبح 0.024 M بعد 3.00 s. ما متوسط سرعة التفاعل بدلالة تكوّن NO؟', null, null, '["0.0080 mol/L·s","0.072 mol/L·s","125 mol/L·s","−0.0080 mol/L·s"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 51 — حساب سرعة تكوّن NO'),
('mcq', 3, 'يمثل المنحنى الآتي تغير تركيزي A وB مع الزمن للتفاعل A → B. ما متوسط سرعة التفاعل بدلالة استهلاك A خلال أول 10 s؟', null, '[{"src":"qimg/chem22/c2-l1a-conc-ab.svg","alt":"منحنيان لتغير التركيز (mol/L) مع الزمن (s) للتفاعل A → B. منحنى [A] يتناقص: 0.80 عند 0 s، و0.50 عند 10 s، و0.30 عند 20 s، و0.20 عند 30 s، و0.15 عند 40 s. ومنحنى [B] يتزايد: 0.00 عند 0 s، و0.30 عند 10 s، و0.50 عند 20 s، و0.60 عند 30 s، و0.65 عند 40 s. خطوط الشبكة كل 0.10 mol/L وكل 10 s."}]'::jsonb, '["0.080 mol/L·s","0.050 mol/L·s","0.015 mol/L·s","0.030 mol/L·s"]'::jsonb, 'تطبيق', 'حساب من منحنى', 'متوسط', 'الكتاب ص 52 — معادلة متوسط سرعة التفاعل'),
('mcq', 4, 'يمثل المنحنى الآتي تغير تركيزي A وB مع الزمن للتفاعل A → B. ما متوسط سرعة تكوّن B خلال الفترة من 0 s إلى 20 s؟', null, '[{"src":"qimg/chem22/c2-l1a-conc-ab.svg","alt":"منحنيان لتغير التركيز (mol/L) مع الزمن (s) للتفاعل A → B. منحنى [A] يتناقص: 0.80 عند 0 s، و0.50 عند 10 s، و0.30 عند 20 s، و0.20 عند 30 s، و0.15 عند 40 s. ومنحنى [B] يتزايد: 0.00 عند 0 s، و0.30 عند 10 s، و0.50 عند 20 s، و0.60 عند 30 s، و0.65 عند 40 s. خطوط الشبكة كل 0.10 mol/L وكل 10 s."}]'::jsonb, '["0.015 mol/L·s","0.050 mol/L·s","0.025 mol/L·s","0.040 mol/L·s"]'::jsonb, 'تطبيق', 'حساب من منحنى', 'متوسط', 'الكتاب ص 51–52 — سرعة تكوّن النواتج'),
('mcq', 5, 'يمثل المنحنى الآتي تغير تركيزي A وB مع الزمن للتفاعل A → B. بمقارنة متوسط سرعة استهلاك A في الفترة (0–10 s) بمتوسطها في الفترة (20–30 s)، ماذا تستنتج؟', null, '[{"src":"qimg/chem22/c2-l1a-conc-ab.svg","alt":"منحنيان لتغير التركيز (mol/L) مع الزمن (s) للتفاعل A → B. منحنى [A] يتناقص: 0.80 عند 0 s، و0.50 عند 10 s، و0.30 عند 20 s، و0.20 عند 30 s، و0.15 عند 40 s. ومنحنى [B] يتزايد: 0.00 عند 0 s، و0.30 عند 10 s، و0.50 عند 20 s، و0.60 عند 30 s، و0.65 عند 40 s. خطوط الشبكة كل 0.10 mol/L وكل 10 s."}]'::jsonb, '["تزداد السرعة من 0.010 mol/L·s إلى 0.030 mol/L·s مع مرور الزمن","تقل السرعة من 0.030 mol/L·s إلى 0.010 mol/L·s مع تناقص تركيز A","تبقى السرعة ثابتة عند 0.020 mol/L·s في الفترتين","تقل السرعة من 0.080 mol/L·s إلى 0.030 mol/L·s مع تناقص تركيز A"]'::jsonb, 'تحليل', 'مقارنة سرعات', 'صعب', 'الكتاب ص 56 — مختبر حل المشكلات (تفسير البيانات)'),
('mcq', 6, 'يمثل المنحنى الآتي تغير تركيز N₂O₅ مع الزمن في التفاعل 2N₂O₅(g) → 4NO₂(g) + O₂(g). ما متوسط سرعة التفاعل بدلالة استهلاك N₂O₅ في الفترة (0–20 min)؟', null, '[{"src":"qimg/chem22/c2-l1a-conc-n2o5.svg","alt":"منحنى تغير تركيز N₂O₅ (mol/L) مع الزمن (min) في التفاعل 2N₂O₅(g) → 4NO₂(g) + O₂(g): 0.01756 عند 0 min، و0.00933 عند 20 min، و0.00531 عند 40 min، و0.00295 عند 60 min، و0.00167 عند 80 min، و0.00094 عند 100 min. المنحنى يتناقص بسرعة في البداية ثم يتناقص ببطء أكبر."}]'::jsonb, '["4.12 × 10⁻⁴ mol/L·min","8.23 × 10⁻³ mol/L·min","4.67 × 10⁻⁴ mol/L·min","6.86 × 10⁻⁶ mol/L·min"]'::jsonb, 'تطبيق', 'حساب من منحنى', 'صعب', 'الكتاب ص 56 — مختبر حل المشكلات: تحلل N₂O₅'),
('mcq', 7, 'وُجد أن متوسط سرعة تفاعل كيميائي 3.0 × 10⁻³ mol/L·s. ما مقدار هذه السرعة بوحدة mol/L·min؟', null, null, '["5.0 × 10⁻⁵ mol/L·min","3.0 × 10⁻³ mol/L·min","1.8 mol/L·min","0.18 mol/L·min"]'::jsonb, 'تطبيق', 'تحويل وحدات', 'متوسط', 'الكتاب ص 70 — إتقان حل المسائل (س36)'),
('essay', 1, 'يتفاعل اليود والكلور في الحالة الغازية: I₂ + Cl₂ → 2ICl. إذا كان [I₂] يساوي 0.500 M عند بداية التفاعل، وأصبح 0.380 M بعد مرور 3.00 min، فاحسب متوسط سرعة التفاعل بوحدة mol/L·min، ثم حوّلها إلى وحدة mol/L·s.', null, null, null, 'تطبيق', 'حساب بخطوات', 'متوسط', 'الكتاب ص 75 — اختبار مقنن (س11)'),
('essay', 2, 'يمثل المنحنى الآتي تغير تركيز N₂O₅ مع الزمن في التفاعل 2N₂O₅(g) → 4NO₂(g) + O₂(g). احسب متوسط سرعة التفاعل بدلالة استهلاك N₂O₅ في كل من الفترات (0–20 min) و(40–60 min) و(80–100 min) بوحدة mol/L·min، ثم صف كيف تتغير السرعة مع الزمن وفسّر ذلك بنظرية التصادم.', null, '[{"src":"qimg/chem22/c2-l1a-conc-n2o5.svg","alt":"منحنى تغير تركيز N₂O₅ (mol/L) مع الزمن (min) في التفاعل 2N₂O₅(g) → 4NO₂(g) + O₂(g): 0.01756 عند 0 min، و0.00933 عند 20 min، و0.00531 عند 40 min، و0.00295 عند 60 min، و0.00167 عند 80 min، و0.00094 عند 100 min. المنحنى يتناقص بسرعة في البداية ثم يتناقص ببطء أكبر."}]'::jsonb, null, 'تحليل', 'حساب وتفسير بيانات', 'صعب', 'الكتاب ص 56 — مختبر حل المشكلات: تحلل N₂O₅'),
('essay', 3, 'يتفاعل الماغنسيوم مع حمض الهيدروكلوريك: Mg(s) + 2HCl(aq) → H₂(g) + MgCl₂(aq). إذا كانت كتلة Mg تساوي 4.86 g لحظة بدء التفاعل، وبقي منها 2.43 g بعد مرور 2.00 min، فاحسب متوسط سرعة التفاعل بدلالة عدد مولات Mg المستهلكة في الدقيقة. (الكتلة المولية لـ Mg = 24.31 g/mol)', null, null, null, 'تطبيق', 'حساب بخطوات', 'متوسط', 'الكتاب ص 70 — إتقان حل المسائل (س35)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L1-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'Rate = −Δ[X]/Δt = −(0.350 M − 0.500 M)/(6.00 s − 0.00 s) = 0.150/6.00 = 0.0250 mol/L·s.', '["قُسم التركيز النهائي 0.350 M على الزمن بدلًا من التغير في التركيز 0.150 M.","","نُسيت الإشارة السالبة في المعادلة؛ فسرعة التفاعل قيمة موجبة دائمًا.","ضُرب التغير في التركيز في الزمن بدلًا من القسمة عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.410Z"}'::jsonb),
('mcq', 2, 0, 'Rate = Δ[NO]/Δt = (0.024 M − 0.000 M)/(3.00 s − 0.00 s) = 0.0080 mol/L·s.', '["","ضُرب التركيز في الزمن (0.024 × 3.00) بدلًا من القسمة عليه.","قُلبت النسبة فقُسم الزمن على التركيز (3.00 ÷ 0.024).","سرعة تكوّن الناتج موجبة دون إشارة سالبة لأن تركيزه يزداد؛ والإشارة السالبة تُستعمل للمتفاعلات فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.410Z"}'::jsonb),
('mcq', 3, 3, 'من المنحنى: [A] = 0.80 mol/L عند 0 s و0.50 mol/L عند 10 s؛ Rate = −(0.50 − 0.80)/(10 − 0) = 0.30/10 = 0.030 mol/L·s.', '["قُسم التركيز الابتدائي 0.80 mol/L على الزمن بدلًا من التغير في التركيز 0.30 mol/L.","قُسم التركيز بعد 10 s (0.50 mol/L) على الزمن بدلًا من التغير في التركيز.","قُسم التغير في التركيز 0.30 mol/L على 20 s بدلًا من الفترة الصحيحة 10 s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-07T17:19:00.410Z"}'::jsonb),
('mcq', 4, 2, 'من المنحنى: [B] = 0.00 mol/L عند 0 s و0.50 mol/L عند 20 s؛ Rate = Δ[B]/Δt = (0.50 − 0.00)/(20 − 0) = 0.025 mol/L·s.', '["قُرئ [B] عند 10 s (0.30 mol/L) بدلًا من قيمته عند 20 s ثم قُسم على 20 s.","قُسم التغير في [B] (0.50 mol/L) على 10 s بدلًا من 20 s.","","خُلط بين المنحنيين؛ فقُسم التركيز الابتدائي لـ A (0.80 mol/L) على 20 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-07T17:19:00.411Z"}'::jsonb),
('mcq', 5, 1, 'الفترة (0–10 s): Rate = (0.80 − 0.50)/10 = 0.030 mol/L·s؛ والفترة (20–30 s): Rate = (0.30 − 0.20)/10 = 0.010 mol/L·s. إذن تقل السرعة من 0.030 mol/L·s إلى 0.010 mol/L·s مع تناقص تركيز A، لأن عدد الجسيمات المتصادمة يقل.', '["قُلبت الفترتان؛ فالتغير في [A] في الفترة الأولى (0.30) أكبر منه في الفترة الثالثة (0.10).","","التغير في [A] ليس متساويًا في الفترتين، فالسرعة ليست ثابتة.","قُسمت التراكيز نفسها على الزمن بدلًا من التغير في التركيز في كل فترة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-11-07T17:19:00.411Z"}'::jsonb),
('mcq', 6, 0, 'Rate = −([N₂O₅]₂₀ − [N₂O₅]₀)/Δt = −(0.00933 − 0.01756)/(20.0 − 0) = 0.00823/20.0 = 4.12 × 10⁻⁴ mol/L·min.', '["","هذا التغير في التركيز (0.01756 − 0.00933) دون القسمة على الزمن 20.0 min.","قُسم التركيز عند 20 min (0.00933) على الزمن بدلًا من التغير في التركيز.","هذه القيمة بوحدة mol/L·s (بعد القسمة على 60)، لا بوحدة mol/L·min المطلوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (49%)"}],"at":"2026-11-07T17:19:00.411Z"}'::jsonb),
('mcq', 7, 3, 'في الدقيقة الواحدة 60 s، فالتغير في التركيز في الدقيقة أكبر 60 مرة: 3.0 × 10⁻³ mol/L·s × 60 s/min = 0.18 mol/L·min.', '["قُسمت القيمة على 60 بدلًا من الضرب؛ ففي الدقيقة 60 s يتغير فيها التركيز أكثر.","لم تُحوَّل القيمة؛ والتحويل من الثانية إلى الدقيقة يتطلب الضرب في 60.","خطأ في منزلة الفاصلة عند الضرب: 3.0 × 10⁻³ × 60 = 0.18 لا 1.8.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.411Z"}'::jsonb),
('essay', 1, null::int, null, null, 'Rate = −Δ[I₂]/Δt = −(0.380 M − 0.500 M)/(3.00 min) = 0.120/3.00 = 0.0400 mol/L·min. وبالتحويل: 0.0400 ÷ 60 = 6.67 × 10⁻⁴ mol/L·s.', '["كتابة Rate = −Δ[I₂]/Δt","Δ[I₂] = −0.120 M","Rate = 0.0400 mol/L·min","Rate = 6.67 × 10⁻⁴ mol/L·s"]'::jsonb, '["Rate = −([I₂]t₂ − [I₂]t₁)/(t₂ − t₁)","Δ[I₂] = 0.380 M − 0.500 M = −0.120 M","Rate = −(−0.120 M)/(3.00 min) = 0.0400 mol/L·min","1 min = 60 s ⇐ 0.0400/60 = 6.67 × 10⁻⁴ mol/L·s"]'::jsonb, '[{"element":"المعادلة بالإشارة الصحيحة","marks":1},{"element":"حساب التغير في التركيز","marks":1},{"element":"السرعة بوحدة mol/L·min","marks":1},{"element":"التحويل إلى mol/L·s","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات وناتجان صحيحان بوحداتهما"},{"level":"2–3 درجات","description":"الناتج الأول صحيح وخطأ في التحويل أو العكس"},{"level":"1 درجة","description":"المعادلة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الإشارة السالبة فتظهر السرعة سالبة","الضرب في 60 بدلًا من القسمة عند التحويل إلى الثانية","استعمال 0.380 M بدلًا من التغير في التركيز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.411Z"}'::jsonb),
('essay', 2, null::int, null, null, '(0–20 min): (0.01756 − 0.00933)/20.0 = 4.12 × 10⁻⁴ mol/L·min. (40–60 min): (0.00531 − 0.00295)/20.0 = 1.18 × 10⁻⁴ mol/L·min. (80–100 min): (0.00167 − 0.00094)/20.0 = 3.7 × 10⁻⁵ mol/L·min. تقل السرعة مع مرور الزمن؛ لأن تركيز N₂O₅ يتناقص فيقل عدد جزيئاته في وحدة الحجم، فيقل عدد التصادمات بينها في وحدة الزمن، ومن ثم يقل عدد التصادمات المثمرة.', '["4.12 × 10⁻⁴ mol/L·min","1.18 × 10⁻⁴ mol/L·min","3.7 × 10⁻⁵ mol/L·min","السرعة تتناقص مع الزمن","نقص التركيز يقلل عدد التصادمات"]'::jsonb, '["Rate = −Δ[N₂O₅]/Δt","(0–20 min): 0.00823/20.0 = 4.12 × 10⁻⁴ mol/L·min","(40–60 min): 0.00236/20.0 = 1.18 × 10⁻⁴ mol/L·min","(80–100 min): 0.00073/20.0 = 3.7 × 10⁻⁵ mol/L·min","المقارنة: 4.12 × 10⁻⁴ > 1.18 × 10⁻⁴ > 3.7 × 10⁻⁵"]'::jsonb, '[{"element":"سرعة الفترة الأولى","marks":1},{"element":"سرعة الفترة الثانية","marks":1},{"element":"سرعة الفترة الثالثة","marks":1},{"element":"وصف التغير","marks":1},{"element":"التفسير بنظرية التصادم","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ثلاث سرعات صحيحة ووصف وتفسير سليمان"},{"level":"3–4 درجات","description":"خطأ في سرعة واحدة أو تفسير ناقص"},{"level":"1–2 درجة","description":"سرعة واحدة صحيحة أو وصف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة التركيز نفسه على الزمن بدل التغير فيه","قراءة قيم خاطئة من المنحنى","تفسير النقص بنقص طاقة التنشيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (49%)"}],"at":"2026-11-07T17:19:00.411Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الكتلة المستهلكة = 4.86 − 2.43 = 2.43 g؛ عدد المولات = 2.43 ÷ 24.31 = 0.100 mol؛ متوسط السرعة = 0.100 mol ÷ 2.00 min = 0.0500 mol/min.', '["الكتلة المستهلكة 2.43 g","عدد المولات 0.100 mol","السرعة 0.0500 mol/min"]'::jsonb, '["كتلة Mg المستهلكة = 4.86 g − 2.43 g = 2.43 g","n = m ÷ M = 2.43 g ÷ 24.31 g/mol = 0.100 mol","Rate = 0.100 mol ÷ 2.00 min = 0.0500 mol/min"]'::jsonb, '[{"element":"الكتلة المستهلكة","marks":1},{"element":"التحويل إلى مولات","marks":1},{"element":"القسمة على الزمن والوحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الخطوات الثلاث صحيحة مع الوحدة"},{"level":"2 درجتان","description":"خطأ في خطوة واحدة"},{"level":"1 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال الكتلة المتبقية بدلًا من المستهلكة","إهمال التحويل إلى مولات (1.22 g/min)","عدم القسمة على الزمن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.412Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C2-L1-O02') and x.type = v.type and x.number = v.number
