insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C2-L1-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما شرطا التصادم المثمر (الفعّال) بين جسيمات المواد المتفاعلة؟', null, null, '["التصادم في الاتجاه الصحيح، وبوجود عامل محفّز في الوسط","التصادم بطاقة كافية، وفي درجة حرارة الغرفة تحديدًا","أن تكون المواد غازية، وأن تتصادم بسرعة ثابتة","التصادم في الاتجاه الصحيح، وبطاقة كافية لتكوين المعقد المنشط"]'::jsonb, 'تذكر', 'تذكر شروط', 'سهل', 'الكتاب ص 55 — الجدول 2-1 شروط التصادم الفعال'),
('mcq', 2, 'يبين الشكل الآتي اتجاهين لتصادم جزيء CO مع جزيء NO₂. إذا كانت طاقة التصادم كافية في الحالتين، ففي أيّهما يمكن أن يحدث التفاعل؟', null, '[{"src":"qimg/chem22/c2-l1a-collision-orient.svg","alt":"شكل من لوحتين لتصادم جزيء CO مع جزيء NO₂ (الكربون رمادي داكن، والنيتروجين أزرق، والأكسجين أحمر)، والسهمان يبيّنان اقتراب الجزيئين أحدهما من الآخر. في اللوحة (س): ذرة الأكسجين في جزيء CO هي المواجهة لذرة النيتروجين في جزيء NO₂. وفي اللوحة (ص): ذرة الكربون في جزيء CO هي المواجهة لإحدى ذرتي الأكسجين في جزيء NO₂."}]'::jsonb, '["(س)؛ لأن ذرة الأكسجين في CO تواجه ذرة النيتروجين في NO₂","(ص)؛ لأن ذرة الكربون في CO تواجه ذرة أكسجين في NO₂","(س) و(ص) معًا؛ لأن طاقة التصادم كافية في الحالتين","لا يحدث تفاعل في أيّ منهما؛ لأن الجزيئين مختلفان"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط'),
('mcq', 3, 'تصادم جزيئان بطاقة أكبر كثيرًا من طاقة التنشيط، لكن في اتجاه غير صحيح. أيّ شرطي التصادم المثمر لم يتحقق؟', null, null, '["شرط الاتجاه الصحيح","شرط الطاقة الكافية","الشرطان كلاهما","لم يختل أيّ شرط، فالتصادم مثمر"]'::jsonb, 'فهم', 'تطبيق شروط', 'متوسط', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط'),
('mcq', 4, 'أيّ العبارات الآتية تصف العلاقة بين شرطي التصادم المثمر وصفًا صحيحًا؟', null, null, '["يكفي تحقق أحد الشرطين لكي يحدث التفاعل","تحقق شرط الطاقة الكافية يضمن تحقق شرط الاتجاه الصحيح","يجب تحقق الشرطين معًا، ولا يغني أحدهما عن الآخر","شرط الاتجاه الصحيح لازم في تفاعلات الغازات فقط"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 54–55 — الجدول 2-1 شروط التصادم الفعال'),
('mcq', 5, 'في التفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g)، ما الاتجاه الصحيح للتصادم الذي يمكن أن يؤدي إلى التفاعل؟', null, null, '["أن ترتبط ذرة الأكسجين في CO بذرة النيتروجين في NO₂","أن ترتبط ذرة الكربون في CO بذرة النيتروجين في NO₂","أن ترتبط ذرة الأكسجين في CO بذرة أكسجين من NO₂","أن ترتبط ذرة الكربون في CO بذرة أكسجين من NO₂"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط'),
('mcq', 6, 'ما المقصود بالطاقة الكافية التي يجب أن يتصادم بها جسيمان حتى يكون التصادم مثمرًا؟', null, null, '["طاقة تساوي طاقة التنشيط أو تزيد عليها، فيتكون المعقد المنشط","طاقة تساوي الطاقة المنطلقة من التفاعل ΔH","طاقة تساوي طاقة النواتج بعد انتهاء التفاعل","أيّ مقدار من الطاقة الحركية مهما كان صغيرًا"]'::jsonb, 'تذكر', 'تذكر شرط', 'سهل', 'الكتاب ص 54–55 — طاقة التنشيط والجدول 2-1'),
('mcq', 7, 'أيّ التصادمات الآتية بين جزيء CO وجزيء NO₂ يُعدّ تصادمًا مثمرًا؟', null, null, '["تصادم في اتجاه غير صحيح بطاقة أكبر من طاقة التنشيط","تصادم في الاتجاه الصحيح بطاقة أقل من طاقة التنشيط","تصادم في الاتجاه الصحيح بطاقة أكبر من طاقة التنشيط","تصادم في اتجاه غير صحيح بطاقة أقل من طاقة التنشيط"]'::jsonb, 'تطبيق', 'تطبيق شروط', 'صعب', 'الكتاب ص 54–55 — الشكل 2-4 والجدول 2-1'),
('essay', 1, 'اذكر شرطي التصادم المثمر (الفعّال)، ثم وضّح كل شرط منهما بالتفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g).', null, null, null, 'تذكر', 'ذكر وتوضيح', 'سهل', 'الكتاب ص 54–55 — الجدول 2-1'),
('essay', 2, 'يبين الشكل الآتي اتجاهين (س) و(ص) لتصادم جزيء CO مع جزيء NO₂. حدّد الحالة التي يمكن أن تنتج عنها نواتج، وفسّر سبب فشل الحالة الأخرى، ثم بيّن الشرط الآخر الذي يجب توافره حتى يحدث التفاعل فعلًا في الحالة التي اخترتها.', null, '[{"src":"qimg/chem22/c2-l1a-collision-orient.svg","alt":"شكل من لوحتين لتصادم جزيء CO مع جزيء NO₂ (الكربون رمادي داكن، والنيتروجين أزرق، والأكسجين أحمر)، والسهمان يبيّنان اقتراب الجزيئين أحدهما من الآخر. في اللوحة (س): ذرة الأكسجين في جزيء CO هي المواجهة لذرة النيتروجين في جزيء NO₂. وفي اللوحة (ص): ذرة الكربون في جزيء CO هي المواجهة لإحدى ذرتي الأكسجين في جزيء NO₂."}]'::jsonb, null, 'تحليل', 'تفسير شكل', 'متوسط', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط'),
('essay', 3, 'يبين الجدول الآتي أربعة تصادمات بين جزيئات CO وNO₂. حدّد التصادم المثمر منها، وفسّر لماذا لا تؤدي التصادمات الثلاثة الأخرى إلى تفاعل.', '{"headers":["التصادم","اتجاه التصادم","طاقة التصادم"],"rows":[["(1)","غير صحيح","أقل من طاقة التنشيط"],["(2)","غير صحيح","أكبر من طاقة التنشيط"],["(3)","صحيح","أكبر من طاقة التنشيط"],["(4)","صحيح","أقل من طاقة التنشيط"]]}'::jsonb, null, null, 'تطبيق', 'تطبيق نظرية', 'صعب', 'الكتاب ص 54–55، 57 — الشكل 2-4 والجدول 2-1 (التقويم س10)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
