from (values
('mcq', 1, 3, 'يجب أن تتصادم المواد المتفاعلة في الاتجاه الصحيح، وأن تتصادم بطاقة كافية لتكوين المعقد المنشط؛ وهذان هما شرطا التصادم المثمر.', '["المحفّز يزيد السرعة لكنه ليس شرطًا للتصادم المثمر؛ والشرط الثاني هو الطاقة الكافية.","لا يُشترط درجة حرارة بعينها؛ فالشرطان هما الاتجاه الصحيح والطاقة الكافية.","حالة المادة وثبات السرعة ليسا من شروط التصادم المثمر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.412Z"}'::jsonb),
('mcq', 2, 1, 'لكي يتكون CO₂ يجب أن ترتبط ذرة الكربون في CO بذرة أكسجين من NO₂ لحظة الاصطدام؛ وهذا الاتجاه متحقق في (ص) فقط، أما في (س) فلا تلامس ذرة الكربون ذرة الأكسجين فترتد الجزيئات.', '["لكي يحدث التفاعل يجب أن ترتبط ذرة الكربون بذرة أكسجين من NO₂، وهذا لا يتحقق في (س).","","الطاقة الكافية وحدها لا تكفي؛ يلزم أيضًا الاتجاه الصحيح للتصادم.","التفاعل يحدث بين جزيئات مختلفة؛ والمهم اتجاه التصادم وطاقته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.412Z"}'::jsonb),
('mcq', 3, 0, 'الطاقة أكبر من طاقة التنشيط فشرط الطاقة الكافية متحقق، أما الاتجاه فغير صحيح؛ فالشرط الذي لم يتحقق هو شرط الاتجاه الصحيح، ولذلك لا يكون التصادم مثمرًا.', '["","الطاقة أكبر من طاقة التنشيط، فهذا الشرط متحقق.","شرط الطاقة متحقق؛ والذي اختل شرط واحد هو الاتجاه.","التصادم المثمر يتطلب الشرطين معًا، والاتجاه هنا غير صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.412Z"}'::jsonb),
('mcq', 4, 2, 'لكي يكون التصادم مثمرًا يجب أن تتصادم المواد المتفاعلة في الاتجاه الصحيح وبطاقة كافية لتكوين المعقد المنشط؛ فالطاقة الكبيرة لا تعوّض الاتجاه غير الصحيح، والاتجاه الصحيح لا يعوّض نقص الطاقة. إذن يجب تحقق الشرطين معًا، ولا يغني أحدهما عن الآخر.', '["التصادم في الاتجاه الصحيح بطاقة غير كافية، أو بطاقة كافية في اتجاه غير صحيح، لا يؤدي إلى تفاعل.","الشرطان مستقلان؛ فقد تكون الطاقة كبيرة والاتجاه غير صحيح فترتد الجزيئات.","","شرطا التصادم المثمر عامّان لكل التفاعلات، لا للغازات وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.412Z"}'::jsonb),
('mcq', 5, 3, 'لكي يحدث التفاعل يجب أن ترتبط ذرة الكربون من جزيء CO مع ذرة أكسجين من جزيء NO₂ لحظة الاصطدام، فتنتقل ذرة الأكسجين إلى CO ويتكون CO₂ وNO.', '["هذا الاتجاه لا يسمح بانتقال ذرة أكسجين إلى CO، فترتد الجزيئات دون تفاعل.","يتكون CO₂ بانتقال ذرة أكسجين إلى ذرة الكربون، لا بارتباط الكربون بالنيتروجين.","ارتباط ذرتي الأكسجين لا ينقل ذرة أكسجين إلى ذرة الكربون ليتكون CO₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.413Z"}'::jsonb),
('mcq', 6, 0, 'يجب أن تتصادم المواد المتفاعلة بطاقة كافية لتكوين المعقد المنشط، أي بطاقة تساوي طاقة التنشيط (الحد الأدنى من الطاقة اللازم لتكوين المعقد المنشط) أو تزيد عليها.', '["","الطاقة المطلوبة للتصادم المثمر هي طاقة التنشيط، لا ΔH.","طاقة النواتج لا تحدد الحد الأدنى اللازم للتصادم؛ فالمطلوب بلوغ طاقة التنشيط.","الطاقة الصغيرة لا تكفي؛ إذ يجب أن تبلغ الحد الأدنى وهو طاقة التنشيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-07T17:19:00.413Z"}'::jsonb),
('mcq', 7, 2, 'التصادم المثمر يتطلب تحقق الشرطين معًا: الاتجاه الصحيح، والطاقة الكافية (تساوي طاقة التنشيط أو تزيد عليها)؛ وهذا متحقق فقط في التصادم في الاتجاه الصحيح بطاقة أكبر من طاقة التنشيط.', '["الطاقة الكبيرة لا تعوّض الاتجاه غير الصحيح؛ فلا بد من تحقق الشرطين معًا.","الاتجاه الصحيح وحده لا يكفي؛ فالطاقة الأقل من طاقة التنشيط لا تكوّن المعقد المنشط.","","هذا التصادم لا يحقق أيًّا من الشرطين، فهو غير مثمر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.413Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الشرط الأول: أن تتصادم المواد المتفاعلة في الاتجاه الصحيح؛ ففي هذا التفاعل يجب أن ترتبط ذرة الكربون في CO بذرة أكسجين من NO₂ لحظة الاصطدام. الشرط الثاني: أن تتصادم بطاقة كافية لتكوين المعقد المنشط؛ فإذا تصادم جزيئا CO وNO₂ في الاتجاه الصحيح بطاقة أقل من طاقة التنشيط ارتدا دون تفاعل.', '["الاتجاه الصحيح","ارتباط ذرة C في CO بذرة O من NO₂","طاقة كافية لتكوين المعقد المنشط","الطاقة غير الكافية تؤدي إلى ارتداد الجزيئات"]'::jsonb, '[]'::jsonb, '[{"element":"الشرط الأول","marks":1},{"element":"توضيحه بالمثال","marks":1},{"element":"الشرط الثاني","marks":1},{"element":"توضيحه بالمثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الشرطان صحيحان وموضّحان بالمثال"},{"level":"2–3 درجات","description":"الشرطان دون توضيح كامل أو شرط واحد موضّح"},{"level":"1 درجة","description":"شرط واحد دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر المحفّز أو درجة الحرارة شرطًا","عكس الاتجاه الصحيح (ارتباط O في CO بـ N)","الاكتفاء بشرط واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.413Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الحالة (ص) هي التي يمكن أن ينتج عنها تفاعل؛ لأن ذرة الكربون في CO تواجه ذرة أكسجين من NO₂، فتنتقل ذرة الأكسجين إلى CO ويتكون CO₂ وNO. أما في (س) فذرة الأكسجين في CO هي التي تواجه ذرة النيتروجين، فلا تلامس ذرة الكربون ذرة الأكسجين، وترتد الجزيئات دون تكوين روابط. ويجب أيضًا أن يكون التصادم في (ص) بطاقة كافية (تساوي طاقة التنشيط أو تزيد عليها) لتكوين المعقد المنشط.', '["الحالة (ص)","ذرة C تواجه ذرة O من NO₂","في (س) لا تلامس ذرة C ذرة O فترتد الجزيئات","شرط الطاقة الكافية لتكوين المعقد المنشط"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الحالة (ص)","marks":1},{"element":"تبرير الاختيار","marks":1},{"element":"تفسير فشل (س)","marks":1},{"element":"ذكر شرط الطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح وتبرير وتفسير وذكر شرط الطاقة"},{"level":"2–3 درجات","description":"تحديد صحيح مع نقص في التفسير أو إغفال شرط الطاقة"},{"level":"1 درجة","description":"تحديد الحالة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار (س)","إغفال شرط الطاقة الكافية","الظن أن الاتجاه الصحيح وحده يضمن التفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.413Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التصادم (3) هو المثمر؛ لأنه في الاتجاه الصحيح وبطاقة أكبر من طاقة التنشيط فيتكون المعقد المنشط ثم النواتج. التصادمان (1) و(2) في اتجاه غير صحيح، فلا تلامس ذرة الكربون ذرة الأكسجين وترتد الجزيئات حتى لو كانت الطاقة كبيرة. والتصادم (4) في الاتجاه الصحيح لكن طاقته أقل من طاقة التنشيط، فلا يتكون المعقد المنشط وترتد الجزيئات.', '["التصادم (3) مثمر","(1) و(2) اتجاههما غير صحيح","الطاقة الكبيرة لا تعوّض الاتجاه","(4) طاقته غير كافية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد التصادم المثمر","marks":1},{"element":"تفسير (1)","marks":1},{"element":"تفسير (2)","marks":1},{"element":"تفسير (4)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح وتفسير التصادمات الثلاثة"},{"level":"2–3 درجات","description":"تحديد صحيح وتفسير ناقص"},{"level":"1 درجة","description":"تحديد صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التصادم (2) مثمرًا لأن طاقته كبيرة","عدّ التصادم (4) مثمرًا لأن اتجاهه صحيح","إغفال تفسير أحد التصادمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.413Z"}'::jsonb)
