from (values
('mcq', 1, 1, 'المعقد المنشط هو حالة انتقالية غير مستقرة من تجمع الذرات، يحدث خلالها تكسير الروابط وتكوين روابط جديدة.', '["المعقد المنشط غير مستقر وقصير العمر، ولا يمكن فصله؛ والنواتج هي التي تتكون في النهاية.","","هذا تعريف طاقة التنشيط، وليس المعقد المنشط.","هذا وصف المحفّز، وليس المعقد المنشط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.413Z"}'::jsonb),
('mcq', 2, 2, 'تُسمّى مرحلة تكوّن المعقد المنشط الحالة الانتقالية؛ لأنها مرحلة مؤقتة يمر بها التفاعل بين المتفاعلات والنواتج.', '["الحالة القياسية تعني ظروف 1 atm و25°C، ولا علاقة لها بالمعقد المنشط.","الاتزان حالة تتساوى فيها سرعتا التفاعلين الأمامي والعكسي، وليست المعقد المنشط.","","الحالة النهائية هي النواتج، أما المعقد المنشط فمرحلة انتقالية بين المتفاعلات والنواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb),
('mcq', 3, 0, 'المعقد المنشط هو الحالة الانتقالية ذات الطاقة الأعلى في سير التفاعل، فيقع عند قمة المنحنى؛ والرقم عند القمة هو 3.', '["","الرقم 2 يشير إلى مستوى طاقة المتفاعلات في بداية التفاعل.","الرقم 4 يشير إلى مستوى طاقة النواتج في نهاية التفاعل.","الرقم 1 يشير إلى السهم الممتد من المتفاعلات إلى القمة، وهو طاقة التنشيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb),
('mcq', 4, 3, 'في المرحلة (2) تتجمع الذرات الأربع تجمعًا مؤقتًا غير مستقر لحظة التصادم، تتكسر فيه الروابط القديمة وتتكون روابط جديدة، وهذا هو المعقد المنشط.', '["النواتج 2AB تظهر في المرحلة (3)، أما (2) فتجمع مؤقت للذرات الأربع.","المتفاعلات المنفصلة تظهر في المرحلة (1) قبل التصادم.","المرحلة (2) ليست مخلوطًا مستقرًا؛ ففيها تتكسر روابط وتتكون أخرى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb),
('mcq', 5, 0, 'المعقد المنشط حالة غير مستقرة قصيرة العمر، ونتيجة لذلك قد يؤدي إلى تكوين المواد الناتجة، أو يتكسر ليعيد تكوين المواد المتفاعلة مرة أخرى.', '["","المعقد المنشط قصير العمر جدًّا، فلا يبقى دون تغيير.","ليس بالضرورة أن يتحول إلى النواتج؛ فقد يتكسر ليعطي المتفاعلات مرة أخرى.","قد يكوّن المعقد المنشط النواتج، وهذا ما يحدث في التصادم المثمر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb),
('mcq', 6, 2, 'عند تكوّن المعقد المنشط تتكون جسيمات عمرها قصير في حالة انتقالية غير مستقرة، وتقع عند قمة مخطط الطاقة؛ أي إن طاقتها أعلى من طاقة المتفاعلات والنواتج.', '["المعقد المنشط غير مستقر، وطاقته أعلى ما يمكن في سير التفاعل.","عمره قصير، ولا يتكون إلا من التصادم في الاتجاه الصحيح وبطاقة كافية.","","طاقة المعقد المنشط أعلى من طاقة المتفاعلات بمقدار طاقة التنشيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb),
('mcq', 7, 1, 'عندما يكون اتجاه الجزيئات مناسبًا في أثناء التصادم وتكون الطاقة كافية (تساوي طاقة التنشيط أو تزيد عليها) يتكون المعقد المنشط.', '["لا يحدث تفاعل دون تصادم الجسيمات؛ فالمعقد المنشط يتكون لحظة التصادم المناسب.","","ليس كل تصادم يكوّن المعقد المنشط؛ فلا بد من الاتجاه الصحيح والطاقة الكافية.","المعقد المنشط يتكون قبل النواتج، فهو حالة انتقالية بين المتفاعلات والنواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المعقد المنشط حالة انتقالية غير مستقرة من تجمع الذرات، يحدث خلالها تكسير الروابط وتكوين روابط جديدة. فخلال فترة تكوّنه القصيرة تبدأ روابط المتفاعلات بالتكسر وتبدأ روابط النواتج بالتكوّن، ثم قد يؤدي إلى تكوين المواد الناتجة، أو يتكسر ليعيد تكوين المواد المتفاعلة مرة أخرى.', '["حالة انتقالية غير مستقرة من تجمع الذرات","تكسير روابط","تكوين روابط جديدة","قد يكوّن النواتج","أو يعيد تكوين المتفاعلات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"ما يحدث خلال تكوّنه","marks":1},{"element":"المصيران المحتملان","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعريف كامل ووصف ما يحدث والمصيران"},{"level":"3–4 درجات","description":"تعريف صحيح مع نقص في الوصف أو أحد المصيرين"},{"level":"1–2 درجة","description":"تعريف ناقص فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف المعقد المنشط بأنه مستقر","الخلط بينه وبين طاقة التنشيط","القول إنه يتحول دائمًا إلى النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يقع المعقد المنشط عند قمة المنحنى. لأنه حالة انتقالية غير مستقرة تكون فيها الروابط القديمة في طور التكسر والروابط الجديدة في طور التكوين، فتكون طاقته أعلى طاقة في سير التفاعل، أعلى من طاقة المتفاعلات والنواتج. والسهم Ea يمثل طاقة التنشيط، وهي الحد الأدنى من الطاقة الذي يجب أن تمتلكه جزيئات CO وNO₂ المتصادمة لتكوين المعقد المنشط؛ أي إنها الفرق بين طاقة المعقد المنشط وطاقة المتفاعلات.', '["عند قمة المنحنى","حالة غير مستقرة أعلى طاقة","Ea الحد الأدنى من الطاقة لتكوين المعقد المنشط","Ea = طاقة المعقد المنشط − طاقة المتفاعلات"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الموقع","marks":1},{"element":"تفسير الموقع","marks":1},{"element":"معنى Ea","marks":1},{"element":"العلاقة بين Ea والمعقد المنشط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد وتفسير صحيحان وعلاقة واضحة"},{"level":"2–3 درجات","description":"تحديد صحيح مع تفسير أو علاقة ناقصة"},{"level":"1 درجة","description":"تحديد الموقع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تحديد المعقد المنشط عند مستوى النواتج","الخلط بين سهم Ea وسهم ΔH","قياس Ea من مستوى النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المعقد المنشط هو المرحلة الانتقالية التي يمر بها كل تفاعل بين المتفاعلات والنواتج؛ ففيه تتكسر روابط المتفاعلات وتتكون روابط النواتج، ولا يمكن أن تتكون النواتج دون المرور به. وإذا تصادم جزيئان بطاقة أقل من طاقة التنشيط فلن تكون الطاقة كافية لتكوين المعقد المنشط، فلا تتكسر الروابط، ويرتد الجزيئان دون تكوين نواتج.', '["مرحلة انتقالية بين المتفاعلات والنواتج","تتكسر فيه روابط وتتكون روابط","لا تتكون النواتج دون المرور به","الطاقة الأقل من Ea لا تكوّن المعقد المنشط فترتد الجزيئات"]'::jsonb, '[]'::jsonb, '[{"element":"دور المعقد المنشط","marks":2},{"element":"تفسير عدم تكوّن النواتج","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"دور واضح وتفسير صحيح"},{"level":"2–3 درجات","description":"أحد الجزأين كامل والآخر ناقص"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المعقد المنشط مادة محفّزة","القول إن الطاقة القليلة تكوّن نواتج ببطء","إغفال تكسير الروابط وتكوينها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.414Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
