('mcq', 3, 1, 'طاقة التنشيط هي الفرق بين طاقة المتفاعلات وطاقة المعقد المنشط، فيمثلها السهم الممتد من مستوى المتفاعلات صعودًا إلى القمة، وهو السهم 2.', '["الرقم 1 عند قمة المنحنى، ويشير إلى المعقد المنشط لا إلى طاقة التنشيط.","","السهم 3 من المتفاعلات إلى النواتج يمثل الطاقة التي يطلقها التفاعل ΔH.","الرقم 4 يشير إلى مستوى طاقة النواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-07T17:19:00.415Z"}'::jsonb),
('mcq', 4, 2, 'Ea = طاقة المعقد المنشط − طاقة المتفاعلات = 210 kJ − 150 kJ = 60 kJ.', '["هذه طاقة قمة المنحنى (المعقد المنشط) مقيسة من الصفر، لا من مستوى المتفاعلات.","هذا الفرق بين القمة ومستوى النواتج (210 − 40)، وهو طاقة تنشيط التفاعل العكسي.","","هذا الفرق بين المتفاعلات والنواتج (150 − 40)، أي مقدار ΔH لا طاقة التنشيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-07T17:19:00.415Z"}'::jsonb),
('mcq', 5, 0, 'طاقة التنشيط هي الحد الأدنى من الطاقة اللازم لتكوين المعقد المنشط، فتمثَّل على المخطط بالمسافة الرأسية من مستوى المتفاعلات إلى القمة، أي الفرق بين طاقة المعقد المنشط وطاقة المتفاعلات.', '["","هذا الفرق هو التغير في الطاقة ΔH، لا طاقة التنشيط.","طاقة التنشيط تُقاس من مستوى المتفاعلات لا من الصفر.","هذا الفرق هو طاقة تنشيط التفاعل العكسي، لا الأمامي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.415Z"}'::jsonb),
('mcq', 6, 3, 'قمة منحنى (ص) أدنى، فطاقة تنشيطه أقل؛ لذا يكون عدد أكبر من التصادمات له طاقة كافية لتكوين المعقد المنشط، فيكون (ص) أسرع من (س).', '["Ea الكبيرة تعني أن عددًا أقل من التصادمات يملك الطاقة الكافية، فيكون التفاعل أبطأ.","تساوي ΔH لا يعني تساوي السرعة؛ فالسرعة تتأثر بطاقة التنشيط.","Ea المنخفضة تعني أن عددًا أكبر من التصادمات يملك الطاقة الكافية، فيكون التفاعل أسرع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.415Z"}'::jsonb),
('mcq', 7, 2, 'طاقة التنشيط هي الحد الأدنى من الطاقة اللازم لتكوين المعقد المنشط وإحداث التفاعل؛ فإذا ساوتها طاقة التصادم مع صحة الاتجاه، يتكوّن المعقد المنشط لأن طاقتهما بلغت الحد الأدنى اللازم.', '["طاقة التنشيط حد أدنى؛ فالطاقة المساوية لها كافية ولا يلزم أن تزيد عليها.","كل تفاعل يمر بالمعقد المنشط قبل تكوّن النواتج.","","التصادم الواحد إما أن يكون مثمرًا أو لا؛ ولا يكوّن «نصف» النواتج، والطاقة هنا كافية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.416Z"}'::jsonb),
('essay', 1, null::int, null, null, 'طاقة التنشيط Ea هي الحد الأدنى من الطاقة لدى الجزيئات المتفاعلة واللازم لتكوين المعقد المنشط وإحداث التفاعل. والعلاقة عكسية: فعندما تكون Ea عالية يكون عدد قليل من الاصطدامات له طاقة كافية لتكوين المعقد المنشط، فتكون سرعة التفاعل بطيئة؛ وعندما تكون Ea منخفضة يكون عدد كبير من الاصطدامات له طاقة كافية، فيكون التفاعل أسرع.', '["الحد الأدنى من الطاقة","لتكوين المعقد المنشط وإحداث التفاعل","Ea عالية ← تصادمات مثمرة قليلة ← تفاعل بطيء","Ea منخفضة ← تصادمات مثمرة كثيرة ← تفاعل سريع"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"حالة Ea العالية","marks":1},{"element":"حالة Ea المنخفضة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل وعلاقة موضّحة في الحالتين"},{"level":"2–3 درجات","description":"تعريف صحيح وعلاقة ناقصة أو العكس"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Ea العالية تزيد السرعة","الخلط بين Ea وΔH","تعريف Ea بأنها أقصى طاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.416Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Ea (الأمامي) = طاقة القمة − طاقة المتفاعلات = 225 − 50 = 175 kJ. Ea (العكسي) = طاقة القمة − طاقة النواتج = 225 − 125 = 100 kJ. إذن طاقة تنشيط التفاعل الأمامي أكبر من طاقة تنشيط التفاعل العكسي بمقدار 75 kJ.', '["Ea الأمامي = 175 kJ","Ea العكسي = 100 kJ","Ea الأمامي أكبر بمقدار 75 kJ"]'::jsonb, '["Ea (الأمامي) = 225 kJ − 50 kJ = 175 kJ","Ea (العكسي) = 225 kJ − 125 kJ = 100 kJ","الفرق = 175 kJ − 100 kJ = 75 kJ"]'::jsonb, '[{"element":"Ea الأمامي","marks":1},{"element":"Ea العكسي","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الحسابان والمقارنة صحيحة"},{"level":"2 درجتان","description":"حساب واحد صحيح مع مقارنة متسقة"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ 225 kJ هي طاقة التنشيط","قياس Ea العكسي من مستوى المتفاعلات","طرح المتفاعلات من النواتج بدل الحساب من القمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.416Z"}'::jsonb),
('essay', 3, null::int, null, null, 'طاقة التنشيط هي الحد الأدنى من الطاقة اللازم لتكوين المعقد المنشط؛ فإذا تصادمت جزيئات CO وNO₂ بطاقة أقل منها لم يتكون المعقد المنشط وارتدت الجزيئات دون تفاعل، حتى لو كان الاتجاه صحيحًا. وتُشبَّه بقمة التل لأنها حاجز يجب أن تتغلب عليه المتفاعلات؛ فكلما كان التل مرتفعًا احتاج الشخص إلى طاقة كبيرة ووقت طويل للوصول إلى القمة، وكذلك كلما كانت Ea عالية قلّ عدد التصادمات التي تملك طاقة كافية فكان التفاعل أبطأ.', '["Ea الحد الأدنى لتكوين المعقد المنشط","الطاقة الأقل لا تكوّن المعقد المنشط فترتد الجزيئات","Ea حاجز يجب تجاوزه كقمة التل","التل المرتفع ← طاقة أكبر ووقت أطول ← تفاعل أبطأ"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير عدم التفاعل","marks":2},{"element":"وجه الشبه (الحاجز)","marks":1},{"element":"ربط الارتفاع بالسرعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح وتشبيه موضّح بربط السرعة"},{"level":"2–3 درجات","description":"تفسير صحيح وتشبيه ناقص"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إرجاع عدم التفاعل إلى الاتجاه فقط","تشبيه ارتفاع التل بـ ΔH","إغفال المعقد المنشط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.416Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C2-L1-O05') and x.type = v.type and x.number = v.number
