from (values
('mcq', 1, 'يبين المخطط الآتي طاقة التفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g). ما نوع هذا التفاعل من حيث الطاقة؟', null, '[{"src":"qimg/chem22/c2-l1a-profile-exo-co.svg","alt":"مخطط طاقة التفاعل (الطاقة على المحور الرأسي وسير التفاعل على المحور الأفقي) للتفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g): يبدأ المنحنى من مستوى CO(g) + NO₂(g) على اليسار، ويرتفع إلى قمة مكتوب عندها «المعقد المنشط»، ثم ينخفض إلى مستوى CO₂(g) + NO(g) على اليمين، وهو أدنى من مستوى البداية. سهم أحمر مكتوب عليه Ea من مستوى البداية إلى القمة، وسهم أزرق مكتوب عليه ΔH من مستوى البداية إلى مستوى النهاية."}]'::jsonb, '["طارد للحرارة؛ لأن طاقة النواتج أقل من طاقة المتفاعلات","ماص للحرارة؛ لأن طاقة النواتج أقل من طاقة المتفاعلات","ماص للحرارة؛ لأن المنحنى يرتفع إلى قمة قبل أن ينخفض","لا يمكن تحديد نوعه إلا بمعرفة قيمة طاقة التنشيط"]'::jsonb, 'فهم', 'تفسير مخطط', 'سهل', 'الكتاب ص 55 — الشكل 2-5'),
('mcq', 2, 'يبين الشكل الآتي مخططي طاقة لتفاعلين (س) و(ص). أيّ العبارات الآتية تصنّف التفاعلين تصنيفًا صحيحًا؟', null, '[{"src":"qimg/chem22/c2-l1a-profile-two.svg","alt":"مخططا طاقة تفاعل متجاوران (الطاقة على المحور الرأسي وسير التفاعل على الأفقي) بمقياس واحد. في المخطط (س): مستوى المتفاعلات منخفض، ويرتفع المنحنى إلى قمة ثم ينخفض إلى مستوى النواتج وهو أعلى من مستوى المتفاعلات. وفي المخطط (ص): مستوى المتفاعلات مرتفع، ويرتفع المنحنى إلى قمة ثم ينخفض إلى مستوى النواتج وهو أدنى بكثير من مستوى المتفاعلات."}]'::jsonb, '["(س) طارد للحرارة، و(ص) ماص للحرارة","كلاهما طارد للحرارة لأن لكل منهما قمة طاقة","(س) ماص للحرارة، و(ص) طارد للحرارة","كلاهما ماص للحرارة لأن المتفاعلات تحتاج إلى طاقة تنشيط"]'::jsonb, 'تحليل', 'مقارنة مخططات', 'متوسط', 'الكتاب ص 55–56 — مخططا الطاقة للتفاعل الطارد والماص'),
('mcq', 3, 'يبين المخطط الآتي طاقة تفاعل ما مع سير التفاعل. ما قيمة ΔH لهذا التفاعل، وما نوعه؟', null, '[{"src":"qimg/chem22/c2-l1a-profile-values-endo.svg","alt":"مخطط طاقة تفاعل محوره الرأسي الطاقة (kJ) عليه القيم 0 و50 و125 و225، ومحوره الأفقي سير التفاعل: مستوى المتفاعلات عند 50 kJ، وقمة المنحنى عند 225 kJ، ومستوى النواتج عند 125 kJ."}]'::jsonb, '["ΔH = −75 kJ، والتفاعل طارد للحرارة","ΔH = +175 kJ، والتفاعل ماص للحرارة","ΔH = +100 kJ، والتفاعل ماص للحرارة","ΔH = +75 kJ، والتفاعل ماص للحرارة"]'::jsonb, 'تطبيق', 'حساب من مخطط', 'متوسط', 'الكتاب ص 55–56 — مخططا الطاقة للتفاعل الطارد والماص'),
('mcq', 4, 'اعتمادًا على قيم الطاقة المبينة في المخطط الآتي، احسب التغير في المحتوى الحراري للتفاعل، ثم حدّد هل هو طارد أم ماص للحرارة.', null, '[{"src":"qimg/chem22/c2-l1a-profile-values-exo.svg","alt":"مخطط طاقة تفاعل محوره الرأسي الطاقة (kJ) عليه القيم 0 و40 و150 و210، ومحوره الأفقي سير التفاعل: مستوى المتفاعلات عند 150 kJ، وقمة المنحنى عند 210 kJ، ومستوى النواتج عند 40 kJ."}]'::jsonb, '["ΔH = +110 kJ، والتفاعل ماص للحرارة","ΔH = −110 kJ، والتفاعل طارد للحرارة","ΔH = −170 kJ، والتفاعل طارد للحرارة","ΔH = −60 kJ، والتفاعل طارد للحرارة"]'::jsonb, 'تطبيق', 'حساب من مخطط', 'صعب', 'الكتاب ص 55–56 — مخططا الطاقة للتفاعل الطارد والماص'),
('mcq', 5, 'يبين المنحنى الآتي طاقة تفاعل ما مع سير التفاعل. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c2-l1a-profile-numbered-endo.svg","alt":"منحنى طاقة تفاعل (الطاقة على المحور الرأسي وسير التفاعل على المحور الأفقي) عليه أربعة أرقام: الرقم 2 على المستوى الأفقي المنخفض في بداية المنحنى (يسارًا)، والرقم 3 عند قمة المنحنى، والرقم 4 على المستوى الأفقي في نهاية المنحنى (يمينًا) وهو أعلى من مستوى الرقم 2 وأدنى من القمة، والرقم 1 بجانب سهم رأسي يمتد من مستوى الرقم 2 إلى القمة."}]'::jsonb, '["التفاعل طارد للحرارة؛ لأن مستوى الرقم 4 أعلى من مستوى الرقم 2","التفاعل ماص للحرارة؛ لأن مستوى الرقم 4 أعلى من مستوى الرقم 2","التفاعل طارد للحرارة؛ لأن مستوى الرقم 4 أدنى من القمة 3","التفاعل ماص للحرارة؛ لأن السهم 1 يتجه إلى الأعلى"]'::jsonb, 'تحليل', 'تفسير مخطط', 'متوسط', 'الكتاب ص 75 — اختبار مقنن (س9)'),
('mcq', 6, 'يبين المخطط الآتي طاقة التفاعل CO₂(g) + NO(g) → CO(g) + NO₂(g). أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c2-l1a-profile-endo-co2.svg","alt":"مخطط طاقة التفاعل للتفاعل CO₂(g) + NO(g) → CO(g) + NO₂(g): يبدأ المنحنى من مستوى منخفض هو CO₂(g) + NO(g) على اليسار، ويرتفع إلى قمة عالية مكتوب عندها «المعقد المنشط»، ثم ينخفض قليلًا إلى مستوى CO(g) + NO₂(g) على اليمين، وهو أعلى من مستوى البداية. سهم أحمر مكتوب عليه Ea من مستوى البداية إلى القمة، وسهم أزرق مكتوب عليه ΔH من مستوى البداية صعودًا إلى مستوى النهاية."}]'::jsonb, '["التفاعل طارد للحرارة، وطاقة تنشيطه أكبر من طاقة تنشيط التفاعل العكسي له","التفاعل ماص للحرارة، وطاقة تنشيطه أقل من طاقة تنشيط التفاعل العكسي له","التفاعل طارد للحرارة، وطاقة تنشيطه تساوي طاقة تنشيط التفاعل العكسي له","التفاعل ماص للحرارة، وطاقة تنشيطه أكبر من طاقة تنشيط التفاعل العكسي له"]'::jsonb, 'تحليل', 'تفسير مخطط', 'صعب', 'الكتاب ص 56 — الشكل 2-6'),
('mcq', 7, 'يبين المنحنى الآتي طاقة تفاعل ما مع سير التفاعل. أيّ الأرقام يمثل الطاقة التي يطلقها التفاعل (ΔH)؟', null, '[{"src":"qimg/chem22/c2-l1a-profile-numbered-exo.svg","alt":"منحنى طاقة تفاعل (الطاقة على المحور الرأسي وسير التفاعل على المحور الأفقي): يبدأ من مستوى مكتوب عليه «المتفاعلات» ويرتفع إلى قمة عليها الرقم 1، ثم ينخفض إلى مستوى نهائي عليه الرقم 4 وهو أدنى بكثير من مستوى المتفاعلات. الرقم 2 بجانب سهم رأسي من مستوى المتفاعلات صعودًا إلى القمة، والرقم 3 بجانب سهم رأسي من مستوى المتفاعلات نزولًا إلى المستوى النهائي."}]'::jsonb, '["2","1","3","4"]'::jsonb, 'فهم', 'تفسير مخطط', 'سهل', 'الكتاب ص 55 — الشكل 2-5'),
('essay', 1, 'يبين المخطط الآتي طاقة التفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g). حدّد نوع التفاعل من حيث الطاقة مع ذكر الدليل من المخطط، واذكر ما يمثله كل من السهمين Ea وΔH، ثم صف كيف يختلف مخطط التفاعل العكسي CO₂(g) + NO(g) → CO(g) + NO₂(g) عنه.', null, '[{"src":"qimg/chem22/c2-l1a-profile-exo-co.svg","alt":"مخطط طاقة التفاعل (الطاقة على المحور الرأسي وسير التفاعل على المحور الأفقي) للتفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g): يبدأ المنحنى من مستوى CO(g) + NO₂(g) على اليسار، ويرتفع إلى قمة مكتوب عندها «المعقد المنشط»، ثم ينخفض إلى مستوى CO₂(g) + NO(g) على اليمين، وهو أدنى من مستوى البداية. سهم أحمر مكتوب عليه Ea من مستوى البداية إلى القمة، وسهم أزرق مكتوب عليه ΔH من مستوى البداية إلى مستوى النهاية."}]'::jsonb, null, 'تحليل', 'تفسير مخطط', 'متوسط', 'الكتاب ص 55–56 — مخططا الطاقة للتفاعل الطارد والماص'),
('essay', 2, 'يبين المخطط الآتي طاقة تفاعل ما مع سير التفاعل. احسب: طاقة التنشيط للتفاعل الأمامي، وΔH للتفاعل الأمامي، وطاقة التنشيط للتفاعل العكسي، ثم حدّد نوع كل من التفاعلين الأمامي والعكسي من حيث الطاقة.', null, '[{"src":"qimg/chem22/c2-l1a-profile-values-exo.svg","alt":"مخطط طاقة تفاعل محوره الرأسي الطاقة (kJ) عليه القيم 0 و40 و150 و210، ومحوره الأفقي سير التفاعل: مستوى المتفاعلات عند 150 kJ، وقمة المنحنى عند 210 kJ، ومستوى النواتج عند 40 kJ."}]'::jsonb, null, 'تحليل', 'حساب وتصنيف', 'صعب', 'الكتاب ص 55–56 — مخططا الطاقة للتفاعل الطارد والماص'),
('essay', 3, 'تفاعل كيميائي يحدث في خطوة واحدة، قيمة ΔH له = +50 kJ، وطاقة التنشيط له = 120 kJ. حدّد نوع التفاعل، وقارن بين طاقة النواتج وطاقة المتفاعلات، وصف مخطط طاقته (موقع المتفاعلات والنواتج والقمة)، ثم احسب طاقة التنشيط للتفاعل العكسي.', null, null, null, 'تحليل', 'استنتاج وحساب', 'صعب', 'الكتاب ص 56، 72 — التفاعل الماص (س56، س64)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
