from (values
('mcq', 1, 0, 'مستوى CO₂(g) + NO(g) أدنى من مستوى CO(g) + NO₂(g)، أي إن طاقة النواتج أقل من طاقة المتفاعلات؛ فالتفاعل يفقد طاقة، وهو طارد للحرارة.', '["","انخفاض طاقة النواتج عن المتفاعلات يعني أن التفاعل فقد طاقة، فهو طارد لا ماص.","كل التفاعلات (الطاردة والماصة) لها قمة طاقة تنشيط؛ والنوع يحدده موقع النواتج بالنسبة إلى المتفاعلات.","نوع التفاعل يُحدد بمقارنة مستويي المتفاعلات والنواتج، لا بقيمة طاقة التنشيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-07T17:19:00.416Z"}'::jsonb),
('mcq', 2, 2, 'في (س) مستوى النواتج أعلى من مستوى المتفاعلات، فالتفاعل يمتص طاقة (ماص)؛ وفي (ص) مستوى النواتج أدنى من مستوى المتفاعلات، فالتفاعل يطلق طاقة (طارد). إذن (س) ماص للحرارة، و(ص) طارد للحرارة.', '["قُلب التصنيف؛ ففي (س) النواتج أعلى من المتفاعلات (ماص)، وفي (ص) أدنى منها (طارد).","وجود القمة لا يحدد النوع؛ والنوع يحدده موقع النواتج بالنسبة إلى المتفاعلات.","","كل التفاعلات تحتاج إلى طاقة تنشيط، وهذا لا يجعلها كلها ماصة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-07T17:19:00.416Z"}'::jsonb),
('mcq', 3, 3, 'ΔH = طاقة النواتج − طاقة المتفاعلات = 125 kJ − 50 kJ = +75 kJ؛ وبما أن ΔH موجبة (النواتج أعلى من المتفاعلات) فالتفاعل ماص للحرارة.', '["طُرحت طاقة النواتج من طاقة المتفاعلات؛ والصحيح ΔH = طاقة النواتج − طاقة المتفاعلات = +75 kJ.","175 kJ هي طاقة التنشيط (225 − 50)، لا ΔH.","100 kJ هي طاقة تنشيط التفاعل العكسي (225 − 125)، لا ΔH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-07T17:19:00.417Z"}'::jsonb),
('mcq', 4, 1, 'ΔH = طاقة النواتج − طاقة المتفاعلات = 40 kJ − 150 kJ = −110 kJ؛ وبما أن ΔH سالبة (النواتج أدنى من المتفاعلات) فالتفاعل طارد للحرارة.', '["طُرحت طاقة المتفاعلات من النواتج بترتيب معكوس؛ والنواتج أدنى من المتفاعلات فـ ΔH سالبة.","","170 kJ هي الفرق بين القمة والنواتج، أي طاقة تنشيط التفاعل العكسي.","60 kJ هي طاقة التنشيط للتفاعل الأمامي (210 − 150)، لا ΔH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.417Z"}'::jsonb),
('mcq', 5, 1, 'الرقم 2 يمثل المتفاعلات والرقم 4 يمثل النواتج؛ ولأن مستوى النواتج أعلى من مستوى المتفاعلات فقد امتص التفاعل طاقة، أي إنه ماص للحرارة.', '["النواتج (4) أعلى من المتفاعلات (2)، أي إن التفاعل امتص طاقة، فهو ماص لا طارد.","","النواتج دائمًا أدنى من القمة في أي تفاعل؛ والمقارنة الصحيحة بين النواتج (4) والمتفاعلات (2).","السهم 1 هو طاقة التنشيط ويتجه إلى الأعلى في كل التفاعلات؛ فلا يحدد نوع التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.417Z"}'::jsonb),
('mcq', 6, 3, 'مستوى CO(g) + NO₂(g) أعلى من مستوى CO₂(g) + NO(g)، فالتفاعل ماص للحرارة؛ ولأن المتفاعلات في مستوى أدنى من النواتج تكون المسافة من المتفاعلات إلى القمة أكبر من المسافة من النواتج إلى القمة، أي إن طاقة تنشيطه أكبر من طاقة تنشيط التفاعل العكسي له.', '["النواتج أعلى من المتفاعلات فالتفاعل ماص، وليس طاردًا.","في التفاعل الماص تبدأ المتفاعلات من مستوى منخفض، فالمسافة إلى القمة أكبر منها من مستوى النواتج.","التفاعل ماص، وطاقتا التنشيط مختلفتان بمقدار ΔH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-07T17:19:00.417Z"}'::jsonb),
('mcq', 7, 2, 'الطاقة التي يطلقها التفاعل ΔH هي الفرق بين مستوى المتفاعلات ومستوى النواتج، فيمثلها السهم الممتد من المتفاعلات نزولًا إلى النواتج، وهو السهم 3.', '["السهم 2 من المتفاعلات إلى القمة يمثل طاقة التنشيط، لا الطاقة المنطلقة.","الرقم 1 عند قمة المنحنى ويشير إلى المعقد المنشط.","","الرقم 4 يشير إلى مستوى النواتج نفسه، لا إلى الفرق في الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.417Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التفاعل طارد للحرارة؛ لأن مستوى طاقة النواتج CO₂(g) + NO(g) أدنى من مستوى طاقة المتفاعلات CO(g) + NO₂(g)، فالتفاعل يفقد طاقة. السهم Ea يمثل طاقة التنشيط: الفرق بين طاقة المتفاعلات وطاقة المعقد المنشط. والسهم ΔH يمثل الطاقة التي يطلقها التفاعل: الفرق بين طاقة المتفاعلات وطاقة النواتج. وفي التفاعل العكسي تبدأ المتفاعلات CO₂ وNO من المستوى المنخفض وتنتهي النواتج CO وNO₂ في المستوى الأعلى، فيكون التفاعل ماصًّا للحرارة، وطاقة تنشيطه أكبر من طاقة تنشيط التفاعل الأمامي.', '["طارد للحرارة","طاقة النواتج أقل من المتفاعلات","Ea: الفرق بين المتفاعلات والمعقد المنشط","ΔH: الفرق بين المتفاعلات والنواتج","العكسي ماص وطاقة تنشيطه أكبر"]'::jsonb, '[]'::jsonb, '[{"element":"نوع التفاعل","marks":1},{"element":"الدليل","marks":1},{"element":"معنى Ea","marks":1},{"element":"معنى ΔH","marks":1},{"element":"وصف التفاعل العكسي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد ودليل ومعنى السهمين ووصف العكسي صحيح"},{"level":"3–4 درجات","description":"نقص في عنصر أو اثنين"},{"level":"1–2 درجة","description":"تحديد النوع فقط أو مع الدليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التفاعل ماصًّا لوجود قمة","الخلط بين سهمي Ea وΔH","القول إن طاقتي التنشيط متساويتان للتفاعلين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.417Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Ea (الأمامي) = 210 − 150 = 60 kJ. ΔH (الأمامي) = 40 − 150 = −110 kJ. Ea (العكسي) = 210 − 40 = 170 kJ. التفاعل الأمامي طارد للحرارة لأن ΔH سالبة (النواتج أدنى من المتفاعلات)، والتفاعل العكسي ماص للحرارة (ΔH = +110 kJ).', '["Ea الأمامي = 60 kJ","ΔH = −110 kJ","Ea العكسي = 170 kJ","الأمامي طارد","العكسي ماص"]'::jsonb, '["Ea (الأمامي) = 210 kJ − 150 kJ = 60 kJ","ΔH = طاقة النواتج − طاقة المتفاعلات = 40 kJ − 150 kJ = −110 kJ","Ea (العكسي) = 210 kJ − 40 kJ = 170 kJ","ΔH (العكسي) = +110 kJ"]'::jsonb, '[{"element":"Ea الأمامي","marks":1},{"element":"ΔH بإشارته","marks":1},{"element":"Ea العكسي","marks":1},{"element":"نوع التفاعل الأمامي","marks":1},{"element":"نوع التفاعل العكسي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات الثلاثة والتصنيفان صحيحة"},{"level":"3–4 درجات","description":"خطأ في حساب أو تصنيف واحد"},{"level":"1–2 درجة","description":"حساب واحد أو تصنيف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ΔH موجبة","حساب Ea من الصفر (210 kJ)","عدّ التفاعلين من النوع نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-07T17:19:00.417Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التفاعل ماص للحرارة لأن ΔH موجبة، فطاقة النواتج أعلى من طاقة المتفاعلات بمقدار 50 kJ. في مخطط طاقته يبدأ المنحنى من مستوى المتفاعلات المنخفض، ويرتفع 120 kJ إلى قمة المعقد المنشط، ثم ينخفض إلى مستوى النواتج الذي يعلو مستوى المتفاعلات بـ 50 kJ ويقع تحت القمة بـ 70 kJ. طاقة التنشيط للتفاعل العكسي = 120 − 50 = 70 kJ.', '["ماص للحرارة","طاقة النواتج أعلى بـ 50 kJ","وصف المخطط: المتفاعلات منخفضة، القمة أعلى بـ 120 kJ، النواتج أعلى من المتفاعلات","Ea العكسي = 70 kJ"]'::jsonb, '["ΔH > 0 ⇐ ماص: H(النواتج) − H(المتفاعلات) = +50 kJ","طاقة القمة = طاقة المتفاعلات + 120 kJ","Ea (العكسي) = Ea (الأمامي) − ΔH = 120 kJ − 50 kJ = 70 kJ"]'::jsonb, '[{"element":"نوع التفاعل","marks":1},{"element":"مقارنة الطاقتين","marks":1},{"element":"وصف المخطط","marks":1},{"element":"Ea العكسي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد ومقارنة ووصف وحساب صحيح"},{"level":"2–3 درجات","description":"خطأ في عنصر أو عنصرين"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التفاعل طاردًا","جمع ΔH وEa للحصول على Ea العكسي (170 kJ)","رسم النواتج أعلى من القمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.417Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
