('mcq', 1, 'ما الذي تنص عليه نظرية التصادم؟', null, null, '["يكفي أن تقترب جسيمات المواد المتفاعلة بعضها من بعض لكي يحدث التفاعل دون أن تتصادم","كل تصادم بين جسيمات المواد المتفاعلة يؤدي حتمًا إلى تكوين المواد الناتجة","يجب أن تتصادم الذرات والأيونات والجزيئات بعضها ببعض لكي يتم التفاعل","تزداد سرعة التفاعل كلما قلّ عدد التصادمات بين جسيمات المواد المتفاعلة"]'::jsonb, 'تذكر', 'تذكر نص نظرية', 'سهل', 'الكتاب ص 53 — نظرية التصادم'),
('mcq', 2, 'أيّ مما يأتي يمثل فرضَي نظرية التصادم معًا؟', null, null, '["يجب أن تتصادم المواد المتفاعلة، وكل تصادم بينها يؤدي إلى حدوث تفاعل","يجب أن تتصادم المواد المتفاعلة، وليس من الضروري أن يؤدي كل تصادم إلى حدوث تفاعل","لا يلزم تصادم المواد المتفاعلة، ويكفي أن تمتلك جسيماتها طاقة كافية لحدوث التفاعل","يجب أن تتصادم المواد الناتجة، وليس من الضروري أن يعيد كل تصادم تكوين المتفاعلات"]'::jsonb, 'تذكر', 'تذكر فروض', 'سهل', 'الكتاب ص 55 — الجدول 2-1 فروض نظرية التصادم'),
('mcq', 3, 'يمثل الشكل الآتي تفاعل جزيئات A₂ مع جزيئات B₂ لتكوين جزيئات AB. أيّ فروض نظرية التصادم يوضحه الشكل؟', null, '[{"src":"qimg/chem22/c2-l1b-a2b2.svg","alt":"شكل من ثلاث مراحل من اليسار إلى اليمين: جزيء A₂ (ذرتان A متصلتان) وجزيء B₂ (ذرتان B متصلتان) بينهما إشارة +، ثم سهم إلى لحظة تصادم الجزيئين وقد أحاط بهما شكل نجمة يرمز إلى التصادم، ثم سهم إلى جزيئين من AB كل منهما ذرة A مرتبطة بذرة B. وتحت المراحل الرموز: A₂ و B₂ و«تصادم» و2AB."}]'::jsonb, '["يجب أن تتصادم جزيئات المواد المتفاعلة لكي تتكون المواد الناتجة","تتكون المواد الناتجة بمجرد خلط المواد المتفاعلة دون حاجة إلى تصادم","تتصادم جزيئات AB الناتجة لتكوّن جزيئات A₂ و B₂ من جديد","تنتج كل التصادمات بين جزيئات A₂ و B₂ جزيئات AB بالعدد نفسه"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 53 — الشكل 2-3 تفاعل A₂ مع B₂'),
('mcq', 4, 'يتفاعل CO مع NO₂ عند درجة حرارة أعلى من 500 K، وعند حساب عدد التصادمات بين جزيئاتهما في كل ثانية تكون النتيجة عددًا هائلًا، في حين يكوّن عدد قليل فقط من هذه التصادمات نواتج. أيّ فروض نظرية التصادم تؤكده هذه الملاحظة؟', null, null, '["تزداد سرعة التفاعل بزيادة عدد التصادمات التي لا تكوّن نواتج","تتكون جزيئات CO₂ و NO من كل تصادم يحدث بين الجزيئات في الثانية","يحدث التفاعل بين CO و NO₂ دون تصادم عند درجات الحرارة المرتفعة","ليس من الضروري أن يؤدي كل تصادم بين الجزيئات إلى حدوث تفاعل"]'::jsonb, 'فهم', 'ربط ملاحظة بفرض', 'صعب', 'الكتاب ص 53 — نظرية التصادم'),
('mcq', 5, 'وفقًا لنظرية التصادم، أيّ الجسيمات يجب أن تتصادم لكي يحدث التفاعل الكيميائي؟', null, null, '["ذرات المواد المتفاعلة أو أيوناتها أو جزيئاتها","الإلكترونات الحرة الموجودة في وعاء التفاعل","جزيئات المواد الناتجة بعد تكوّنها مباشرة","جزيئات الوعاء الذي يحدث فيه التفاعل"]'::jsonb, 'تذكر', 'تذكر', 'سهل', 'الكتاب ص 55 — الجدول 2-1 فروض نظرية التصادم'),
('mcq', 6, 'ادرس العبارات الآتية:
الأولى: يجب أن تتصادم جسيمات المواد المتفاعلة حتى يحدث تفاعل.
الثانية: كل تصادم بين جسيمات المواد المتفاعلة يكوّن مواد ناتجة.
الثالثة: عدد التصادمات التي تكوّن نواتج قليل مقارنة بالعدد الكلي للتصادمات.
أيّ العبارات السابقة تتفق مع نظرية التصادم؟', null, null, '["الأولى والثانية","الأولى والثالثة","الثانية والثالثة","الأولى فقط"]'::jsonb, 'فهم', 'تقييم عبارات', 'صعب', 'الكتاب ص 53، 55، 74 — فروض نظرية التصادم'),
('mcq', 7, 'نظرية التصادم هي المفتاح لفهم:', null, null, '["الاختلاف في كميات الحرارة التي تطلقها التفاعلات","الاختلاف في الكتل المولية للمواد المتفاعلة","الاختلاف في سرعة التفاعلات الكيميائية","الاختلاف في حالات المواد الناتجة الفيزيائية"]'::jsonb, 'تذكر', 'تذكر الفكرة الرئيسة', 'متوسط', 'الكتاب ص 50، 69 — الفكرة الرئيسة للقسم 2-1'),
('essay', 1, 'اذكر فرضَي نظرية التصادم، ثم وضّح كل فرض منهما بالرجوع إلى تفاعل غاز أول أكسيد الكربون CO مع غاز ثاني أكسيد النيتروجين NO₂:
CO(g) + NO₂(g) → CO₂(g) + NO(g)', null, null, null, 'فهم', 'ذكر وتوضيح', 'متوسط', 'الكتاب ص 53، 55 — نظرية التصادم والجدول 2-1'),
('essay', 2, 'صنّف كل عبارة مما يأتي إلى «فرض من فروض نظرية التصادم» أو «شرط من شروط التصادم الفعال (المثمر)»:
(أ) يجب أن تتصادم المواد المتفاعلة في الاتجاه الصحيح.
(ب) يجب أن تتصادم المواد المتفاعلة (ذرات أو أيونات أو جزيئات).
(ج) يجب أن تتصادم المواد المتفاعلة بطاقة كافية لتكوين المعقد المنشط.
(د) ليس من الضروري أن يؤدي كل تصادم بين الذرات أو الأيونات أو الجزيئات إلى حدوث تفاعل.
ثم بيّن العلاقة بين المجموعتين.', null, null, null, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 55 — الجدول 2-1 فروض نظرية التصادم'),
('essay', 3, 'قوّم صحة العبارة الآتية، ثم صحّحها إن كانت خاطئة مع التعليل: «وفقًا لنظرية التصادم، يكفي أن تتصادم جسيمات المواد المتفاعلة لكي تتكون المواد الناتجة، لذا فكل تصادم بين جزيئات CO و NO₂ ينتج CO₂ و NO».', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 53 — نظرية التصادم')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
