select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تنص نظرية التصادم على وجوب تصادم الذرات والأيونات والجزيئات بعضها ببعض لكي يتم التفاعل؛ فالتصادم شرط لا يحدث التفاعل من دونه.', '["الاقتراب وحده لا يكفي؛ فالنظرية تشترط حدوث التصادم بين الجسيمات.","هذا يناقض الفرض الثاني للنظرية؛ فليس من الضروري أن يؤدي كل تصادم إلى تفاعل.","","قلة التصادمات تعني فرصًا أقل لحدوث التفاعل، لا سرعة أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.418Z"}'::jsonb),
('mcq', 2, 1, 'فرضا نظرية التصادم هما: (1) يجب أن تتصادم المواد المتفاعلة (ذرات أو أيونات أو جزيئات). (2) ليس من الضروري أن يؤدي كل تصادم بين الذرات أو الأيونات أو الجزيئات إلى حدوث تفاعل.', '["الشطر الثاني خطأ؛ فليس كل تصادم يؤدي إلى تفاعل.","","الشطر الأول يناقض الفرض الأساسي؛ فالتصادم شرط لازم لحدوث التفاعل، والطاقة وحدها لا تكفي.","الفرضان يتعلقان بتصادم المواد المتفاعلة، لا بتصادم المواد الناتجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-07T17:19:00.418Z"}'::jsonb),
('mcq', 3, 0, 'يُظهر الشكل جزيئي A₂ و B₂ يتصادمان أولًا ثم تتكون جزيئات AB؛ وهذا يوضح الفرض القائل بوجوب تصادم جسيمات المواد المتفاعلة لكي يتم التفاعل.', '["","الشكل يُظهر مرحلة تصادم قبل تكوّن AB، فالتفاعل لا يحدث بمجرد الخلط.","الشكل يمثل اتجاه التفاعل من A₂ و B₂ إلى AB، لا العكس.","الشكل يمثل تصادمًا واحدًا ناجحًا، ولا يدل على أن كل التصادمات تنتج AB؛ والنظرية تقرر أن بعض التصادمات لا يؤدي إلى تفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.418Z"}'::jsonb),
('mcq', 4, 3, 'كثرة التصادمات مع قلة ما ينتج منها نواتج تعني أن معظم التصادمات لا يؤدي إلى تفاعل؛ وهذا هو الفرض الثاني: ليس من الضروري أن يؤدي كل تصادم إلى حدوث تفاعل.', '["التصادمات التي لا تكوّن نواتج لا تسهم في سرعة التفاعل.","الملاحظة تقول إن عددًا قليلًا فقط من التصادمات يكوّن نواتج، لا كلها.","الملاحظة قائمة على حساب التصادمات بين الجزيئات؛ فالتفاعل لا يحدث دون تصادم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.418Z"}'::jsonb),
('mcq', 5, 0, 'ينص الفرض الأول لنظرية التصادم على أنه يجب أن تتصادم المواد المتفاعلة: ذراتها أو أيوناتها أو جزيئاتها.', '["","النظرية تتحدث عن تصادم جسيمات المواد المتفاعلة (ذرات أو أيونات أو جزيئات)، لا الإلكترونات الحرة.","تصادم جسيمات المواد المتفاعلة هو ما يكوّن النواتج، لا تصادم النواتج.","اصطدام الجسيمات بجدار الوعاء ليس هو التصادم الذي يكوّن النواتج في النظرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.418Z"}'::jsonb),
('mcq', 6, 1, 'العبارة الأولى هي الفرض الأول للنظرية، والثالثة تتفق مع الفرض الثاني (ليس كل تصادم يؤدي إلى تفاعل، ويكوّن عدد قليل فقط من التصادمات نواتج)، أما الثانية فتناقض الفرض الثاني. إذن العبارتان الصحيحتان: الأولى والثالثة.', '["العبارة الثانية خطأ؛ فليس كل تصادم يكوّن نواتج.","","العبارة الثانية خطأ، والأولى صحيحة وقد أُسقطت.","العبارة الثالثة صحيحة أيضًا؛ لأن عددًا قليلًا فقط من التصادمات يكوّن نواتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.419Z"}'::jsonb),
('mcq', 7, 2, 'الفكرة الرئيسة للدرس: نظرية التصادم هي المفتاح لفهم الاختلاف في سرعة التفاعلات؛ لأن السرعة تعتمد على عدد التصادمات التي تؤدي إلى تفاعل.', '["كمية الحرارة (ΔH) موضوع الكيمياء الحرارية، ولا تفسرها نظرية التصادم.","الكتلة المولية خاصية للمادة تُحسب من الصيغة، ولا علاقة لها بنظرية التصادم.","","الحالة الفيزيائية للنواتج لا تفسرها نظرية التصادم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.419Z"}'::jsonb),
('essay', 1, null::int, null, null, 'فرضا نظرية التصادم: (1) يجب أن تتصادم المواد المتفاعلة (ذرات أو أيونات أو جزيئات) لكي يحدث التفاعل. (2) ليس من الضروري أن يؤدي كل تصادم بين الذرات أو الأيونات أو الجزيئات إلى حدوث تفاعل. التوضيح: لكي يتكون CO₂ و NO يجب أن تتصادم جزيئات CO مع جزيئات NO₂؛ فلا يحدث التفاعل دون تصادم. وعند حساب عدد التصادمات بين هذه الجزيئات في كل ثانية نجده عددًا هائلًا، لكن عددًا قليلًا فقط منها يكوّن نواتج؛ فمعظم التصادمات لا يؤدي إلى تفاعل.', '["الفرض الأول: يجب أن تتصادم المواد المتفاعلة","الفرض الثاني: ليس كل تصادم يؤدي إلى تفاعل","توضيح الأول: يجب أن تتصادم جزيئات CO و NO₂ لتكوين النواتج","توضيح الثاني: عدد التصادمات هائل وما يكوّن نواتج منها قليل"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الفرض الأول","marks":1},{"element":"ذكر الفرض الثاني","marks":1},{"element":"توضيح الفرض الأول بالتفاعل","marks":1},{"element":"توضيح الفرض الثاني بالتفاعل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الفرضان صحيحان وموضحان بالتفاعل"},{"level":"2–3 درجات","description":"الفرضان صحيحان مع توضيح ناقص أو توضيح أحدهما فقط"},{"level":"1 درجة","description":"ذكر فرض واحد صحيح دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن كل تصادم يؤدي إلى تفاعل","ذكر شروط التصادم الفعال (الاتجاه والطاقة) بدلًا من فرضي النظرية","الاكتفاء بالفرضين دون ربطهما بالتفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.419Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) شرط من شروط التصادم الفعال. (ب) فرض من فروض نظرية التصادم. (ج) شرط من شروط التصادم الفعال. (د) فرض من فروض نظرية التصادم. العلاقة: الفرضان يقرران أن التصادم لازم لحدوث التفاعل لكنه لا يكفي دائمًا، والشرطان يحددان أيّ التصادمات يؤدي إلى تفاعل: وهي التي تحدث في الاتجاه الصحيح وبطاقة كافية لتكوين المعقد المنشط.', '["(أ) شرط","(ب) فرض","(ج) شرط","(د) فرض","الشرطان يفسران لماذا لا يؤدي كل تصادم إلى تفاعل"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ)","marks":1},{"element":"تصنيف (ب)","marks":1},{"element":"تصنيف (ج)","marks":1},{"element":"تصنيف (د)","marks":1},{"element":"بيان العلاقة بين المجموعتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف العبارات الأربع صحيح وبيان العلاقة صحيح"},{"level":"3–4 درجات","description":"تصنيف صحيح لثلاث عبارات أو أكثر مع علاقة ناقصة"},{"level":"1–2 درجة","description":"تصنيف صحيح لعبارة أو عبارتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ شرط الاتجاه الصحيح فرضًا من فروض النظرية","عدّ العبارة (د) شرطًا للتصادم الفعال","إغفال بيان العلاقة بين الفروض والشروط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.419Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة. صحيح أن النظرية تشترط تصادم جسيمات المواد المتفاعلة، لكن التصادم وحده لا يكفي؛ فالفرض الثاني للنظرية ينص على أنه ليس من الضروري أن يؤدي كل تصادم إلى حدوث تفاعل. والدليل أن عدد التصادمات بين جزيئات CO و NO₂ في كل ثانية عدد هائل، ومع ذلك يكوّن عدد قليل فقط منها CO₂ و NO. التصحيح: «وفقًا لنظرية التصادم، يجب أن تتصادم جسيمات المواد المتفاعلة لكي يحدث التفاعل، لكن ليس كل تصادم بين جزيئات CO و NO₂ ينتج CO₂ و NO».', '["الحكم: العبارة خاطئة","التصادم شرط لازم لكنه غير كافٍ","ذكر الفرض الثاني للنظرية","الدليل: كثرة التصادمات وقلة ما يكوّن نواتج","صياغة العبارة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح على العبارة","marks":1},{"element":"بيان أن التصادم لازم لكنه غير كافٍ","marks":1},{"element":"الاستشهاد بالفرض الثاني","marks":1},{"element":"الدليل من تفاعل CO مع NO₂","marks":1},{"element":"صياغة التصحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح وتعليل كامل بالفرضين والدليل وتصحيح سليم"},{"level":"3–4 درجات","description":"حكم صحيح وتعليل ناقص أو تصحيح غير دقيق"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل كافٍ"},{"level":"صفر","description":"الحكم بصحة العبارة أو لا إجابة"}]'::jsonb, '["الحكم بصحة العبارة لأن النظرية تشترط التصادم","تصحيح العبارة بحذف شرط التصادم كليًا","عدم تقديم دليل على أن معظم التصادمات لا يكوّن نواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.419Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
