on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C2-L1-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الشكل الآتي أربعة احتمالات لتصادم جزيء CO مع جزيء NO₂ في التفاعل: CO(g) + NO₂(g) → CO₂(g) + NO(g). في أيّ اللوحات يؤدي التصادم إلى حدوث التفاعل؟', null, '[{"src":"qimg/chem22/c2-l1b-collisions.svg","alt":"أربع لوحات مرقمة من (1) إلى (4)، في كل منها جزيء CO على اليسار (ذرة كربون C داكنة متصلة بذرة أكسجين O حمراء) يتحرك نحو اليمين، وجزيء NO₂ على اليمين (ذرة نيتروجين N زرقاء متصلة بذرتي أكسجين O حمراوين) يتحرك نحو اليسار، وتحت كل لوحة عبارة عن طاقة التصادم. اللوحة (1): ذرة الأكسجين في CO تواجه ذرة أكسجين من NO₂، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (2): ذرة الكربون في CO تواجه ذرة النيتروجين في NO₂ وذرتا الأكسجين في الجهة البعيدة، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (3): ذرة الكربون في CO تواجه ذرة أكسجين من NO₂، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (4): ذرة الكربون في CO تواجه ذرة أكسجين من NO₂، وسهما الحركة قصيران، والعبارة «طاقة التصادم أقل من Ea»."}]'::jsonb, '["اللوحة (1)","اللوحة (2)","اللوحة (4)","اللوحة (3)"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط (الشكل 2-4)'),
('mcq', 2, 'في الشكل الآتي، طاقة التصادم في اللوحة (2) أكبر من طاقة التنشيط، ومع ذلك لا يحدث تفاعل. ما سبب ذلك؟', null, '[{"src":"qimg/chem22/c2-l1b-collisions.svg","alt":"أربع لوحات مرقمة من (1) إلى (4)، في كل منها جزيء CO على اليسار (ذرة كربون C داكنة متصلة بذرة أكسجين O حمراء) يتحرك نحو اليمين، وجزيء NO₂ على اليمين (ذرة نيتروجين N زرقاء متصلة بذرتي أكسجين O حمراوين) يتحرك نحو اليسار، وتحت كل لوحة عبارة عن طاقة التصادم. اللوحة (1): ذرة الأكسجين في CO تواجه ذرة أكسجين من NO₂، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (2): ذرة الكربون في CO تواجه ذرة النيتروجين في NO₂ وذرتا الأكسجين في الجهة البعيدة، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (3): ذرة الكربون في CO تواجه ذرة أكسجين من NO₂، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (4): ذرة الكربون في CO تواجه ذرة أكسجين من NO₂، وسهما الحركة قصيران، والعبارة «طاقة التصادم أقل من Ea»."}]'::jsonb, '["لأن الطاقة الزائدة عن طاقة التنشيط تفكك الجزيئين إلى ذرات منفصلة","لأن ذرة الكربون في CO لا تلامس ذرة أكسجين من NO₂ لحظة التصادم، فترتد الجزيئات","لأن جزيء NO₂ يتحرك أسرع من جزيء CO فلا يكتمل التصادم بينهما","لأن المعقد المنشط يتكون في هذا التصادم ثم يبقى مستقرًا دون أن يتغير"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط (الشكل 2-4)'),
('mcq', 3, 'تفشل معظم التصادمات بين جزيئات المواد المتفاعلة في تكوين نواتج؛ لأنها:', null, null, '["تحدث في الاتجاه المناسب وبطاقة كافية لتكوين المعقد المنشط","تحدث بين جزيئات متشابهة من المادة المتفاعلة نفسها فقط","تحدث في اتجاه غير مناسب أو بطاقة أقل من طاقة التنشيط","تحدث بطاقة أكبر من طاقة التنشيط فتتفكك الجزيئات المتصادمة"]'::jsonb, 'تذكر', 'تذكر سبب', 'سهل', 'الكتاب ص 54، 55 — اتجاه التصادم وطاقة التنشيط'),
('mcq', 4, 'تصادم جزيء CO مع جزيء NO₂ في الاتجاه الصحيح، لكن طاقة التصادم كانت أقل من طاقة التنشيط. ماذا يحدث؟', null, null, '["يتكون المعقد المنشط ويتحول حتمًا إلى CO₂ و NO","تنتقل ذرة أكسجين من CO إلى NO₂ فيتكون NO₃","يتكون CO₂ و NO لكن ببطء شديد في هذا التصادم","لا يتكون المعقد المنشط وترتد الجزيئات دون أن تتفاعل"]'::jsonb, 'فهم', 'تنبؤ بنتيجة', 'سهل', 'الكتاب ص 54 — الشكل 2-4d'),
('mcq', 5, 'حتى عندما يتكون المعقد المنشط في أثناء التصادم، فقد لا تتكون المواد الناتجة. ما تفسير ذلك؟', null, null, '["المعقد المنشط مستقر جدًا فيبقى في وعاء التفاعل دون أن يتغير","المعقد المنشط غير مستقر، وقد يتكسر ليكوّن المواد المتفاعلة مرة أخرى","المعقد المنشط يحتاج إلى تصادم ثانٍ في الاتجاه الصحيح لكي يتكون","المعقد المنشط أقل طاقة من المتفاعلات فلا يستطيع تكوين نواتج"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 54 — المعقد المنشط'),
('mcq', 6, 'خُلط غازان في وعاء مغلق عند درجة حرارة الغرفة، وتحدث بين جزيئاتهما بلايين التصادمات في كل ثانية، ومع ذلك لم تتكون أي كمية ملحوظة من النواتج. ما التفسير الأنسب لذلك وفق نظرية التصادم؟', null, null, '["جزيئات الغازين لا تتصادم مطلقًا عند درجة حرارة الغرفة","التفاعل طارد للحرارة فلا يحدث إلا بعد تبريد الخليط","طاقة معظم التصادمات أقل من طاقة التنشيط اللازمة لتكوين المعقد المنشط","كل التصادمات تكوّن نواتج لكنها تختفي فور تكوّنها"]'::jsonb, 'تحليل', 'تفسير موقف', 'صعب', 'الكتاب ص 54، 55، 70 — طاقة التنشيط وسرعة التفاعل (س34)'),
('mcq', 7, 'ماذا يحدث لجزيئات المواد المتفاعلة في التصادم غير المثمر؟', null, null, '["ترتد الجزيئات دون تكوين روابط جديدة","تتحد الجزيئات فتكوّن نواتج بكمية أقل","تتفكك الجزيئات إلى ذرات منفردة","يتكون المعقد المنشط ويبقى مستقرًا"]'::jsonb, 'تذكر', 'تذكر', 'سهل', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط (الشكل 2-4)'),
('essay', 1, 'يبين الشكل الآتي أربعة احتمالات لتصادم جزيء CO مع جزيء NO₂. حدّد في كل لوحة هل يؤدي التصادم إلى تفاعل أم لا، وفسّر إجابتك.', null, '[{"src":"qimg/chem22/c2-l1b-collisions.svg","alt":"أربع لوحات مرقمة من (1) إلى (4)، في كل منها جزيء CO على اليسار (ذرة كربون C داكنة متصلة بذرة أكسجين O حمراء) يتحرك نحو اليمين، وجزيء NO₂ على اليمين (ذرة نيتروجين N زرقاء متصلة بذرتي أكسجين O حمراوين) يتحرك نحو اليسار، وتحت كل لوحة عبارة عن طاقة التصادم. اللوحة (1): ذرة الأكسجين في CO تواجه ذرة أكسجين من NO₂، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (2): ذرة الكربون في CO تواجه ذرة النيتروجين في NO₂ وذرتا الأكسجين في الجهة البعيدة، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (3): ذرة الكربون في CO تواجه ذرة أكسجين من NO₂، والعبارة «طاقة التصادم أكبر من Ea». اللوحة (4): ذرة الكربون في CO تواجه ذرة أكسجين من NO₂، وسهما الحركة قصيران، والعبارة «طاقة التصادم أقل من Ea»."}]'::jsonb, null, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط (الشكل 2-4)'),
('essay', 2, 'طبّق نظرية التصادم لتفسير ما يأتي: عدد التصادمات بين جزيئات CO وجزيئات NO₂ في كل ثانية كبير جدًا، ومع ذلك يكون عدد التصادمات التي تنتج CO₂ و NO قليلًا.', null, null, null, 'تطبيق', 'تطبيق نظرية', 'متوسط', 'الكتاب ص 53، 54، 57 — س10'),
('essay', 3, 'قارن بين حالتين من حالات تصادم CO مع NO₂ لا تؤديان إلى تفاعل:
الحالة الأولى: تصادم ذرة الكربون في CO بذرة النيتروجين في NO₂ بطاقة أكبر من طاقة التنشيط.
الحالة الثانية: تصادم ذرة الكربون في CO بذرة أكسجين في NO₂ بطاقة أقل من طاقة التنشيط.
بيّن ما تشترك فيه الحالتان وما تختلفان فيه، واقترح ما يلزم تغييره في كل حالة لكي يصبح التصادم فعالًا.', null, null, null, 'تحليل', 'مقارنة واقتراح', 'صعب', 'الكتاب ص 54 — اتجاه التصادم وتكوين المعقد المنشط (الشكل 2-4)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L1-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'يكون التصادم فعالًا عندما يتحقق الشرطان معًا: الاتجاه الصحيح (ذرة الكربون في CO تلامس ذرة أكسجين من NO₂) وطاقة أكبر من طاقة التنشيط. وهذا متحقق في اللوحة (3) وحدها.', '["الطاقة كافية لكن الاتجاه غير صحيح؛ فذرة الأكسجين في CO هي التي تواجه NO₂ لا ذرة الكربون.","الطاقة كافية لكن ذرة الكربون تواجه ذرة النيتروجين لا ذرة الأكسجين، فلا تتكون رابطة C–O.","الاتجاه صحيح لكن طاقة التصادم أقل من طاقة التنشيط، فلا يتكون المعقد المنشط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-07T17:19:00.420Z"}'::jsonb),
('mcq', 2, 1, 'في اللوحة (2) تواجه ذرة الكربون ذرة النيتروجين؛ واتجاه التصادم غير صحيح لأن ذرة الكربون لا تلامس ذرة الأكسجين، فلا تنتقل ذرة الأكسجين إلى CO وترتد الجزيئات دون تكوين روابط.', '["زيادة طاقة التصادم عن Ea لا تمنع التفاعل؛ فالمانع هنا هو اتجاه التصادم.","","سرعتا الجزيئين المتقاربتين لا تمنعان التصادم، والشكل يُظهر تصادمهما فعلًا.","المعقد المنشط غير مستقر وعمره قصير، ولا يتكون أصلًا في تصادم اتجاهه غير صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.420Z"}'::jsonb),
('mcq', 3, 2, 'لا يؤدي التصادم إلى تفاعل إذا اختل أحد شرطي التصادم الفعال: الاتجاه الصحيح، والطاقة الكافية (التي تساوي طاقة التنشيط أو تزيد عليها) لتكوين المعقد المنشط.', '["هذان هما شرطا التصادم الفعال، وتحققهما يؤدي إلى التفاعل لا إلى فشله.","التصادم بين جزيئات المادة المتفاعلة نفسها ليس سببًا لفشل التصادمات بين المواد المتفاعلة.","","الطاقة الأكبر من طاقة التنشيط شرط لنجاح التصادم لا لفشله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.420Z"}'::jsonb),
('mcq', 4, 3, 'طاقة التنشيط هي الحد الأدنى من الطاقة اللازم لتكوين المعقد المنشط وإحداث التفاعل؛ فإذا كانت طاقة التصادم أقل منها لا يتكون المعقد المنشط، وترتد الجزيئات دون تفاعل رغم صحة الاتجاه.', '["لا يتكون المعقد المنشط إلا إذا كانت طاقة التصادم كافية.","في هذا التفاعل تنتقل ذرة الأكسجين من NO₂ إلى CO لا العكس، ولا يحدث ذلك أصلًا بطاقة غير كافية.","التصادم الواحد إما أن يكون فعالًا فيكوّن نواتج وإما ألا يكون؛ والطاقة غير الكافية لا تكوّن نواتج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.420Z"}'::jsonb),
('mcq', 5, 1, 'المعقد المنشط حالة انتقالية غير مستقرة قصيرة العمر، تتكسر فيها روابط وتتكون أخرى؛ لذا قد يؤدي إلى تكوين المواد الناتجة، أو يتكسر لتكوين المواد المتفاعلة مرة أخرى.', '["المعقد المنشط غير مستقر وعمره قصير، فلا يبقى دون تغير.","","المعقد المنشط يتكون من التصادم نفسه، والسؤال عن سبب عدم تكوّن النواتج بعد تكوّنه.","المعقد المنشط في قمة مخطط الطاقة، فطاقته أعلى من طاقة المتفاعلات لا أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.421Z"}'::jsonb),
('mcq', 6, 2, 'التصادمات تحدث فعلًا وبأعداد هائلة، لكن لا يتكون من أيٍّ منها نواتج تقريبًا؛ والتفسير أن طاقة معظم هذه التصادمات لا تبلغ طاقة التنشيط، فلا يتكون المعقد المنشط ولا يحدث التفاعل.', '["هذا يناقض المعطيات؛ فالجزيئات تتصادم بلايين المرات في كل ثانية.","كون التفاعل طاردًا للحرارة يتعلق بالفرق بين طاقة النواتج والمتفاعلات، ولا يفسر عدم حدوثه.","","لو تكونت نواتج لظهرت؛ وتكوّن نواتج من كل تصادم يناقض نظرية التصادم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.421Z"}'::jsonb),
('mcq', 7, 0, 'في التصادم غير المثمر (اتجاه غير مناسب أو طاقة غير كافية) لا يتكون المعقد المنشط، فترتد الجزيئات دون تكوين روابط جديدة ولا تتكون نواتج.', '["","التصادم غير المثمر لا يكوّن أيّ نواتج.","لا تتكسر الروابط في التصادم غير المثمر؛ فالجزيئات ترتد كما هي.","المعقد المنشط لا يتكون في التصادم غير المثمر، وهو غير مستقر أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.421Z"}'::jsonb),
('essay', 1, null::int, null, null, 'اللوحة (1): لا يحدث تفاعل؛ لأن الاتجاه غير صحيح (ذرة الأكسجين في CO تواجه NO₂ فلا تلامس ذرة الكربون ذرة الأكسجين) فترتد الجزيئات، رغم أن الطاقة كافية. اللوحة (2): لا يحدث تفاعل؛ لأن ذرة الكربون تلامس ذرة النيتروجين لا ذرة الأكسجين، فالاتجاه غير صحيح رغم كفاية الطاقة. اللوحة (3): يحدث تفاعل؛ لأن ذرة الكربون تلامس ذرة أكسجين من NO₂ (اتجاه صحيح) وطاقة التصادم أكبر من Ea، فيتكون المعقد المنشط ثم CO₂ و NO. اللوحة (4): لا يحدث تفاعل؛ فالاتجاه صحيح لكن طاقة التصادم أقل من طاقة التنشيط، فلا يتكون المعقد المنشط.', '["(1) لا تفاعل: اتجاه غير صحيح","(2) لا تفاعل: اتجاه غير صحيح","(3) تفاعل: اتجاه صحيح وطاقة كافية","(4) لا تفاعل: طاقة غير كافية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم والتفسير في اللوحة (1)","marks":1},{"element":"الحكم والتفسير في اللوحة (2)","marks":1},{"element":"الحكم والتفسير في اللوحة (3)","marks":1},{"element":"الحكم والتفسير في اللوحة (4)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أحكام اللوحات الأربع صحيحة ومفسرة"},{"level":"2–3 درجات","description":"أحكام صحيحة لمعظم اللوحات مع تفسير ناقص"},{"level":"1 درجة","description":"حكم صحيح مفسر في لوحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ اللوحة (4) تصادمًا فعالًا لأن الاتجاه صحيح","عدّ اللوحة (2) فعالة لأن الطاقة كافية","الحكم دون تفسير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-07T17:19:00.421Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وفق نظرية التصادم يجب أن تتصادم الجزيئات لكي يحدث التفاعل، لكن ليس كل تصادم يؤدي إلى تفاعل. فلكي يكون التصادم فعالًا يجب أن يتحقق شرطان: (1) الاتجاه الصحيح: أن تلامس ذرة الكربون في CO ذرة أكسجين في NO₂؛ وفي معظم التصادمات يكون الاتجاه غير مناسب فترتد الجزيئات دون تكوين روابط. (2) الطاقة الكافية: أن تكون طاقة التصادم مساوية لطاقة التنشيط أو أكبر منها لتكوين المعقد المنشط؛ وكثير من التصادمات يحدث بطاقة غير كافية. ولأن عددًا قليلًا فقط من التصادمات يحقق الشرطين معًا، فإن عدد التصادمات المنتجة قليل. وحتى بعد تكوّن المعقد المنشط قد يتكسر ليعيد تكوين المتفاعلات.', '["ليس كل تصادم يؤدي إلى تفاعل","شرط الاتجاه الصحيح وتطبيقه على CO و NO₂","شرط الطاقة الكافية (≥ Ea) لتكوين المعقد المنشط","قلة التصادمات المحققة للشرطين معًا"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن ليس كل تصادم يؤدي إلى تفاعل","marks":1},{"element":"تفسير دور الاتجاه مع التطبيق على الجزيئين","marks":1},{"element":"تفسير دور الطاقة وطاقة التنشيط","marks":1},{"element":"الربط: قلة ما يحقق الشرطين معًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل بالشرطين مطبق على CO و NO₂ مع الربط بقلة التصادمات المنتجة"},{"level":"2–3 درجات","description":"تفسير بأحد الشرطين أو بالشرطين دون تطبيق"},{"level":"1 درجة","description":"إشارة عامة إلى أن ليس كل تصادم فعالًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الطاقة وحدها وإغفال الاتجاه","القول إن الجزيئات لا تتصادم بالقدر الكافي","عدم تحديد الذرتين اللتين يجب أن تتلامسا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.421Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تشترك الحالتان في أن التصادم غير فعال (غير مثمر)، فلا يتكون المعقد المنشط وترتد الجزيئات دون تكوين نواتج. وتختلفان في سبب الفشل: في الحالة الأولى الطاقة كافية لكن الاتجاه غير صحيح لأن ذرة الكربون لا تلامس ذرة أكسجين؛ وفي الحالة الثانية الاتجاه صحيح لكن الطاقة أقل من Ea. لكي يصبح التصادم فعالًا: في الحالة الأولى يجب أن يتغير اتجاه التصادم فتلامس ذرة الكربون ذرة أكسجين من NO₂؛ وفي الحالة الثانية يجب أن تزداد طاقة التصادم حتى تساوي طاقة التنشيط أو تزيد عليها.', '["الاشتراك: كلاهما غير فعال ولا يكوّن المعقد المنشط","الأولى: سبب الفشل الاتجاه","الثانية: سبب الفشل الطاقة","اقتراح للأولى: تعديل الاتجاه","اقتراح للثانية: زيادة الطاقة إلى Ea فأكثر"]'::jsonb, '[]'::jsonb, '[{"element":"وجه الاشتراك","marks":1},{"element":"سبب فشل الحالة الأولى","marks":1},{"element":"سبب فشل الحالة الثانية","marks":1},{"element":"اقتراح الحالة الأولى","marks":1},{"element":"اقتراح الحالة الثانية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة واقتراحان صحيحان"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع نقص في أحد الاقتراحين"},{"level":"1–2 درجة","description":"تحديد سبب فشل حالة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الحالة الأولى فعالة لأن طاقتها كافية","اقتراح زيادة الطاقة في الحالة الأولى بدلًا من تعديل الاتجاه","إغفال وجه الاشتراك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.421Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
