('mcq', 5, 'يبين الجدول الآتي طاقة التنشيط لأربعة تفاعلات عند درجة الحرارة نفسها. إذا تساوت الظروف الأخرى، فأيّ التفاعلات يُتوقع أن يكون الأبطأ؟', '{"headers":["التفاعل","طاقة التنشيط Ea"],"rows":[["1","25 kJ"],["2","75 kJ"],["3","150 kJ"],["4","210 kJ"]]}'::jsonb, null, '["التفاعل 3","التفاعل 1","التفاعل 4","التفاعل 2"]'::jsonb, 'تطبيق', 'تطبيق على بيانات', 'سهل', 'الكتاب ص 55 — طاقة التنشيط وسرعة التفاعل'),
('mcq', 6, 'أيّ مما يأتي يفسر على مستوى الجسيمات لماذا يكون التفاعل الذي طاقة تنشيطه منخفضة أسرع؟', null, null, '["يكون عدد كبير من التصادمات له طاقة كافية لتكوين المعقد المنشط","يزداد العدد الكلي للتصادمات بين الجسيمات في كل ثانية","تقل طاقة النواتج فيصبح التفاعل أكثر طردًا للحرارة","لا تحتاج الجسيمات إلى التصادم في الاتجاه الصحيح"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 55 — طاقة التنشيط وسرعة التفاعل'),
