from (values
('mcq', 1, 1, 'Ea العالية تعني أن عددًا قليلًا من الاصطدامات له طاقة كافية لتكوين المعقد المنشط، ولذا تكون سرعة التفاعل بطيئة.', '["ارتفاع Ea يعني حاجزًا أعلى، ولا يعني أن الجسيمات تملك طاقة أكبر؛ فالسرعة تقل.","","الجسيمات تبقى تتصادم، لكن قلة من تصادماتها تملك الطاقة الكافية.","كلما ارتفعت Ea صعُب تكوين المعقد المنشط لا العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.422Z"}'::jsonb),
('mcq', 2, 3, 'طاقة تنشيط (أ) 30 kJ وطاقة تنشيط (ب) 90 kJ؛ وكلما قلّت Ea زاد عدد التصادمات التي لها طاقة كافية لتكوين المعقد المنشط، فيكون التفاعل (أ) أسرع.', '["Ea الكبيرة حاجز أعلى يبطئ التفاعل، ولا تمنح الجسيمات طاقة.","الاختيار صحيح لكن التعليل خطأ؛ فطاقة تنشيط (أ) هي الأصغر (30 kJ مقابل 90 kJ).","مستوى النواتج واحد في المخططين، وليس هو ما يحدد السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.422Z"}'::jsonb),
('mcq', 3, 2, 'طاقة التنشيط هي ارتفاع القمة فوق مستوى المتفاعلات، وأدنى قمة لـ Y ثم Z ثم X. وكلما قلّت Ea زادت السرعة؛ إذن الترتيب من الأسرع: Y ثم Z ثم X.', '["هذا ترتيب من الأبطأ إلى الأسرع (عكس المطلوب)؛ فـ X أعلى قمة فهو الأبطأ.","Y أدنى قمة من Z فهو أسرع منه.","","X صاحب أعلى طاقة تنشيط فهو الأبطأ لا الأسرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-07T17:19:00.422Z"}'::jsonb),
('mcq', 4, 3, 'ارتفاع التل هو الحاجز الذي يجب التغلب عليه، ويقابل طاقة التنشيط؛ فالتل المرتفع يحتاج إلى طاقة كبيرة ووقت طويل (تفاعل بطيء)، والتل المنخفض يحتاج إلى طاقة أقل ووقت أقصر (تفاعل أسرع).', '["ΔH هو الفرق بين طاقة النواتج والمتفاعلات، لا الحاجز الذي يجب تجاوزه.","طاقة النواتج تقابل ما بعد عبور التل، لا ارتفاعه.","سرعة الإنجاز نتيجة تتأثر بارتفاع التل، وليست هي ارتفاعه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-07T17:19:00.422Z"}'::jsonb),
('mcq', 5, 2, 'التفاعل الأبطأ هو صاحب أعلى طاقة تنشيط، وهو التفاعل 4 (210 kJ)؛ لأن عددًا أقل من تصادماته يمتلك الطاقة الكافية لتكوين المعقد المنشط.', '["طاقة تنشيط التفاعل 3 (150 kJ) أقل من طاقة تنشيط التفاعل 4، فهو أسرع منه.","التفاعل 1 أقل طاقة تنشيط (25 kJ) فهو الأسرع لا الأبطأ.","","طاقة تنشيط التفاعل 2 (75 kJ) منخفضة نسبيًا، فهو ليس الأبطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-07T17:19:00.422Z"}'::jsonb),
('mcq', 6, 0, 'Ea المنخفضة تعني أن عددًا كبيرًا من الاصطدامات له طاقة كافية لحدوث التفاعل (تكوين المعقد المنشط)، فتزداد نسبة التصادمات الفعالة ويكون التفاعل أسرع.', '["","قيمة Ea لا تغير عدد التصادمات الكلي، بل عدد التصادمات التي تملك الطاقة الكافية.","ΔH وطاقة النواتج لا تحددان سرعة التفاعل؛ الذي يحددها ارتفاع حاجز Ea.","شرط الاتجاه الصحيح يبقى لازمًا مهما كانت قيمة Ea."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.422Z"}'::jsonb),
('mcq', 7, 2, 'السرعة الكبيرة تدل على أن عددًا كبيرًا من التصادمات يملك الطاقة الكافية لتكوين المعقد المنشط، وهذا يحدث عندما تكون طاقة التنشيط منخفضة.', '["طاقة التنشيط العالية تجعل التفاعل بطيئًا لا سريعًا.","Ea و ΔH كميتان مختلفتان، ولا تدل سرعة التفاعل على أنهما متساويتان.","","كل تفاعل يحتاج إلى تصادمات، ولكل تفاعل طاقة تنشيط تمثل حاجزًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.423Z"}'::jsonb),
('essay', 1, null::int, null, null, 'كلما ارتفعت طاقة التنشيط قلّت سرعة التفاعل، وكلما انخفضت زادت السرعة. فعندما تكون Ea عالية يكون عدد قليل من الاصطدامات له طاقة كافية لتكوين المعقد المنشط، فيكون التفاعل بطيئًا؛ وعندما تكون Ea منخفضة يكون عدد كبير من الاصطدامات له طاقة كافية لحدوث التفاعل، فيكون أسرع. التشبيه: ارتفاع التل يمثل طاقة التنشيط؛ فإذا كان التل مرتفعًا احتاج الشخص إلى طاقة كبيرة ووقت طويل لدفع العربة إلى القمة، وإذا كان منخفضًا احتاج إلى طاقة أقل وأنجز المهمة في وقت أسرع.', '["Ea عالية → تفاعل بطيء","Ea منخفضة → تفاعل سريع","التفسير بعدد التصادمات ذات الطاقة الكافية","ارتفاع التل يقابل Ea، والتل المرتفع يحتاج إلى طاقة ووقت أكبر"]'::jsonb, '[]'::jsonb, '[{"element":"وصف العلاقة العكسية","marks":1},{"element":"التفسير بعدد التصادمات ذات الطاقة الكافية","marks":1},{"element":"ربط ارتفاع التل بطاقة التنشيط","marks":1},{"element":"مقارنة التل المرتفع بالمنخفض من حيث الطاقة والوقت","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"علاقة صحيحة مفسرة وتشبيه مكتمل"},{"level":"2–3 درجات","description":"علاقة صحيحة مع تفسير أو تشبيه ناقص"},{"level":"1 درجة","description":"ذكر العلاقة فقط"},{"level":"صفر","description":"علاقة معكوسة أو لا إجابة"}]'::jsonb, '["القول إن Ea العالية تسرع التفاعل","الخلط بين Ea و ΔH","تقديم التشبيه دون ربط ارتفاع التل بطاقة التنشيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-07T17:19:00.423Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) التفاعل (1) أسرع؛ لأن طاقة تنشيطه (15 kJ) أقل كثيرًا من طاقة تنشيط التفاعل (2) (180 kJ)، فيكون عدد التصادمات التي تملك طاقة كافية لتكوين المعقد المنشط في التفاعل (1) أكبر، فتزداد نسبة التصادمات الفعالة. (ب) تزداد سرعة التفاعل (2)؛ لأن خفض Ea يجعل عددًا أكبر من التصادمات يمتلك الحد الأدنى من الطاقة اللازم لتكوين المعقد المنشط، فيزداد عدد التصادمات المؤدية إلى تفاعل.', '["(أ) التفاعل (1) أسرع","التعليل: Ea أقل → تصادمات أكثر بطاقة كافية","(ب) تزداد السرعة","التعليل: عدد أكبر من التصادمات يبلغ Ea"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد التفاعل الأسرع","marks":1},{"element":"تعليل التوقع بنظرية التصادم","marks":1},{"element":"التنبؤ بزيادة سرعة التفاعل (2)","marks":1},{"element":"تعليل الزيادة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابتان صحيحتان مع تعليل كامل"},{"level":"2–3 درجات","description":"إجابتان صحيحتان مع تعليل ناقص، أو إجابة واحدة كاملة"},{"level":"1 درجة","description":"تحديد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار التفاعل (2) لأن قيمة Ea الأكبر تعني طاقة أكبر","القول إن خفض Ea يزيد العدد الكلي للتصادمات","التعليل دون ذكر المعقد المنشط أو الطاقة الكافية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.423Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب خاطئ. فالكمية التي تحدد سرعة التفاعل هي طاقة التنشيط Ea لا ΔH؛ إذ إن ΔH يمثل الفرق بين طاقة النواتج وطاقة المتفاعلات، ولا يحدد عدد التصادمات القادرة على تكوين المعقد المنشط. طاقة تنشيط (أ) = 120 kJ وطاقة تنشيط (ب) = 35 kJ؛ لذا فالتفاعل (ب) أسرع، لأن عددًا أكبر من تصادماته يملك طاقة كافية لتجاوز حاجز Ea الأقل. أما كون (أ) يطلق طاقة أكبر (ΔH = −150 kJ مقابل −20 kJ) فلا يجعله أسرع؛ فقد يكون التفاعل طاردًا جدًا للحرارة وبطيئًا إذا كانت طاقة تنشيطه عالية.', '["الحكم: قول الطالب خاطئ","Ea هي التي تحدد السرعة لا ΔH","قراءة Ea للتفاعلين (120 kJ و35 kJ)","التفاعل (ب) أسرع مع التعليل بالتصادمات","التفاعل الطارد جدًا قد يكون بطيئًا"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على قول الطالب","marks":1},{"element":"تحديد أن Ea هي التي تحدد السرعة","marks":1},{"element":"قراءة قيمتي Ea من المخطط","marks":1},{"element":"تحديد (ب) أسرع وتعليله","marks":1},{"element":"بيان أن ΔH لا يحدد السرعة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح، وتحديد التفاعل الأسرع، وتعليل كامل بـ Ea و ΔH"},{"level":"3–4 درجات","description":"حكم وتحديد صحيحان مع تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد صحيح للتفاعل الأسرع دون تقويم أو تعليل"},{"level":"صفر","description":"تأييد قول الطالب أو لا إجابة"}]'::jsonb, '["تأييد الطالب لأن (أ) أكثر طردًا للحرارة","الخلط بين سهم Ea وسهم ΔH","قراءة ارتفاع القمة عن محور الطاقة بدل قراءته فوق مستوى المتفاعلات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.423Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C2-L1-O09') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

