select (select id from public.objectives where code = 'K22-C2-L1-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا توضع إشارة سالبة في معادلة متوسط سرعة التفاعل المحسوبة من استهلاك المواد المتفاعلة: Rate = −Δ[reactants]/Δt؟', null, null, '["لأن تركيز المتفاعلات يقل فتكون Δ[reactants] سالبة، وسرعة التفاعل يجب أن تكون موجبة","لأن سرعة التفاعل تكون سالبة دائمًا عندما تُحسب من استهلاك المواد المتفاعلة","لأن الزمن النهائي أصغر من الزمن الابتدائي فتكون Δt سالبة","لأن تركيز المتفاعلات يزداد مع الزمن فيلزم عكس إشارة التغير"]'::jsonb, 'فهم', 'تفسير إشارة', 'سهل', 'الكتاب ص 51، 52 — التعبير عن سرعة التفاعل ومعادلة متوسط السرعة'),
('mcq', 2, 'يمثل المنحنيان في الشكل الآتي تغيّر تركيز CO وتركيز NO مع الزمن في التفاعل: CO(g) + NO₂(g) → CO₂(g) + NO(g). أيّ المنحنيين يمثل تركيز CO، وما إشارة Δ[CO]/Δt؟', null, '[{"src":"qimg/chem22/c2-l1b-conc-time.svg","alt":"منحنيان للتركيز مع الزمن: المحور الأفقي «الزمن (s)» من 0 إلى 40 بتدريج كل 10 s، والمحور الرأسي «التركيز (M)» من 0.000 إلى 0.200 بتدريج كل 0.050. المنحنى (1) يتناقص مع الزمن: 0.200 M عند 0 s، و0.160 M عند 10 s، و0.140 M عند 20 s، و0.128 M عند 30 s، و0.120 M عند 40 s. المنحنى (2) يتزايد مع الزمن: 0.000 M عند 0 s، و0.040 M عند 10 s، و0.060 M عند 20 s، و0.072 M عند 30 s، و0.080 M عند 40 s. وقد كُتبت على الشكل القيم 0.200 و0.140 و0.120 على المنحنى (1)، والقيمتان 0.060 و0.080 على المنحنى (2)."}]'::jsonb, '["المنحنى (2)، و Δ[CO]/Δt موجبة","المنحنى (1)، و Δ[CO]/Δt موجبة","المنحنى (1)، و Δ[CO]/Δt سالبة","المنحنى (2)، و Δ[CO]/Δt سالبة"]'::jsonb, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 51، 52، 57 — س6'),
('mcq', 3, 'في التفاعل: CO(g) + NO₂(g) → CO₂(g) + NO(g)، أيّ العلاقات الآتية تعبر تعبيرًا صحيحًا عن سرعة التفاعل بدلالة استهلاك CO؟', null, null, '["Rate = −Δ[CO]/Δt","Rate = Δ[CO]/Δt","Rate = −Δt/Δ[CO]","Rate = −Δ[CO₂]/Δt"]'::jsonb, 'تطبيق', 'كتابة علاقة', 'سهل', 'الكتاب ص 51، 52 — التعبير عن سرعة التفاعل ومعادلة متوسط السرعة'),
('mcq', 4, 'يمثل المنحنيان في الشكل الآتي تغيّر تركيز CO وتركيز NO مع الزمن في التفاعل: CO(g) + NO₂(g) → CO₂(g) + NO(g). ما متوسط سرعة التفاعل بدلالة استهلاك CO خلال أول 20 s؟', null, '[{"src":"qimg/chem22/c2-l1b-conc-time.svg","alt":"منحنيان للتركيز مع الزمن: المحور الأفقي «الزمن (s)» من 0 إلى 40 بتدريج كل 10 s، والمحور الرأسي «التركيز (M)» من 0.000 إلى 0.200 بتدريج كل 0.050. المنحنى (1) يتناقص مع الزمن: 0.200 M عند 0 s، و0.160 M عند 10 s، و0.140 M عند 20 s، و0.128 M عند 30 s، و0.120 M عند 40 s. المنحنى (2) يتزايد مع الزمن: 0.000 M عند 0 s، و0.040 M عند 10 s، و0.060 M عند 20 s، و0.072 M عند 30 s، و0.080 M عند 40 s. وقد كُتبت على الشكل القيم 0.200 و0.140 و0.120 على المنحنى (1)، والقيمتان 0.060 و0.080 على المنحنى (2)."}]'::jsonb, '["−0.0030 mol/L·s","0.010 mol/L·s","0.0015 mol/L·s","0.0030 mol/L·s"]'::jsonb, 'تطبيق', 'حساب من منحنى', 'متوسط', 'الكتاب ص 52 — معادلة متوسط سرعة التفاعل'),
('mcq', 5, 'في التفاعل: CO(g) + NO₂(g) → CO₂(g) + NO(g)، ما العلاقة بين متوسط سرعة التفاعل المحسوبة من استهلاك CO والمحسوبة من تكوّن NO خلال الفترة الزمنية نفسها؟', null, null, '["سرعة تكوّن NO ضعف سرعة استهلاك CO","متساويتان؛ لأن كل 1 mol من CO يُستهلك يتكون معه 1 mol من NO","سرعة استهلاك CO سالبة وسرعة تكوّن NO موجبة","سرعة استهلاك CO أكبر؛ لأن المتفاعلات تُستهلك قبل تكوّن النواتج"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 51، 52، 70 — س32'),
('mcq', 6, 'في التفاعل A → B، تكوّن B بمتوسط سرعة 0.0030 mol/L·s خلال 120 s. ما التغير في تركيز المادة A، أي Δ[A]، خلال هذه الفترة؟', null, null, '["−0.36 M","+0.36 M","−0.0030 M","−2.5 × 10⁻⁵ M"]'::jsonb, 'تطبيق', 'حساب وتفسير إشارة', 'صعب', 'الكتاب ص 51، 52 — التعبير عن سرعة التفاعل ومعادلة متوسط السرعة'),
('mcq', 7, 'حسب طالب التغير في تركيز المادة المتفاعلة X مقسومًا على الزمن، فحصل على Δ[X]/Δt = −0.0045 mol/L·s. كيف يكتب متوسط سرعة التفاعل؟', null, null, '["−0.0045 mol/L·s؛ لأن المادة X تُستهلك في التفاعل","0.0045 mol/L·s؛ لأن سرعة التفاعل تُكتب دائمًا بقيمة موجبة","0.0045 mol/L·s؛ لأن تركيز X يزداد مع مرور الزمن","−0.0045 mol/L·s؛ لأن الزمن النهائي أقل من الابتدائي"]'::jsonb, 'فهم', 'تفسير نتيجة', 'متوسط', 'الكتاب ص 51، 52 — التعبير عن سرعة التفاعل ومعادلة متوسط السرعة'),
('essay', 1, 'في التفاعل العام A → B:
(أ) كيف تعبر عن سرعة التفاعل بالاعتماد على تركيز المادة المتفاعلة A؟
(ب) كيف تعبر عنها بالاعتماد على تركيز المادة الناتجة B؟
(ج) قارن بين العلاقتين، وفسّر وجود الإشارة السالبة في إحداهما.', null, null, null, 'فهم', 'تعبير ومقارنة', 'سهل', 'الكتاب ص 51، 52، 70 — س32'),
('essay', 2, 'في تجربة للتفاعل: CO(g) + NO₂(g) → CO₂(g) + NO(g)، كان تركيز CO عند بدء القياس 0.250 M، وأصبح 0.190 M بعد 15.0 s، في حين ازداد تركيز NO من 0.000 M إلى 0.060 M في الفترة نفسها.
(أ) احسب متوسط سرعة التفاعل بدلالة استهلاك CO بوحدة mol/L·s.
(ب) احسب متوسط سرعة التفاعل بدلالة تكوّن NO.
(ج) فسّر لماذا استعملت الإشارة السالبة في (أ) ولم تستعملها في (ب)، ولماذا تساوت النتيجتان.', null, null, null, 'تطبيق', 'حساب مع خطوات', 'صعب', 'الكتاب ص 51، 52 — مثال 2-1 ومسائل تدريبية'),
('essay', 3, 'يمثل المنحنيان في الشكل الآتي تغيّر تركيز CO وتركيز NO مع الزمن في التفاعل: CO(g) + NO₂(g) → CO₂(g) + NO(g).
(أ) حدّد المنحنى الذي يمثل كل مادة، وصف كيف يتغير تركيزها مع الزمن، وما إشارة ميل كل منحنى؟
(ب) احسب متوسط سرعة التفاعل بدلالة استهلاك CO في الفترتين (0–20 s) و(20–40 s).
(ج) ماذا تستنتج عن تغير سرعة التفاعل مع مرور الزمن؟', null, '[{"src":"qimg/chem22/c2-l1b-conc-time.svg","alt":"منحنيان للتركيز مع الزمن: المحور الأفقي «الزمن (s)» من 0 إلى 40 بتدريج كل 10 s، والمحور الرأسي «التركيز (M)» من 0.000 إلى 0.200 بتدريج كل 0.050. المنحنى (1) يتناقص مع الزمن: 0.200 M عند 0 s، و0.160 M عند 10 s، و0.140 M عند 20 s، و0.128 M عند 30 s، و0.120 M عند 40 s. المنحنى (2) يتزايد مع الزمن: 0.000 M عند 0 s، و0.040 M عند 10 s، و0.060 M عند 20 s، و0.072 M عند 30 s، و0.080 M عند 40 s. وقد كُتبت على الشكل القيم 0.200 و0.140 و0.120 على المنحنى (1)، والقيمتان 0.060 و0.080 على المنحنى (2)."}]'::jsonb, null, 'تحليل', 'تحليل منحنى وحساب', 'صعب', 'الكتاب ص 52، 56 — معادلة متوسط السرعة ومختبر حل المشكلات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
