select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'يقل تركيز المادة المتفاعلة مع استمرار التفاعل، فيكون [reactants]t₂ − [reactants]t₁ سالبًا؛ ولأن سرعة التفاعل يجب أن تكون دائمًا موجبة يضع العلماء إشارة سالبة أمام المعادلة.', '["","سرعة التفاعل تُكتب دائمًا موجبة؛ والإشارة السالبة وُضعت لتجعلها موجبة.","الزمن يتقدم دائمًا فيكون t₂ أكبر من t₁ و Δt موجبًا.","تركيز المتفاعلات يقل مع الزمن لا يزداد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.423Z"}'::jsonb),
('mcq', 2, 2, 'CO مادة متفاعلة يقل تركيزها مع الزمن، فيمثلها المنحنى المتناقص (1)؛ ولأن [CO] يقل يكون Δ[CO] سالبًا فتكون Δ[CO]/Δt سالبة، ولذلك تُضرب في −1 عند التعبير عن السرعة.', '["المنحنى (2) متزايد فيمثل NO الناتج، وإشارة Δ[NO]/Δt هي الموجبة.","المنحنى صحيح لكن الإشارة خطأ؛ فتركيز CO يقل فيكون التغير سالبًا.","","المنحنى (2) متزايد فلا يمثل مادة متفاعلة تُستهلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-07T17:19:00.424Z"}'::jsonb),
('mcq', 3, 0, 'CO مادة متفاعلة يقل تركيزها، فتُكتب السرعة بدلالة استهلاكه بإشارة سالبة لتصبح موجبة: Rate = −Δ[CO]/Δt.', '["","Δ[CO] سالبة، فهذه العلاقة تعطي قيمة سالبة للسرعة.","السرعة هي التغير في التركيز مقسومًا على التغير في الزمن، لا العكس.","CO₂ مادة ناتجة يزداد تركيزها، والإشارة السالبة معها تعطي سرعة سالبة؛ كما أن المطلوب بدلالة CO."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-07T17:19:00.424Z"}'::jsonb),
('mcq', 4, 3, 'CO مادة متفاعلة فيمثلها المنحنى المتناقص (1). Rate = −([CO]₂₀ − [CO]₀)/(20 s − 0 s) = −(0.140 M − 0.200 M)/20 s = −(−0.060 M)/20 s = 0.0030 mol/L·s.', '["أُهملت الإشارة السالبة في معادلة السرعة، فظهرت السرعة سالبة.","قُسم التركيز الابتدائي 0.200 M على 20 s بدلًا من قسمة التغير في التركيز.","قُسم التغير 0.060 M على 40 s (الزمن الكلي للشكل) بدلًا من 20 s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-07T17:19:00.424Z"}'::jsonb),
('mcq', 5, 1, 'نسبة المولات في المعادلة 1 : 1؛ فكل 1 mol من CO يُستهلك يتكون معه 1 mol من NO، أي إن ما يقل من تركيز CO يساوي ما يزداد من تركيز NO في الفترة نفسها. وبوضع الإشارة السالبة مع CO تكون السرعتان متساويتين وموجبتين.', '["معاملا CO و NO في المعادلة متساويان (1 و1)، فلا يتكون NO بضعف السرعة.","","السرعة تُكتب موجبة في الحالتين؛ فالإشارة السالبة تُضاف إلى Δ[CO] لتصبح السرعة موجبة.","الاستهلاك والتكوّن يحدثان معًا، والكميتان متساويتان بحسب نسبة 1 : 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-07T17:19:00.424Z"}'::jsonb),
('mcq', 6, 0, 'Δ[B] = 0.0030 mol/L·s × 120 s = 0.36 M، ولأن نسبة A إلى B هي 1 : 1 يقل تركيز A بالمقدار نفسه، فيكون Δ[A] = −0.36 M، وتبقى السرعة بدلالة A: −Δ[A]/Δt = 0.0030 mol/L·s.', '["","تركيز A يقل لأنه مادة متفاعلة، فالتغير سالب لا موجب.","هذه قيمة السرعة لا التغير في التركيز؛ إذ لم تُضرب في الزمن 120 s.","قُسمت السرعة على الزمن بدلًا من ضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.424Z"}'::jsonb),
('mcq', 7, 1, 'بدلالة استهلاك المادة المتفاعلة: Rate = −Δ[X]/Δt = −(−0.0045 mol/L·s) = 0.0045 mol/L·s؛ فسرعة التفاعل يجب أن تكون دائمًا موجبة.', '["استهلاك X يجعل Δ[X] سالبًا، لكن السرعة نفسها تُكتب موجبة بإضافة الإشارة السالبة.","","القيمة صحيحة والتعليل خطأ؛ فـ X مادة متفاعلة يقل تركيزها.","الزمن النهائي أكبر دائمًا من الابتدائي، والسرعة تُكتب موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.424Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) Rate = −Δ[A]/Δt = −([A]t₂ − [A]t₁)/(t₂ − t₁). (ب) Rate = Δ[B]/Δt = ([B]t₂ − [B]t₁)/(t₂ − t₁). (ج) العلاقتان تعطيان القيمة نفسها لأن نسبة A إلى B هي 1 : 1، فما يقل من [A] يساوي ما يزداد من [B]. ووُضعت الإشارة السالبة في علاقة A لأن تركيز A يقل مع الزمن فيكون Δ[A] سالبًا، والسرعة يجب أن تكون دائمًا موجبة؛ أما Δ[B] فموجب لأن [B] يزداد.', '["Rate = −Δ[A]/Δt","Rate = Δ[B]/Δt","العلاقتان متساويتان (1 : 1)","Δ[A] سالب لأن A تُستهلك، والسرعة موجبة دائمًا"]'::jsonb, '[]'::jsonb, '[{"element":"علاقة A مع الإشارة","marks":1},{"element":"علاقة B","marks":1},{"element":"المقارنة: تساوي القيمتين","marks":1},{"element":"تفسير الإشارة السالبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العلاقتان صحيحتان والمقارنة والتفسير صحيحان"},{"level":"2–3 درجات","description":"العلاقتان صحيحتان مع مقارنة أو تفسير ناقص"},{"level":"1 درجة","description":"علاقة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال الإشارة السالبة في علاقة A","وضع الإشارة السالبة مع B","القول إن السرعة بدلالة A سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-07T17:19:00.425Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Rate = −Δ[CO]/Δt = −(0.190 M − 0.250 M)/(15.0 s − 0.0 s) = −(−0.060 M)/15.0 s = 0.0040 mol/L·s. (ب) Rate = Δ[NO]/Δt = (0.060 M − 0.000 M)/15.0 s = 0.0040 mol/L·s. (ج) تركيز CO يقل فيكون Δ[CO] سالبًا، فتوضع الإشارة السالبة لتصبح السرعة موجبة؛ أما [NO] فيزداد فيكون Δ[NO] موجبًا ولا حاجة إلى الإشارة. وتساوت النتيجتان لأن نسبة المولات بين CO و NO في المعادلة 1 : 1.', '["Rate(CO) = 0.0040 mol/L·s","Rate(NO) = 0.0040 mol/L·s","الإشارة السالبة لأن Δ[CO] سالب","التساوي بسبب نسبة 1 : 1"]'::jsonb, '["Δ[CO] = 0.190 M − 0.250 M = −0.060 M","Rate = −Δ[CO]/Δt = −(−0.060 M)/15.0 s = 0.0040 mol/L·s","Δ[NO] = 0.060 M − 0.000 M = 0.060 M","Rate = Δ[NO]/Δt = 0.060 M/15.0 s = 0.0040 mol/L·s"]'::jsonb, '[{"element":"حساب السرعة بدلالة CO مع الوحدة","marks":2},{"element":"حساب السرعة بدلالة NO","marks":1},{"element":"تفسير الإشارة السالبة","marks":1},{"element":"تفسير تساوي النتيجتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان بالوحدة وتفسيران صحيحان"},{"level":"3–4 درجات","description":"حسابان صحيحان مع تفسير ناقص، أو حساب واحد مع تفسيرين"},{"level":"1–2 درجة","description":"حساب واحد صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة السرعة بدلالة CO سالبة (−0.0040 mol/L·s)","قسمة التركيز النهائي على الزمن بدلًا من التغير في التركيز","إغفال الوحدة mol/L·s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.425Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المنحنى (1) يمثل CO والمنحنى (2) يمثل NO؛ فتركيز CO (مادة متفاعلة) يقل مع الزمن فميل المنحنى (1) سالب (Δ[CO]/Δt سالبة)، وتركيز NO (مادة ناتجة) يزداد فميل المنحنى (2) موجب. (ب) في (0–20 s): Rate = −(0.140 M − 0.200 M)/20 s = 0.0030 mol/L·s. وفي (20–40 s): Rate = −(0.120 M − 0.140 M)/20 s = 0.0010 mol/L·s. (ج) تتناقص سرعة التفاعل مع مرور الزمن؛ لأن تركيز المواد المتفاعلة يقل، وتصبح المنحنيات أقل انحدارًا. وتبقى السرعة موجبة في الفترتين رغم أن ميل منحنى CO سالب، بسبب الإشارة السالبة في معادلة السرعة.', '["المنحنى (1) لـ CO: يقل وميله سالب؛ المنحنى (2) لـ NO: يزداد وميله موجب","السرعة في (0–20 s) = 0.0030 mol/L·s","السرعة في (20–40 s) = 0.0010 mol/L·s","السرعة تتناقص مع الزمن وتبقى موجبة"]'::jsonb, '["(0–20 s): Δ[CO] = 0.140 M − 0.200 M = −0.060 M؛ Rate = −(−0.060 M)/20 s = 0.0030 mol/L·s","(20–40 s): Δ[CO] = 0.120 M − 0.140 M = −0.020 M؛ Rate = −(−0.020 M)/20 s = 0.0010 mol/L·s","المقارنة: 0.0010 < 0.0030، إذن السرعة تتناقص"]'::jsonb, '[{"element":"تحديد المنحنيين ووصف التغير وإشارة الميل","marks":1},{"element":"حساب السرعة في الفترة الأولى","marks":1},{"element":"حساب السرعة في الفترة الثانية","marks":1},{"element":"استنتاج تناقص السرعة مع بقائها موجبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح وحسابان صحيحان واستنتاج سليم"},{"level":"2–3 درجات","description":"حسابان صحيحان مع وصف أو استنتاج ناقص"},{"level":"1 درجة","description":"وصف صحيح فقط أو حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة السرعتين بقيم سالبة","قراءة قيم المنحنى (2) عند حساب السرعة بدلالة CO","استنتاج أن السرعة ثابتة لأن الفترتين متساويتان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-07T17:19:00.425Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
