('mcq', 1, 'يبين الشكل الآتي مخطط الطاقة للتفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g). كيف تكون طاقة تنشيط التفاعل العكسي CO₂(g) + NO(g) → CO(g) + NO₂(g) مقارنة بطاقة تنشيط التفاعل الأمامي؟', null, '[{"src":"qimg/chem22/c2-l1b-co-no2.svg","alt":"مخطط طاقة لتفاعل من خطوة واحدة؛ المحور الرأسي «الطاقة» والأفقي «سير التفاعل». يبدأ المنحنى عند مستوى المتفاعلات CO(g) + NO₂(g)، ثم يرتفع إلى قمة مكتوب عندها «المعقد المنشط»، ثم ينخفض إلى مستوى النواتج CO₂(g) + NO(g) الواقع أدنى من مستوى المتفاعلات. سهم أحمر من مستوى المتفاعلات إلى القمة مكتوب بجانبه «طاقة التنشيط»، وسهم أزرق من مستوى المتفاعلات إلى مستوى النواتج مكتوب بجانبه ΔH."}]'::jsonb, '["أصغر؛ لأن التفاعل العكسي ماص للطاقة","مساوية لها؛ لأن للتفاعلين المعقد المنشط نفسه","مساوية لقيمة ΔH للتفاعل الأمامي","أكبر؛ لأن مستوى طاقة CO₂ و NO أدنى من مستوى طاقة CO و NO₂"]'::jsonb, 'فهم', 'مقارنة من مخطط', 'سهل', 'الكتاب ص 56 — الشكل 2-6 التفاعل العكسي الماص للطاقة'),
('mcq', 2, 'في مخطط الطاقة الآتي، أيّ الأسهم يمثل طاقة تنشيط التفاعل العكسي؟', null, '[{"src":"qimg/chem22/c2-l1b-numbered.svg","alt":"مخطط طاقة لتفاعل من خطوة واحدة مستوى نواتجه أدنى من مستوى متفاعلاته (المحور الرأسي «الطاقة» والأفقي «سير التفاعل»)، وعليه ثلاثة أسهم مرقمة: السهم (1) يتجه إلى أعلى من مستوى المتفاعلات إلى قمة المنحنى، والسهم (2) يتجه إلى أعلى من مستوى النواتج إلى قمة المنحنى، والسهم (3) يتجه إلى أسفل من مستوى المتفاعلات إلى مستوى النواتج."}]'::jsonb, '["السهم (2)","السهم (1)","السهم (3)","طول (1) ناقص طول (3)"]'::jsonb, 'تحليل', 'تحليل مخطط', 'متوسط', 'الكتاب ص 56 — الشكل 2-6 التفاعل العكسي الماص للطاقة'),
('mcq', 3, 'اعتمادًا على مخطط الطاقة الآتي، ما طاقة التنشيط لكل من التفاعل الأمامي والتفاعل العكسي؟', null, '[{"src":"qimg/chem22/c2-l1b-exo-values.svg","alt":"مخطط طاقة لتفاعل من خطوة واحدة؛ المحور الرأسي «الطاقة (kJ)» مدرج من 0 إلى 180 كل 20 kJ، والأفقي «سير التفاعل». مستوى المتفاعلات عند 60 kJ، وقمة المنحنى (المعقد المنشط) عند 160 kJ، ومستوى النواتج عند 20 kJ، وخطوط متقطعة تصل كل مستوى بمحور الطاقة."}]'::jsonb, '["الأمامي 140 kJ، والعكسي 100 kJ","الأمامي 160 kJ، والعكسي 160 kJ","الأمامي 100 kJ، والعكسي 40 kJ","الأمامي 100 kJ، والعكسي 140 kJ"]'::jsonb, 'تطبيق', 'قراءة مخطط وحساب', 'متوسط', 'الكتاب ص 56 — الشكل 2-6 التفاعل العكسي الماص للطاقة'),
('mcq', 4, 'اعتمادًا على مخطط الطاقة الآتي، أيّ العبارات تقارن مقارنة صحيحة بين طاقتي التنشيط للتفاعلين الأمامي والعكسي؟', null, '[{"src":"qimg/chem22/c2-l1b-endo-values.svg","alt":"مخطط طاقة لتفاعل من خطوة واحدة؛ المحور الرأسي «الطاقة (kJ)» مدرج من 0 إلى 180 كل 20 kJ، والأفقي «سير التفاعل». مستوى المتفاعلات عند 30 kJ، وقمة المنحنى (المعقد المنشط) عند 150 kJ، ومستوى النواتج عند 110 kJ، وخطوط متقطعة تصل كل مستوى بمحور الطاقة."}]'::jsonb, '["طاقة تنشيط العكسي (120 kJ) أكبر من طاقة تنشيط الأمامي (40 kJ)","طاقة تنشيط الأمامي (120 kJ) أكبر من طاقة تنشيط العكسي (40 kJ)","طاقتا التنشيط متساويتان (150 kJ) لأن القمة واحدة","طاقة تنشيط الأمامي (80 kJ) أكبر من طاقة تنشيط العكسي (40 kJ)"]'::jsonb, 'تحليل', 'مقارنة من مخطط', 'صعب', 'الكتاب ص 56، 72 — س56'),
('mcq', 5, 'تفاعل طارد للحرارة يحدث في خطوة واحدة، طاقة تنشيط التفاعل الأمامي فيه 85 kJ، والتغير في الطاقة ΔH = −45 kJ. ما طاقة تنشيط التفاعل العكسي؟', null, null, '["130 kJ","40 kJ","85 kJ","45 kJ"]'::jsonb, 'تطبيق', 'حساب طاقة تنشيط العكسي', 'صعب', 'الكتاب ص 56 — الشكل 2-6 التفاعل العكسي الماص للطاقة'),
('mcq', 6, 'في أيّ تفاعل طارد للحرارة يحدث في خطوة واحدة، تكون:', null, null, '["طاقة تنشيط التفاعل الأمامي أكبر من طاقة تنشيط التفاعل العكسي","طاقة تنشيط التفاعل الأمامي مساوية لطاقة تنشيط التفاعل العكسي","طاقة تنشيط التفاعل العكسي أكبر من طاقة تنشيط التفاعل الأمامي","طاقة تنشيط التفاعل العكسي مساوية للتغير في الطاقة ΔH"]'::jsonb, 'فهم', 'تعميم', 'سهل', 'الكتاب ص 55، 56 — الشكلان 2-5 و2-6'),
('mcq', 7, 'يبين الجدول الآتي طاقتي التنشيط لتفاعل انعكاسي يحدث في خطوة واحدة. أيّ الاتجاهين أسرع عند الظروف نفسها، وما نوع التفاعل الأمامي؟', '{"headers":["الاتجاه","طاقة التنشيط Ea"],"rows":[["التفاعل الأمامي","50 kJ"],["التفاعل العكسي","90 kJ"]]}'::jsonb, null, '["العكسي أسرع، والتفاعل الأمامي طارد للحرارة","الأمامي أسرع، والتفاعل الأمامي ماص للحرارة","العكسي أسرع، والتفاعل الأمامي ماص للحرارة","الأمامي أسرع، والتفاعل الأمامي طارد للحرارة"]'::jsonb, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 56 — الشكل 2-6 التفاعل العكسي الماص للطاقة'),
('essay', 1, 'صف مخطط الطاقة لتفاعل ماص للحرارة يحدث في خطوة واحدة، محددًا عليه مواقع المتفاعلات والنواتج والمعقد المنشط وطاقة التنشيط للتفاعل الأمامي وللتفاعل العكسي، ثم قارن بين ارتفاعي طاقتي التنشيط.', null, null, null, 'تحليل', 'وصف مخطط ومقارنة', 'متوسط', 'الكتاب ص 72 — س56'),
('essay', 2, 'يبين الشكل الآتي مخطط الطاقة للتفاعل CO(g) + NO₂(g) → CO₂(g) + NO(g).
(أ) قارن بين طاقتي التنشيط للتفاعل الأمامي والتفاعل العكسي CO₂(g) + NO(g) → CO(g) + NO₂(g).
(ب) فسّر لماذا يحتاج التفاعل العكسي إلى طاقة أعلى.
(ج) ما نوع التفاعل العكسي من حيث الطاقة؟ وكيف يكون مستوى طاقة CO و NO₂ الناتجين منه؟', null, '[{"src":"qimg/chem22/c2-l1b-co-no2.svg","alt":"مخطط طاقة لتفاعل من خطوة واحدة؛ المحور الرأسي «الطاقة» والأفقي «سير التفاعل». يبدأ المنحنى عند مستوى المتفاعلات CO(g) + NO₂(g)، ثم يرتفع إلى قمة مكتوب عندها «المعقد المنشط»، ثم ينخفض إلى مستوى النواتج CO₂(g) + NO(g) الواقع أدنى من مستوى المتفاعلات. سهم أحمر من مستوى المتفاعلات إلى القمة مكتوب بجانبه «طاقة التنشيط»، وسهم أزرق من مستوى المتفاعلات إلى مستوى النواتج مكتوب بجانبه ΔH."}]'::jsonb, null, 'تحليل', 'مقارنة من مخطط', 'سهل', 'الكتاب ص 56 — الشكل 2-6 التفاعل العكسي الماص للطاقة'),
('essay', 3, 'في تفاعل انعكاسي يحدث في خطوة واحدة: A + B ⇌ C + D، كانت طاقة المتفاعلات A + B تساوي 40 kJ، وطاقة المعقد المنشط 175 kJ، وطاقة النواتج C + D تساوي 95 kJ (قيم نسبية على مخطط الطاقة).
(أ) احسب طاقة التنشيط للتفاعل الأمامي وللتفاعل العكسي، و ΔH للتفاعل الأمامي.
(ب) حدد نوع التفاعل الأمامي من حيث الطاقة.
(ج) أيّ الاتجاهين أسرع عند الظروف نفسها؟ علّل.
(د) بيّن العلاقة بين طاقتي التنشيط و ΔH باستعمال نتائجك.', null, null, null, 'تطبيق', 'حساب مع خطوات', 'صعب', 'الكتاب ص 55، 56، 72 — مخططات الطاقة والتفاعل العكسي')
