select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'التفاعلان يمران بالمعقد المنشط نفسه (القمة نفسها)، لكن التفاعل العكسي يبدأ من مستوى CO₂ و NO الأدنى؛ فالمسافة من مستواه إلى القمة أكبر، أي أن طاقة تنشيطه أكبر من طاقة تنشيط التفاعل الأمامي.', '["كون التفاعل العكسي ماصًا يعني أنه يبدأ من مستوى أدنى، فيحتاج إلى طاقة تنشيط أكبر لا أصغر.","القمة واحدة فعلًا، لكن نقطتي البداية مختلفتان فتختلف طاقتا التنشيط.","طاقة تنشيط العكسي هي المسافة من النواتج إلى القمة، وهي تساوي طاقة تنشيط الأمامي مضافًا إليها مقدار ΔH، لا ΔH وحده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.426Z"}'::jsonb),
('mcq', 2, 0, 'التفاعل العكسي يبدأ من النواتج، وطاقة تنشيطه هي الفرق بين طاقة المعقد المنشط (القمة) وطاقة النواتج؛ وهذا ما يمثله السهم (2).', '["","السهم (1) من المتفاعلات إلى القمة، فهو طاقة تنشيط التفاعل الأمامي.","السهم (3) هو التغير في الطاقة ΔH بين المتفاعلات والنواتج.","الفرق بين طولي (1) و(3) أصغر من طاقة تنشيط العكسي؛ فطاقة تنشيط العكسي تساوي طول (1) مضافًا إليه طول (3)، وهو طول السهم (2)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-07T17:19:00.426Z"}'::jsonb),
('mcq', 3, 3, 'Ea (الأمامي) = طاقة المعقد المنشط − طاقة المتفاعلات = 160 − 60 = 100 kJ. Ea (العكسي) = طاقة المعقد المنشط − طاقة النواتج = 160 − 20 = 140 kJ.', '["عُكست القيمتان؛ فالأمامي يبدأ من المتفاعلات (60 kJ) والعكسي من النواتج (20 kJ).","قُرئت طاقة القمة من المحور مباشرة دون طرح طاقة نقطة البداية.","40 kJ هو مقدار ΔH (60 − 20)، لا طاقة تنشيط التفاعل العكسي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-07T17:19:00.426Z"}'::jsonb),
('mcq', 4, 1, 'Ea (الأمامي) = 150 − 30 = 120 kJ، و Ea (العكسي) = 150 − 110 = 40 kJ؛ فالتفاعل الأمامي ماص (النواتج أعلى من المتفاعلات)، وطاقة تنشيطه أكبر من طاقة تنشيط العكسي بمقدار ΔH = +80 kJ.', '["عُكست القيمتان؛ فالعكسي يبدأ من النواتج عند 110 kJ وهي قريبة من القمة.","","150 kJ طاقة القمة نفسها؛ وطاقة التنشيط تُقاس من نقطة بداية كل تفاعل إلى القمة.","80 kJ هو ΔH (110 − 30)، لا طاقة تنشيط التفاعل الأمامي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.426Z"}'::jsonb),
('mcq', 5, 0, 'مستوى النواتج أدنى من مستوى المتفاعلات بمقدار 45 kJ، والقمة أعلى من المتفاعلات بمقدار 85 kJ؛ إذن ارتفاع القمة فوق النواتج = 85 + 45 = 130 kJ، وهي طاقة تنشيط التفاعل العكسي.', '["","طُرح ΔH من طاقة التنشيط (85 − 45)، مع أن النواتج أدنى من المتفاعلات فتُضاف المسافة.","افتُرض أن طاقتي التنشيط متساويتان لأن القمة واحدة، مع أن نقطتي البداية مختلفتان.","هذا مقدار ΔH فقط، لا المسافة من النواتج إلى القمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.427Z"}'::jsonb),
('mcq', 6, 2, 'في التفاعل الطارد تكون طاقة النواتج أقل من طاقة المتفاعلات، فيبدأ التفاعل العكسي من مستوى أدنى ويحتاج إلى طاقة أكبر ليصل إلى المعقد المنشط نفسه؛ فطاقة تنشيط العكسي أكبر.', '["هذا يصح في التفاعل الماص (الأمامي) لا الطارد.","تتساويان فقط لو تساوت طاقة المتفاعلات والنواتج، وهذا لا ينطبق على تفاعل طارد.","","طاقة تنشيط العكسي تساوي طاقة تنشيط الأمامي مضافًا إليها مقدار ΔH، لا ΔH وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.427Z"}'::jsonb),
('mcq', 7, 3, 'طاقة تنشيط الأمامي (50 kJ) أقل من طاقة تنشيط العكسي (90 kJ)، فالأمامي أسرع. ولأن القمة أعلى من المتفاعلات بـ 50 kJ ومن النواتج بـ 90 kJ، فالنواتج أدنى من المتفاعلات بـ 40 kJ (ΔH = 50 − 90 = −40 kJ)، فالتفاعل الأمامي طارد للحرارة.', '["طاقة تنشيط العكسي هي الأكبر فهو الأبطأ.","الأمامي أسرع فعلًا، لكن كون Ea (العكسي) أكبر يعني أن النواتج أدنى من المتفاعلات فالأمامي طارد.","العكسي أبطأ، والأمامي طارد لا ماص.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.427Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يبدأ المنحنى عند مستوى المتفاعلات المنخفض، ثم يرتفع إلى قمة تمثل المعقد المنشط، ثم ينخفض قليلًا إلى مستوى النواتج الذي يقع أعلى من مستوى المتفاعلات (لأن التفاعل ماص، و ΔH موجب). طاقة تنشيط التفاعل الأمامي هي المسافة الرأسية من مستوى المتفاعلات إلى القمة، وطاقة تنشيط التفاعل العكسي هي المسافة الرأسية من مستوى النواتج إلى القمة. المقارنة: طاقة تنشيط التفاعل الأمامي أكبر من طاقة تنشيط التفاعل العكسي، والفرق بينهما يساوي ΔH؛ لأن التفاعلين يشتركان في المعقد المنشط نفسه والنواتج أعلى من المتفاعلات.', '["النواتج أعلى من المتفاعلات","القمة تمثل المعقد المنشط","Ea الأمامي: من المتفاعلات إلى القمة","Ea العكسي: من النواتج إلى القمة","Ea الأمامي أكبر بمقدار ΔH"]'::jsonb, '[]'::jsonb, '[{"element":"موقع المتفاعلات والنواتج صحيح","marks":1},{"element":"تحديد المعقد المنشط","marks":1},{"element":"تحديد Ea الأمامي","marks":1},{"element":"تحديد Ea العكسي","marks":1},{"element":"المقارنة الصحيحة مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل للمخطط ومقارنة صحيحة معللة"},{"level":"3–4 درجات","description":"وصف صحيح مع نقص في تحديد إحدى طاقتي التنشيط أو في التعليل"},{"level":"1–2 درجة","description":"وصف جزئي أو مقارنة دون وصف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم النواتج أدنى من المتفاعلات في التفاعل الماص","قياس طاقة التنشيط من محور الطاقة لا من مستوى البداية","القول إن طاقة تنشيط العكسي أكبر في التفاعل الماص"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.427Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) طاقة تنشيط التفاعل العكسي أكبر من طاقة تنشيط التفاعل الأمامي. (ب) لأن التفاعلين يمران بالمعقد المنشط نفسه، لكن التفاعل العكسي يبدأ من مستوى طاقة CO₂ و NO الأدنى؛ فيجب أن يتغلب على حاجز أعلى (يساوي Ea الأمامي مضافًا إليه مقدار ΔH) لإعادة إنتاج CO و NO₂. (ج) التفاعل العكسي ماص للطاقة؛ فإذا حدث وأنتج CO و NO₂ يكون مستوى طاقتها أعلى من مستوى طاقة CO₂ و NO.', '["Ea العكسي > Ea الأمامي","المعقد المنشط نفسه ونقطة بداية العكسي أدنى","الحاجز العكسي = Ea الأمامي + |ΔH|","العكسي ماص وتكون نواتجه (CO و NO₂) أعلى طاقة"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة الصحيحة","marks":1},{"element":"تفسير الحاجز الأعلى للعكسي","marks":1},{"element":"تحديد نوع التفاعل العكسي","marks":1},{"element":"مستوى طاقة CO و NO₂ الناتجين أعلى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابات الأجزاء الثلاثة صحيحة ومفسرة"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع نقص في التفسير أو في الجزء (ج)"},{"level":"1 درجة","description":"مقارنة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن طاقتي التنشيط متساويتان لأن القمة واحدة","وصف التفاعل العكسي بأنه طارد","عدّ ΔH وحده طاقة تنشيط التفاعل العكسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.427Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) Ea (الأمامي) = 175 − 40 = 135 kJ؛ Ea (العكسي) = 175 − 95 = 80 kJ؛ ΔH = 95 − 40 = +55 kJ. (ب) التفاعل الأمامي ماص للحرارة لأن طاقة النواتج أعلى من طاقة المتفاعلات (ΔH موجب). (ج) التفاعل العكسي أسرع؛ لأن طاقة تنشيطه (80 kJ) أقل من طاقة تنشيط الأمامي (135 kJ)، فيكون عدد التصادمات التي تملك الطاقة الكافية أكبر. (د) Ea (الأمامي) − Ea (العكسي) = 135 − 80 = 55 kJ = ΔH؛ أي أن طاقة تنشيط التفاعل الأمامي الماص أكبر من طاقة تنشيط العكسي بمقدار ΔH.', '["Ea الأمامي = 135 kJ","Ea العكسي = 80 kJ","ΔH = +55 kJ والتفاعل الأمامي ماص","العكسي أسرع لأن طاقة تنشيطه أقل","Ea الأمامي − Ea العكسي = ΔH"]'::jsonb, '["Ea (الأمامي) = 175 kJ − 40 kJ = 135 kJ","Ea (العكسي) = 175 kJ − 95 kJ = 80 kJ","ΔH = 95 kJ − 40 kJ = +55 kJ","Ea (الأمامي) − Ea (العكسي) = 135 kJ − 80 kJ = 55 kJ = ΔH"]'::jsonb, '[{"element":"حساب Ea الأمامي","marks":1},{"element":"حساب Ea العكسي","marks":1},{"element":"حساب ΔH وتحديد نوع التفاعل","marks":1},{"element":"تحديد الاتجاه الأسرع مع التعليل","marks":1},{"element":"بيان العلاقة بين Ea و ΔH","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات الثلاثة صحيحة، والأجزاء (ب) و(ج) و(د) صحيحة ومعللة"},{"level":"3–4 درجات","description":"الحسابات صحيحة مع خطأ أو نقص في جزء واحد من الاستنتاجات"},{"level":"1–2 درجة","description":"حساب واحد أو اثنان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب Ea العكسي من المتفاعلات بدل النواتج","كتابة ΔH سالبًا للتفاعل الماص","اختيار الأمامي أسرع لأن طاقة تنشيطه أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.427Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
