from (values
('mcq', 1, 'لماذا تُستعمل المحفزات على نطاق واسع في الصناعات الكيميائية؟', null, null, '["لأنها تزيد الكمية النهائية من النواتج التي تتكون من كمية المتفاعلات نفسها","لأنها تُنتج كمية أكبر من المنتج في وقت أقصر، فتقل تكلفة إنتاجه","لأنها تتحول في أثناء التفاعل إلى جزء من المنتج فتزيد كتلته","لأنها ترفع درجة حرارة خليط التفاعل فتزداد سرعته"]'::jsonb, 'فهم', 'تفسير أهمية', 'سهل', 'الكتاب ص 61 — المحفزات (استعمالها في الصناعات الكيميائية)'),
('mcq', 2, 'يحتاج الجسم إلى تسريع تحلل الجلوكوز داخل الخلية الحية. ما الطريقة العملية التي تتم بها زيادة سرعة هذا التفاعل في الخلية؟', null, null, '["رفع درجة حرارة الخلية رفعًا كبيرًا لزيادة عدد الاصطدامات","زيادة تركيز الجلوكوز في الخلية زيادة كبيرة جدًّا","إضافة مثبطات ترتبط بالإنزيمات الموجودة في الخلية","وجود إنزيمات تحفز التفاعل عند درجة حرارة الجسم الطبيعية"]'::jsonb, 'فهم', 'تطبيق مفهوم على موقف حياتي', 'متوسط', 'الكتاب ص 61 — المحفزات (تحلل الجلوكوز في الخلية الحية)'),
('mcq', 3, 'أيّ مما يأتي مثال على محفز حيوي يعمل في أجسام المخلوقات الحية؟', null, null, '["الإنزيم الذي يسرّع تحلل الجلوكوز في الخلية","المادة الحافظة المضافة إلى الأغذية","المادة المضادة للأكسدة في الزيوت","الجلوكوز الذي يتحلل في الخلية"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 61 — المحفزات (الإنزيمات)'),
('mcq', 4, 'يتحول ATP في خلايا الجسم إلى ADP ومجموعة الفوسفات Pᵢ وتتحرر طاقة وفق المعادلة: ATP → ADP + Pᵢ + طاقة. ما أهمية الإنزيمات لهذا التفاعل؟', null, null, '["تزيد مقدار الطاقة المتحررة من تحول كل جزيء ATP","تُستهلك في التفاعل فتتحول إلى ADP ومجموعة الفوسفات","تجعل التفاعل يحدث بالسرعة التي يحتاج إليها الجسم عند درجة حرارته الطبيعية","ترفع درجة حرارة الخلية كثيرًا فيزداد عدد الاصطدامات"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 67 — الكيمياء والصحة: التفاعلات الكيميائية تسخن الجسم (ATP والإنزيمات)'),
('mcq', 5, 'يُنتج مصنع مادة كيميائية بالتفاعل نفسه وبالكميات نفسها من المتفاعلات مرة دون محفز ومرة مع محفز، والنتائج في الجدول الآتي. أيّ استنتاج تدعمه هذه البيانات؟', '{"headers":["الدفعة","زمن الإنتاج","كتلة المنتج","كتلة المحفز قبل التفاعل","كتلة المحفز بعد التفاعل"],"rows":[["دون محفز","10 h","100 kg","—","—"],["مع محفز","2 h","100 kg","5 kg","5 kg"]]}'::jsonb, null, '["المحفز يزيد كتلة المنتج المتكونة من الكمية نفسها من المتفاعلات","المحفز يقصّر زمن الإنتاج ويمكن إعادة استعماله، فتقل تكلفة المنتج","المحفز يُستهلك في أثناء التفاعل، فيلزم تعويضه بعد كل دفعة","المحفز يقصّر زمن الإنتاج لكنه يقلل كتلة المنتج المتكونة"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 61 — المحفزات (استعمالها في الصناعات الكيميائية)'),
('mcq', 6, 'يتحلل فوق أكسيد الهيدروجين إلى ماء وغاز الأكسجين ببطء، وعند إضافة كمية قليلة من ثاني أكسيد المنجنيز MnO₂ يتصاعد الأكسجين بسرعة أكبر، وتبقى كتلة MnO₂ في نهاية التفاعل كما هي. ما الذي يجعل استعمال MnO₂ مفيدًا في هذا التفاعل؟', null, null, '["يسرّع إنتاج الأكسجين، ولا يُستهلك فيمكن استرجاعه واستعماله مرة أخرى","يزيد الحجم الكلي للأكسجين الناتج من الكمية نفسها من فوق أكسيد الهيدروجين","يتفاعل مع فوق أكسيد الهيدروجين فيُنتج كمية إضافية من الأكسجين","يرفع درجة حرارة المحلول فيبطئ تحلل فوق أكسيد الهيدروجين"]'::jsonb, 'فهم', 'تفسير موقف', 'متوسط', 'الكتاب ص 70 — تقويم الفصل (س43: تحلل فوق أكسيد الهيدروجين وثاني أكسيد المنجنيز)'),
('mcq', 7, 'تمكن علماء من اكتشاف محفز جديد يزيد سرعة إنتاج دواء فعال ضد مرض الإنفلونزا. ما النتيجة المتوقعة لاستعمال هذا المحفز في مصنع الدواء؟', null, null, '["الحصول على كمية دواء تفوق ما تسمح به كميات المتفاعلات المستعملة","استهلاك المحفز كاملًا فيلزم إضافته بكميات كبيرة باستمرار","ظهور المحفز ضمن نواتج التفاعل فيختلط بالدواء الناتج","إنتاج الكمية المطلوبة من الدواء في زمن أقصر وبتكلفة أقل"]'::jsonb, 'تطبيق', 'تطبيق في موقف جديد', 'صعب', 'الكتاب ص 73 — تقويم إضافي (س65: محفز لإنتاج دواء الإنفلونزا)'),
('essay', 1, 'بيّن أهمية المحفزات في كل من: (أ) أجسام المخلوقات الحية. (ب) الصناعات الكيميائية. واذكر مثالًا واحدًا في كل حالة.', null, null, null, 'فهم', 'بيان أهمية مع أمثلة', 'سهل', 'الكتاب ص 61، 67 — المحفزات والإنزيمات'),
('essay', 2, 'يُنتج مصنع مادة كيميائية بتفاعل بطيء. اقترح مهندس رفع درجة حرارة التفاعل كثيرًا، واقترح آخر استعمال محفز مناسب. (أ) وضّح كيف يزيد كل من الاقتراحين سرعة التفاعل. (ب) بيّن لماذا يُعد استعمال المحفز أكثر فائدة اقتصاديًّا، علمًا بأن الإبقاء على درجة حرارة مرتفعة يحتاج إلى استهلاك مستمر للطاقة. (ج) هل يزيد أيٌّ من الاقتراحين الكمية الكلية للمنتج من الكمية نفسها من المتفاعلات؟ وضّح.', null, null, null, 'تحليل', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 60–61 — درجة الحرارة؛ المحفزات (استعمالها في الصناعات الكيميائية)'),
('essay', 3, 'قال طالب: «ما دامت زيادة درجة الحرارة تزيد سرعة التفاعلات الكيميائية، فيمكن لجسم الإنسان أن يستغني عن الإنزيمات برفع درجة حرارته». قوّم هذه العبارة، ووضّح أهمية الإنزيمات بديلًا عن رفع درجة الحرارة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 61، 67 — المحفزات والإنزيمات ودرجة حرارة الجسم')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تزيد المحفزات سرعة التفاعل دون أن تُستهلك، فتُنتج المصانع كمية أكبر من المنتج في وقت أقصر، مما يقلل تكلفته؛ لذا فالإجابة: تُنتج كمية أكبر من المنتج في وقت أقصر فتقل تكلفة إنتاجه.', '["المحفز لا يزيد عدد النواتج ولا كميتها النهائية؛ إنما يجعلها تتكون بسرعة أكبر.","","المحفز لا يُستهلك في التفاعل ولا يصبح جزءًا من النواتج.","المحفز لا يعمل برفع درجة الحرارة؛ بل يزيد السرعة بتقليل طاقة التنشيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.428Z"}'::jsonb),
('mcq', 2, 3, 'زيادة درجة الحرارة أو التركيز في الخلية الحية قد تضر بها أو تقتلها، لذا تعتمد الخلية على الإنزيمات، وهي محفزات تجعل التفاعلات تحدث بالسرعة الكافية عند درجة حرارة الجسم الطبيعية.', '["رفع درجة حرارة الخلية كثيرًا قد يضر بها أو يقتلها، فليس طريقة عملية في الخلية الحية.","زيادة تركيز المتفاعلات كثيرًا داخل الخلية قد تضر بها، فلا يعتمد الجسم على ذلك.","المثبطات تبطئ التفاعل أو تمنع حدوثه، ولا تزيد سرعته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.428Z"}'::jsonb),
('mcq', 3, 0, 'الإنزيم نوع من أنواع المحفزات، يزيد سرعة التفاعلات الكيميائية في المخلوقات الحية دون أن يُستهلك؛ فالإنزيم الذي يسرّع تحلل الجلوكوز في الخلية محفز حيوي، أما المواد الحافظة والمضادة للأكسدة فمثبطات، والجلوكوز مادة متفاعلة.', '["","المادة الحافظة من المثبطات المستعملة في صناعة الأغذية لإبطاء التفاعلات.","المواد المضادة للأكسدة من المثبطات، فهي تبطئ التفاعل ولا تسرّعه.","الجلوكوز مادة متفاعلة تتحلل في الخلية، وليس محفزًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.428Z"}'::jsonb),
('mcq', 4, 2, 'لا يمكن أن تحدث مثل هذه التفاعلات بالسرعة التي تلبي احتياجات الجسم دون مساعدة الإنزيمات، وهي محفزات بروتينية تزيد سرعة التفاعل دون أن تُستهلك؛ فأهميتها أنها تجعل التفاعل يحدث بالسرعة التي يحتاج إليها الجسم عند درجة حرارته الطبيعية (نحو 37 °C).', '["المحفز لا يغير طاقة المتفاعلات ولا النواتج، فلا يزيد الطاقة المتحررة؛ بل يسرّع التفاعل فقط.","الإنزيم محفز لا يُستهلك في التفاعل، وADP ومجموعة الفوسفات نواتج تحول ATP نفسه.","","الإنزيمات لا ترفع درجة حرارة الخلية؛ ورفعها كثيرًا يضر بالخلية ويكسر تركيب الإنزيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.428Z"}'::jsonb),
('mcq', 5, 1, 'كتلة المنتج 100 kg في الحالتين، لكن زمن الإنتاج قصر من 10 h إلى 2 h، وبقيت كتلة المحفز 5 kg قبل التفاعل وبعده فلم يُستهلك؛ لذا يُنتج المصنع كمية أكبر في الزمن نفسه ويعيد استعمال المحفز، فتقل تكلفة المنتج.', '["كتلة المنتج 100 kg في الدفعتين، فالمحفز لم يزد كمية المنتج.","","كتلة المحفز بقيت 5 kg بعد التفاعل، فهو لم يُستهلك ولا يلزم تعويضه.","كتلة المنتج لم تقل بل بقيت 100 kg؛ والمحفز غيّر الزمن فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.429Z"}'::jsonb),
('mcq', 6, 0, 'ثبات كتلة MnO₂ يدل على أنه لم يُستهلك، وتصاعد الأكسجين بسرعة أكبر يدل على أنه محفز؛ فهو يسرّع إنتاج الأكسجين ويمكن استرجاعه واستعماله مرة أخرى.', '["","المحفز لا يزيد كمية النواتج؛ فحجم الأكسجين الكلي يتحدد بكمية فوق أكسيد الهيدروجين.","لو تفاعل MnO₂ لاستُهلك ونقصت كتلته، لكن كتلته بقيت ثابتة.","التحلل صار أسرع لا أبطأ، والمحفز لا يعمل برفع درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-07T17:19:00.429Z"}'::jsonb),
('mcq', 7, 3, 'المحفز يزيد سرعة التفاعل دون أن يُستهلك، فيُنتج المصنع الكمية المطلوبة من الدواء في زمن أقصر، ما يقلل التكلفة ويوفر الدواء بسرعة وقت انتشار المرض.', '["المحفز لا يزيد كمية النواتج عن الكمية التي تسمح بها المتفاعلات؛ بل يسرّع تكوّنها.","المحفز لا يُستهلك في التفاعل، فلا يلزم تعويضه بكميات كبيرة.","المحفز لا يُعد من المواد الناتجة عن التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.429Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) في المخلوقات الحية: لا يحدث كثير من التفاعلات الكيميائية بالسرعة الكافية للمحافظة على الحياة عند درجات الحرارة الطبيعية لولا وجود الإنزيمات، وهي محفزات حيوية؛ ورفع درجة الحرارة أو التركيز ليس حلًّا لأنه قد يضر بالخلية أو يقتلها. مثال: تحلل الجلوكوز في الخلية، أو تحول ATP إلى ADP ومجموعة الفوسفات وتحرير الطاقة بمساعدة الإنزيمات. (ب) في الصناعة: تُستعمل المحفزات على نطاق واسع لإنتاج كمية أكبر من المنتج بسرعة كبيرة، مما يقلل من تكلفته، دون أن تُستهلك. مثال: استعمال محفز يسرّع إنتاج دواء لمرض الإنفلونزا.', '["الإنزيمات تجعل تفاعلات الجسم تحدث بالسرعة الكافية عند درجة حرارته الطبيعية","مثال حيوي صحيح (تحلل الجلوكوز أو تحول ATP)","المحفزات في الصناعة تزيد سرعة الإنتاج فتقل التكلفة","مثال صناعي صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"أهمية المحفزات في المخلوقات الحية","marks":1},{"element":"مثال حيوي","marks":1},{"element":"أهمية المحفزات في الصناعة","marks":1},{"element":"مثال صناعي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: أهمية المحفزات في المخلوقات الحية؛ مثال حيوي؛ أهمية المحفزات في الصناعة؛ مثال صناعي"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يزيد كمية المنتج الكلية بدلًا من سرعة إنتاجه","ذكر مادة حافظة مثالًا على المحفز","إغفال سبب عدم الاعتماد على رفع درجة حرارة الخلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.429Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) رفع درجة الحرارة يزيد متوسط الطاقة الحركية للجسيمات، فيزداد عدد الاصطدامات وعدد الاصطدامات التي لها طاقة مساوية لطاقة التنشيط أو أكبر منها. أما المحفز فيزيد سرعة التفاعل بتقليل طاقة التنشيط، دون أن يُستهلك. (ب) المحفز لا يُستهلك في التفاعل، فيمكن استعمال كمية صغيرة منه مرات عديدة، ولا يحتاج إلى طاقة مستمرة كالتسخين؛ فيُنتج المصنع كمية أكبر من المنتج بسرعة كبيرة، مما يقلل من تكلفته. (ج) لا؛ فكلاهما يزيد سرعة تكوّن المنتج فقط، أما الكمية الكلية للمنتج فتتحدد بكمية المواد المتفاعلة؛ والمحفز لا يزيد عدد النواتج.', '["رفع درجة الحرارة يزيد متوسط الطاقة الحركية والاصطدامات ذات الطاقة الكافية","المحفز يقلل طاقة التنشيط دون أن يُستهلك","المحفز يُعاد استعماله ولا يحتاج إلى طاقة مستمرة فيُنتج أسرع وتقل التكلفة","لا يزيد أي منهما الكمية الكلية للمنتج"]'::jsonb, '[]'::jsonb, '[{"element":"آلية رفع درجة الحرارة","marks":1},{"element":"آلية المحفز","marks":1},{"element":"الفائدة الاقتصادية للمحفز","marks":1},{"element":"ثبات الكمية الكلية للمنتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: آلية رفع درجة الحرارة؛ آلية المحفز؛ الفائدة الاقتصادية للمحفز؛ ثبات الكمية الكلية للمنتج"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يزيد كمية المنتج الكلية","القول إن المحفز يعمل برفع درجة الحرارة","إغفال أن المحفز لا يُستهلك فيُعاد استعماله"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.429Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. صحيح أن رفع درجة الحرارة يزيد سرعة التفاعل عمومًا، لكنه ليس طريقة عملية في الخلية الحية؛ لأن رفع درجة حرارة الخلية كثيرًا قد يضر بها أو يقتلها، كما أن الطاقة الحرارية الكبيرة تكسر التركيب البنائي للبروتينات. لذا تعتمد المخلوقات الحية على الإنزيمات، وهي محفزات تزيد سرعة التفاعلات الكيميائية دون أن تُستهلك، فتحدث التفاعلات بالسرعة الكافية للمحافظة على الحياة عند درجة حرارة الجسم الطبيعية (نحو 37 °C).', '["الحكم بأن العبارة غير صحيحة","رفع درجة حرارة الخلية كثيرًا يضر بها أو يقتلها ويكسر تركيب البروتينات","الإنزيمات محفزات تزيد السرعة دون أن تُستهلك","الإنزيمات تتيح السرعة الكافية عند درجة حرارة الجسم الطبيعية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح على العبارة","marks":1},{"element":"ضرر رفع درجة حرارة الخلية","marks":1},{"element":"تعريف دور الإنزيم محفزًا","marks":1},{"element":"أهمية الإنزيمات عند درجة حرارة الجسم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: الحكم الصحيح على العبارة؛ ضرر رفع درجة حرارة الخلية؛ تعريف دور الإنزيم محفزًا؛ أهمية الإنزيمات عند درجة حرارة الجسم"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة لأن الحرارة تزيد السرعة دائمًا","إغفال أثر الحرارة المرتفعة في تركيب البروتينات","الخلط بين الإنزيمات والمثبطات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.430Z"}'::jsonb)
