('mcq', 1, 'أيّ مجموعة مما يأتي تتكون كلها من عوامل تؤثر في سرعة التفاعل الكيميائي؟', null, null, '["التركيز، ولون المواد المتفاعلة، ودرجة الحرارة، والمحفزات","مساحة السطح، وكتلة النواتج، والتركيز، والمحفزات","التركيز، ومساحة السطح، ودرجة الحرارة، والمحفزات","طبيعة المواد المتفاعلة، وشكل وعاء التفاعل، والتركيز، ودرجة الحرارة"]'::jsonb, 'تذكر', 'تذكر حقائق', 'سهل', 'الكتاب ص 58، 62 — الفكرة الرئيسة والخلاصة'),
('mcq', 2, 'يمثل الشكل الآتي وعاءين متساويين في الحجم وعند درجة الحرارة نفسها، فيهما جسيمات من المادتين A وB. ما العامل المؤثر في سرعة التفاعل الذي يختلف بين الوعاءين؟', null, '[{"src":"qimg/chem22/c2-l2a-particles.svg","alt":"وعاءان (1) و(2) متساويان في الحجم وعند درجة الحرارة نفسها، فيهما جسيمات من المادتين A (دوائر زرقاء) وB (دوائر حمراء): في الوعاء (1) أربعة جسيمات من A وثلاثة جسيمات من B، وفي الوعاء (2) أربعة جسيمات من A وتسعة جسيمات من B."}]'::jsonb, '["تركيز المادة B","مساحة سطح المادة B","درجة حرارة الوعاء","وجود مادة محفزة"]'::jsonb, 'تذكر', 'تعرف عامل من شكل', 'سهل', 'الكتاب ص 59 — التركيز'),
('mcq', 3, 'تفسد الأطعمة بسرعة أكبر عند تركها في درجة حرارة الغرفة مقارنةً بوضعها في الثلاجة. ما العامل المؤثر في سرعة التفاعل في هذا المثال؟', null, null, '["تركيز المواد المتفاعلة","مساحة سطح الطعام","طبيعة المواد المتفاعلة","درجة الحرارة"]'::jsonb, 'فهم', 'تحديد عامل في موقف حياتي', 'متوسط', 'الكتاب ص 60 — درجة الحرارة (تلف الأطعمة والثلاجة)'),
('mcq', 4, 'تحترق شمعة في الهواء الذي يحتوي على نحو 20% أكسجين، وتحترق شمعة مماثلة داخل زجاجة تحتوي على نحو 100% أكسجين بلهب أشد إضاءة. ما العامل الذي يفسر احتراق الشمعة داخل الزجاجة بسرعة أكبر؟', null, null, '["ارتفاع درجة حرارة الزجاجة، فتزداد الطاقة الحركية للجسيمات","زيادة تركيز الأكسجين، فيزداد عدد الاصطدامات بين جزيئاته وجزيئات الشمع","زيادة مساحة سطح الشمعة داخل الزجاجة","وجود الزجاجة التي تعمل محفزًا لتفاعل الاحتراق"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'متوسط', 'الكتاب ص 59 — التركيز (الشكل 2-8)'),
('mcq', 5, 'يمثل الشكل الآتي عينتين من المادة الصلبة نفسها لهما الكتلة نفسها، وُضعت كل منهما في محلول الحمض نفسه بالتركيز نفسه وعند درجة الحرارة نفسها. ما العامل المؤثر في سرعة التفاعل الذي يختلف بين العينتين؟', null, '[{"src":"qimg/chem22/c2-l2a-cubes.svg","alt":"شكلان لعينتين من المادة الصلبة نفسها لهما الكتلة نفسها: (س) مكعب واحد طول ضلعه 2 cm، و(ص) ثمانية مكعبات صغيرة منفصلة طول ضلع كل منها 1 cm."}]'::jsonb, '["تركيز المادة المتفاعلة","طبيعة المادة المتفاعلة","درجة الحرارة","مساحة السطح"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 59، 62 — مساحة السطح؛ الخلاصة'),
('mcq', 6, 'ما العامل المؤثر في سرعة التفاعل الكيميائي الذي يعتمد على مدى النشاط الكيميائي للمواد المتفاعلة؟', null, null, '["طبيعة المواد المتفاعلة","مساحة سطح المادة","تركيز المواد المتفاعلة","وجود المحفزات"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 58 — طبيعة المواد المتفاعلة'),
('mcq', 7, 'أُجري التفاعل نفسه في أربع تجارب، وغُيِّر في كل تجربة عامل واحد فقط فزادت سرعة التفاعل. في أيّ تجربة كان العامل المغيَّر هو المحفزات؟', null, null, '["طُحنت المادة الصلبة المتفاعلة حتى صارت مسحوقًا","سُخِّن خليط التفاعل من 25 °C إلى 35 °C","أُضيفت كمية قليلة من مادة استُرجعت كاملة بعد التفاعل","استُعمل محلول حمض تركيزه 2 M بدلًا من 1 M"]'::jsonb, 'فهم', 'تصنيف', 'صعب', 'الكتاب ص 58–62 — العوامل المؤثرة في سرعة التفاعل؛ الخلاصة'),
('essay', 1, 'اذكر خمسة عوامل تؤثر في سرعة التفاعل الكيميائي، وأعطِ مثالًا واحدًا يوضح أثر كل عامل منها.', null, null, null, 'تذكر', 'تعداد مع أمثلة', 'سهل', 'الكتاب ص 58–62 — العوامل المؤثرة في سرعة التفاعل الكيميائي'),
('essay', 2, 'حدد العامل المؤثر في سرعة التفاعل الذي يوضحه كل موقف مما يأتي، مع ذكر السبب: (أ) يُحفظ الحليب في الثلاجة ليبقى صالحًا مدة أطول. (ب) يتوهج المسمار الساخن في الأكسجين، بينما تشتعل كتلة من سلك تنظيف الأواني المعدنية بشدة. (ج) تحدث تفاعلات تحلل الجلوكوز في الخلية بسرعة كافية بوجود الإنزيمات. (د) يتفاعل فلز الماغنسيوم مع حمض HCl أسرع من تفاعل الحديد معه في الظروف نفسها.', null, null, null, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 58–62 — العوامل المؤثرة في سرعة التفاعل؛ التقويم 2-2 (س12)'),
