('mcq', 1, 2, 'العوامل الرئيسة المؤثرة في سرعة التفاعل هي: طبيعة المواد المتفاعلة، والتركيز، ومساحة السطح، ودرجة الحرارة، والمحفزات؛ والمجموعة التي كل عناصرها منها هي: التركيز، ومساحة السطح، ودرجة الحرارة، والمحفزات.', '["لون المواد المتفاعلة ليس من العوامل المؤثرة في سرعة التفاعل.","كتلة النواتج ليست عاملًا يتحكم في سرعة التفاعل.","","شكل وعاء التفاعل ليس من العوامل المؤثرة في سرعة التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.430Z"}'::jsonb),
('mcq', 2, 0, 'عدد جسيمات A متساوٍ في الوعاءين (4)، أما جسيمات B فثلاثة في الوعاء (1) وتسعة في الوعاء (2) في الحجم نفسه؛ فالمختلف هو تركيز المادة B، وزيادته تزيد عدد الاصطدامات بين A وB.', '["","مساحة السطح تخص المواد الصلبة المجزأة، والشكل يُظهر اختلاف عدد الجسيمات في الحجم نفسه، أي التركيز.","درجة الحرارة متساوية في الوعاءين، فليست هي العامل المختلف.","لا توجد في الشكل أي مادة ثالثة محفزة؛ فالمختلف هو عدد جسيمات B فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.430Z"}'::jsonb),
('mcq', 3, 3, 'الاختلاف الوحيد بين الحالتين هو درجة الحرارة؛ فالتفاعلات التي تسبب تلف الأطعمة تكون أسرع كثيرًا عند درجة حرارة الغرفة منها في الثلاجة.', '["تركيز مكونات الطعام نفسه في الحالتين؛ والذي تغير هو درجة الحرارة.","مساحة سطح الطعام لم تتغير بنقله إلى الثلاجة.","الطعام نفسه في الحالتين، فطبيعة المواد المتفاعلة لم تتغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.430Z"}'::jsonb),
('mcq', 4, 1, 'الزجاجة تحتوي على أكسجين تركيزه نحو خمسة أضعاف تركيزه في الهواء، وبحسب نظرية التصادم كلما زاد تركيز الأكسجين زادت الاصطدامات بين جزيئات الشمع وجزيئات الأكسجين فزادت سرعة الاحتراق.', '["لم يُذكر تغير في درجة الحرارة؛ والفرق بين الحالتين هو نسبة الأكسجين.","","الشمعتان متماثلتان، فمساحة سطح الشمع لم تتغير.","الزجاجة وعاء فقط وليست محفزًا؛ والسبب زيادة تركيز الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.431Z"}'::jsonb),
('mcq', 5, 3, 'العينتان من المادة نفسها وبالكتلة نفسها، والحمض نفسه بالتركيز ودرجة الحرارة نفسيهما؛ والمختلف هو تجزئة المادة: العينة (ص) مقسمة إلى ثماني قطع، فمساحة سطحها أكبر. فالعامل المختلف هو مساحة السطح.', '["تركيز الحمض واحد في الحالتين، فليس هو العامل المختلف.","العينتان من المادة نفسها، فطبيعة المادة المتفاعلة لم تختلف.","التجربتان عند درجة الحرارة نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-07T17:19:00.431Z"}'::jsonb),
('mcq', 6, 0, 'تتفاعل بعض المواد أسرع من غيرها لأنها أنشط كيميائيًّا، مثل الخارصين الذي يتفاعل مع نترات الفضة أسرع من النحاس؛ وهذا العامل هو طبيعة المواد المتفاعلة.', '["","مساحة السطح تتعلق بتجزئة المادة الصلبة وعدد جسيماتها المعرضة للتصادم، لا بنشاطها الكيميائي.","التركيز يتعلق بكمية المادة في حجم معين، لا بنشاطها الكيميائي.","المحفزات مواد تُضاف لتقليل طاقة التنشيط، وليست صفة في المواد المتفاعلة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.431Z"}'::jsonb),
('mcq', 7, 2, 'المحفز مادة تزيد سرعة التفاعل دون أن تُستهلك فيه؛ والمادة التي أُضيفت ثم استُرجعت كاملة بعد التفاعل لم تُستهلك، فالعامل المغيَّر في هذه التجربة هو المحفزات.', '["الطحن يزيد مساحة السطح، فالعامل المغيَّر هنا مساحة السطح.","التسخين يغير درجة الحرارة، فالعامل المغيَّر هنا درجة الحرارة.","","رفع تركيز الحمض يغير التركيز، فالعامل المغيَّر هنا التركيز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.431Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) طبيعة المواد المتفاعلة: يتفاعل الخارصين مع محلول نترات الفضة أسرع من النحاس لأنه أنشط كيميائيًّا. 2) التركيز: تحترق الشمعة في وعاء فيه نحو 100% أكسجين أسرع منها في الهواء (نحو 20% أكسجين). 3) مساحة السطح: تشتعل كتلة سلك تنظيف الأواني بشدة في الأكسجين بينما يتوهج المسمار الساخن فقط. 4) درجة الحرارة: تفسد الأطعمة عند درجة حرارة الغرفة أسرع منها في الثلاجة. 5) المحفزات: الإنزيمات تسرّع تفاعلات الجسم، أو ثاني أكسيد المنجنيز يسرّع تحلل فوق أكسيد الهيدروجين.', '["طبيعة المواد المتفاعلة مع مثال","التركيز مع مثال","مساحة السطح مع مثال","درجة الحرارة مع مثال","المحفزات مع مثال"]'::jsonb, '[]'::jsonb, '[{"element":"طبيعة المواد المتفاعلة ومثالها","marks":1},{"element":"التركيز ومثاله","marks":1},{"element":"مساحة السطح ومثالها","marks":1},{"element":"درجة الحرارة ومثالها","marks":1},{"element":"المحفزات ومثالها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: طبيعة المواد المتفاعلة ومثالها؛ التركيز ومثاله؛ مساحة السطح ومثالها؛ درجة الحرارة ومثالها؛ المحفزات ومثالها"},{"level":"1–4 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الضغط أو لون المادة عاملًا من عوامل الدرس","ذكر مثال لا يوضح العامل المذكور","ذكر المثبطات دون المحفزات عاملًا خامسًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.431Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) درجة الحرارة: انخفاض درجة الحرارة في الثلاجة يبطئ التفاعلات التي تفسد الحليب. (ب) مساحة السطح: مساحة سطح سلك التنظيف أكبر كثيرًا من مساحة سطح المسمار، فيزداد عدد الاصطدامات بين الأكسجين والفلز. (ج) المحفزات: الإنزيمات محفزات تزيد سرعة التفاعلات دون أن تُستهلك. (د) طبيعة المواد المتفاعلة: الماغنسيوم أنشط كيميائيًّا من الحديد.', '["(أ) درجة الحرارة","(ب) مساحة السطح","(ج) المحفزات","(د) طبيعة المواد المتفاعلة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) درجة الحرارة","marks":1},{"element":"(ب) مساحة السطح","marks":1},{"element":"(ج) المحفزات","marks":1},{"element":"(د) طبيعة المواد المتفاعلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: (أ) درجة الحرارة؛ (ب) مساحة السطح؛ (ج) المحفزات؛ (د) طبيعة المواد المتفاعلة"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الثلاجة مثالًا على التركيز","عدّ الإنزيمات مثبطات","تفسير سرعة تفاعل الماغنسيوم بمساحة السطح مع أن الظروف نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-07T17:19:00.432Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القائمة غير دقيقة. فيها عاملان خطأ: لون المواد المتفاعلة، وكتلة النواتج؛ فليسا من العوامل الرئيسة المؤثرة في سرعة التفاعل. وينقصها عاملان: (1) مساحة السطح، مثل: تشتعل كتلة سلك تنظيف الأواني المعدنية بشدة في الأكسجين بينما يتوهج المسمار الساخن فقط، أو يتفاعل مسحوق الخارصين مع HCl أسرع من قطعة كبيرة منه. (2) المحفزات، مثل: الإنزيمات في الجسم، أو ثاني أكسيد المنجنيز MnO₂ الذي يسرّع تحلل فوق أكسيد الهيدروجين. فتصبح العوامل الرئيسة: طبيعة المواد المتفاعلة، والتركيز، ومساحة السطح، ودرجة الحرارة، والمحفزات.', '["تحديد العاملين الخطأين (لون المادة وكتلة النواتج)","إضافة مساحة السطح","إضافة المحفزات","مثال صحيح لكل عامل مضاف"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد العاملين الخطأين (لون المادة وكتلة النواتج)","marks":1},{"element":"إضافة مساحة السطح","marks":1},{"element":"إضافة المحفزات","marks":1},{"element":"مثال صحيح لكل عامل مضاف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: تحديد العاملين الخطأين (لون المادة وكتلة النواتج)؛ إضافة مساحة السطح؛ إضافة المحفزات؛ مثال صحيح لكل عامل مضاف"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حذف طبيعة المواد المتفاعلة أو التركيز مع أنهما صحيحان","إضافة المثبطات بدل المحفزات","ذكر مثال لا يوضح العامل المضاف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.432Z"}'::jsonb)
