('mcq', 3, 'يبين الشكل الآتي كأسين فيهما محلول نترات الفضة بالتركيز نفسه، وفي أحدهما شريط خارصين وفي الآخر شريط نحاس بالحجم نفسه، بعد مرور الزمن نفسه. أيّ الكأسين فيه شريط الخارصين، ولماذا؟', null, '[{"src":"qimg/chem22/c2-l2a-beakers-xy.svg","alt":"كأسان (س) و(ص) في كل منهما محلول نترات الفضة AgNO₃ تركيزه 0.05 M وحجمه متساوٍ، وفي كل منهما شريط فلزي بالحجم نفسه؛ أحد الشريطين من الخارصين والآخر من النحاس. بعد مرور الزمن نفسه تظهر على شريط الكأس (س) حبيبات قليلة رمادية من الفضة، وعلى شريط الكأس (ص) حبيبات كثيرة جدًّا من الفضة."}]'::jsonb, '["(س)؛ لأن كمية الفضة المتكونة أقل، فالخارصين أقل نشاطًا","(ص)؛ لأن كمية الفضة المتكونة أكبر، فالتفاعل أسرع لأن الخارصين أنشط","(س)؛ لأن الفضة تترسب على النحاس أسرع، فالنحاس في (ص)","لا يمكن التحديد؛ لأن تركيز نترات الفضة واحد في الكأسين"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 58 — طبيعة المواد المتفاعلة (الشكل 2-7)'),
('mcq', 4, 'ما المعادلة الكيميائية الموزونة لتفاعل الخارصين مع محلول نترات الفضة؟', null, null, '["Zn(s) + AgNO₃(aq) → ZnNO₃(aq) + Ag(s)","Zn(s) + 2AgNO₃(aq) → Zn(NO₃)₂(aq) + Ag₂(s)","Zn(s) + AgNO₃(aq) → Zn(NO₃)₂(aq) + Ag(s)","Zn(s) + 2AgNO₃(aq) → Zn(NO₃)₂(aq) + 2Ag(s)"]'::jsonb, 'تطبيق', 'كتابة معادلة موزونة', 'متوسط', 'الكتاب ص 58 — طبيعة المواد المتفاعلة (الشكل 2-7) (اكتب المعادلات الكيميائية الموزونة)'),
('mcq', 5, 'ما الذي يجعل الفرق في سرعة تفاعلَي الخارصين والنحاس مع نترات الفضة يُعزى إلى نوع الفلز وحده؟', null, null, '["استعمال محلول أكثر تركيزًا مع النحاس لتعويض بطء تفاعله","تسخين كأس الخارصين ليتفاعل بسرعة أكبر من النحاس","تثبيت تركيز المحلول واستعمال شريطين متماثلين في الحجم","استعمال مسحوق الخارصين مع شريط واحد من النحاس"]'::jsonb, 'فهم', 'تفسير تصميم تجربة', 'متوسط', 'الكتاب ص 58 — طبيعة المواد المتفاعلة (الشكل 2-7)'),
('mcq', 6, 'وُضع شريطان متماثلان في الحجم، أحدهما من الماغنسيوم والآخر من الحديد، في محلولين من حمض الهيدروكلوريك HCl لهما التركيز نفسه وعند درجة الحرارة نفسها. أيّ التفاعلين أسرع، ولماذا؟', null, null, '["تفاعل الحديد؛ لأنه أنشط كيميائيًّا من الماغنسيوم","تفاعل الماغنسيوم؛ لأنه أنشط كيميائيًّا من الحديد","تفاعل الحديد؛ لأن كثافته أكبر من كثافة الماغنسيوم","يتساويان؛ لأن تركيز الحمض ودرجة الحرارة متساويان"]'::jsonb, 'تحليل', 'تطبيق المفهوم على حالة مماثلة', 'صعب', 'الكتاب ص 62 — التقويم 2-2 (س12)'),
('mcq', 7, 'وُضعت ثلاثة أشرطة متماثلة في الحجم من الفلزات X وY وZ في محاليل من نترات الفضة لها التركيز نفسه وعند درجة الحرارة نفسها، وقيس الزمن اللازم لتكوّن الكمية نفسها من الفضة في الجدول الآتي. ما ترتيب الفلزات من الأنشط إلى الأقل نشاطًا؟', '{"headers":["الفلز","الزمن اللازم لتكوّن الكمية نفسها من الفضة"],"rows":[["X","12 min"],["Y","3 min"],["Z","7 min"]]}'::jsonb, null, '["Y ثم Z ثم X","X ثم Z ثم Y","Z ثم Y ثم X","Y ثم X ثم Z"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 58 — طبيعة المواد المتفاعلة (الشكل 2-7)'),
('essay', 1, 'يبين الشكل الآتي شريطًا من الخارصين وشريطًا من النحاس بالحجم نفسه، كلٌّ منهما في محلول نترات الفضة تركيزه 0.05 M، بعد مرور الزمن نفسه. (أ) صف الفرق بين الكأسين. (ب) علّل: تفاعل الخارصين مع نترات الفضة أسرع من تفاعل النحاس معها، مع أن الفلزين متشابهان في خواصهما الفيزيائية.', null, '[{"src":"qimg/chem22/c2-l2a-beakers-zncu.svg","alt":"كأسان في كل منهما محلول نترات الفضة AgNO₃ تركيزه 0.05 M وحجمه متساوٍ: في الكأس اليسرى شريط خارصين Zn رمادي، وفي الكأس اليمنى شريط نحاس Cu برتقالي، والشريطان بالحجم نفسه. بعد مرور الزمن نفسه تظهر على شريط الخارصين حبيبات كثيرة رمادية من الفضة، وعلى شريط النحاس حبيبات قليلة منها."}]'::jsonb, null, 'فهم', 'وصف وتعليل', 'سهل', 'الكتاب ص 58 — طبيعة المواد المتفاعلة (الشكل 2-7)'),
('essay', 2, '(أ) اكتب المعادلتين الكيميائيتين الموزونتين لتفاعل كل من الخارصين والنحاس مع محلول نترات الفضة، علمًا بأن النحاس يكوّن نترات النحاس II. (ب) أيّ التفاعلين يكوّن كمية أكبر من الفضة في الزمن نفسه عند تساوي الظروف؟ وضّح السبب.', null, null, null, 'تطبيق', 'كتابة معادلات وتعليل', 'متوسط', 'الكتاب ص 58 — طبيعة المواد المتفاعلة (الشكل 2-7) (اكتب المعادلات الكيميائية الموزونة)'),
('essay', 3, 'أراد طالب إثبات أن الخارصين يتفاعل مع نترات الفضة أسرع من النحاس، فوضع مسحوق الخارصين في محلول نترات الفضة تركيزه 0.10 M، ووضع شريطًا من النحاس في محلول تركيزه 0.05 M، ثم استنتج أن الخارصين أنشط. قوّم تصميم تجربته، واقترح تعديلًا يجعل استنتاجه صحيحًا.', null, null, null, 'تقويم', 'تقويم تصميم تجربة', 'صعب', 'الكتاب ص 58 — طبيعة المواد المتفاعلة (الشكل 2-7)؛ ص 59 — التركيز ومساحة السطح')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
