select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'التجربتان متماثلتان في التركيز والظروف، والفلزان متشابهان فيزيائيًّا؛ لذا يعود الفرق إلى طبيعة المواد المتفاعلة: الخارصين أنشط كيميائيًّا من النحاس، فيتفاعل أسرع.', '["","الشريطان متماثلان في الحجم، والفرق في السرعة يعود إلى طبيعة الفلز لا إلى مساحة السطح.","التركيز متساوٍ في الكأسين (0.05 M)، فليس هو سبب الاختلاف.","الفلزان متشابهان في خواصهما الفيزيائية بسبب قرب موقعيهما في الجدول الدوري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.432Z"}'::jsonb),
('mcq', 2, 2, 'المتغير الوحيد بين التجربتين هو نوع الفلز (الخارصين أو النحاس)، أي طبيعة المواد المتفاعلة؛ فهي العامل المدروس.', '["التركيز ثابت في التجربتين (0.05 M)، فلا يُدرس أثره هنا.","لم تتغير درجة الحرارة بين التجربتين.","","لم تُضف أي مادة محفزة؛ والمتغير الوحيد هو نوع الفلز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.433Z"}'::jsonb),
('mcq', 3, 1, 'في الزمن نفسه تكونت فضة أكثر بكثير في الكأس (ص)، أي أن التفاعل فيها أسرع؛ والخارصين أنشط كيميائيًّا من النحاس، فشريط الخارصين في الكأس (ص).', '["الخارصين أنشط من النحاس لا أقل، فيكوّن فضة أكثر في الزمن نفسه.","","النحاس أقل نشاطًا من الخارصين فيكوّن فضة أقل؛ فالفضة الكثيرة في (ص) تدل على الخارصين لا النحاس.","ثبات التركيز هو ما يجعل المقارنة عادلة، فيمكن التحديد من كمية الفضة المتكونة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.433Z"}'::jsonb),
('mcq', 4, 3, 'الخارصين يحل محل الفضة: يتكون Zn(NO₃)₂ لأن شحنة الخارصين 2+، ويلزم أيونا Ag⁺، فالمعادلة الموزونة: Zn(s) + 2AgNO₃(aq) → Zn(NO₃)₂(aq) + 2Ag(s).', '["صيغة نترات الخارصين خاطئة؛ فأيون الخارصين Zn²⁺ يرتبط بأيوني نترات: Zn(NO₃)₂.","الفضة تُكتب Ag لا Ag₂، ومعاملها 2 في المعادلة الموزونة.","المعادلة غير موزونة؛ ففي النواتج مجموعتا نترات وفي المتفاعلات مجموعة واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-07T17:19:00.433Z"}'::jsonb),
('mcq', 5, 2, 'لكي يُنسب الفرق إلى طبيعة الفلز وحدها يجب تثبيت بقية العوامل: تثبيت تركيز المحلول (0.05 M) واستعمال شريطين متماثلين في الحجم من فلزين متشابهين فيزيائيًّا؛ وعندها يُعزى الفرق إلى نشاط الفلز.', '["تغيير التركيز يضيف متغيرًا ثانيًا، فلا يمكن عندها عزو الفرق إلى نوع الفلز وحده.","التسخين يغير درجة الحرارة، فيصبح الفرق ناتجًا عن عاملين لا عن نوع الفلز وحده.","","المسحوق يغير مساحة السطح، فيختلط أثرها بأثر نوع الفلز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-07T17:19:00.433Z"}'::jsonb),
('mcq', 6, 1, 'الظروف متماثلة والاختلاف في نوع الفلز فقط، والماغنسيوم أنشط كيميائيًّا من الحديد؛ لذا يتفاعل الماغنسيوم مع HCl أسرع.', '["الماغنسيوم أنشط من الحديد، فتفاعله مع الحمض أسرع.","","الكثافة ليست من العوامل المؤثرة في سرعة التفاعل؛ والمهم نشاط الفلز.","تساوي التركيز ودرجة الحرارة لا يلغي أثر اختلاف طبيعة الفلز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.433Z"}'::jsonb),
('mcq', 7, 0, 'كلما قصر الزمن اللازم لتكوّن الكمية نفسها من الفضة كان التفاعل أسرع والفلز أنشط: Y (3 min) ثم Z (7 min) ثم X (12 min).', '["","هذا ترتيب معكوس؛ فالزمن الأطول يعني تفاعلًا أبطأ وفلزًا أقل نشاطًا.","الفلز Y استغرق أقل زمن (3 min)، فهو الأنشط لا Z.","الفلز X استغرق أطول زمن (12 min)، فهو الأقل نشاطًا ويأتي أخيرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.434Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) تكونت على شريط الخارصين كمية من الفضة أكبر بكثير من الكمية المتكونة على شريط النحاس في الزمن نفسه. (ب) الظروف متماثلة (التركيز نفسه 0.05 M، والحجم نفسه، والفلزان متشابهان فيزيائيًّا لقرب موقعيهما في الجدول الدوري)، فيعود الفرق إلى طبيعة المواد المتفاعلة؛ إذ إن الخارصين أنشط كيميائيًّا من النحاس، فيتفاعل مع أيونات الفضة بسرعة أكبر وتتكون كمية أكبر من الفضة في الزمن نفسه.', '["كمية الفضة على الخارصين أكبر","الظروف الأخرى متماثلة","الخارصين أنشط كيميائيًّا من النحاس","الفرق يعود إلى طبيعة المواد المتفاعلة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الفرق في كمية الفضة","marks":1},{"element":"بيان تماثل الظروف الأخرى","marks":1},{"element":"التعليل بنشاط الخارصين الأكبر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: وصف الفرق في كمية الفضة؛ بيان تماثل الظروف الأخرى؛ التعليل بنشاط الخارصين الأكبر"},{"level":"1–2 درجة","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الفرق بمساحة السطح أو التركيز","القول إن النحاس أنشط من الخارصين","الاكتفاء بالوصف دون التعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-07T17:19:00.434Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Zn(s) + 2AgNO₃(aq) → Zn(NO₃)₂(aq) + 2Ag(s)، وCu(s) + 2AgNO₃(aq) → Cu(NO₃)₂(aq) + 2Ag(s). (ب) تفاعل الخارصين؛ لأن الخارصين أنشط كيميائيًّا من النحاس، فسرعة تفاعله أكبر، وتتكون كمية أكبر من الفضة في الزمن نفسه.', '["معادلة الخارصين موزونة","معادلة النحاس موزونة","الخارصين يكوّن فضة أكثر","السبب: الخارصين أنشط"]'::jsonb, '["كتابة صيغ النترات: Zn(NO₃)₂ وCu(NO₃)₂ لأن الشحنة 2+","موازنة أيونات الفضة ومجموعات النترات بالمعامل 2","مقارنة النشاط الكيميائي للفلزين"]'::jsonb, '[{"element":"معادلة الخارصين","marks":1},{"element":"معادلة النحاس","marks":1},{"element":"تحديد التفاعل الذي يكوّن فضة أكثر","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: معادلة الخارصين؛ معادلة النحاس؛ تحديد التفاعل الذي يكوّن فضة أكثر؛ التعليل"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ZnNO₃ أو CuNO₃","نسيان المعامل 2 أمام AgNO₃ وAg","تعليل الفرق بأن الخارصين أثقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-07T17:19:00.434Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التصميم غير سليم؛ لأنه غيّر أكثر من عامل في آن واحد: (1) استعمل مسحوق الخارصين مقابل شريط النحاس، فمساحة سطح الخارصين أكبر، وزيادة مساحة السطح تزيد السرعة. (2) استعمل تركيزًا أعلى مع الخارصين (0.10 M مقابل 0.05 M)، وزيادة التركيز تزيد السرعة. لذا لا يمكن عزو سرعة تفاعل الخارصين إلى نشاطه وحده. التعديل: استعمال شريطين متماثلين في الحجم من الفلزين، في محلولين من نترات الفضة بالتركيز نفسه (0.05 M مثلًا) والحجم نفسه وعند درجة الحرارة نفسها، ثم مقارنة كمية الفضة المتكونة في الزمن نفسه؛ فيكون الفرق ناتجًا عن طبيعة الفلز فقط.', '["الحكم بأن التصميم غير سليم","اختلاف مساحة السطح (مسحوق مقابل شريط)","اختلاف التركيز (0.10 M مقابل 0.05 M)","تعديل يثبت جميع العوامل ما عدا نوع الفلز"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على التصميم","marks":1},{"element":"تحديد خطأ مساحة السطح","marks":1},{"element":"تحديد خطأ التركيز","marks":1},{"element":"اقتراح تعديل صحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: الحكم على التصميم؛ تحديد خطأ مساحة السطح؛ تحديد خطأ التركيز؛ اقتراح تعديل صحيح"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ملاحظة خطأ واحد فقط من الخطأين","اقتراح تعديل يغير درجة الحرارة","القبول بالاستنتاج لأن الخارصين أنشط فعلًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.434Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
