from (values
('mcq', 1, 'لماذا تؤدي زيادة مساحة سطح المادة المتفاعلة الصلبة إلى زيادة سرعة التفاعل؟', null, null, '["لأنها تقلل طاقة التنشيط اللازمة للتفاعل","لأنها تزيد متوسط الطاقة الحركية للجسيمات","لأنها تزيد الكمية الكلية للمادة المتفاعلة","لأنها تزيد عدد الاصطدامات بين الجسيمات المتفاعلة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 59 — مساحة السطح (الشكل 2-9)'),
('mcq', 2, 'يمثل الشكل الآتي عينتين من المادة الصلبة نفسها لهما الكتلة نفسها: (س) مكعب واحد، و(ص) ثماني قطع مكعبة منفصلة. ما العلاقة بين المساحة الكلية لسطح العينتين؟', null, '[{"src":"qimg/chem22/c2-l2a-cubes.svg","alt":"شكلان لعينتين من المادة الصلبة نفسها لهما الكتلة نفسها: (س) مكعب واحد طول ضلعه 2 cm، و(ص) ثمانية مكعبات صغيرة منفصلة طول ضلع كل منها 1 cm."}]'::jsonb, '["مساحتا سطح العينتين متساويتان؛ لأن كتلتيهما متساويتان","مساحة سطح (ص) ضعف مساحة سطح (س)","مساحة سطح (ص) ثمانية أضعاف مساحة سطح (س)","مساحة سطح (ص) نصف مساحة سطح (س)"]'::jsonb, 'تطبيق', 'حساب من شكل', 'متوسط', 'الكتاب ص 59 — مساحة السطح (الشكل 2-9)؛ ص 62 — س15'),
('mcq', 3, 'وُضعت العينتان (س) و(ص) المبينتان في الشكل الآتي، ولهما الكتلة نفسها، كلٌّ منهما في محلول من حمض الهيدروكلوريك بالتركيز نفسه وعند درجة الحرارة نفسها. أيّ العينتين تتفاعل أسرع، ولماذا؟', null, '[{"src":"qimg/chem22/c2-l2a-cubes.svg","alt":"شكلان لعينتين من المادة الصلبة نفسها لهما الكتلة نفسها: (س) مكعب واحد طول ضلعه 2 cm، و(ص) ثمانية مكعبات صغيرة منفصلة طول ضلع كل منها 1 cm."}]'::jsonb, '["(س)؛ لأن القطعة الواحدة تحتوي على عدد أكبر من الجسيمات","تتساويان؛ لأن للعينتين الكتلة نفسها","(ص)؛ لأن مساحة سطحها المعرضة للحمض أكبر فتزداد الاصطدامات","(س)؛ لأن حجم القطعة الواحدة أكبر من حجم كل قطعة صغيرة"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 59 — مساحة السطح (الشكل 2-9)'),
('mcq', 4, 'يتوهج المسمار الساخن عند وضعه في الأكسجين، بينما تشتعل كتلة من سلك تنظيف الأواني المعدنية بشدة في الأكسجين. ما سبب الاختلاف؟', null, null, '["مساحة سطح السلك أكبر، فيزداد عدد الاصطدامات بين الأكسجين والفلز","تركيز الأكسجين حول السلك أعلى منه حول المسمار","السلك مصنوع من فلز أنشط كيميائيًّا من المسمار","درجة حرارة المسمار أعلى من درجة حرارة السلك"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'سهل', 'الكتاب ص 59 — مساحة السطح (الشكل 2-9)'),
('mcq', 5, 'لماذا يتفاعل مسحوق الخارصين مع حمض الهيدروكلوريك لإنتاج غاز الهيدروجين أسرع من تفاعل قطع كبيرة منه لها الكتلة نفسها؟', null, null, '["لأن عدد ذرات الخارصين المعرضة للاصطدام بجسيمات الحمض في المسحوق أكبر","لأن طحن الخارصين يرفع درجة حرارته فيتفاعل أسرع","لأن مسحوق الخارصين أنشط كيميائيًّا من قطع الخارصين","لأن المسحوق يعمل محفزًا لتفاعل الحمض مع القطع"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 70 — تقويم الفصل (س42)'),
('mcq', 6, 'وُضع 5 g من مسحوق الخارصين في حمض الهيدروكلوريك الفائض، ووُضعت قطعة خارصين واحدة كتلتها 5 g في كمية مماثلة من الحمض نفسه وعند درجة الحرارة نفسها. أيّ العبارات الآتية صحيحة؟', null, null, '["يتكون الهيدروجين مع المسحوق أسرع، وتكون كميته الكلية أكبر","يتكون الهيدروجين بالسرعة نفسها، لكن كميته مع المسحوق أكبر","يتكون الهيدروجين مع القطعة أسرع؛ لأن كتلتها في مكان واحد","يتكون الهيدروجين مع المسحوق أسرع، وتبقى كميته الكلية نفسها في التجربتين"]'::jsonb, 'تحليل', 'تمييز أثر العامل', 'صعب', 'الكتاب ص 59 — مساحة السطح؛ ص 70 — س42'),
('mcq', 7, 'قُطع مكعب من مادة صلبة طول ضلعه 3 cm إلى 27 مكعبًا صغيرًا متساويًا طول ضلع كل منها 1 cm. كم مرة تتضاعف المساحة الكلية لسطح المادة؟', null, null, '["27 مرة","3 مرات","9 مرات","لا تتغير"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 59 — مساحة السطح (الشكل 2-9)'),
('essay', 1, 'فسّر لماذا تتفاعل المادة الصلبة التي على شكل مسحوق مع الغاز أسرع من تفاعل المادة الصلبة نفسها إذا كانت قطعة واحدة.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 70 — تقويم الفصل (س40)؛ ص 59 — مساحة السطح'),
('essay', 2, 'يبين الشكل الآتي عينتين من المادة الصلبة نفسها لهما الكتلة نفسها. (أ) احسب المساحة الكلية لسطح كل عينة. (ب) احسب النسبة بين المساحتين. (ج) توقع أيّ العينتين تتفاعل أسرع مع محلول حمض بالتركيز نفسه، وفسّر توقعك.', null, '[{"src":"qimg/chem22/c2-l2a-cubes.svg","alt":"شكلان لعينتين من المادة الصلبة نفسها لهما الكتلة نفسها: (س) مكعب واحد طول ضلعه 2 cm، و(ص) ثمانية مكعبات صغيرة منفصلة طول ضلع كل منها 1 cm."}]'::jsonb, null, 'تطبيق', 'حساب وتفسير', 'متوسط', 'الكتاب ص 59 — مساحة السطح (الشكل 2-9)؛ ص 62 — س15'),
('essay', 3, 'طُحنت مادة صلبة متفاعلة وحُوِّلت إلى مسحوق بدلًا من وضعها قطعة واحدة في تفاعل ما. (أ) صف أثر ذلك في سرعة التفاعل مفسرًا إجابتك وفق نظرية التصادم. (ب) هل يتغير بذلك مقدار الناتج الكلي إذا بقيت كمية المواد المتفاعلة نفسها؟ وضّح. (ج) فسّر لماذا تعمل التجزئة عمل زيادة التركيز في أثرها في سرعة التفاعل مع أنهما عاملان مختلفان.', null, null, null, 'تحليل', 'تفسير ومقارنة', 'صعب', 'الكتاب ص 59 — التركيز ومساحة السطح؛ ص 62 — س15')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
