from (values
('mcq', 1, 3, 'زيادة مساحة السطح تعرّض عددًا أكبر من جسيمات المادة الصلبة للمادة الأخرى، فيزداد عدد الاصطدامات بين الجسيمات المتفاعلة، فتزداد سرعة التفاعل.', '["تقليل طاقة التنشيط هو عمل المحفز، لا أثر زيادة مساحة السطح.","زيادة متوسط الطاقة الحركية تنتج عن رفع درجة الحرارة، لا عن تجزئة المادة.","تجزئة المادة لا تغير كميتها؛ بل تعرّض عددًا أكبر من جسيماتها للتصادم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.435Z"}'::jsonb),
('mcq', 2, 1, 'مساحة سطح (س) = 6 × (2 cm × 2 cm) = 24 cm²، ومساحة سطح (ص) = 8 × 6 × (1 cm × 1 cm) = 48 cm²؛ إذن مساحة سطح (ص) ضعف مساحة سطح (س).', '["تساوي الكتلة لا يعني تساوي مساحة السطح: 24 cm² للعينة (س) و48 cm² للعينة (ص).","","هذا خطأ في الحساب: ضُرب عدد القطع دون مراعاة أن مساحة وجه القطعة الصغيرة ربع مساحة وجه المكعب الكبير.","العلاقة مقلوبة؛ فالتجزئة تزيد مساحة السطح ولا تقللها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-07T17:19:00.435Z"}'::jsonb),
('mcq', 3, 2, 'تجزئة المادة إلى قطع صغيرة تزيد مساحة السطح المعرضة للحمض، فيزداد عدد الاصطدامات بين جسيمات الحمض وجسيمات المادة الصلبة، فتتفاعل العينة (ص) أسرع.', '["العينتان من المادة نفسها وبالكتلة نفسها، فعدد جسيماتهما متساوٍ.","تساوي الكتلة لا يعني تساوي السرعة؛ فمساحة السطح مختلفة.","","الحجم الأكبر للقطعة الواحدة يعني سطحًا معرضًا أقل نسبة إلى كتلتها، فتتفاعل أبطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-07T17:19:00.435Z"}'::jsonb),
('mcq', 4, 0, 'سلك التنظيف مكون من خيوط رفيعة كثيرة، فمساحة سطحه المعرضة للأكسجين أكبر كثيرًا من مساحة سطح المسمار، فيزداد عدد الاصطدامات بين الأكسجين والفلز ويشتعل بشدة.', '["","التفاعلان يحدثان في الأكسجين نفسه؛ والفرق في شكل الفلز ومساحة سطحه.","الفرق المدروس هو شكل الفلز وتجزئته، أي مساحة السطح، لا نوعه.","ارتفاع درجة الحرارة يزيد السرعة؛ فلو كان المسمار أسخن لكان أسرع، والملاحظ عكس ذلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-07T17:19:00.435Z"}'::jsonb),
('mcq', 5, 0, 'المسحوق مساحة سطحه أكبر بكثير، فيتعرض عدد أكبر من ذرات الخارصين لجسيمات الحمض، فيزداد عدد الاصطدامات وتزداد سرعة إنتاج الهيدروجين.', '["","سبب زيادة السرعة هو زيادة مساحة السطح المعرضة، لا تغير درجة الحرارة.","المادة نفسها في الحالتين، فنشاطها الكيميائي لا يتغير بالطحن.","المسحوق مادة متفاعلة تُستهلك في التفاعل، وليس محفزًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.435Z"}'::jsonb),
('mcq', 6, 3, 'المسحوق مساحة سطحه أكبر، فيزداد عدد الاصطدامات ويتكون الهيدروجين أسرع؛ لكن كمية الخارصين واحدة (5 g) والحمض فائض، فتبقى الكمية الكلية للهيدروجين نفسها في التجربتين.', '["زيادة مساحة السطح تزيد سرعة التفاعل فقط؛ أما الكمية الكلية فتتحدد بكتلة الخارصين وهي 5 g في الحالتين.","المسحوق يغير السرعة لا الكمية؛ فالعبارة عكست أثر مساحة السطح.","تجمع الكتلة في قطعة واحدة يقلل مساحة السطح المعرضة فيبطئ التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.435Z"}'::jsonb),
('mcq', 7, 1, 'مساحة سطح المكعب الكبير = 6 × (3 cm)² = 54 cm²، ومساحة سطح المكعبات الصغيرة = 27 × 6 × (1 cm)² = 162 cm²؛ والنسبة 162 ÷ 54 = 3 مرات، فتزداد سرعة التفاعل لزيادة الاصطدامات.', '["هذا عدد القطع، لا نسبة مساحة السطح: 162 cm² ÷ 54 cm² = 3.","","هذا ناتج قسمة مساحة وجه المكعب الكبير (9 cm²) على مساحة وجه المكعب الصغير (1 cm²)، دون حساب المساحة الكلية.","كمية المادة لا تتغير، لكن مساحة سطحها تزداد بالتجزئة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.436Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المسحوق مساحة سطحه أكبر بكثير من مساحة سطح القطعة الواحدة التي لها الكتلة نفسها؛ فيتعرض عدد أكبر من جسيمات المادة الصلبة لجزيئات الغاز، فيزداد عدد الاصطدامات بين الجسيمات المتفاعلة في وحدة الزمن، وبحسب نظرية التصادم تزداد سرعة التفاعل.', '["المسحوق مساحة سطحه أكبر","يتعرض عدد أكبر من الجسيمات للغاز","يزداد عدد الاصطدامات فتزداد السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"مساحة سطح المسحوق أكبر","marks":1},{"element":"زيادة الجسيمات المعرضة للغاز","marks":1},{"element":"زيادة الاصطدامات وزيادة السرعة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: مساحة سطح المسحوق أكبر؛ زيادة الجسيمات المعرضة للغاز؛ زيادة الاصطدامات وزيادة السرعة"},{"level":"1–2 درجة","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المسحوق يقلل طاقة التنشيط","القول إن المسحوق كميته أكبر","إغفال ربط مساحة السطح بعدد الاصطدامات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.436Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) العينة (س): مكعب طول ضلعه 2 cm، له 6 أوجه مساحة كل منها 2 × 2 = 4 cm²، فالمساحة = 6 × 4 = 24 cm². العينة (ص): 8 مكعبات طول ضلع كل منها 1 cm، مساحة سطح المكعب الواحد = 6 × 1 = 6 cm²، فالمساحة الكلية = 8 × 6 = 48 cm². (ب) النسبة = 48 ÷ 24 = 2، أي مساحة سطح (ص) ضعف مساحة سطح (س). (ج) العينة (ص) تتفاعل أسرع؛ لأن مساحة سطحها المعرضة للحمض أكبر، فيزداد عدد الاصطدامات بين جسيمات الحمض وجسيمات المادة الصلبة.', '["مساحة (س) = 24 cm²","مساحة (ص) = 48 cm²","النسبة = 2","(ص) أسرع لزيادة الاصطدامات"]'::jsonb, '["مساحة وجه المكعب الكبير = 2 cm × 2 cm = 4 cm²","مساحة سطح (س) = 6 × 4 cm² = 24 cm²","مساحة سطح المكعب الصغير = 6 × 1 cm² = 6 cm²","مساحة سطح (ص) = 8 × 6 cm² = 48 cm²","النسبة = 48 ÷ 24 = 2"]'::jsonb, '[{"element":"مساحة سطح (س)","marks":1},{"element":"مساحة سطح (ص)","marks":1},{"element":"النسبة بين المساحتين","marks":1},{"element":"التوقع والتفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: مساحة سطح (س)؛ مساحة سطح (ص)؛ النسبة بين المساحتين؛ التوقع والتفسير"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب وجه واحد فقط بدلًا من الأوجه الستة","ضرب عدد القطع في مساحة سطح المكعب الكبير","التفسير بأن العينة (ص) كتلتها أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-07T17:19:00.436Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) تزداد سرعة التفاعل؛ لأن الطحن يزيد مساحة السطح، فيتعرض عدد أكبر من جسيمات المادة الصلبة للمادة الأخرى، فيزداد عدد الاصطدامات بين الجسيمات المتفاعلة في وحدة الزمن. (ب) لا يتغير مقدار الناتج الكلي؛ لأن كمية المادة المتفاعلة نفسها، والطحن يغير سرعة تكوّن الناتج فقط. (ج) كلا العاملين يزيد عدد الاصطدامات بين الجسيمات المتفاعلة في وحدة الزمن: زيادة التركيز تزيد عدد الجسيمات في الحجم نفسه، وزيادة مساحة السطح تزيد عدد الجسيمات المعرضة للتصادم على سطح المادة الصلبة؛ ولا يغير أيٌّ منهما طاقة التنشيط.', '["الطحن يزيد مساحة السطح فتزداد الاصطدامات والسرعة","الناتج الكلي لا يتغير","العاملان يزيدان عدد الاصطدامات بطريقتين مختلفتين"]'::jsonb, '[]'::jsonb, '[{"element":"أثر الطحن في السرعة وتفسيره","marks":2},{"element":"ثبات الناتج الكلي","marks":1},{"element":"المقارنة بين التجزئة والتركيز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: أثر الطحن في السرعة وتفسيره؛ ثبات الناتج الكلي؛ المقارنة بين التجزئة والتركيز"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الطحن يزيد كمية الناتج","القول إن الطحن يقلل طاقة التنشيط","الخلط بين مساحة السطح وتركيز المحلول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.436Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
