from (values
('mcq', 1, 'ما المادة المحفِّزة؟', null, null, '["مادة تبطئ سرعة التفاعل الكيميائي أو تمنع حدوثه","مادة تزيد سرعة التفاعل الكيميائي دون أن تُستهلك في التفاعل","مادة تزيد سرعة التفاعل الكيميائي وتتحول إلى أحد نواتجه","مادة تزيد كمية النواتج المتكونة في نهاية التفاعل"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 61 — المحفزات'),
('mcq', 2, 'ماذا يحدث لكتلة المادة المحفزة عند انتهاء التفاعل الكيميائي الذي تحفزه؟', null, null, '["تبقى كما كانت قبل التفاعل","تنقص لأنها تُستهلك في التفاعل","تزداد لأنها تتحد مع النواتج","تصبح صفرًا لتحولها كاملًا إلى نواتج"]'::jsonb, 'تذكر', 'تذكر خاصية', 'سهل', 'الكتاب ص 61 — المحفزات'),
('mcq', 3, 'لماذا لا يُكتب المحفز ضمن المواد المتفاعلة أو المواد الناتجة في المعادلة الكيميائية؟', null, null, '["لأنه يتفاعل كاملًا قبل بدء التفاعل الرئيس","لأن كميته كبيرة جدًّا مقارنة بالمتفاعلات","لأنه لا يُستهلك في التفاعل ولا يُعد من المواد الناتجة عنه","لأنه يغير نواتج التفاعل في كل مرة يُستعمل فيها"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 61 — المحفزات'),
('mcq', 4, 'يمثل المخطط الآتي طاقة تفاعل يحدث دون محفز ومع محفز. أيّ العبارات الآتية تصف المادة المحفزة وصفًا صحيحًا في ضوء المخطط؟', null, '[{"src":"qimg/chem22/c2-l2a-cat-dh.svg","alt":"مخطط طاقة لتفاعل طارد للطاقة: المحور الرأسي «الطاقة» والمحور الأفقي «سير التفاعل». مستوى المتفاعلات على اليسار أعلى من مستوى النواتج على اليمين. منحنى أحمر «دون محفز» قمته عالية، ومنحنى أزرق «مع محفز» قمته أقل ارتفاعًا، ويبدأ المنحنيان من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه. على اليمين سهم أحمر واحد متجه إلى أسفل من مستوى المتفاعلات إلى مستوى النواتج مكتوب عليه ΔH."}]'::jsonb, '["تجعل النواتج أقل طاقة من نواتج التفاعل غير المحفز","تجعل التفاعل يحتاج إلى طاقة تنشيط أكبر","تزيد طاقة المتفاعلات حتى تبلغ قمة المنحنى بسهولة","تسرّع تكوّن النواتج نفسها، ولا تغير طاقة المتفاعلات ولا طاقة النواتج"]'::jsonb, 'فهم', 'تفسير مخطط', 'متوسط', 'الكتاب ص 62 — الشكل 2-11'),
('mcq', 5, 'يتحلل فوق أكسيد الهيدروجين وفق المعادلة: 2H₂O₂(aq) → 2H₂O(l) + O₂(g). عند إضافة قليل من ثاني أكسيد المنجنيز MnO₂ يزداد تصاعد الأكسجين، ويُسترجع MnO₂ كاملًا بعد التفاعل. ما المادة المحفزة في هذا التفاعل؟', null, null, '["MnO₂","H₂O₂","O₂","H₂O"]'::jsonb, 'تطبيق', 'تطبيق التعريف', 'متوسط', 'الكتاب ص 70 — تقويم الفصل (س43)'),
('mcq', 6, 'أُجريت تجربة لتحلل فوق أكسيد الهيدروجين، وقيس الزمن اللازم لتجمع 50 mL من الأكسجين، وكتلة مادة مضافة قبل التفاعل وبعده، والنتائج في الجدول الآتي. أيّ المادتين تُعد محفزًا؟', '{"headers":["التجربة","الكتلة قبل التفاعل","الكتلة بعد التفاعل","زمن تجمع 50 mL من O₂"],"rows":[["دون إضافة","—","—","300 s"],["مع المادة X","0.50 g","0.50 g","40 s"],["مع المادة Y","0.50 g","0.20 g","60 s"]]}'::jsonb, null, '["المادة Y فقط","المادتان X وY","المادة X فقط","لا أيّ منهما"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 61 — المحفزات'),
('mcq', 7, 'ما الفرق بين المحفزات والمثبطات من حيث أثرها في سرعة التفاعل الكيميائي؟', null, null, '["المحفزات تبطئ سرعة التفاعل، والمثبطات تزيدها","المحفزات تُستهلك في التفاعل، والمثبطات لا تُستهلك","المحفزات تزيد كمية النواتج، والمثبطات تقللها","المحفزات تزيد سرعة التفاعل، والمثبطات تبطئها وقد يمنع بعضها حدوثه"]'::jsonb, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 61 — المحفزات والمثبطات؛ ص 62 — س14'),
('essay', 1, 'عرّف المادة المحفِّزة، واذكر ثلاث خصائص لها.', null, null, null, 'تذكر', 'تعريف وخصائص', 'سهل', 'الكتاب ص 61 — المحفزات؛ ص 62 — الشكل 2-11'),
('essay', 2, 'يتحلل فوق أكسيد الهيدروجين إلى ماء وغاز الأكسجين بسرعة أكبر عند إضافة ثاني أكسيد المنجنيز MnO₂. (أ) اكتب المعادلة الموزونة لتحلل فوق أكسيد الهيدروجين. (ب) اشرح دور MnO₂ في التفاعل علمًا بأنه لا يُستهلك. (ج) اقترح طريقة عملية للتحقق من أن MnO₂ لم يُستهلك.', null, null, null, 'فهم', 'شرح دور مادة', 'متوسط', 'الكتاب ص 70 — تقويم الفصل (س43)؛ ص 61 — المحفزات'),
('essay', 3, 'كتب طالب: «المحفز مادة تزيد كمية النواتج في التفاعل الكيميائي، ويُكتب في المعادلة ضمن المواد المتفاعلة لأنه يشارك في التفاعل». قوّم هذه العبارة، وصحّح ما فيها من أخطاء، ثم اكتب التعريف الصحيح للمحفز.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 61 — المحفزات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المحفز مادة تعمل على زيادة سرعة التفاعل الكيميائي دون أن تُستهلك في التفاعل.', '["هذا وصف المثبطات، وهي عكس المحفزات.","","المحفز لا يُستهلك ولا يتحول إلى ناتج.","المحفز لا يزيد عدد النواتج أو كميتها؛ بل سرعة تكوّنها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.436Z"}'::jsonb),
('mcq', 2, 0, 'المحفز لا يُستهلك في التفاعل، لذا تبقى كتلته في نهاية التفاعل كما كانت قبله.', '["","المحفز لا يُستهلك في التفاعل، فلا تنقص كتلته.","المحفز لا يتحد مع النواتج ولا يُعد منها، فلا تزداد كتلته.","لو تحول المحفز إلى نواتج لكان مادة متفاعلة، والمحفز لا يُستهلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-07T17:19:00.437Z"}'::jsonb),
('mcq', 3, 2, 'لا يُعد المحفز ضمن المواد المتفاعلة أو الناتجة عن التفاعل لأنه لا يُستهلك ولا يتكون فيه، لذا لا يتم تضمينه في المعادلات الكيميائية.', '["المحفز لا يُستهلك، فلا يتفاعل كاملًا ولا يختفي.","السبب ليس كمية المحفز؛ بل كونه غير مستهلك وغير ناتج.","","المحفز لا يغير النواتج ولا يزيد عددها؛ بل يسرّع تكوّنها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.437Z"}'::jsonb),
('mcq', 4, 3, 'يبدأ المنحنيان من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه، والقمة مع المحفز أقل؛ فالمحفز يسرّع تكوّن النواتج نفسها دون أن يغير طاقة المتفاعلات أو النواتج ودون أن يُستهلك.', '["المنحنيان ينتهيان عند مستوى النواتج نفسه، فالمحفز لا يغير طاقة النواتج.","قمة المنحنى مع المحفز أقل، أي أن طاقة التنشيط أقل لا أكبر.","المنحنيان يبدآن من مستوى المتفاعلات نفسه، فالمحفز لا يرفع طاقة المتفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.437Z"}'::jsonb),
('mcq', 5, 0, 'MnO₂ زاد سرعة تحلل H₂O₂ واستُرجع كاملًا دون أن يُستهلك، ولم يظهر في المعادلة متفاعلًا أو ناتجًا؛ فهو المادة المحفزة.', '["","H₂O₂ مادة متفاعلة تُستهلك في التفاعل، فليس محفزًا.","O₂ ناتج من نواتج التفاعل، والمحفز لا يُعد من النواتج.","H₂O ناتج من نواتج التفاعل، وليس المادة التي زادت السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.437Z"}'::jsonb),
('mcq', 6, 2, 'المحفز يزيد سرعة التفاعل دون أن يُستهلك: X قللت الزمن من 300 s إلى 40 s وبقيت كتلتها 0.50 g، أما Y فقد نقصت كتلتها إلى 0.20 g أي استُهلكت؛ فالمحفز هو المادة X فقط.', '["كتلة Y نقصت من 0.50 g إلى 0.20 g، أي أنها استُهلكت، والمحفز لا يُستهلك.","Y استُهلكت جزئيًّا، فلا ينطبق عليها تعريف المحفز رغم أنها سرّعت التفاعل.","","X زادت السرعة (40 s بدلًا من 300 s) وبقيت كتلتها 0.50 g، فهي محفز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.437Z"}'::jsonb),
('mcq', 7, 3, 'المحفز يزيد سرعة التفاعل دون أن يُستهلك، وخلافًا له تعمل المثبطات على إبطاء سرعة التفاعل، بل قد يمنع بعضها حدوثه على الإطلاق.', '["الأثر معكوس؛ فالمحفز يزيد السرعة والمثبط يبطئها.","المحفز لا يُستهلك في التفاعل، وهذا جزء من تعريفه.","المحفز لا يزيد كمية النواتج؛ وإنما يؤثر كلاهما في السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.438Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحفز مادة تعمل على زيادة سرعة التفاعل الكيميائي دون أن تُستهلك في التفاعل. من خصائصه: (1) لا يُستهلك في التفاعل فتبقى كتلته ثابتة. (2) لا يزيد عدد النواتج أو كميتها، بل يسرّع تكوّنها. (3) لا يُعد من المواد المتفاعلة أو الناتجة، فلا يُكتب ضمنها في المعادلة الكيميائية. (4) يزيد السرعة بتقليل طاقة التنشيط.', '["التعريف: مادة تزيد سرعة التفاعل دون أن تُستهلك","خاصية صحيحة أولى","خاصية صحيحة ثانية","خاصية صحيحة ثالثة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الخاصية الأولى","marks":1},{"element":"الخاصية الثانية","marks":1},{"element":"الخاصية الثالثة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: التعريف؛ الخاصية الأولى؛ الخاصية الثانية؛ الخاصية الثالثة"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال عبارة «دون أن تُستهلك» في التعريف","القول إن المحفز يزيد كمية النواتج","الخلط بين المحفز والمثبط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.438Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) 2H₂O₂(aq) → 2H₂O(l) + O₂(g). (ب) MnO₂ مادة محفزة؛ يزيد سرعة تحلل فوق أكسيد الهيدروجين دون أن يُستهلك، لذا لا يُكتب ضمن المتفاعلات أو النواتج، ولا يزيد كمية الأكسجين الناتجة، بل يجعلها تتكون أسرع بتقليل طاقة التنشيط. (ج) قياس كتلة MnO₂ قبل إضافته، ثم فصله بعد انتهاء التفاعل (بالترشيح مثلًا) وتجفيفه وقياس كتلته؛ فإذا بقيت الكتلة نفسها فإنه لم يُستهلك.', '["معادلة موزونة صحيحة","MnO₂ محفز يزيد السرعة دون أن يُستهلك","لا يزيد كمية الأكسجين ولا يكتب في المعادلة","مقارنة كتلة MnO₂ قبل التفاعل وبعده"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة الموزونة","marks":1},{"element":"دور MnO₂ محفزًا","marks":1},{"element":"عدم كتابته في المعادلة وعدم زيادته للنواتج","marks":1},{"element":"طريقة التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: المعادلة الموزونة؛ دور MnO₂ محفزًا؛ عدم كتابته في المعادلة وعدم زيادته للنواتج؛ طريقة التحقق"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة MnO₂ ضمن المتفاعلات أو النواتج","القول إن MnO₂ يزيد حجم الأكسجين الناتج","كتابة المعادلة غير موزونة: H₂O₂ → H₂O + O₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-07T17:19:00.438Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة تحتوي على خطأين: (1) المحفز لا يزيد كمية النواتج أو عددها، وإنما يزيد سرعة تكوّنها. (2) المحفز لا يُكتب ضمن المواد المتفاعلة أو الناتجة في المعادلة؛ لأنه لا يُستهلك في التفاعل ولا يُعد من المواد الناتجة عنه. التعريف الصحيح: المحفز مادة تعمل على زيادة سرعة التفاعل الكيميائي دون أن تُستهلك في التفاعل.', '["تصحيح الخطأ الأول: يزيد السرعة لا كمية النواتج","تصحيح الخطأ الثاني: لا يُكتب ضمن المتفاعلات لأنه لا يُستهلك","التعريف الصحيح للمحفز"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ الأول وتصحيحه","marks":1},{"element":"تحديد الخطأ الثاني وتصحيحه","marks":1},{"element":"كتابة التعريف الصحيح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: تحديد الخطأ الأول وتصحيحه؛ تحديد الخطأ الثاني وتصحيحه؛ كتابة التعريف الصحيح"},{"level":"1–2 درجة","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح خطأ واحد فقط","الموافقة على أن المحفز يُستهلك","تعريف المحفز بأنه مادة تبطئ التفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-07T17:19:00.438Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O05') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C2-L2-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'كيف تزيد المادة المحفزة سرعة التفاعل الكيميائي؟', null, null, '["برفع درجة حرارة المواد المتفاعلة","بزيادة متوسط الطاقة الحركية للجسيمات","بتقليل طاقة التنشيط اللازمة للتفاعل","بزيادة تركيز المواد المتفاعلة"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 62 — الخلاصة'),
('mcq', 2, 'يمثل المخطط الآتي الطاقة لتفاعل واحد يحدث بمسارين (1) و(2). أيّ المسارين يمثل التفاعل بوجود محفز، ولماذا؟', null, '[{"src":"qimg/chem22/c2-l2a-cat-12.svg","alt":"مخطط طاقة لتفاعل واحد طارد للطاقة يحدث بمسارين: المحور الرأسي «الطاقة» والمحور الأفقي «سير التفاعل». مستوى المتفاعلات على اليسار أعلى من مستوى النواتج على اليمين، والمستويان مشتركان بين المسارين. المنحنى (1) (أحمر) قمته عالية، والمنحنى (2) (أزرق) قمته أقل ارتفاعًا."}]'::jsonb, '["(1)؛ لأن قمته أعلى فطاقة الاصطدامات فيه أكبر","(2)؛ لأن طاقة نواتجه أقل من نواتج (1)","(1)؛ لأنه يطلق طاقة أكبر في أثناء التفاعل","(2)؛ لأن طاقة التنشيط فيه أقل"]'::jsonb, 'فهم', 'تفسير مخطط', 'متوسط', 'الكتاب ص 62 — الشكل 2-11 (مخطط طاقة التفاعل المحفز وغير المحفز)'),
('mcq', 3, 'يمثل المخطط الآتي طاقة تفاعل دون محفز ومع محفز. ما أثر المحفز في الطاقة المنطلقة من التفاعل (ΔH)؟', null, '[{"src":"qimg/chem22/c2-l2a-cat-dh.svg","alt":"مخطط طاقة لتفاعل طارد للطاقة: المحور الرأسي «الطاقة» والمحور الأفقي «سير التفاعل». مستوى المتفاعلات على اليسار أعلى من مستوى النواتج على اليمين. منحنى أحمر «دون محفز» قمته عالية، ومنحنى أزرق «مع محفز» قمته أقل ارتفاعًا، ويبدأ المنحنيان من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه. على اليمين سهم أحمر واحد متجه إلى أسفل من مستوى المتفاعلات إلى مستوى النواتج مكتوب عليه ΔH."}]'::jsonb, '["يزيدها؛ لأن قمة المنحنى مع المحفز أقل","لا يغيرها؛ لأن طاقتي المتفاعلات والنواتج لا تتغيران","يقللها؛ لأن المحفز يمتص جزءًا من الطاقة المنطلقة","يجعل التفاعل ماصًّا للطاقة بدلًا من طارد"]'::jsonb, 'فهم', 'تفسير مخطط', 'متوسط', 'الكتاب ص 62 — الشكل 2-11 (مخطط طاقة التفاعل المحفز وغير المحفز) (اختبار الرسم البياني)'),
('mcq', 4, 'يبين الشكل الآتي توزيع طاقة جسيمات المتفاعلات عند درجة حرارة ثابتة، وموقع طاقة التنشيط دون محفز ومع محفز. لماذا يكون التفاعل المحفز أسرع عند درجة الحرارة نفسها؟', null, '[{"src":"qimg/chem22/c2-l2a-dist-cat.svg","alt":"منحنى واحد لتوزيع طاقة جسيمات المتفاعلات عند درجة حرارة ثابتة: المحور الأفقي «طاقة التصادم» والمحور الرأسي «عدد الجسيمات»؛ قمة المنحنى عند طاقة منخفضة ثم ينخفض تدريجيًّا نحو الطاقات العالية. على المحور الأفقي خطان رأسيان متقطعان: خط عند طاقة عالية عنوانه «Ea دون محفز» والمنطقة الواقعة تحت المنحنى على يمينه صغيرة، وخط أخضر عند طاقة أقل عنوانه «Ea مع محفز» والمنطقة الواقعة تحت المنحنى على يمينه أكبر بكثير."}]'::jsonb, '["لأن عدد الجسيمات التي لها طاقة تساوي طاقة التنشيط الأقل أو تزيد عليها أكبر","لأن المحفز يزيد طاقة الجسيمات فينزاح المنحنى نحو طاقات أعلى","لأن المحفز يزيد العدد الكلي لجسيمات المتفاعلات","لأن المحفز يرفع طاقة التنشيط فتصبح الاصطدامات أكثر فاعلية"]'::jsonb, 'فهم', 'تفسير منحنى توزيع الطاقة', 'متوسط', 'الكتاب ص 62 — الشكل 2-11 (مخطط طاقة التفاعل المحفز وغير المحفز)؛ ص 60 — الشكل 2-10'),
('mcq', 5, 'يحتاج الحصان والفارس إلى قليل من الطاقة لاجتياز حاجز منخفض، بينما يحتاجان إلى مزيد من السرعة والطاقة لاجتياز حاجز مرتفع. بماذا يُشبَّه الحاجز المنخفض في التفاعلات الكيميائية؟', null, null, '["بالطاقة المنطلقة من التفاعل (ΔH)","بطاقة التنشيط المنخفضة للتفاعل المحفز","بطاقة النواتج المنخفضة للتفاعل","بطاقة التنشيط المرتفعة للتفاعل غير المحفز"]'::jsonb, 'تطبيق', 'تفسير تشبيه', 'سهل', 'الكتاب ص 62 — الشكل 2-12'),
('mcq', 6, 'تفاعل طارد للطاقة دون محفز له طاقة تنشيط Ea = 120 kJ وتغير في الطاقة ΔH = −50 kJ. أيّ القيم الآتية يمكن أن تكون للتفاعل نفسه عند إضافة محفز؟', null, null, '["Ea = 70 kJ، ΔH = −20 kJ","Ea = 150 kJ، ΔH = −50 kJ","Ea = 70 kJ، ΔH = −50 kJ","Ea = 120 kJ، ΔH = −90 kJ"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 62 — الشكل 2-11 (مخطط طاقة التفاعل المحفز وغير المحفز)'),
('mcq', 7, 'يمثل المخطط الآتي طاقة تفاعل دون محفز ومع محفز. ما الوصف الأدق لما يفعله المحفز وفق المخطط؟', null, '[{"src":"qimg/chem22/c2-l2a-cat-profile.svg","alt":"مخطط طاقة لتفاعل طارد للطاقة: المحور الرأسي «الطاقة» والمحور الأفقي «سير التفاعل». مستوى المتفاعلات على اليسار أعلى من مستوى النواتج على اليمين. منحنيان يبدآن من مستوى المتفاعلات وينتهيان عند مستوى النواتج نفسه: المنحنى الأحمر «تفاعل غير محفز» قمته عالية، والمنحنى الأزرق «تفاعل محفز» قمته أقل ارتفاعًا. سهم أحمر طويل من مستوى المتفاعلات إلى ارتفاع قمة المنحنى الأحمر مكتوب عليه «Ea غير محفز»، وسهم أزرق أقصر من مستوى المتفاعلات إلى ارتفاع قمة المنحنى الأزرق مكتوب عليه «Ea محفز»."}]'::jsonb, '["يرفع طاقة المتفاعلات حتى تقترب من قمة المنحنى","يخفض طاقة النواتج فيزداد الفرق بينها وبين المتفاعلات","يزيل طاقة التنشيط تمامًا فيحدث التفاعل دون اصطدامات","يوفر للتفاعل مسارًا آخر طاقة تنشيطه أقل، دون أن يغير المتفاعلات أو النواتج"]'::jsonb, 'فهم', 'تفسير مخطط', 'صعب', 'الكتاب ص 62 — الشكل 2-11 (مخطط طاقة التفاعل المحفز وغير المحفز)'),
('essay', 1, 'استعمل نظرية التصادم ومفهوم المعقد المنشط في تعليل زيادة المحفزات لسرعة التفاعلات الكيميائية.', null, null, null, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 62 — الشكل 2-11 والخلاصة'),
('essay', 2, 'يمثل المخطط الآتي الطاقة لتفاعل واحد يحدث بمسارين (1) و(2). (أ) حدد المسار الذي يمثل التفاعل المحفز، مع التعليل. (ب) قارن بين المسارين من حيث طاقة التنشيط، ومن حيث الطاقة المنطلقة من التفاعل. (ج) أيّ المسارين ينتج النواتج بسرعة أكبر؟ ولماذا؟', null, '[{"src":"qimg/chem22/c2-l2a-cat-12.svg","alt":"مخطط طاقة لتفاعل واحد طارد للطاقة يحدث بمسارين: المحور الرأسي «الطاقة» والمحور الأفقي «سير التفاعل». مستوى المتفاعلات على اليسار أعلى من مستوى النواتج على اليمين، والمستويان مشتركان بين المسارين. المنحنى (1) (أحمر) قمته عالية، والمنحنى (2) (أزرق) قمته أقل ارتفاعًا."}]'::jsonb, null, 'تحليل', 'تحليل مخطط', 'متوسط', 'الكتاب ص 62 — الشكل 2-11 (مخطط طاقة التفاعل المحفز وغير المحفز) (اختبار الرسم البياني)'),
('essay', 3, 'يبين الشكل الآتي منحنى توزيع طاقة جسيمات المتفاعلات عند درجة حرارة ثابتة، وعليه موقع طاقة التنشيط دون محفز ومع محفز. (أ) فسّر بالاستعانة بالشكل كيف يزيد المحفز سرعة التفاعل. (ب) قارن بين أثر إضافة المحفز وأثر رفع درجة الحرارة في هذا الشكل وفي سرعة التفاعل.', null, '[{"src":"qimg/chem22/c2-l2a-dist-cat.svg","alt":"منحنى واحد لتوزيع طاقة جسيمات المتفاعلات عند درجة حرارة ثابتة: المحور الأفقي «طاقة التصادم» والمحور الرأسي «عدد الجسيمات»؛ قمة المنحنى عند طاقة منخفضة ثم ينخفض تدريجيًّا نحو الطاقات العالية. على المحور الأفقي خطان رأسيان متقطعان: خط عند طاقة عالية عنوانه «Ea دون محفز» والمنطقة الواقعة تحت المنحنى على يمينه صغيرة، وخط أخضر عند طاقة أقل عنوانه «Ea مع محفز» والمنطقة الواقعة تحت المنحنى على يمينه أكبر بكثير."}]'::jsonb, null, 'تحليل', 'تفسير ومقارنة بالاستعانة بشكل', 'صعب', 'الكتاب ص 62 — الشكل 2-11 (مخطط طاقة التفاعل المحفز وغير المحفز)؛ ص 60 — الشكل 2-10')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تزيد المحفزات سرعة التفاعل الكيميائي بتقليل طاقة التنشيط، فيصبح عدد أكبر من الاصطدامات قادرًا على تكوين المعقد المنشط.', '["المحفز لا يرفع درجة الحرارة؛ وأثر الحرارة عامل مستقل عنه.","زيادة متوسط الطاقة الحركية تنتج عن رفع درجة الحرارة لا عن المحفز.","","المحفز لا يغير تركيز المتفاعلات، ولا يُستهلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.438Z"}'::jsonb),
('mcq', 2, 3, 'المساران يبدآن وينتهيان عند المستويين نفسيهما، لكن قمة المسار (2) أقل؛ أي أن طاقة التنشيط فيه أقل، وهذا ما يفعله المحفز، فالمسار (2) هو التفاعل المحفز.', '["القمة الأعلى تعني طاقة تنشيط أكبر، أي تفاعلًا أبطأ، والمحفز يقلل طاقة التنشيط.","المساران ينتهيان عند مستوى النواتج نفسه؛ والفرق في ارتفاع القمة فقط.","الطاقة المنطلقة واحدة في المسارين لأن المتفاعلات والنواتج نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-07T17:19:00.439Z"}'::jsonb),
('mcq', 3, 1, 'ΔH هي الفرق بين طاقة النواتج وطاقة المتفاعلات، والمنحنيان يبدآن من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه؛ فالمحفز يقلل طاقة التنشيط فقط ولا يغير الطاقة المنطلقة.', '["انخفاض القمة يعني طاقة تنشيط أقل، ولا علاقة له بالفرق بين المتفاعلات والنواتج.","","المحفز لا يُستهلك ولا يغير طاقة النواتج، فتبقى ΔH كما هي.","مستوى النواتج بقي أقل من مستوى المتفاعلات، فالتفاعل يبقى طاردًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.439Z"}'::jsonb),
('mcq', 4, 0, 'المنحنى نفسه لأن درجة الحرارة ثابتة، لكن خط طاقة التنشيط مع المحفز يقع عند طاقة أقل، فتكبر المساحة تحت المنحنى على يمينه؛ أي يزداد عدد الجسيمات (والاصطدامات) التي تملك الطاقة الكافية، فيزداد عدد الاصطدامات الفعالة وتزداد السرعة.', '["","المنحنى واحد لم يتغير؛ فالمحفز لا يغير طاقة الجسيمات بل يقلل طاقة التنشيط.","العدد الكلي للجسيمات ثابت، والمحفز لا يُضيف جسيمات متفاعلة.","المحفز يقلل طاقة التنشيط ولا يرفعها، كما يظهر من موقع خط «Ea مع محفز»."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-07T17:19:00.439Z"}'::jsonb),
('mcq', 5, 1, 'يمكن اعتبار طاقة التنشيط عقبة يجب تخطيها؛ والحاجز المرتفع يقابل طاقة التنشيط العالية للتفاعل غير المحفز، أما الحاجز المنخفض فيقابل طاقة التنشيط المنخفضة للتفاعل المحفز.', '["ارتفاع الحاجز يمثل الطاقة اللازمة لبدء التفاعل، لا الطاقة المنطلقة منه.","","طاقة النواتج لا تمثل عقبة يجب تخطيها؛ فالعقبة هي طاقة التنشيط.","التفاعل غير المحفز يقابل الحاجز المرتفع لا المنخفض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-07T17:19:00.439Z"}'::jsonb),
('mcq', 6, 2, 'المحفز يقلل طاقة التنشيط (من 120 kJ إلى قيمة أقل مثل 70 kJ) ولا يغير الطاقة المنطلقة لأن المتفاعلات والنواتج نفسها؛ فالقيم الممكنة: Ea = 70 kJ، ΔH = −50 kJ.', '["المحفز لا يغير ΔH؛ فطاقتا المتفاعلات والنواتج لا تتغيران، فتبقى −50 kJ.","المحفز يقلل طاقة التنشيط، وارتفاعها إلى 150 kJ يجعل التفاعل أبطأ.","","طاقة التنشيط بقيت 120 kJ فلم تقل، وΔH تغيرت إلى −90 kJ؛ والمحفز يفعل العكس: يقلل طاقة التنشيط ولا يغير ΔH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.439Z"}'::jsonb),
('mcq', 7, 3, 'في المخطط مساران يبدآن وينتهيان عند المستويين نفسيهما: المسار الأحمر دون محفز والمسار الأزرق مع محفز وقمته أقل؛ فالمحفز يجعل التفاعل يسير في مسار طاقة تنشيطه أقل، دون تغيير المتفاعلات أو النواتج.', '["مستوى المتفاعلات واحد في المسارين، فالمحفز لا يرفع طاقتها.","مستوى النواتج واحد في المسارين، فلا يتغير الفرق ΔH.","للمسار المحفز قمة أيضًا، فطاقة التنشيط تقل ولا تزول، ولا بد من التصادم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.439Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لأن المحفز يقلل طاقة التنشيط اللازمة للتفاعل؛ فيسير التفاعل في مسار طاقة تنشيطه أقل، فيصبح عدد أكبر من الاصطدامات بين الجسيمات المتفاعلة يملك طاقة مساوية لطاقة التنشيط أو أكبر منها، فيزداد عدد الاصطدامات الفعالة التي تكوّن المعقد المنشط، وتتكون النواتج بسرعة أكبر.', '["المحفز يقلل طاقة التنشيط","عدد أكبر من الاصطدامات يملك الطاقة الكافية","يزداد عدد الاصطدامات الفعالة فتزداد السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"تقليل طاقة التنشيط","marks":1},{"element":"زيادة الاصطدامات ذات الطاقة الكافية","marks":1},{"element":"الربط بزيادة السرعة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: تقليل طاقة التنشيط؛ زيادة الاصطدامات ذات الطاقة الكافية؛ الربط بزيادة السرعة"},{"level":"1–2 درجة","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يزيد طاقة الجسيمات أو درجة الحرارة","القول إن المحفز يزيد عدد الاصطدامات الكلي","القول إن المحفز يزيد كمية النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-07T17:19:00.439Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المسار (2)؛ لأن قمته أقل، أي أن طاقة التنشيط فيه أقل، والمحفز يقلل طاقة التنشيط. (ب) طاقة التنشيط في المسار (2) أقل كثيرًا منها في المسار (1)، أما الطاقة المنطلقة (ΔH) فمتساوية في المسارين؛ لأنهما يبدآن من مستوى المتفاعلات نفسه وينتهيان عند مستوى النواتج نفسه. (ج) المسار (2)؛ لأن طاقة التنشيط الأقل تعني أن عددًا أكبر من الاصطدامات يملك الطاقة الكافية لتكوين المعقد المنشط، فيزداد عدد الاصطدامات الفعالة.', '["المسار (2) هو المحفز لأن طاقة تنشيطه أقل","طاقة التنشيط في (2) أقل","الطاقة المنطلقة متساوية في المسارين","المسار (2) أسرع لزيادة الاصطدامات الفعالة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المسار المحفز وتعليله","marks":1},{"element":"مقارنة طاقة التنشيط","marks":1},{"element":"مقارنة الطاقة المنطلقة","marks":1},{"element":"تحديد المسار الأسرع وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: تحديد المسار المحفز وتعليله؛ مقارنة طاقة التنشيط؛ مقارنة الطاقة المنطلقة؛ تحديد المسار الأسرع وتعليله"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار المسار (1) لأن قمته أعلى","القول إن المحفز يزيد الطاقة المنطلقة","مقارنة مستويي النواتج بدلًا من القمتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-07T17:19:00.439Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المحفز لا يغير منحنى توزيع الطاقة لأن درجة الحرارة ثابتة، لكنه يقلل طاقة التنشيط فينتقل خطها إلى طاقة أقل؛ فتكبر المساحة تحت المنحنى على يمين الخط، أي يزداد عدد الجسيمات التي تملك طاقة مساوية لطاقة التنشيط أو أكبر منها، فيزداد عدد الاصطدامات الفعالة وتزداد سرعة التفاعل. (ب) كلاهما يزيد سرعة التفاعل بزيادة عدد الاصطدامات التي لها طاقة كافية، لكن بطريقتين مختلفتين: المحفز يُبقي المنحنى كما هو ويخفض طاقة التنشيط، أما رفع درجة الحرارة فيُبقي طاقة التنشيط كما هي ويغير المنحنى نفسه، إذ يزيد متوسط الطاقة الحركية فينبسط المنحنى وينزاح نحو الطاقات الأعلى، ويزيد كذلك عدد الاصطدامات الكلي.', '["المحفز لا يغير المنحنى بل يخفض خط طاقة التنشيط","زيادة عدد الجسيمات ذات الطاقة الكافية (المساحة على يمين الخط)","رفع درجة الحرارة يغير المنحنى ويُبقي طاقة التنشيط","كلاهما يزيد الاصطدامات الفعالة والسرعة"]'::jsonb, '[]'::jsonb, '[{"element":"أثر المحفز في موقع طاقة التنشيط","marks":1},{"element":"الربط بالمساحة وعدد الاصطدامات الفعالة","marks":1},{"element":"أثر رفع درجة الحرارة في المنحنى","marks":1},{"element":"بيان أن كليهما يزيد السرعة بطريقة مختلفة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: أثر المحفز في موقع طاقة التنشيط؛ الربط بالمساحة وعدد الاصطدامات الفعالة؛ أثر رفع درجة الحرارة في المنحنى؛ بيان أن كليهما يزيد السرعة بطريقة مختلفة"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يزيح المنحنى نحو الطاقات الأعلى","القول إن رفع درجة الحرارة يقلل طاقة التنشيط","إغفال ثبات المنحنى لثبات درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-07T17:19:00.440Z"}'::jsonb)
