('essay', 1, 'عرّف المثبطات، واذكر مثالين عليها من صناعة الأغذية، مع بيان فائدتهما.', null, null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 61–62 — المثبطات'),
('essay', 2, 'قارن بين المحفزات والمثبطات من حيث: (أ) الأثر في سرعة التفاعل. (ب) الأثر في طاقة التنشيط. (ج) مثال واحد على كل منهما.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 61–62 — المحفزات والمثبطات؛ س14'),
('essay', 3, 'يمثل المخطط الآتي طاقة تفاعل واحد بمسارين (1) و(2)، أحدهما بعد إضافة مثبط. (أ) حدد المسار الذي يمثل التفاعل بوجود المثبط، وعلّل. (ب) فسّر لماذا تقل سرعة التفاعل في هذا المسار. (ج) اذكر طريقتين أخريين تعمل بهما المثبطات غير الطريقة التي يمثلها المخطط.', null, '[{"src":"qimg/chem22/c2-l2a-inhib-profile.svg","alt":"مخطط طاقة لتفاعل طارد للطاقة يحدث بمسارين: المحور الرأسي «الطاقة» والمحور الأفقي «سير التفاعل». مستوى المتفاعلات على اليسار أعلى من مستوى النواتج على اليمين، والمستويان مشتركان بين المسارين. المنحنى (1) (أزرق) قمته منخفضة نسبيًّا، والمنحنى (2) (بنفسجي) قمته أعلى بكثير."}]'::jsonb, null, 'تحليل', 'تحليل مخطط وتفسير', 'صعب', 'الكتاب ص 62 — طرائق عمل المثبطات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
