insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'المثبطات مواد تؤثر في سرعة التفاعل؛ فخلافًا للمحفز تعمل على إبطاء سرعة التفاعل، بل قد يمنع بعضها حدوث التفاعل على الإطلاق.', '["","هذا تعريف المحفزات، والمثبطات عكسها.","تقليل طاقة التنشيط عمل المحفز؛ أما بعض المثبطات فيزيد طاقة التنشيط.","المثبطات لا تزيد النواتج؛ بل تبطئ التفاعل أو تمنعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-07T17:19:00.440Z"}'::jsonb),
('mcq', 2, 1, 'في صناعة الأغذية تسمى المثبطات المواد الحافظة، أو المواد المضادة للأكسدة، وبعضها آمن للأكل ويعطي فترة صلاحية أطول للغذاء.', '["الإنزيمات محفزات تزيد سرعة التفاعلات، فهي عكس المثبطات.","","المثبطات لا تُعد من المتفاعلات أو النواتج؛ وهذان اسمان لا يخصانها.","المواد المحفزة تزيد سرعة التفاعل، والمثبطات تبطئه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.440Z"}'::jsonb),
('mcq', 3, 3, 'قمة المسار (2) أعلى من قمة المسار (1) والمتفاعلات والنواتج نفسها؛ أي أن المثبط زاد طاقة التنشيط، فيقل عدد الاصطدامات التي تملك الطاقة الكافية وتقل سرعة التفاعل.', '["قمة المسار (2) أعلى، أي أن طاقة التنشيط زادت ولم تقل.","المساران ينتهيان عند مستوى النواتج نفسه، فالطاقة المنطلقة لم تتغير، والسرعة تقل.","مستوى النواتج واحد في المسارين وأقل من المتفاعلات، فالتفاعل يبقى طاردًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.440Z"}'::jsonb),
('mcq', 4, 2, 'من طرائق عمل المثبطات: إغلاق المسارات المنخفضة الطاقة فتزيد طاقة التنشيط، والتفاعل مع المحفز فتدمره أو تمنعه من أداء وظيفته، والارتباط بالإنزيمات في التفاعلات الحيوية؛ فالإجابة: تتفاعل مع المحفز فتدمره أو تمنعه من أداء وظيفته.', '["زيادة متوسط الطاقة الحركية تزيد سرعة التفاعل، وهي أثر رفع درجة الحرارة.","زيادة مساحة السطح تزيد عدد الاصطدامات فتزيد السرعة ولا تبطئها.","","المسار ذو طاقة التنشيط الأقل هو عمل المحفز، أما المثبط فقد يغلق هذه المسارات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.440Z"}'::jsonb),
('mcq', 5, 3, 'المواد الحافظة مثبطات تبطئ سرعة التفاعلات التي تسبب فساد الغذاء، وبعضها آمن للأكل، فتعطي فترة صلاحية أطول للغذاء.', '["المواد الحافظة مثبطات تبطئ التفاعلات، ولا تسرّعها.","عمل المادة الحافظة إبطاء التفاعلات، لا إنتاج مواد غذائية جديدة.","المحفزات الهاضمة هي الإنزيمات؛ أما المادة الحافظة فمثبط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.440Z"}'::jsonb),
('mcq', 6, 1, 'في التفاعلات الحيوية ترتبط المثبطات مع الإنزيمات التي تحفز التفاعل، فتمنع حدوثه؛ فالمادة مثبط، وأثرها منع التفاعل أو إبطاؤه.', '["المادة التي تمنع الإنزيم من العمل تبطئ التفاعل، فهي مثبط لا محفز.","","المادة ارتبطت بالإنزيم وأوقفت عمله، فهي ليست إنزيمًا.","المادة لم تتفاعل لتكوين نواتج، بل منعت عمل الإنزيم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.440Z"}'::jsonb),
('mcq', 7, 0, 'المواد المضادة للأكسدة من المثبطات المستعملة في صناعة الأغذية؛ فهي تبطئ تفاعلات فساد الزيت، أما بقية الخيارات فمحفزات أو مواد متفاعلة تزيد السرعة.', '["","MnO₂ يزيد سرعة تحلل فوق أكسيد الهيدروجين، فهو محفز.","الإنزيم محفز حيوي يزيد سرعة التفاعل.","مسحوق الخارصين مادة متفاعلة، وتجزئته تزيد سرعة التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.441Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المثبطات مواد تعمل على إبطاء سرعة التفاعل الكيميائي، وقد يمنع بعضها حدوث التفاعل على الإطلاق. في صناعة الأغذية تسمى المثبطات: (1) المواد الحافظة، (2) المواد المضادة للأكسدة. وفائدتهما إبطاء التفاعلات التي تفسد الغذاء، فيصبح للغذاء فترة صلاحية أطول، وبعض المواد الحافظة آمنة للأكل.', '["تعريف المثبطات","المواد الحافظة","المواد المضادة للأكسدة","الفائدة: إطالة فترة صلاحية الغذاء"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1},{"element":"بيان الفائدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: التعريف؛ المثال الأول؛ المثال الثاني؛ بيان الفائدة"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المثبط بأنه يزيد سرعة التفاعل","ذكر الإنزيمات مثالًا على المثبطات","إغفال أن بعض المثبطات يمنع التفاعل كليًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.441Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المحفزات تزيد سرعة التفاعل الكيميائي دون أن تُستهلك، أما المثبطات فتبطئ سرعة التفاعل وقد يمنع بعضها حدوثه. (ب) المحفزات تقلل طاقة التنشيط، أما بعض المثبطات فتغلق المسارات المنخفضة الطاقة فتزيد طاقة التنشيط (وبعضها يدمر المحفز أو يمنعه من العمل). (ج) مثال المحفز: الإنزيمات في الجسم، أو ثاني أكسيد المنجنيز في تحلل فوق أكسيد الهيدروجين؛ ومثال المثبط: المواد الحافظة أو المواد المضادة للأكسدة في الأغذية.', '["المحفز يزيد السرعة والمثبط يبطئها","المحفز يقلل طاقة التنشيط وبعض المثبطات تزيدها","مثال صحيح للمحفز","مثال صحيح للمثبط"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في السرعة","marks":1},{"element":"المقارنة في طاقة التنشيط","marks":1},{"element":"مثال المحفز","marks":1},{"element":"مثال المثبط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: المقارنة في السرعة؛ المقارنة في طاقة التنشيط؛ مثال المحفز؛ مثال المثبط"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المثبط يُستهلك دائمًا بينما المحفز لا يُستهلك","القول إن المثبط يقلل طاقة التنشيط","تبادل الأمثلة بين المحفز والمثبط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-07T17:19:00.441Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المسار (2)؛ لأن قمته أعلى، أي أن طاقة التنشيط فيه أكبر، وبعض المثبطات تغلق المسارات المنخفضة الطاقة فتزيد طاقة التنشيط. (ب) عند زيادة طاقة التنشيط يقل عدد الاصطدامات التي تملك طاقة مساوية لطاقة التنشيط أو أكبر منها، فيقل عدد الاصطدامات الفعالة وتقل سرعة التفاعل. (ج) بعض المثبطات تتفاعل مع المحفز فتدمره أو تمنعه من أداء وظيفته؛ وفي التفاعلات الحيوية ترتبط المثبطات مع الإنزيمات التي تحفز التفاعل فتمنع حدوثه.', '["المسار (2) لأن طاقة تنشيطه أكبر","قلة الاصطدامات ذات الطاقة الكافية تقلل السرعة","التفاعل مع المحفز وتدميره أو منعه","الارتباط بالإنزيمات في التفاعلات الحيوية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد مسار المثبط وتعليله","marks":1},{"element":"تفسير نقص السرعة","marks":1},{"element":"الطريقة الأولى","marks":1},{"element":"الطريقة الثانية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تتضمن جميع العناصر المطلوبة: تحديد مسار المثبط وتعليله؛ تفسير نقص السرعة؛ الطريقة الأولى؛ الطريقة الثانية"},{"level":"1–3 درجات","description":"إجابة جزئية: درجة لكل عنصر صحيح من العناصر المطلوبة، مع نقص أو خطأ في بعضها"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار المسار (1) بحجة أن المثبط يقلل الطاقة","القول إن المثبط يغير طاقة النواتج","ذكر رفع درجة الحرارة طريقة لعمل المثبط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.441Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
