from (values
('mcq', 1, 'ما الأثر المباشر لرفع درجة حرارة مادة في الجسيمات التي تتكون منها؟', null, null, '["تقل طاقة التنشيط اللازمة لتفاعل جسيماتها","يزداد متوسط الطاقة الحركية لجسيماتها","يزداد عدد جسيماتها في وحدة الحجم","تزداد كتلة كل جسيم من جسيماتها"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 60 — درجة الحرارة'),
('mcq', 2, 'لا تفسر زيادة عدد التصادمات وحدها الزيادة الكبيرة في سرعة التفاعل عند رفع درجة الحرارة قليلًا. ما التفسير الأدق لهذه الزيادة؟', null, null, '["تنخفض طاقة التنشيط للتفاعل كلما ارتفعت درجة الحرارة","يزداد تركيز المواد المتفاعلة في الوعاء بارتفاع الحرارة","يتحول التفاعل من تفاعل ماص للطاقة إلى تفاعل طارد لها","يزداد كثيرًا عدد التصادمات التي طاقتها تساوي طاقة التنشيط أو تزيد عليها"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 60 — درجة الحرارة'),
('mcq', 3, 'يفسد الطعام ببطء عند حفظه في الثلاجة مقارنة ببقائه عند درجة حرارة الغرفة. ما تفسير ذلك وفق نظرية التصادم؟', null, null, '["يقل متوسط الطاقة الحركية للجسيمات فيقل عدد التصادمات الفعالة","تتوقف تصادمات الجسيمات تمامًا عند درجات الحرارة المنخفضة","تزداد طاقة التنشيط لتفاعلات الفساد عند خفض درجة الحرارة","يقل تركيز المواد المتفاعلة في الطعام عند تبريده"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 60 — درجة الحرارة (تلف الأطعمة)'),
('mcq', 4, 'يمثل المنحنى الآتي توزيع طاقة جسيمات خليط متفاعل عند درجتي الحرارة T₁ وT₂. بم يفسر المنحنى أن التفاعل أسرع عند T₂؟', null, '[{"src":"qimg/chem22/c2-l2b-dist-t1t2.svg","alt":"منحنيا توزيع طاقة الجسيمات: المحور الأفقي طاقة التصادم، والمحور الرأسي عدد الجسيمات. المنحنى T₁ (أزرق) قمته عالية وضيقة عند طاقة منخفضة، والمنحنى T₂ (أحمر) قمته أخفض وأعرض وتقع عند طاقة أعلى، ومكتوب أعلى الشكل T₂ > T₁. خط رأسي متقطع يمثل طاقة التنشيط، والمنطقة تحت كل منحنى يمين هذا الخط مظللة: المنطقة تحت المنحنى T₂ (وردية) أكبر بكثير من المنطقة تحت المنحنى T₁ (زرقاء)."}]'::jsonb, '["طاقة التنشيط عند T₂ أقل منها عند T₁","العدد الكلي لجسيمات الخليط عند T₂ أكبر منه عند T₁","عدد الجسيمات ذات الطاقة الكافية لتجاوز طاقة التنشيط أكبر عند T₂","قمة المنحنى T₂ أعلى من قمة المنحنى T₁"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 60 — الشكل 2-10 توزيع طاقة الجسيمات'),
('mcq', 5, 'أُجريت تجربتان متماثلتان لتفاعل شريط مغنيسيوم مع حمض HCl، الأولى عند 20°C والثانية عند 40°C. أيّ العبارات الآتية صحيحة؟', null, null, '["يتصاعد H₂ أسرع عند 40°C لزيادة التصادمات ذات الطاقة الكافية","تتكون كمية أكبر من H₂ عند 40°C في نهاية التفاعل","يتصاعد H₂ أسرع عند 20°C لأن الجسيمات البطيئة تتصادم أطول","يتصاعد H₂ أسرع عند 40°C لانخفاض طاقة التنشيط"]'::jsonb, 'تطبيق', 'تطبيق على موقف', 'متوسط', 'الكتاب ص 60 — درجة الحرارة'),
('mcq', 6, 'أيّ مما يأتي يبقى ثابتًا لتفاعل ما عند رفع درجة حرارته من T₁ إلى T₂؟', null, null, '["متوسط الطاقة الحركية للجسيمات","عدد التصادمات في وحدة الزمن","عدد التصادمات ذات الطاقة الكافية","طاقة التنشيط للتفاعل"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 60 — درجة الحرارة (الشكل 2-10)'),
('mcq', 7, 'يحتوي عود الثقاب على مواد تتفاعل مع أكسجين الهواء، ومع ذلك لا يشتعل إلا عند حكه لتسخين رأسه. ما تفسير ذلك وفق نظرية التصادم؟', null, null, '["جسيمات مادة الثقاب لا تتصادم مع الأكسجين قبل الحك","تصادمات قليلة جدًا تبلغ طاقة التنشيط عند درجة حرارة الغرفة","الحك يزيد تركيز الأكسجين حول رأس عود الثقاب","الحك يخفض طاقة التنشيط لتفاعل الاحتراق"]'::jsonb, 'تطبيق', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 60 — درجة الحرارة'),
('essay', 1, 'طبّق نظرية التصادم لتفسير فساد الطعام ببطء عند وضعه في الثلاجة مقارنة ببقائه خارجها عند درجة حرارة الغرفة.', null, null, null, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 70 — س41، وص 60 — درجة الحرارة'),
('essay', 2, 'طبّق نظرية التصادم لتوضح سببين يجعلان زيادة درجة حرارة التفاعل بمقدار 10 K تؤدي غالبًا إلى مضاعفة سرعته، وبيّن أيّ السببين أكبر أثرًا.', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 72 — س58، وص 60 — درجة الحرارة'),
('essay', 3, 'وُضعت قطعتان متساويتان من قرص فوّار في كأسين فيهما الكمية نفسها من الماء، الأولى عند 25°C والثانية عند 50°C. (أ) توقع في أيّ الكأسين يذوب القرص ويتوقف الفوران أسرع. (ب) فسّر توقعك بنظرية التصادم. (ج) أين تتوقع أن يقع زمن التفاعل لو أُعيدت التجربة عند 40°C؟', null, null, null, 'تحليل', 'توقع وتفسير', 'صعب', 'الكتاب ص 61 — تجربة دراسة العلاقة بين سرعة التفاعل ودرجة الحرارة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
