from (values
('mcq', 1, 1, 'زيادة درجة حرارة المادة تزيد متوسط الطاقة الحركية لجسيماتها، فتتحرك أسرع وتتصادم أكثر وبطاقة أكبر.', '["خفض طاقة التنشيط عمل المحفز، أما رفع درجة الحرارة فلا يغير طاقة التنشيط.","","زيادة عدد الجسيمات في وحدة الحجم هي زيادة التركيز، ولا تنتج عن التسخين.","كتلة الجسيم لا تتغير بتغير درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.441Z"}'::jsonb),
('mcq', 2, 3, 'عند درجة الحرارة الأعلى يصبح عدد الاصطدامات عالية الطاقة (التي طاقتها تساوي طاقة التنشيط أو أكبر منها) أكبر كثيرًا، وهذه هي التصادمات التي تنتج عنها تفاعلات؛ لذا يزداد عدد التصادمات الفعالة ازديادًا كبيرًا.', '["طاقة التنشيط خاصية للتفاعل لا تتغير برفع درجة الحرارة؛ الذي يتغير هو عدد الجسيمات القادرة على تجاوزها.","التسخين لا يزيد عدد الجسيمات في وحدة الحجم، فالتركيز لا يتغير.","نوع التفاعل (ماص أو طارد) لا يتغير بتغير درجة الحرارة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.441Z"}'::jsonb),
('mcq', 3, 0, 'خفض درجة الحرارة يقلل متوسط الطاقة الحركية للجسيمات، فتتصادم بمعدل أقل، ويقل عدد التصادمات التي طاقتها تساوي طاقة التنشيط أو أكبر منها؛ فتبطؤ تفاعلات فساد الطعام.', '["","الجسيمات تبقى متحركة ومتصادمة عند درجة حرارة الثلاجة، لكن بطاقة أقل؛ لذا يبطؤ الفساد ولا يتوقف.","طاقة التنشيط لا تتغير بتغير درجة الحرارة؛ الذي يقل هو عدد الجسيمات التي تبلغها.","التبريد لا يغير كمية المواد في الطعام أو تركيزها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-07T17:19:00.441Z"}'::jsonb),
('mcq', 4, 2, 'المنطقة المظللة يمين خط طاقة التنشيط تحت المنحنى T₂ أكبر كثيرًا منها تحت T₁؛ أي أن عدد الجسيمات (والاصطدامات) التي طاقتها تساوي طاقة التنشيط أو تزيد عليها أكبر عند T₂، فالتفاعل أسرع.', '["خط طاقة التنشيط واحد للمنحنيين؛ فطاقة التنشيط لم تتغير برفع درجة الحرارة.","العينة نفسها عند درجتي حرارة؛ فالعدد الكلي للجسيمات لم يتغير، وإنما تغير توزيع طاقاتها.","","قمة المنحنى T₂ أخفض من قمة T₁ وليست أعلى، وارتفاع القمة لا يدل على سرعة التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.442Z"}'::jsonb),
('mcq', 5, 0, 'عند 40°C يكون متوسط الطاقة الحركية للجسيمات أكبر، فتتصادم أكثر ويزداد عدد التصادمات التي طاقتها تساوي طاقة التنشيط أو تزيد عليها؛ لذا يتصاعد غاز H₂ أسرع.', '["","رفع درجة الحرارة يسرع التفاعل ولا يغير كمية النواتج النهائية لكميات المتفاعلات نفسها.","الجسيمات الأبطأ تتصادم بمعدل أقل وبطاقة أقل، فيكون التفاعل أبطأ عند 20°C لا أسرع.","طاقة التنشيط لا تتغير بتغير درجة الحرارة؛ والتفسير الصحيح زيادة الطاقة الحركية للجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.442Z"}'::jsonb),
('mcq', 6, 3, 'طاقة التنشيط أقل طاقة يجب أن تمتلكها الجسيمات المتصادمة لتكوين المعقد المنشط، وهي خاصية للتفاعل لا تتغير برفع درجة الحرارة، في حين يزداد متوسط الطاقة الحركية وعدد التصادمات وعدد التصادمات ذات الطاقة الكافية.', '["متوسط الطاقة الحركية يزداد بارتفاع درجة الحرارة.","تتحرك الجسيمات أسرع عند T₂ فيزداد عدد التصادمات في وحدة الزمن.","هذا العدد يزداد كثيرًا عند T₂، وهو سبب زيادة السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.442Z"}'::jsonb),
('mcq', 7, 1, 'عند درجة حرارة الغرفة يكون عدد التصادمات التي طاقتها تساوي طاقة التنشيط أو تزيد عليها قليلًا جدًا، فلا يحدث احتراق يُذكر. والحك يرفع درجة الحرارة فيزيد متوسط الطاقة الحركية، فيتجاوز كثير من التصادمات طاقة التنشيط ويبدأ الاشتعال.', '["الجسيمات تتصادم دائمًا عند درجة حرارة الغرفة، لكن أغلب تصادماتها لا تمتلك طاقة كافية.","","الحك لا يغير تركيز الأكسجين في الهواء، وإنما يرفع درجة حرارة رأس العود.","الحك لا يعمل عمل المحفز؛ فهو يرفع درجة الحرارة ولا يغير طاقة التنشيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-07T17:19:00.442Z"}'::jsonb),
('essay', 1, null::int, null, null, 'درجة حرارة الثلاجة أقل من درجة حرارة الغرفة، فيكون متوسط الطاقة الحركية لجسيمات المواد المتفاعلة في الطعام أقل؛ فتتحرك أبطأ وتتصادم بمعدل أقل، والأهم أن عدد التصادمات التي طاقتها تساوي طاقة التنشيط أو تزيد عليها يقل كثيرًا. وبما أن هذه التصادمات وحدها تنتج تفاعلًا، تقل سرعة تفاعلات الفساد فيبقى الطعام صالحًا مدة أطول.', '["انخفاض درجة الحرارة يقلل متوسط الطاقة الحركية للجسيمات","يقل عدد التصادمات في وحدة الزمن","يقل عدد التصادمات التي طاقتها تساوي طاقة التنشيط أو أكبر، فتقل سرعة الفساد"]'::jsonb, '[]'::jsonb, '[{"element":"ربط انخفاض الحرارة بنقص متوسط الطاقة الحركية","marks":1},{"element":"نقص عدد التصادمات","marks":1},{"element":"نقص التصادمات ذات الطاقة الكافية وأثره في السرعة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يربط انخفاض الحرارة بالطاقة الحركية وبعدد التصادمات وبالتصادمات ذات الطاقة الكافية"},{"level":"2 درجتان","description":"يذكر نقص الطاقة الحركية ونقص التصادمات دون ربطها بطاقة التنشيط"},{"level":"1 درجة","description":"يذكر أن التبريد يبطئ التفاعل دون تفسير بنظرية التصادم"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعلات تتوقف تمامًا في الثلاجة","القول إن طاقة التنشيط تزداد عند التبريد","إهمال شرط امتلاك التصادم طاقة كافية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-07T17:19:00.442Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السبب الأول: زيادة درجة الحرارة تزيد متوسط الطاقة الحركية للجسيمات فتتحرك أسرع وتتصادم مرات أكثر في وحدة الزمن. السبب الثاني: يزداد كثيرًا عدد التصادمات عالية الطاقة التي طاقتها تساوي طاقة التنشيط أو تزيد عليها، وهي التصادمات القادرة على تكوين المعقد المنشط وإحداث التفاعل. والسبب الثاني هو الأكبر أثرًا؛ لأن زيادة عدد التصادمات وحدها لا تفسر مضاعفة السرعة بزيادة صغيرة في درجة الحرارة، في حين يتضاعف تقريبًا عدد التصادمات ذات الطاقة الكافية.', '["زيادة متوسط الطاقة الحركية تزيد عدد التصادمات في وحدة الزمن","زيادة عدد التصادمات التي طاقتها ≥ طاقة التنشيط","التصادمات ذات الطاقة الكافية هي التي تكوّن المعقد المنشط","السبب الثاني أكبر أثرًا"]'::jsonb, '[]'::jsonb, '[{"element":"السبب الأول","marks":1},{"element":"السبب الثاني","marks":1},{"element":"ربط التصادمات ذات الطاقة الكافية بالمعقد المنشط","marks":1},{"element":"تحديد السبب الأكبر أثرًا مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر السببين ويربطهما بطاقة التنشيط والمعقد المنشط ويحدد الأكبر أثرًا مع التعليل"},{"level":"2–3 درجات","description":"يذكر السببين دون تحديد الأكبر أثرًا أو دون الربط بالمعقد المنشط"},{"level":"1 درجة","description":"يذكر سببًا واحدًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بزيادة عدد التصادمات سببًا وحيدًا","القول إن رفع درجة الحرارة يخفض طاقة التنشيط","الخلط بين أثر درجة الحرارة وأثر التركيز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-07T17:19:00.442Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) يتوقف الفوران أسرع في الكأس التي عند 50°C. (ب) درجة الحرارة الأعلى تزيد متوسط الطاقة الحركية لجسيمات الماء ومواد القرص، فيزداد عدد التصادمات في وحدة الزمن، ويزداد كثيرًا عدد التصادمات التي طاقتها تساوي طاقة التنشيط أو تزيد عليها؛ فتزداد سرعة التفاعل ويقصر زمنه. (ج) عند 40°C يقع زمن التفاعل بين زمنيه عند 25°C و50°C: أقصر منه عند 25°C وأطول منه عند 50°C.', '["التوقع: أسرع عند 50°C","زيادة متوسط الطاقة الحركية وعدد التصادمات","زيادة التصادمات ذات الطاقة الكافية","زمن التفاعل عند 40°C بين الزمنين"]'::jsonb, '[]'::jsonb, '[{"element":"التوقع الصحيح","marks":1},{"element":"زيادة الطاقة الحركية وعدد التصادمات","marks":1},{"element":"زيادة التصادمات ذات الطاقة ≥ طاقة التنشيط","marks":1},{"element":"التوقع عند 40°C","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يتوقع النتيجة صحيحًا ويفسرها بالطاقة الحركية والتصادمات ذات الطاقة الكافية ويتوقع زمن 40°C صحيحًا"},{"level":"2–3 درجات","description":"يتوقع صحيحًا ويفسر تفسيرًا ناقصًا أو يخطئ في توقع 40°C"},{"level":"1 درجة","description":"يتوقع النتيجة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع أن الماء البارد أسرع","تفسير السرعة بزيادة كمية القرص أو الماء","توقع أن زمن 40°C أقصر من زمن 50°C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-07T17:19:00.443Z"}'::jsonb)
