from (values
('mcq', 1, 'وفق نظرية التصادم، لماذا تزداد سرعة التفاعل عند زيادة تركيز إحدى المواد المتفاعلة؟', null, null, '["تزداد الطاقة الحركية لكل جسيم من الجسيمات المتفاعلة","تقل طاقة التنشيط اللازمة لحدوث التفاعل","يزداد عدد الجسيمات في الحجم نفسه فيزداد عدد التصادمات","تزداد الطاقة التي يحملها كل تصادم بين الجسيمات"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 59 — التركيز'),
('mcq', 2, 'تحترق شمعة ببطء في الهواء، وتحترق بلهب شديد الإضاءة داخل وعاء يحتوي أكسجين تركيزه 100% تقريبًا. ما تفسير ذلك؟', null, null, '["تزداد التصادمات بين جزيئات الشمع والأكسجين لزيادة تركيزه","يعمل الأكسجين النقي محفزًا يخفض طاقة التنشيط","يرفع الوعاء الزجاجي درجة حرارة اللهب فقط","يزيد الأكسجين النقي مساحة سطح الشمعة المعرضة للهب"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 59 — التركيز (الشكل 2-8)'),
