('mcq', 4, 'في الشكل الآتي، إذا افترضنا أن كل جسيم من A يمكن أن يتصادم مع كل جسيم من B، فكم ضعفًا يصبح عدد احتمالات التصادم بين A وB في الوعاء (3) مقارنة بالوعاء (1)؟', null, '[{"src":"qimg/chem22/c2-l2b-boxes.svg","alt":"ثلاثة أوعية متساوية في الحجم ودرجة الحرارة تحتوي جسيمات المادتين A (دوائر زرقاء) وB (دوائر حمراء): الوعاء (1) فيه جسيمان من A وجسيمان من B، والوعاء (2) فيه أربعة جسيمات من A وجسيمان من B، والوعاء (3) فيه أربعة جسيمات من A وأربعة جسيمات من B."}]'::jsonb, '["ضعفين","أربعة أضعاف","ثمانية أضعاف","العدد نفسه"]'::jsonb, 'تحليل', 'تحليل شكل', 'صعب', 'الكتاب ص 72 — س59، وص 59 — التركيز'),
('mcq', 5, 'وُضع شريط مغنيسيوم طوله 1 cm في كل أنبوب من أربعة أنابيب تحتوي حجومًا متساوية من حمض HCl مختلف التركيز، وسُجّل الزمن حتى توقف الفقاعات كما في الجدول الآتي. ما الاستنتاج الذي تدعمه النتائج؟', '{"headers":["رقم الأنبوب","تركيز HCl","زمن توقف الفقاعات"],"rows":[["1","6.0 M","12 s"],["2","3.0 M","35 s"],["3","1.5 M","105 s"],["4","0.75 M","290 s"]]}'::jsonb, null, '["كلما زاد تركيز HCl طال الزمن وقلت سرعة التفاعل","سرعة التفاعل لا تعتمد على تركيز HCl لأن طول Mg ثابت","كلما زاد تركيز HCl قصر الزمن وزادت سرعة التفاعل","كلما زاد تركيز HCl زادت كمية Mg المتفاعلة"]'::jsonb, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 68 — مختبر الكيمياء: تأثير التركيز في سرعة التفاعل'),
('mcq', 6, 'يحدث التفاعل A + B → AB بسرعة معينة. إذا زيد تركيز المادة A مع بقاء تركيز B ودرجة الحرارة ثابتين، فماذا يحدث؟', null, null, '["تبقى السرعة ثابتة لأن تركيز B لم يتغير","تزداد تصادمات A مع B في وحدة الزمن فتزداد السرعة","تقل السرعة لأن جسيمات A تتصادم معًا بدل B","تزداد كمية AB النهائية دون أن تتغير السرعة"]'::jsonb, 'فهم', 'توقع', 'سهل', 'الكتاب ص 59 — التركيز (ماذا قرأت؟)'),
