('mcq', 1, 2, 'تنص نظرية التصادم على أن الجسيمات يجب أن تتصادم حتى يحدث التفاعل، وكلما زاد عدد الجسيمات في الحجم نفسه (زاد التركيز) ازداد عدد الاصطدامات، فتزداد سرعة التفاعل.', '["زيادة الطاقة الحركية للجسيمات تنتج عن رفع درجة الحرارة لا عن زيادة التركيز.","التركيز لا يغير طاقة التنشيط؛ والذي يخفضها هو المحفز.","","طاقة التصادم الواحد تعتمد على درجة الحرارة، والتركيز يزيد عدد التصادمات لا طاقتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.443Z"}'::jsonb),
('mcq', 2, 0, 'يبلغ تركيز الأكسجين في الهواء نحو 20%، أما في الوعاء فنحو 100%؛ أي نحو خمسة أضعاف. وكلما زاد تركيز الأكسجين زاد عدد الاصطدامات بين جزيئات الشمع وجزيئات الأكسجين، فتزداد سرعة الاحتراق ويشتد اللهب.', '["","الأكسجين مادة متفاعلة تُستهلك في الاحتراق وليس محفزًا.","الشمعة في الهواء ترتفع حرارتها أيضًا؛ والفرق بين الحالتين هو تركيز الأكسجين.","مساحة سطح الشمعة واحدة في الحالتين؛ الذي تغير هو تركيز الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-07T17:19:00.443Z"}'::jsonb),
('mcq', 3, 3, 'الوعاء (3) فيه أكبر تركيز من A ومن B معًا (أربعة جسيمات من كل منهما في الحجم نفسه)، فيكون عدد التصادمات بين A وB فيه أكبر، وتكون سرعة التفاعل فيه أكبر.', '["الوعاء (1) فيه أقل عدد من الجسيمات، فعدد التصادمات فيه أقل.","الوعاء (2) فيه أربعة جسيمات من A لكن جسيمان فقط من B، فتصادماته أقل من الوعاء (3).","لا يتساوى الوعاءان؛ فعدد جسيمات B في الوعاء (3) ضعف عددها في الوعاء (2)، فتصادمات A مع B فيه أكثر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-07T17:19:00.443Z"}'::jsonb),
('mcq', 4, 1, 'عدد احتمالات التصادم = عدد جسيمات A × عدد جسيمات B. في الوعاء (1): 2 × 2 = 4، وفي الوعاء (3): 4 × 4 = 16، فالعدد في الوعاء (3) أربعة أضعاف العدد في الوعاء (1).', '["هذا ما يحدث عند مضاعفة تركيز مادة واحدة فقط (الوعاء 2)، أما في الوعاء (3) فتضاعف تركيز A وB معًا.","","عدد الاحتمالات في الوعاء (3) يساوي 4 × 4 = 16، وفي الوعاء (1) يساوي 2 × 2 = 4؛ فالنسبة 4 لا 8.","زيادة عدد جسيمات A وB تزيد احتمالات التصادم بينها ولا تبقيها ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-07T17:19:00.444Z"}'::jsonb),
('mcq', 5, 2, 'تراكيز HCl من 6.0 M إلى 0.75 M قابلتها أزمنة من 12 s إلى 290 s؛ فكلما زاد التركيز قصر الزمن اللازم لتفاعل الشريط نفسه، أي زادت سرعة التفاعل، لأن زيادة عدد جسيمات الحمض في الحجم نفسه تزيد التصادمات مع سطح المغنيسيوم.', '["البيانات تبين أن الزمن يقصر (12 s عند 6.0 M) كلما زاد التركيز، فالعلاقة معكوسة في هذا البديل.","ثبات طول الشريط يجعل التجربة عادلة، والاختلاف الكبير في الأزمنة يدل على أثر التركيز.","","كمية Mg واحدة (1 cm) في كل الأنابيب، والذي تغير هو سرعة استهلاكها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.444Z"}'::jsonb),
('mcq', 6, 1, 'وفق نظرية التصادم، زيادة تركيز A تعني جسيمات أكثر من A في الحجم نفسه، فيزداد عدد التصادمات بين جسيمات A وجسيمات B في وحدة الزمن، فتزداد سرعة التفاعل.', '["السرعة تعتمد على تصادمات A مع B، وزيادة جسيمات A تزيد هذه التصادمات حتى لو بقي تركيز B ثابتًا.","","زيادة جسيمات A تزيد فرص تصادمها مع جسيمات B ولا تقللها.","التغير في التركيز يغير سرعة تكون AB؛ وكمية AB النهائية محدودة بكمية B."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.444Z"}'::jsonb),
('mcq', 7, 0, 'مع تقدم التفاعل تُستهلك المواد المتفاعلة فيقل تركيزها، أي يقل عدد جسيماتها في الحجم نفسه، فيقل عدد الاصطدامات بينها في وحدة الزمن وتقل سرعة التفاعل.', '["","طاقة التنشيط ثابتة للتفاعل عند ثبات الظروف، ولا تزداد بتقدم التفاعل.","درجة الحرارة ثابتة، فمتوسط الطاقة الحركية لا يتغير.","المحفز يزيد سرعة التفاعل ولا يبطئه، والنواتج هنا ليست محفزًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-07T17:19:00.444Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تنص نظرية التصادم على أن جسيمات المواد المتفاعلة يجب أن تتصادم حتى يحدث التفاعل. وزيادة تركيز المادة المتفاعلة تعني وجود عدد أكبر من جسيماتها في الحجم نفسه، فيزداد عدد الاصطدامات بين الجسيمات المتفاعلة في وحدة الزمن، ويزداد بذلك عدد الاصطدامات التي تؤدي إلى تفاعل، فتزداد سرعة التفاعل. مثال: تحترق الشمعة بلهب شديد في وعاء فيه أكسجين تركيزه 100% تقريبًا (نحو خمسة أضعاف تركيزه في الهواء)؛ لزيادة التصادمات بين جزيئات الشمع والأكسجين.', '["يجب أن تتصادم الجسيمات حتى يحدث التفاعل","زيادة التركيز تزيد عدد الجسيمات في الحجم نفسه فيزداد عدد التصادمات","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"نص نظرية التصادم","marks":1},{"element":"الربط بين التركيز وعدد التصادمات والسرعة","marks":1},{"element":"مثال صحيح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يذكر شرط التصادم ويربط التركيز بعدد التصادمات والسرعة ويعطي مثالًا صحيحًا"},{"level":"2 درجتان","description":"يربط التركيز بالتصادمات دون مثال، أو يعطي مثالًا مع تفسير ناقص"},{"level":"1 درجة","description":"يذكر أن السرعة تزداد بزيادة التركيز دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن زيادة التركيز تزيد طاقة الجسيمات","القول إن زيادة التركيز تخفض طاقة التنشيط","إعطاء مثال على أثر درجة الحرارة بدل التركيز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-07T17:19:00.444Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) كلما زاد تركيز HCl قصر الزمن اللازم لتوقف الفقاعات (من 290 s عند 0.75 M إلى 12 s عند 6.0 M)، أي أن سرعة التفاعل تزداد بزيادة التركيز. (ب) زيادة التركيز تعني عددًا أكبر من جسيمات الحمض في الحجم نفسه، فيزداد عدد التصادمات بين جسيمات الحمض وذرات سطح المغنيسيوم في وحدة الزمن، فيزداد عدد التصادمات المؤدية إلى التفاعل وتزداد السرعة. (ج) من المتغيرات الضابطة: طول شريط المغنيسيوم (مساحة سطحه)، وحجم الحمض، ودرجة الحرارة؛ ويجب تثبيتها لأن كلًّا منها يؤثر في سرعة التفاعل، فيكون التركيز وحده سبب اختلاف النتائج.', '["زيادة التركيز تزيد السرعة (يقل الزمن)","التفسير بزيادة عدد الجسيمات والتصادمات","متغيران ضابطان صحيحان","سبب تثبيت المتغيرات"]'::jsonb, '[]'::jsonb, '[{"element":"وصف العلاقة بالاستناد إلى البيانات","marks":1},{"element":"التفسير بنظرية التصادم","marks":1},{"element":"متغيران ضابطان","marks":1},{"element":"سبب التثبيت","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يصف العلاقة بالبيانات ويفسرها ويذكر متغيرين ضابطين وسبب تثبيتهما"},{"level":"2–3 درجات","description":"يصف العلاقة ويفسرها مع نقص في المتغيرات الضابطة أو سبب تثبيتها"},{"level":"1 درجة","description":"يصف العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الزمن والسرعة (الزمن الأطول يعني سرعة أكبر)","عدّ التركيز متغيرًا ضابطًا","تفسير النتائج بزيادة طاقة الجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-07T17:19:00.444Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) كل جسيم من A يمكن أن يتصادم مع كل جسيم من B، فعدد الاحتمالات = 2 × 2 = 4. (ب) عند 3 جسيمات من A: 3 × 2 = 6 احتمالات، وعند 4 جسيمات من A: 4 × 2 = 8 احتمالات. (ج) يزداد عدد احتمالات التصادم بين A وB بزيادة عدد جسيمات A (زيادة تركيزها) في الحجم نفسه؛ فمضاعفة جسيمات A من 2 إلى 4 ضاعفت احتمالات التصادم من 4 إلى 8، وزيادة التصادمات تعني زيادة سرعة التفاعل.', '["4 احتمالات في البداية","6 احتمالات ثم 8 احتمالات","زيادة التركيز تزيد التصادمات فتزيد السرعة"]'::jsonb, '["عدد الاحتمالات = عدد جسيمات A × عدد جسيمات B","2 × 2 = 4","3 × 2 = 6","4 × 2 = 8","مضاعفة A ضاعفت الاحتمالات من 4 إلى 8"]'::jsonb, '[{"element":"حساب الحالة الأولى","marks":1},{"element":"حساب الحالتين الأخريين","marks":2},{"element":"الاستنتاج حول سرعة التفاعل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحسب الحالات الثلاث صحيحًا ويستنتج أثر التركيز في عدد التصادمات والسرعة"},{"level":"2–3 درجات","description":"يحسب بعض الحالات صحيحًا أو يحسبها دون استنتاج"},{"level":"1 درجة","description":"يستنتج أن السرعة تزداد دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع عدد الجسيمات بدل ضربها","عدّ تصادمات A مع A ضمن التصادمات المؤدية إلى AB","استنتاج أن السرعة لا تتغير لثبات B"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.444Z"}'::jsonb)
