('mcq', 4, 'ينتج محلول H₂O₂ غاز O₂ حجمه 12 mL خلال 100 s عند 298 K. ما الزمن التقريبي اللازم لإنتاج 12 mL من O₂ من مقدار مماثل من المحلول عند 288 K؟', null, null, '["200 s","50 s","100 s","400 s"]'::jsonb, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 70 — س45'),
('mcq', 5, 'يبين المنحنى الآتي السرعة النسبية لتفاعل عند درجات حرارة مختلفة. ما السرعة النسبية المتوقعة للتفاعل عند 330 K؟', null, '[{"src":"qimg/chem22/c2-l2b-rate-temp.svg","alt":"منحنى سرعة التفاعل النسبية (المحور الرأسي من 0 إلى 35) مع درجة الحرارة بوحدة K (المحور الأفقي من 280 إلى 330). المنحنى يتصاعد بانحدار متزايد، وعليه خمس نقاط عند 290 K و300 K و310 K و320 K و330 K، وكتبت إحداثيات ثلاث منها فقط: (290 K, 2) و(300 K, 4) و(310 K, 8)، أما النقطتان عند 320 K و330 K فبلا أرقام."}]'::jsonb, '["16","24","64","32"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'سهل', 'الكتاب ص 60 — درجة الحرارة (الشكل 2-10)'),
('mcq', 6, 'اعتمادًا على المنحنى الآتي، أين تقع السرعة النسبية للتفاعل عند 325 K؟', null, '[{"src":"qimg/chem22/c2-l2b-rate-temp.svg","alt":"منحنى سرعة التفاعل النسبية (المحور الرأسي من 0 إلى 35) مع درجة الحرارة بوحدة K (المحور الأفقي من 280 إلى 330). المنحنى يتصاعد بانحدار متزايد، وعليه خمس نقاط عند 290 K و300 K و310 K و320 K و330 K، وكتبت إحداثيات ثلاث منها فقط: (290 K, 2) و(300 K, 4) و(310 K, 8)، أما النقطتان عند 320 K و330 K فبلا أرقام."}]'::jsonb, '["بين 4 و8","بين 8 و16","بين 16 و32","أكبر من 32"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 60 — اختبار الرسم البياني (الشكل 2-10)'),
('mcq', 7, 'سرعة تفاعل عند 300 K تساوي 2.5 × 10⁻³ mol/L·s. ما السرعة التقريبية للتفاعل نفسه عند 280 K بالتراكيز نفسها؟', null, null, '["1.3 × 10⁻³ mol/L·s","6.3 × 10⁻⁴ mol/L·s","1.0 × 10⁻² mol/L·s","2.5 × 10⁻⁴ mol/L·s"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 60 — درجة الحرارة'),
('essay', 1, 'يكتمل تفاعل كيميائي خلال 160 s عند 25°C. باستعمال قاعدة مضاعفة السرعة لكل 10 K تقريبًا، قدّر زمن اكتمال التفاعل نفسه (بالكميات نفسها): (أ) عند 45°C. (ب) عند 15°C. وبيّن خطوات الحل.', null, null, null, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 60 — درجة الحرارة، وص 62 — س16'),
('essay', 2, 'سرعة تفاعل عند 310 K تساوي 4.0 × 10⁻⁴ mol/L·s. باستعمال قاعدة مضاعفة السرعة لكل 10 K تقريبًا: (أ) قدّر سرعة التفاعل عند 340 K. (ب) قدّر سرعته عند 290 K. (ج) كم مرة تقريبًا يكون التفاعل عند 340 K أسرع منه عند 290 K؟', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 60 — درجة الحرارة، وص 70 — س44 وس45'),
('essay', 3, 'قال طالب: «إذا رفعنا درجة حرارة تفاعل من 20°C إلى 40°C فإن درجة الحرارة تتضاعف، لذا تتضاعف سرعة التفاعل مرة واحدة فقط». قوّم هذا القول، وصحّح ما فيه من خطأ.', null, null, null, 'تقويم', 'تقويم قول', 'صعب', 'الكتاب ص 60 — درجة الحرارة، وص 62 — س16')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'تؤدي زيادة درجة الحرارة بمقدار 10 K إلى مضاعفة سرعة التفاعل تقريبًا.', '["الربط بين 10 K وعشرة أضعاف خطأ؛ فالزيادة بمقدار 10 K تضاعف السرعة مرة واحدة تقريبًا.","الزيادة أكبر بكثير من 10%؛ فهي نحو 100% (مضاعفة).","رفع درجة الحرارة يزيد سرعة التفاعل ولا يقللها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.445Z"}'::jsonb),
('mcq', 2, 1, 'الزيادة 20 K تتكون من زيادتين كل منهما 10 K، وكل زيادة تضاعف السرعة: 2 × 2 = 4؛ فتصبح السرعة أربعة أمثال قيمتها الأصلية تقريبًا.', '["هذه زيادة 10 K واحدة؛ أما 20 K فهي زيادتان متتاليتان: 2 × 2 = 4.","","خلط بين مقدار الزيادة في درجة الحرارة ومقدار تضاعف السرعة.","ثمانية أمثال تقابل زيادة 30 K (2 × 2 × 2)، لا 20 K."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-07T17:19:00.445Z"}'::jsonb),
('mcq', 3, 2, 'الفرق 308 − 298 = 10 K، فتتضاعف السرعة تقريبًا، فيتضاعف الحجم الناتج في الزمن نفسه: 12 mL × 2 = 24 mL.', '["قسمة الحجم على 2 بدل ضربه؛ فرفع درجة الحرارة يزيد السرعة لا يقللها.","إهمال أثر درجة الحرارة؛ فارتفاعها بمقدار 10 K يضاعف السرعة تقريبًا.","","ضرب الحجم في 10 لأن الفرق 10 K، والصواب أن الزيادة 10 K تضاعف السرعة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-07T17:19:00.445Z"}'::jsonb),
('mcq', 4, 0, 'الفرق 298 − 288 = 10 K انخفاضًا، فتقل السرعة إلى النصف تقريبًا، فيتضاعف الزمن اللازم لإنتاج الحجم نفسه: 100 s × 2 = 200 s.', '["","خفض درجة الحرارة يبطئ التفاعل فيطول الزمن؛ وقسمة الزمن على 2 تعني تسريع التفاعل.","إهمال أثر خفض درجة الحرارة بمقدار 10 K.","الفرق 10 K فقط، فتقل السرعة إلى النصف مرة واحدة ويتضاعف الزمن مرة واحدة، لا مرتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-07T17:19:00.445Z"}'::jsonb),
('mcq', 5, 3, 'يبين المنحنى أن السرعة تتضاعف كل 10 K (2 ثم 4 ثم 8). ومن 310 K إلى 330 K زيادتان: 8 × 2 = 16 عند 320 K، ثم 16 × 2 = 32 عند 330 K.', '["هذه السرعة عند 320 K، أو ناتج إكمال المنحنى خطيًا بزيادة ثابتة؛ والصواب أن السرعة تتضاعف كل 10 K.","ضرب السرعة عند 310 K في عدد الخطوات (8 × 3)؛ والصواب مضاعفتها مرتين: 8 × 2 × 2.","مضاعفة زائدة؛ فمن 310 K إلى 330 K زيادتان فقط كل منهما 10 K.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-07T17:19:00.445Z"}'::jsonb),
('mcq', 6, 2, 'السرعة تتضاعف كل 10 K: 8 عند 310 K، و16 عند 320 K، و32 عند 330 K. ودرجة الحرارة 325 K تقع بين 320 K و330 K، فالسرعة النسبية بين 16 و32 (نحو 23 تقريبًا).', '["هذا المدى يقابل درجات الحرارة بين 300 K و310 K.","هذا المدى يقابل درجات الحرارة بين 310 K و320 K.","","السرعة 32 تقابل 330 K، و325 K أقل منها فالسرعة أقل من 32."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-07T17:19:00.445Z"}'::jsonb),
('mcq', 7, 1, 'الانخفاض 300 − 280 = 20 K يعني انخفاضين كل منهما 10 K، فتقل السرعة إلى النصف مرتين أي إلى الربع: 2.5 × 10⁻³ ÷ 4 = 6.25 × 10⁻⁴ ≈ 6.3 × 10⁻⁴ mol/L·s.', '["قسمة السرعة على 2 مرة واحدة فقط؛ والانخفاض 20 K يعني القسمة على 2 مرتين (على 4).","","ضرب السرعة في 4 بدل قسمتها؛ فخفض درجة الحرارة يقلل السرعة.","قسمة السرعة على 10 لأن الفرق 20 K؛ والصواب أن كل 10 K تغير السرعة بعامل 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-07T17:19:00.446Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفرق في درجات الحرارة بوحدة K يساوي الفرق نفسه بوحدة °C. (أ) من 25°C إلى 45°C ارتفاع 20 K، أي زيادتان كل منهما 10 K، فتصبح السرعة 2 × 2 = 4 أمثالها، ويقل الزمن إلى الربع: 160 s ÷ 4 = 40 s. (ب) من 25°C إلى 15°C انخفاض 10 K، فتقل السرعة إلى النصف ويتضاعف الزمن: 160 s × 2 = 320 s.', '["الفرق 20 K والسرعة أربعة أمثالها","الزمن عند 45°C = 40 s","الفرق 10 K انخفاضًا والسرعة نصفها","الزمن عند 15°C = 320 s"]'::jsonb, '["ΔT (أ) = 45 − 25 = 20°C = 20 K","عامل السرعة = 2 × 2 = 4","الزمن = 160 s ÷ 4 = 40 s","ΔT (ب) = 15 − 25 = −10 K","عامل السرعة = ½، الزمن = 160 s × 2 = 320 s"]'::jsonb, '[{"element":"عامل تغير السرعة في (أ)","marks":1},{"element":"الزمن في (أ)","marks":1},{"element":"عامل تغير السرعة في (ب)","marks":1},{"element":"الزمن في (ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد عاملي تغير السرعة ويحسب الزمنين صحيحين مع الخطوات"},{"level":"2–3 درجات","description":"يحل أحد الجزأين صحيحًا، أو يحدد عاملي السرعة ويخطئ في ربط السرعة بالزمن"},{"level":"1 درجة","description":"يحدد عامل السرعة في جزء واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الزمن في عامل السرعة بدل قسمته عليه","تحويل الفرق في درجات الحرارة إلى K بإضافة 273 إليه","مضاعفة السرعة مرة واحدة لارتفاع 20 K"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.446Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) من 310 K إلى 340 K ارتفاع 30 K = ثلاث زيادات، فالسرعة تُضرب في 2 × 2 × 2 = 8: 4.0 × 10⁻⁴ × 8 = 3.2 × 10⁻³ mol/L·s. (ب) من 310 K إلى 290 K انخفاض 20 K، فالسرعة تُقسم على 4: 4.0 × 10⁻⁴ ÷ 4 = 1.0 × 10⁻⁴ mol/L·s. (ج) 3.2 × 10⁻³ ÷ 1.0 × 10⁻⁴ = 32؛ أي أسرع 32 مرة تقريبًا، وهو ما يتفق مع الفرق 50 K (2⁵ = 32).', '["السرعة عند 340 K = 3.2 × 10⁻³ mol/L·s","السرعة عند 290 K = 1.0 × 10⁻⁴ mol/L·s","النسبة 32 مرة"]'::jsonb, '["340 − 310 = 30 K → العامل 2³ = 8","4.0 × 10⁻⁴ × 8 = 3.2 × 10⁻³ mol/L·s","310 − 290 = 20 K → العامل 2² = 4","4.0 × 10⁻⁴ ÷ 4 = 1.0 × 10⁻⁴ mol/L·s","النسبة = 3.2 × 10⁻³ ÷ 1.0 × 10⁻⁴ = 32"]'::jsonb, '[{"element":"السرعة عند 340 K","marks":2},{"element":"السرعة عند 290 K","marks":1},{"element":"النسبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحسب السرعتين والنسبة صحيحة مع الخطوات والوحدات"},{"level":"2–3 درجات","description":"يحسب سرعة واحدة صحيحة أو يخطئ في النسبة"},{"level":"1 درجة","description":"يحدد عامل التغير صحيحًا دون إكمال الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب السرعة في 3 بدل 8 لارتفاع 30 K","ضرب السرعة بدل قسمتها عند خفض درجة الحرارة","إهمال الأس السالب في الوحدة العلمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-07T17:19:00.446Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول غير صحيح. أولًا: درجة الحرارة لم تتضاعف فعلًا؛ فبالكلفن ارتفعت من 293 K إلى 313 K فقط، ومضاعفة الرقم بالسيلزيوس لا تعني مضاعفة درجة الحرارة. ثانيًا: قاعدة تقدير السرعة تعتمد على مقدار الارتفاع لا على نسبته: الارتفاع 20 K يساوي زيادتين كل منهما 10 K، وكل زيادة تضاعف السرعة تقريبًا، فتصبح السرعة 2 × 2 = 4 أمثالها تقريبًا لا مثليها. ثالثًا: القاعدة تقريبية تصلح للتقدير.', '["الحكم بأن القول غير صحيح","تضاعف الرقم بالسيلزيوس لا يعني تضاعف درجة الحرارة (293 K → 313 K)","الارتفاع 20 K يعطي أربعة أمثال السرعة تقريبًا"]'::jsonb, '["20°C = 293 K و40°C = 313 K","ΔT = 20 K = زيادتان من 10 K","العامل = 2 × 2 = 4"]'::jsonb, '[{"element":"الحكم على القول","marks":1},{"element":"تصحيح فكرة تضاعف درجة الحرارة","marks":1},{"element":"التقدير الصحيح لتغير السرعة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يحكم صحيحًا ويصحح فكرة تضاعف الحرارة ويقدر السرعة أربعة أمثالها"},{"level":"2 درجتان","description":"يقدر السرعة صحيحًا دون تصحيح فكرة تضاعف الحرارة، أو العكس"},{"level":"1 درجة","description":"يحكم بخطأ القول دون تعليل كاف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على أن السرعة تتضاعف مرة واحدة","عدّ 40°C ضعف 20°C في درجة الحرارة المطلقة","تقدير السرعة بعشرين ضعفًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-07T17:19:00.446Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O10') and x.type = v.type and x.number = v.number
